function getContrastText(hex) {
  try {
    let c = (hex || "").replace("#", "");
    if (c.length === 3) c = c[0] + c[0] + c[1] + c[1] + c[2] + c[2];
    const r = parseInt(c.substr(0, 2), 16) || 0;
    const g = parseInt(c.substr(2, 2), 16) || 0;
    const b = parseInt(c.substr(4, 2), 16) || 0;
    const y = (r * 299 + g * 587 + b * 114) / 1000;
    return y > 160 ? "#111" : "#fff";
  } catch (e) { return "#fff"; }
}
function setAccentColor(color) {
  if (!color) return;
  document.documentElement.style.setProperty("--accent", color);
  document.documentElement.style.setProperty("--accent-text", getContrastText(color));
  try {
    let c = color.replace("#", "");
    if (c.length === 3) c = c[0] + c[0] + c[1] + c[1] + c[2] + c[2];
    const r = parseInt(c.substr(0, 2), 16);
    const g = parseInt(c.substr(2, 2), 16);
    const b = parseInt(c.substr(4, 2), 16);
    document.documentElement.style.setProperty("--accent-soft", `rgba(${r}, ${g}, ${b}, 0.15)`);
    document.documentElement.style.setProperty("--accent-subtle", `rgba(${r}, ${g}, ${b}, 0.1)`);
  } catch {}
}

// Load branding early for login screen
(async function loadBrandingEarly() {
  try {
    const resp = await fetch("/api/branding");
    if (resp.ok) {
      const branding = await resp.json();
      // Cache for instant load on next page
      try { localStorage.setItem("sietch_branding_cache", JSON.stringify(branding)); } catch {}
      // Apply to login screen immediately
      if (branding.companyName) {
        document.title = branding.companyName;
        const loginTitle = document.querySelector(".login-title");
        if (loginTitle) loginTitle.textContent = branding.loginTitle || branding.companyName;
        const noscript = document.querySelector("noscript div");
        if (noscript) noscript.textContent = `JavaScript is required for the ${branding.companyName}. Please enable it and reload.`;
      }
      // favicon is static (not overridable per non-negotiables); branding watermark/logo still customizable
      // if (branding.faviconPath) { ... }
      if (branding.primaryColor) {
        setAccentColor(branding.primaryColor);
      }
    }
  } catch (e) {
    // Silently fail — branding is cosmetic
  }
})();

