// ── SSE (Server-Sent Events) ──────────────────────────────────────────────
let _evtSource = null;
let _sseReconnectTimer = null;
let _sseReconnectDelay = 5000;
const _SSE_MAX_DELAY = 30000;

function connectSSE() {
  if (_evtSource) return;
  _evtSource = new EventSource("/api/events");
  _evtSource.addEventListener("connected", () => {
    console.log("[SSE] Connected");
    _sseReconnectDelay = 5000; // Reset backoff on success
  });
  _evtSource.onmessage = (e) => {
    try {
      const { type, data } = JSON.parse(e.data);
      handleSSEEvent(type, data);
    } catch (err) {
      console.error("[SSE] Parse error:", err);
    }
  };
  _evtSource.onerror = () => {
    console.log(`[SSE] Connection lost, reconnecting in ${_sseReconnectDelay / 1000}s...`);
    _evtSource.close();
    _evtSource = null;
    _sseReconnectTimer = setTimeout(connectSSE, _sseReconnectDelay);
    _sseReconnectDelay = Math.min(_sseReconnectDelay * 2, _SSE_MAX_DELAY);
  };
}

function disconnectSSE() {
  if (_sseReconnectTimer) { clearTimeout(_sseReconnectTimer); _sseReconnectTimer = null; }
  if (_evtSource) { _evtSource.close(); _evtSource = null; }
}

function handleSSEEvent(type, data) {
  switch (type) {
    case "dm:new": handleNewDM(data); break;
    case "dm:read": handleDMRead(data); break;
    case "presence:update": handlePresenceUpdate(data); break;
    case "task:created":
    case "task:updated":
    case "task:deleted": loadTasks(); break;
    case "task:reminder":
      showToast(`Reminder: ${data.title || data.data?.title || "Task reminder"}`);
      loadTasks();
      break;
case "notification:new":
    // Always re-poll the server count for the badge, not just trust the
    // local cache. The cache can be empty (drawer never opened, or the SSE
    // arrived while the drawer was in the middle of a fetch). Without this
    // re-poll, automation notifications can land in the DB without ever
    // lighting the bell badge — the user opens the drawer later, sees the
    // notification, but the badge was hidden the whole time.
    _pollNotificationBadge();
    // Pulse animation on bell icon
    const bellBtn = $("#notification-bell-btn");
    if (bellBtn) {
      bellBtn.classList.remove("notification-pulse");
      void bellBtn.offsetWidth; // trigger reflow
      bellBtn.classList.add("notification-pulse");
    }
      if (state.feedModalOpen) loadNotificationFeed({ force: true });
      // Browser notification for calendar reminders
      if (data.type === "calendar_reminder" && document.hidden && Notification.permission === "granted") {
        new Notification("Calendar Reminder", { body: data.message || "Event starting soon", tag: "cal-reminder" });
      }
      break;
    case "mail:new":
      if (state.mailModalOpen) loadMailMessagesForModal(true);
      renderMailUnreadBadge();
      break;
  }
}

function handleNewDM(data) {
  const d = data.data || data;
  const selectedUser = state.presenceSelectedUserId;
  if (selectedUser && String(selectedUser) === String(d.from)) {
    // Refresh the DM popup thread for this user
    presenceFetch(`/api/presence/dm?with=${encodeURIComponent(d.from)}`)
      .then(res => res.json())
      .then(d2 => {
        const log = $("#dm-popup-log");
        if (log) {
          const msgs = (d2 && d2.messages) || [];
          renderDMLog(log, msgs);
        }
      })
      .catch(() => {});
  }
  renderPresenceTileCompact(state.presenceData);
  updateUnreadBadge();
  if (document.hidden && Notification.permission === "granted") {
    new Notification(d.fromName || "New message", { body: d.text, tag: `dm-${d.from}` });
  }
}

function handleDMRead(data) {
  const d = data.data || data;
  const selectedUser = state.presenceSelectedUserId;
  if (selectedUser && String(selectedUser) === String(d.with_user)) {
    presenceFetch(`/api/presence/dm?with=${encodeURIComponent(d.with_user)}`)
      .then(res => res.json())
      .then(d2 => {
        const log = $("#dm-popup-log");
        if (log) {
          const msgs = (d2 && d2.messages) || [];
          renderDMLog(log, msgs);
        }
      })
      .catch(() => {});
  }
}

function handlePresenceUpdate(data) {
  const d = data.data || data;
  if (state.presenceData) {
    const idx = state.presenceData.findIndex(u => String(u.id) === String(d.user_id));
    if (idx >= 0) Object.assign(state.presenceData[idx], d);
    if (state.presenceModalOpen) renderPresenceModal(state.presenceData);
    if (state.hasPresenceTile) renderPresenceTileCompact(state.presenceData);
  }
}

function newId() {
  try {
    if (typeof crypto !== "undefined" && crypto && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch {}
  // Fallback for non-secure contexts (plain http on LAN IPs) and older browsers
  const t = Date.now().toString(36);
  const r = Math.random().toString(36).slice(2);
  const r2 = Math.random().toString(36).slice(2);
  return `${t}-${r}-${r2}`;
}

