function defaultTileOrder() {
  return [
    "tile-feed",
    "tile-tasks",
    ...state.groups.map((g) => `group-${g.id}`),
    ...state.calendarTiles.map((c) => calendarTileId(c)),
    ...activeNotesTiles().map((n) => notesTileId(n)),
    ...activeLocalKanbanTiles().map((k) => localKanbanTileId(k)),
  ];
}

function notesTileId(notes) {
  return `notes-${notes.id}`;
}

function localKanbanTileId(kanban) {
  return `local-kanban-${kanban.id}`;
}

function activeLocalKanbanTiles() {
  return (state.localKanbanTiles || []).filter(k => !k.archived);
}

function calendarTileId(cal) {
  return `calendar-${cal.id}`;
}

function isAutoRefreshTileId(tileId) {
  // SSE handles tasks and feed updates in real-time; only calendars and groups need manual refresh
  return (typeof tileId === "string" && (tileId.startsWith("calendar-") || tileId.startsWith("group-")));
}

function getCalendarByTileId(tileId) {
  const id = String(tileId || "").replace(/^calendar-/, "");
  return state.calendarTiles.find((c) => c.id === id) || null;
}

function ensureTileLayout() {
  const order = state.tileLayout.order?.length ? [...state.tileLayout.order] : defaultTileOrder();
  const known = new Set(defaultTileOrder());
  known.add("tile-notes");
  // tile-presence is user-controllable (Add Tile / X button): preserve it in the
  // order only if already present — never force-add it (known excludes it) and
  // never strip it (whitelisted here), so add/remove both survive refresh.
  const filtered = order.filter((id) => known.has(id) || id === "tile-presence");
  for (const id of known) {
    if (!filtered.includes(id)) filtered.push(id);
  }
  // Drop stale pin if the tile was removed
  if (!filtered.includes("tile-presence") && state.tileLayout.pinned) {
    delete state.tileLayout.pinned["tile-presence"];
  }
  // Only save if order actually changed
  const origOrder = state.tileLayout.order?.join(",") || "";
  state.tileLayout.order = filtered;
  if (!state.tileLayout.order.includes("tile-notes")) {
    state.tileLayout.order.push("tile-notes");
  }
  if (state.tileLayout.order.join(",") !== origOrder) {
    saveLayoutToStorage();
  }
}

function tileWidth(tileId) {
  const w = state.tileLayout.widths[tileId];
  if (w === "quarter" || w === "half" || w === "three") return w;
  return "full";
}

function tileHeight(tileId) {
  const h = state.tileLayout.heights[tileId];
  if (h === "double") return 2;
  if (typeof h === "number" && h >= 2) return Math.min(h, 8);
  return 1;
}

function setTileWidth(tileId, width) {
  state.tileLayout.widths[tileId] =
    width === "quarter" ? "quarter" : width === "half" ? "half"
    : width === "three" ? "three" : "full";
  saveLayoutToStorage();
}

function setTileHeight(tileId, height) {
  const n = typeof height === "number" ? height : (height === "double" ? 2 : 1);
  state.tileLayout.heights[tileId] = Math.max(1, Math.min(n, 8));
  saveLayoutToStorage();
}

function tileBodyCollapsed(tileId) {
  return state.tileLayout.collapsed?.[tileId] === true;
}

function setTileBodyCollapsed(tileId, collapsed) {
  if (!state.tileLayout.collapsed) state.tileLayout.collapsed = {};
  if (collapsed) state.tileLayout.collapsed[tileId] = true;
  else delete state.tileLayout.collapsed[tileId];
  saveLayoutToStorage();
  const tileEl = document.querySelector(`[data-tile-id="${tileId}"]`);
  if (tileEl) {
    applyTileBodyCollapsed(tileEl, tileId);
  }
}

/* Tasks tile: two-column layout (Todo + Project Tasks side by side). Only
   available (and only rendered) while the tile is half-width — see CSS
   `.tasks-panel.tile-half.tasks-columns-on`. */
function tasksColumnsMode() {
  return state.tileLayout.tasksColumns === true;
}

function setTasksColumnsMode(on) {
  state.tileLayout.tasksColumns = !!on;
  saveLayoutToStorage();
}

function applyTasksColumnsState(tileEl) {
  if (!tileEl || tileEl.dataset.tileId !== "tile-tasks") return;
  const on = tasksColumnsMode();
  tileEl.classList.toggle("tasks-columns-on", on);
  const btn = tileEl.querySelector(".tasks-columns-btn");
  if (btn) {
    btn.classList.toggle("active", on);
    btn.title = on ? "Show one list at a time" : "Show Todo and Project Tasks side by side";
  }
}

/** Tiles that fetch CRM (or calendar feed) data when expanded. Notes tiles are local-only. */
function isCrmDataTileId(tileId) {
  if (!tileId) return false;
  if (tileId === "tile-feed" || tileId === "tile-tasks") return true;
  if (tileId.startsWith("group-") || tileId.startsWith("calendar-")) return true;
  return false;
}

/** CRM‑origin tiles only (excludes 3rd‑party calendar). Used by the loading indicator. */
function isCrmOnlyTileId(tileId) {
  if (!tileId) return false;
  if (tileId === "tile-feed" || tileId === "tile-tasks") return true;
  if (tileId.startsWith("group-")) return true;
  return false;
}

function shouldFetchTileCrmData(tileId) {
  return isCrmDataTileId(tileId) && !tileBodyCollapsed(tileId);
}

function groupForTileId(tileId) {
  if (!tileId?.startsWith("group-")) return null;
  const groupId = tileId.slice("group-".length);
  return state.groups.find((g) => String(g.id) === String(groupId)) || null;
}

function dashboardTileIdsForLoad() {
  const ids = [...PINNED_TILE_IDS, ...(state.tileLayout.order || [])];
  return [...new Set(ids.filter(Boolean))];
}

function showTileCollapsedHint(tileId, message) {
  const tileEl = document.querySelector(`[data-tile-id="${tileId}"]`);
  if (!tileEl || !tileBodyCollapsed(tileId)) return;
  if (tileId === "tile-feed") {
    const list = $("#notification-feed", tileEl);
    if (list) list.innerHTML = `<li class="feed-collapsed-hint">${escapeHtml(message)}</li>`;
    updatePanelTileCount("tile-feed", 0);
    return;
  }
  if (tileId === "tile-tasks") {
    const wrap = $(".tasks-by-user", tileEl);
    if (wrap) wrap.innerHTML = `<p class="tile-collapsed-hint">${escapeHtml(message)}</p>`;
    updatePanelTileCount("tile-tasks", 0);
    return;
  }
  if (tileId.startsWith("group-")) {
    const group = groupForTileId(tileId);
    const board = group?._el ? $(".board", group._el) : null;
    if (board) board.innerHTML = `<p class="tile-collapsed-hint">${escapeHtml(message)}</p>`;
    const countEl = group?._el?.querySelector(".board-group-count");
    if (countEl) countEl.textContent = "—";
    return;
  }
  if (tileId.startsWith("calendar-")) {
    const body = tileEl.querySelector(".calendar-month-body");
    if (body) body.innerHTML = `<p class="tile-collapsed-hint">${escapeHtml(message)}</p>`;
  }
}

function updateDashboardStatusText() {
  const openOpps = countOpenOpportunities();
  const openTasks = state.tasks.length;
  let text = `${openOpps} open projects · ${openTasks} open tasks`;
  const users = Array.isArray(state.presenceData?.users) ? state.presenceData.users : [];
  const onlineCount = users.filter(u => u.online).length;
  text += ` · ${onlineCount} online`;
  const status = $("#status-text");
  if (status) status.textContent = text;
}

async function loadTileCrmData(tileId, opts = {}) {
  const { quiet = false, force = false } = opts;
  if (!tileId || (!force && !shouldFetchTileCrmData(tileId))) return;

  if (tileId === "tile-tasks") {
    await loadTasks({ force });
    return;
  }
  if (tileId.startsWith("calendar-")) {
    const cal = getCalendarByTileId(tileId);
    if (cal) await loadCalendarForTile(cal, { quiet });
    return;
  }
  if (tileId.startsWith("group-")) {
    const group = groupForTileId(tileId);
    if (group) await refreshGroup(group, opts);
  }
}

async function loadExpandedDashboardTiles({ quiet = false, force = false } = {}) {
  const allIds = dashboardTileIdsForLoad();
  const crmJobs = [];
  const collapsibleIds = [];
  for (const tileId of allIds) {
    if (shouldFetchTileCrmData(tileId)) {
      crmJobs.push(tileId);
    } else if (isCrmDataTileId(tileId) && tileBodyCollapsed(tileId)) {
      collapsibleIds.push(tileId);
    }
  }

  for (const tileId of collapsibleIds) {
    showTileCollapsedHint(tileId, "Minimized — expand to load");
  }

  // Fire tile loads in background — never block the dashboard for these.
  // Each handles its own errors via try/catch and shows error state inline.
  // CRM‑origin tiles (groups, feed, tasks) are tracked for the loading indicator;
  // calendar (3rd‑party) loads independently and doesn't block the indicator.
  // Both fire as background promises; refreshAll can observe CRM completion
  // via the returned promise without blocking.
  const crmPromises = [];
  const calendarPromises = [];
  for (const tileId of crmJobs) {
    (isCrmOnlyTileId(tileId) ? crmPromises : calendarPromises).push(
      loadTileCrmData(tileId, { quiet, force }).catch(() => {})
    );
  }
  if (calendarPromises.length) {
    Promise.allSettled(calendarPromises).catch(() => {});
  }
  // Always return a promise so callers can observe completion without blocking.
  if (crmPromises.length) {
    return Promise.allSettled(crmPromises).then(() => {
      updateDashboardStatusText();
    }).catch(() => {});
  }
  updateDashboardStatusText();
  return Promise.resolve();
}

const PINNED_TILE_IDS = [];
const PANEL_TILE_IDS = new Set();

function isTilePinnedToTop(tileId) {
  return false;
}

function setTilePinnedToTop(tileId, pinned) {
  // Pin functionality disabled
}

/** Ensure currently-pinned tiles (feed/tasks) appear first in the order array (in their relative user order).
 * This keeps them "at the top" logically, prevents other tiles from being ordered before them,
 * and makes L/R reordering within the pinned pair (when both pinned) and among mains clean and reliable.
 */
function normalizeOrderForPinned() {
  const ord = state.tileLayout.order;
  if (!ord || !ord.length) return;
  const pinnedNow = PINNED_TILE_IDS.filter((id) => isTilePinnedToTop(id));
  const pinnedPart = ord.filter((id) => pinnedNow.includes(id));
  const otherPart = ord.filter((id) => !pinnedNow.includes(id));
  // Preserve relative order within each group as user last arranged via drags
  if (pinnedPart.length !== pinnedNow.length || pinnedPart.join() !== pinnedNow.join() || otherPart.length + pinnedPart.length !== ord.length) {
    state.tileLayout.order = [...pinnedPart, ...otherPart];
  }
}

function saveFeedKeywordToStorage() {
  localStorage.setItem(FEED_KEYWORD_STORAGE_KEY, state.feedKeywordFilter || "");
  scheduleUserProfileSave();
}

function collectDashboardTileNodes() {
  const nodes = new Map();
  const container = $("#dashboard-tiles");
  if (container) {
    for (const child of [...container.children]) {
      if (child.dataset.tileId) nodes.set(child.dataset.tileId, child);
    }
  }
  return nodes;
}

function applyTileBodyCollapsed(tileEl, tileId) {
  if (!tileEl || !tileId) return;
  const collapsed = tileBodyCollapsed(tileId);
  tileEl.classList.toggle("tile-body-collapsed", collapsed);
  if (collapsed) {
    // Preserve width (half/quarter) so collapsed groups keep their "status" instead of going full-width.
    // Only strip height classes (vertical) as collapsed is horizontal bar.
    tileEl.classList.remove("tile-double", "tile-triple", "tile-quad");
  } else {
    applyTileLayoutClasses(tileEl, tileId);
  }
}

function applyTileLayoutClasses(tileEl, tileId) {
  if (!tileEl || !tileId) return;
  const w = tileWidth(tileId);
  const h = tileHeight(tileId);
  tileEl.classList.remove("tile-half", "tile-quarter", "tile-three",
    "tile-double", "tile-triple", "tile-quad");
  if (w === "half") tileEl.classList.add("tile-half");
  else if (w === "quarter") tileEl.classList.add("tile-quarter");
  else if (w === "three") tileEl.classList.add("tile-three");
  if (tileBodyCollapsed(tileId)) return;
  if (h === 2) tileEl.classList.add("tile-double");
  else if (h === 3) tileEl.classList.add("tile-triple");
  else if (h >= 4) tileEl.classList.add("tile-quad");
}

function createCollapseTileButton(tileEl, tileId) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "btn btn-ghost btn-collapse-tile tile-btn tile-btn-icon";
  const sync = () => {
    const collapsed = tileBodyCollapsed(tileId);
    const title = collapsed ? "Expand tile" : "Minimize tile";
    setTileLayoutIconButton(btn, collapsed ? TILE_ICON_TILE_EXPAND : TILE_ICON_MINIMIZE, title);
    btn.classList.toggle("tile-btn-active", collapsed);
    btn.setAttribute("aria-expanded", String(!collapsed));
    applyTileBodyCollapsed(tileEl, tileId);
  };
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    const wasCollapsed = tileBodyCollapsed(tileId);
    setTileBodyCollapsed(tileId, !wasCollapsed);
    sync();
    if (wasCollapsed && isCrmDataTileId(tileId)) {
      loadTileCrmData(tileId).catch((err) => showToast(err.message, true));
    }
    // Do not inject "Minimized — expand to load" hint here.
    // Hint is only shown on initial load for tiles that were *already* collapsed in persisted state.
  });
  sync();
  return btn;
}

function attachTileCollapseButton(tileEl, tileId) {
  const toolbar = tileEl.querySelector(":scope > .tile-toolbar, :scope > .group-tile-bar");
  if (!toolbar) return;
  if (toolbar.querySelector(".btn-collapse-tile")) return;
  const collapseBtn = createCollapseTileButton(tileEl, tileId);
  // Uniform right cluster: Refresh, Minimize, Close. Minimize goes inside
  // .tile-toolbar-actions, before the Close/remove button when present.
  const actions = toolbar.querySelector(":scope > .tile-toolbar-actions");
  if (actions) {
    const closeBtn = actions.querySelector(".btn-tile-remove");
    if (closeBtn) actions.insertBefore(collapseBtn, closeBtn);
    else actions.appendChild(collapseBtn);
    return;
  }
  const removeBtn = toolbar.querySelector(".btn-remove-group, .btn-remove-calendar, .btn-remove-notes, .tile-remove-icon");
  if (removeBtn && removeBtn.parentNode === toolbar) {
    toolbar.insertBefore(collapseBtn, removeBtn);
  } else {
    toolbar.appendChild(collapseBtn);
  }
}

function confirmDialog({ title, message, confirmLabel = "OK", danger = true }) {
  return new Promise((resolve) => {
    const modal = $("#confirm-modal");
    const titleEl = $("#confirm-modal-title");
    const msgEl = $("#confirm-modal-message");
    const okBtn = $("#confirm-modal-ok");
    const cancelBtn = $("#confirm-modal-cancel");
    if (!modal || !titleEl || !msgEl || !okBtn || !cancelBtn) {
      resolve(window.confirm(message));
      return;
    }

    titleEl.textContent = title;
    msgEl.textContent = message;
    okBtn.textContent = confirmLabel;
    okBtn.classList.toggle("btn-danger", danger);
    okBtn.classList.toggle("btn-primary", !danger);
    modal.classList.remove("hidden");

    const close = (result) => {
      modal.classList.add("hidden");
      okBtn.removeEventListener("click", onOk);
      cancelBtn.removeEventListener("click", onCancel);
      modal.querySelectorAll("[data-confirm-dismiss]").forEach((el) => {
        el.removeEventListener("click", onCancel);
      });
      document.removeEventListener("keydown", onKey);
      resolve(result);
    };

    const onOk = () => close(true);
    const onCancel = () => close(false);
    const onKey = (e) => {
      if (e.key === "Escape") onCancel();
    };

    okBtn.addEventListener("click", onOk);
    cancelBtn.addEventListener("click", onCancel);
    modal.querySelectorAll("[data-confirm-dismiss]").forEach((el) => {
      el.addEventListener("click", onCancel);
    });
    document.addEventListener("keydown", onKey);
    cancelBtn.focus();
  });
}

function showTempPasswordDialog(password, userId, userEmail) {
  const overlay = document.createElement("div");
  overlay.className = "modal-backdrop";
  overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:9999;display:flex;align-items:center;justify-content:center;";
  overlay.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:1.5rem;max-width:400px;width:90%;box-shadow:0 8px 32px rgba(0,0,0,0.3);">
      <h3 style="margin:0 0 0.75rem;font-size:1rem;">Temporary Password Generated</h3>
      <p style="font-size:0.85rem;color:var(--muted);margin:0 0 0.75rem;">Share this password with the user. They will be required to change it on first login.</p>
      <div style="display:flex;gap:0.5rem;align-items:center;margin-bottom:0.5rem;">
        <input type="text" value="${escapeHtml(password)}" readonly id="temp-pw-display"
          style="flex:1;padding:0.5rem;font-family:monospace;font-size:1.1rem;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:4px;" />
        <button type="button" id="temp-pw-copy" class="btn btn-secondary btn-sm" style="white-space:nowrap;">Copy</button>
      </div>
      <div style="display:flex; gap:0.3rem; margin-bottom:1rem;">
        <button type="button" id="temp-pw-send-email" class="btn btn-ghost btn-sm" style="flex:1;">Send via Email</button>
        <button type="button" id="temp-pw-send-telegram" class="btn btn-ghost btn-sm" style="flex:1;">Send via Telegram</button>
      </div>
      <div style="text-align:right;">
        <button type="button" id="temp-pw-close" class="btn btn-primary btn-sm">Done</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  const input = overlay.querySelector("#temp-pw-display");
  const copyBtn = overlay.querySelector("#temp-pw-copy");
  const closeBtn = overlay.querySelector("#temp-pw-close");
  const sendEmailBtn = overlay.querySelector("#temp-pw-send-email");
  const sendTelegramBtn = overlay.querySelector("#temp-pw-send-telegram");
  input.select();
  copyBtn.addEventListener("click", () => {
    navigator.clipboard.writeText(password).then(() => {
      copyBtn.textContent = "Copied!";
      setTimeout(() => { copyBtn.textContent = "Copy"; }, 2000);
    });
  });
  if (sendEmailBtn && userId) {
    sendEmailBtn.addEventListener("click", async () => {
      try {
        await api(`/api/v2/users/${userId}/reset-password/send`, { method: "POST", body: JSON.stringify({ method: "email", password }) });
        sendEmailBtn.textContent = "Sent!";
        sendEmailBtn.disabled = true;
      } catch (err) {
        showToast(err.message || "Failed to send email", true);
      }
    });
  }
  if (sendTelegramBtn && userId) {
    sendTelegramBtn.addEventListener("click", async () => {
      try {
        await api(`/api/v2/users/${userId}/reset-password/send`, { method: "POST", body: JSON.stringify({ method: "telegram", password }) });
        sendTelegramBtn.textContent = "Sent!";
        sendTelegramBtn.disabled = true;
      } catch (err) {
        showToast(err.message || "Failed to send via Telegram", true);
      }
    });
  }
  closeBtn.addEventListener("click", () => overlay.remove());
  overlay.addEventListener("click", (e) => { if (e.target === overlay) overlay.remove(); });
}

// ── Forgot Password flow ──────────────────────────────────────────────────
function initForgotPassword() {
  const link = $("#forgot-password-link");
  const loginForm = $("#login-form");
  const forgotSection = $("#forgot-section");
  const methodSection = $("#forgot-method-section");
  const telegramVerify = $("#forgot-telegram-verify");
  const emailSent = $("#forgot-email-sent");
  const newPwSection = $("#forgot-new-password");
  let forgotEmail = "";
  let forgotChallenge = "";

  function showLogin() {
    [loginForm, forgotSection, methodSection, telegramVerify, emailSent, newPwSection].forEach(el => { if (el) el.classList.add("hidden"); });
    loginForm?.classList.remove("hidden");
  }

  if (link) {
    link.addEventListener("click", (e) => {
      e.preventDefault();
      loginForm?.classList.add("hidden");
      forgotSection?.classList.remove("hidden");
    });
  }

  // Back buttons
  ["forgot-back-btn", "forgot-back-btn2", "forgot-back-btn3"].forEach(id => {
    $(`#${id}`)?.addEventListener("click", showLogin);
  });

  // Submit email
  $("#forgot-submit-btn")?.addEventListener("click", async () => {
    forgotEmail = $("#forgot-email")?.value.trim() || "";
    if (!forgotEmail) { showToast("Email is required", true); return; }
    try {
      const result = await api("/api/v2/auth/reset-request-telegram", { method: "POST", body: JSON.stringify({ email: forgotEmail }) });
      if (result.telegram) {
        forgotChallenge = result.challenge || "";
        forgotSection?.classList.add("hidden");
        methodSection?.classList.add("hidden");
        telegramVerify?.classList.remove("hidden");
      } else {
        // No Telegram linked, try email
        await api("/api/v2/auth/reset-request", { method: "POST", body: JSON.stringify({ email: forgotEmail }) });
        forgotSection?.classList.add("hidden");
        methodSection?.classList.add("hidden");
        emailSent?.classList.remove("hidden");
      }
    } catch (err) {
      showToast(err.message || "Failed to send reset", true);
    }
  });

  // Method selection
  $("#forgot-telegram-btn")?.addEventListener("click", async () => {
    try {
      const result = await api("/api/v2/auth/reset-request-telegram", { method: "POST", body: JSON.stringify({ email: forgotEmail }) });
      if (result.challenge) {
        forgotChallenge = result.challenge;
        methodSection?.classList.add("hidden");
        telegramVerify?.classList.remove("hidden");
      }
    } catch (err) {
      showToast(err.message || "Failed to send code", true);
    }
  });

  $("#forgot-email-btn")?.addEventListener("click", async () => {
    try {
      await api("/api/v2/auth/reset-request", { method: "POST", body: JSON.stringify({ email: forgotEmail }) });
      methodSection?.classList.add("hidden");
      emailSent?.classList.remove("hidden");
    } catch (err) {
      showToast(err.message || "Failed to send email", true);
    }
  });

  // Verify Telegram code
  $("#forgot-verify-btn")?.addEventListener("click", async () => {
    const code = $("#forgot-verify-code")?.value.trim() || "";
    if (!code) { showToast("Code is required", true); return; }
    try {
      const result = await api("/api/v2/auth/reset-verify-telegram", { method: "POST", body: JSON.stringify({ challenge: forgotChallenge, code }) });
      if (result.token) {
        forgotChallenge = result.token; // Store reset token
        telegramVerify?.classList.add("hidden");
        newPwSection?.classList.remove("hidden");
      }
    } catch (err) {
      showToast(err.message || "Invalid code", true);
    }
  });

  // Resend code
  $("#forgot-resend-btn")?.addEventListener("click", async () => {
    try {
      const result = await api("/api/v2/auth/reset-request-telegram", { method: "POST", body: JSON.stringify({ email: forgotEmail }) });
      if (result.challenge) forgotChallenge = result.challenge;
      showToast("Code resent");
    } catch (err) {
      showToast(err.message || "Failed to resend", true);
    }
  });

  // Set new password
  $("#forgot-set-pw-btn")?.addEventListener("click", async () => {
    const pw = $("#forgot-new-pw")?.value || "";
    const confirm = $("#forgot-confirm-pw")?.value || "";
    const errEl = $("#forgot-pw-error");
    if (pw.length < 6) { if (errEl) { errEl.textContent = "Password must be at least 6 characters"; errEl.classList.remove("hidden"); } return; }
    if (pw !== confirm) { if (errEl) { errEl.textContent = "Passwords do not match"; errEl.classList.remove("hidden"); } return; }
    if (errEl) errEl.classList.add("hidden");
    try {
      await api("/api/v2/auth/reset", { method: "POST", body: JSON.stringify({ token: forgotChallenge, password: pw }) });
      showToast("Password updated! Please sign in.");
      showLogin();
    } catch (err) {
      showToast(err.message || "Failed to reset password", true);
    }
  });
}

const TILE_ICON_WINDOW_RESTORE = `<svg class="tile-layout-icon" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="8" width="12" height="12" rx="1"/><rect x="8" y="4" width="12" height="12" rx="1"/></svg>`;

const TILE_ICON_WINDOW_MAXIMIZE = `<svg class="tile-layout-icon" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="1"/></svg>`;

const TILE_ICON_HEIGHT_EXPAND = `<svg class="tile-layout-icon" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v18"/><path d="m8 7 4-4 4 4"/><path d="m8 17 4 4 4-4"/></svg>`;

