const FEED_LOADING_SPINNER_HTML = `<svg class="feed-loading-spinner" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>`;

function setTileLayoutIconButton(btn, iconHtml, title) {
  btn.classList.add("tile-btn", "tile-btn-icon");
  btn.innerHTML = iconHtml;
  btn.title = title;
  btn.setAttribute("aria-label", title);
}

function createTileIconActionButton(iconHtml, title, extraClass = "") {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = `btn btn-ghost tile-btn tile-btn-icon ${extraClass}`.trim();
  setTileLayoutIconButton(btn, iconHtml, title);
  return btn;
}

function createTileRemoveButton(title, extraClass = "") {
  return createTileIconActionButton(TILE_ICON_REMOVE, title, `btn-tile-remove ${extraClass}`.trim());
}

/** Standard toolbar shell: tile-specific buttons go in .tile-toolbar-tools
 *  (middle, wraps to row 2 on narrow tiles/mobile), while Refresh/Minimize/Close
 *  live in .tile-toolbar-actions (always pinned top-right). */
function buildTileToolbarShell() {
  const tools = document.createElement("div");
  tools.className = "tile-toolbar-tools";
  const actions = document.createElement("div");
  actions.className = "tile-toolbar-actions";
  return { tools, actions };
}

/** Click-to-edit tile title. The display span is content-sized; the input only
 *  appears while editing and sizes itself to the text (ch units), so neither
 *  ever pushes toolbar buttons onto another row (ISSUE-014).
 *  Enter/blur saves, Escape reverts (via blur with the restored value). */
function makeTileTitleEditable({ displayEl, inputEl, getName, setName, placeholder = "Tile label" }) {
  const syncInputWidth = () => {
    inputEl.style.width = `${Math.max(6, (inputEl.value || "").length + 2)}ch`;
  };
  const start = () => {
    inputEl.value = getName() || "";
    displayEl.style.display = "none";
    inputEl.style.display = "";
    syncInputWidth();
    inputEl.focus();
    inputEl.select();
  };
  const finish = (save) => {
    if (save) setName(inputEl.value.trim());
    displayEl.textContent = getName() || placeholder;
    displayEl.style.display = "";
    inputEl.style.display = "none";
  };
  displayEl.title = "Click to rename";
  displayEl.addEventListener("click", (e) => { e.stopPropagation(); start(); });
  inputEl.addEventListener("input", syncInputWidth);
  inputEl.addEventListener("blur", () => finish(true));
  inputEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter") { e.preventDefault(); inputEl.blur(); }
    else if (e.key === "Escape") { inputEl.value = getName() || ""; inputEl.blur(); }
  });
}

function closeAllTileMenus() {
  document.querySelectorAll(".tile-menu").forEach((menu) => menu.classList.add("hidden"));
  document.querySelectorAll(".tile-menu-trigger").forEach((trigger) => {
    trigger.setAttribute("aria-expanded", "false");
  });
}

function bindTileMenuDismiss() {
  if (document.body.dataset.tileMenuDismissBound) return;
  document.body.dataset.tileMenuDismissBound = "1";
  document.addEventListener("click", () => closeAllTileMenus());
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeAllTileMenus();
  });
}

function createTileMenu({ label, className = "", items }) {
  bindTileMenuDismiss();
  const wrap = document.createElement("div");
  wrap.className = "tile-menu-wrap";
  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = `btn btn-ghost tile-menu-trigger ${className}`.trim();
  trigger.textContent = label;
  trigger.setAttribute("aria-haspopup", "true");
  trigger.setAttribute("aria-expanded", "false");
  const menu = document.createElement("div");
  menu.className = "tile-menu hidden";
  menu.setAttribute("role", "menu");
  for (const item of items) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "tile-menu-item";
    if (item.danger) row.classList.add("tile-menu-item--danger");
    row.textContent = item.label;
    row.setAttribute("role", "menuitem");
    row.addEventListener("click", (e) => {
      e.stopPropagation();
      closeAllTileMenus();
      item.onSelect();
    });
    menu.appendChild(row);
  }
  wrap.appendChild(trigger);
  wrap.appendChild(menu);
  trigger.addEventListener("click", (e) => {
    e.stopPropagation();
    const willOpen = menu.classList.contains("hidden");
    closeAllTileMenus();
    if (willOpen) {
      menu.classList.remove("hidden");
      trigger.setAttribute("aria-expanded", "true");
    }
  });
  menu.addEventListener("click", (e) => e.stopPropagation());
  return wrap;
}

function createLayoutButtons({ showDoubleHeight = true, showQuarterWidth = false, showFullWidth = true } = {}) {
  const wrap = document.createElement("div");
  wrap.className = "tile-layout-btns";

  let quarterBtn = null;
  if (showQuarterWidth) {
    quarterBtn = document.createElement("button");
    quarterBtn.type = "button";
    setTileLayoutIconButton(quarterBtn, TILE_ICON_WINDOW_QUARTER, "Quarter width (1/4)");
    wrap.appendChild(quarterBtn);
  }

  const halfBtn = document.createElement("button");
  halfBtn.type = "button";
  setTileLayoutIconButton(halfBtn, TILE_ICON_WINDOW_RESTORE, "Half width (1/2)");

  const fullBtn = document.createElement("button");
  fullBtn.type = "button";
  fullBtn.dataset.layout = "full";
  setTileLayoutIconButton(fullBtn, TILE_ICON_WINDOW_MAXIMIZE, "Full width");

  wrap.appendChild(halfBtn);
  if (showFullWidth) {
    wrap.appendChild(fullBtn);
  }

  let tallBtn = null;
  if (showDoubleHeight) {
    tallBtn = document.createElement("button");
    tallBtn.type = "button";
    tallBtn.className = "btn-tile-tall";
    setTileLayoutIconButton(tallBtn, TILE_ICON_HEIGHT_EXPAND, "Double tile height (two grid rows)");
    wrap.appendChild(tallBtn);
  }
  return { wrap, quarterBtn, halfBtn, fullBtn: showFullWidth ? fullBtn : null, tallBtn };
}

function bindTileLayoutButtons(tileEl, tileId, halfBtn, fullBtn, tallBtn, quarterBtn = null) {
  const syncTileLayout = () => {
    const w = tileWidth(tileId);
    const h = tileHeight(tileId);
    if (quarterBtn) quarterBtn.classList.toggle("tile-btn-active", w === "quarter");
    halfBtn.classList.toggle("tile-btn-active", w === "half");
    if (fullBtn) fullBtn.classList.toggle("tile-btn-active", w === "full");
    if (tallBtn) tallBtn.classList.toggle("tile-btn-active", h >= 2);
    applyTileLayoutClasses(tileEl, tileId);
    if (tileId === "tile-tasks") renderTasksContent();
    if (PANEL_TILE_IDS.has(tileId)) syncPanelRowLayout();
  };
  quarterBtn?.addEventListener("click", (e) => {
    e.stopPropagation();
    setTileWidth(tileId, "quarter");
    syncTileLayout();
  });
  halfBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    setTileWidth(tileId, "half");
    syncTileLayout();
  });
  fullBtn?.addEventListener("click", (e) => {
    e.stopPropagation();
    setTileWidth(tileId, "full");
    syncTileLayout();
  });
  if (tallBtn) {
    tallBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const cur = tileHeight(tileId);
      setTileHeight(tileId, cur >= 2 ? 1 : 2);
      syncTileLayout();
    });
  }
  syncTileLayout();
  return syncTileLayout;
}

function createTileChrome(tileId, label) {
  const toolbar = document.createElement("div");
  toolbar.className = "tile-toolbar";
  toolbar.dataset.tileId = tileId;

  const hint = document.createElement("span");
  hint.className = "tile-drag-hint";
  hint.textContent = "⋮⋮";
  hint.setAttribute("aria-hidden", "true");
  hint.title = "Drag to reorder";

  const name = document.createElement("span");
  name.className = "tile-toolbar-title";
  name.textContent = label;

  const countBadge = document.createElement("span");
  countBadge.className = "tile-toolbar-count";
  countBadge.dataset.tileCountFor = tileId;
  countBadge.textContent = "(0)";

  const { tools, actions } = buildTileToolbarShell();

  toolbar.appendChild(hint);
  toolbar.appendChild(name);
  toolbar.appendChild(countBadge);
  toolbar.appendChild(tools);
  toolbar.appendChild(actions);

  return { toolbar };
}

function updatePanelTileCount(tileId, count) {
  document.querySelectorAll(`[data-tile-count-for="${tileId}"]`).forEach((el) => {
    el.textContent = `(${count})`;
  });
}

function bindTileChrome(tileEl, tileId) {
  if (!tileEl.querySelector(":scope > .tile-toolbar")) {
    const { toolbar } = createTileChrome(tileId, tileEl.dataset.tileLabel || "Section");
    tileEl.prepend(toolbar);
    wrapTileBodyContent(tileEl);
    bindTileDragDrop(tileEl, tileId, toolbar);
  }
  attachTileCollapseButton(tileEl, tileId);
  applyTileBodyCollapsed(tileEl, tileId);
  addResizeHandles(tileEl, tileId);
  if (isAutoRefreshTileId(tileId)) ensureTileAutoRefreshButton(tileEl, tileId);
  if (tileId === "tile-feed") ensureFeedHiddenToolbarButton(tileEl);
  if (tileId === "tile-tasks") ensureTasksNewTaskButton(tileEl);
}

function wrapTileBodyContent(tileEl) {
  if (tileEl.querySelector(":scope > .tile-body-content")) return;
  const toolbar = tileEl.querySelector(":scope > .tile-toolbar");
  if (!toolbar) return;
  const children = [...tileEl.children].filter(c => c !== toolbar && !c.classList.contains('tile-body-content') && !c.classList.contains('tile-resize-handle'));
  if (!children.length) return;
  const wrapper = document.createElement('div');
  wrapper.className = 'tile-body-content';
  children.forEach(c => wrapper.appendChild(c));
  tileEl.appendChild(wrapper);
}

function bindTileDragDrop(tileEl, tileId, toolbar) {
  if (tileEl.dataset.dragBound === "1") return;
  tileEl.dataset.dragBound = "1";
  const h = toolbar.querySelector(".tile-drag-hint");
  if (h) h.classList.remove("hidden");
}

function isTilePinned(tileId) {
  if (!state.tileLayout.pinned) state.tileLayout.pinned = {};
  return !!state.tileLayout.pinned[tileId];
}

function setTilePinned(tileId, pinned) {
  if (!state.tileLayout.pinned) state.tileLayout.pinned = {};
  if (pinned) state.tileLayout.pinned[tileId] = true;
  else delete state.tileLayout.pinned[tileId];
  saveLayoutToStorage();
}

function applyTilePinState(tileEl, tileId) {
  // Pin functionality disabled
}

function bindTilePinButton(tileEl, tileId, pinBtn) {
  // Pin functionality disabled
}

function addResizeHandles(tileEl, tileId) {
  if (tileEl.querySelector(":scope > .tile-resize-handle")) return;
  if (isTilePinnedToTop(tileId)) return;

  const se = document.createElement("div");
  se.className = "tile-resize-handle tile-resize-se";
  se.title = "Drag to resize";
  tileEl.appendChild(se);

  const sw = document.createElement("div");
  sw.className = "tile-resize-handle tile-resize-sw";
  sw.title = "Drag to resize";
  tileEl.appendChild(sw);

  bindTileResize(tileEl, tileId, se, "se");
  bindTileResize(tileEl, tileId, sw, "sw");
}

function bindTileResize(tileEl, tileId, handle, corner) {
  // ISSUE-013: the old implementation committed span classes + localStorage on
  // every mousemove and re-measured the (just-reflowed) grid each event, so the
  // whole board jumped during a drag. Now: measure ONCE at pointerdown, move a
  // ghost preview during the drag, and commit span + storage exactly once on
  // pointerup. The grid never changes mid-gesture, so cached metrics stay valid.
  let startX, startY, startSpanCols, colWidth, gapWidth, gridContentWidth, rowUnit;
  let baseLeft, baseTop, baseWidth, baseHeight;
  let startHeightName, pendingHeight;
  let ghost = null;
  let pendingWidth = null;
  let singleRowH; /* actual single-row height derived from rendered tile */

  const spanColsForWidth = (name) => (name === "quarter" ? 1 : name === "half" ? 2 : name === "three" ? 3 : 4);
  const widthForSpanCols = (span) => (span <= 1 ? "quarter" : span === 2 ? "half" : span === 3 ? "three" : "full");

  const positionGhost = (spanCols, heightName) => {
    if (!ghost) return;
    let widthPx = spanCols * colWidth + (spanCols - 1) * gapWidth;
    // se grows rightward from the tile's left edge; sw grows leftward with the
    // right edge anchored.
    let left = corner === "se" ? baseLeft : baseLeft + baseWidth - widthPx;
    // Keep the preview inside the grid's content box — an overflowing ghost
    // could force a horizontal page scrollbar mid-drag.
    left = Math.max(0, Math.min(left, gridContentWidth));
    widthPx = Math.min(widthPx, gridContentWidth - left);
    // Height preview: use singleRowH × rows for accurate multi-row sizing.
    const rows = typeof heightName === "number" ? heightName : (heightName === "double" ? 2 : 1);
    const heightPx = singleRowH * rows + gapWidth * Math.max(0, rows - 1);
    ghost.style.top = `${baseTop}px`;
    ghost.style.left = `${left}px`;
    ghost.style.width = `${widthPx}px`;
    ghost.style.height = `${heightPx}px`;
  };

  const onPointerDown = (e) => {
    if (e.button && e.button !== 0) return;
    e.preventDefault();
    e.stopPropagation();

    const grid = tileEl.parentElement;
    if (!grid) return;

    // Measure once. offset* is relative to the grid (position: relative) and is
    // unaffected by page scroll during the gesture.
    const gridStyle = getComputedStyle(grid);
    const tracks = (gridStyle.gridTemplateColumns || "").split(" ").filter(Boolean);
    colWidth = parseFloat(tracks[0]) || tileEl.offsetWidth;
    gapWidth = parseFloat(gridStyle.columnGap || gridStyle.gap) || 0;
    gridContentWidth = tracks.length * colWidth + Math.max(0, tracks.length - 1) * gapWidth;
    baseLeft = tileEl.offsetLeft;
    baseTop = tileEl.offsetTop;
    baseWidth = tileEl.offsetWidth;
    baseHeight = tileEl.offsetHeight;

    startX = e.clientX;
    startY = e.clientY;
    startSpanCols = spanColsForWidth(tileWidth(tileId));
    pendingWidth = tileWidth(tileId);
    startHeightName = tileHeight(tileId);
    pendingHeight = startHeightName;
    rowUnit = parseFloat(gridStyle.getPropertyValue("--tile-row-height")) || 400;
    /* Use the CSS variable for single-row height — the rendered tile may be
       oversized (e.g., group tiles with filter header), which would throw off
       the ghost preview and resize snap calculations. */
    singleRowH = rowUnit;

    ghost = document.createElement("div");
    ghost.className = "tile-resize-ghost";
    grid.appendChild(ghost);
    positionGhost(startSpanCols, startHeightName);

    handle.setPointerCapture?.(e.pointerId);
    document.addEventListener("pointermove", onPointerMove, { passive: false });
    document.addEventListener("pointerup", onPointerUp);
    document.addEventListener("pointercancel", onPointerUp);
    tileEl.classList.add("tile-resizing");
  };

  const onPointerMove = (e) => {
    e.preventDefault();
    const step = colWidth + gapWidth;
    if (!step) return;
    const dx = (e.clientX || 0) - startX;
    // Span N width = N*step - gap  →  N = (width + gap) / step
    const currentSpanWidth = startSpanCols * step - gapWidth;
    const stretched = corner === "se" ? currentSpanWidth + dx : currentSpanWidth - dx;
    let newSpan = Math.round((stretched + gapWidth) / step);
    newSpan = Math.max(1, Math.min(4, newSpan));

    pendingWidth = widthForSpanCols(newSpan);

    // Vertical decision based on pointer position relative to grid rows.
    // Continuous row count: drag down to add rows, up to remove.
    // Skipped while collapsed.
    if (!tileBodyCollapsed(tileId)) {
      const pointerY = (e.clientY || 0);
      const dy = pointerY - startY;
      const rowStep = singleRowH + gapWidth;
      if (Math.abs(dy) > 30) {
        const startRows = typeof startHeightName === "number" ? startHeightName : 1;
        const rowsDelta = Math.round(dy / rowStep);
        pendingHeight = Math.max(1, Math.min(8, startRows + rowsDelta));
      }
    }
    positionGhost(newSpan, pendingHeight);
  };

  const onPointerUp = () => {
    document.removeEventListener("pointermove", onPointerMove);
    document.removeEventListener("pointerup", onPointerUp);
    document.removeEventListener("pointercancel", onPointerUp);
    tileEl.classList.remove("tile-resizing");
    if (ghost) {
      ghost.remove();
      ghost = null;
    }
    // Commit exactly once, on release (one localStorage write per changed
    // dimension + one debounced profile save) — and only if something changed.
    const wChanged = pendingWidth && pendingWidth !== tileWidth(tileId);
    const hChanged = pendingHeight && pendingHeight !== tileHeight(tileId);
    if (wChanged) setTileWidth(tileId, pendingWidth);
    if (hChanged) setTileHeight(tileId, pendingHeight);
    if (wChanged || hChanged) applyTileLayoutClasses(tileEl, tileId);
    pendingWidth = null;
    pendingHeight = null;
  };

  handle.addEventListener("pointerdown", onPointerDown);
}

function loadGroupTemplates() {
  try {
    const raw = localStorage.getItem(GROUP_TEMPLATES_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed;
    }
  } catch {
    /* ignore */
  }
  return [];
}

function saveGroupTemplatesToStorage() {
  localStorage.setItem(GROUP_TEMPLATES_STORAGE_KEY, JSON.stringify(state.groupTemplates));
  scheduleUserProfileSave();
}

function openTemplateDeleteModal() {
  const modal = $("#template-delete-modal");
  const listEl = $("#template-delete-list");
  if (!modal || !listEl) return;

  const renderList = () => {
    listEl.innerHTML = "";
    if (!state.groupTemplates || !state.groupTemplates.length) {
      listEl.innerHTML = '<p class="modal-message">No templates saved.</p>';
      return;
    }
    state.groupTemplates.forEach((tpl, idx) => {
      const row = document.createElement("div");
      row.className = "template-delete-row";
      row.innerHTML = `
        <span class="template-delete-name">${escapeHtml(tpl.name)}</span>
        <button type="button" class="btn btn-ghost btn-delete-tpl" title="Delete template" aria-label="Delete">×</button>
      `;
      const delBtn = row.querySelector(".btn-delete-tpl");
      delBtn.addEventListener("click", () => {
        if (!confirm(`Delete template “${tpl.name}”?`)) return;
        state.groupTemplates.splice(idx, 1);
        saveGroupTemplatesToStorage();
        renderBoardGroups(); // refresh selects in groups
        renderList(); // refresh this list
        showToast("Template deleted");
      });
      listEl.appendChild(row);
    });
  };

  renderList();

  // bind dismiss if not already
  if (!modal.dataset.bound) {
    modal.dataset.bound = "1";
    $("#template-delete-close")?.addEventListener("click", () => modal.classList.add("hidden"));
    modal.querySelectorAll("[data-template-delete-dismiss]").forEach((el) => {
      el.addEventListener("click", () => modal.classList.add("hidden"));
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && !modal.classList.contains("hidden")) {
        modal.classList.add("hidden");
      }
    });
  }

  modal.classList.remove("hidden");
}

function groupConfigSnapshot(group) {
  return JSON.parse(JSON.stringify(stripGroupRuntimeFields(group)));
}

function applyGroupTemplate(group, template) {
  const cfg = stripGroupRuntimeFields(template.config || template);
  const keep = { id: group.id, opportunities: group.opportunities || [], _el: groupDomEl(group) };
  Object.assign(group, newGroup(), cfg, keep);
  const el = groupDomEl(group);
  if (el) {
    el.dataset.tileLabel = group.name || "Project group";
    if (group._syncNameDisplay) group._syncNameDisplay();
    else {
      const nameInput = $(".group-tile-name-input", el);
      if (nameInput) nameInput.value = group.name;
    }
    updateGroupFilterSummary(group);
  }
}

function bindGroupTileChrome(section, group, tileId) {
  if (section.querySelector(":scope > .group-tile-bar")) return;

  const toolbar = document.createElement("div");
  toolbar.className = "tile-toolbar group-tile-bar";
  toolbar.dataset.tileId = tileId;

  const hint = document.createElement("span");
  hint.className = "tile-drag-hint";
  hint.textContent = "⋮⋮";
  hint.setAttribute("aria-hidden", "true");
  hint.title = "Drag to reorder (left/right or up/down)";

  // --- Click-to-edit title (no pencil button — click the title itself) ---
  const nameDisplay = document.createElement("span");
  nameDisplay.className = "group-tile-name-display";
  nameDisplay.textContent = group.name || "Project group";

  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.className = "group-tile-name-input";
  nameInput.placeholder = "Group label";
  nameInput.value = group.name || "";
  nameInput.setAttribute("aria-label", "Group label");
  nameInput.style.display = "none";

  makeTileTitleEditable({
    displayEl: nameDisplay,
    inputEl: nameInput,
    getName: () => group.name,
    setName: (v) => {
      group.name = v || "New group";
      section.dataset.tileLabel = group.name;
      saveGroupsToStorage();
    },
    placeholder: "Project group",
  });

  const countEl = document.createElement("span");
  countEl.className = "group-tile-count board-group-count";
  countEl.textContent = "0 deals";

  const summaryCompactBar = document.createElement("span");
  summaryCompactBar.className = "group-filter-summary-compact";
  summaryCompactBar.textContent = groupFilterSummary(group);

  const countAndSummary = document.createElement("span");
  countAndSummary.className = "group-tile-count-summary";
  countAndSummary.appendChild(countEl);
  countAndSummary.appendChild(summaryCompactBar);

  // --- Filter icon toggle ---
  const toggleFiltersBtn = document.createElement("button");
  toggleFiltersBtn.type = "button";
  toggleFiltersBtn.className = "btn btn-ghost tile-btn tile-btn-icon btn-toggle-filters";
  toggleFiltersBtn.setAttribute("aria-expanded", "true");

  // --- Template popover ---
  const templateBtn = document.createElement("button");
  templateBtn.type = "button";
  templateBtn.className = "btn btn-ghost tile-btn tile-btn-icon btn-template-menu";
  setTileLayoutIconButton(templateBtn, TILE_ICON_TEMPLATE, "Templates");

  const templateDropdown = document.createElement("div");
  templateDropdown.className = "template-dropdown hidden";

  const renderTemplateDropdown = () => {
    templateDropdown.innerHTML = "";

    // Save current
    const saveItem = document.createElement("button");
    saveItem.type = "button";
    saveItem.className = "template-dropdown-item";
    saveItem.innerHTML = `<span class="template-dropdown-icon">${TILE_ICON_SAVE}</span> Save current as template`;
    saveItem.addEventListener("click", (e) => {
      e.stopPropagation();
      templateDropdown.classList.add("hidden");
      const name = prompt("Template name", group.name || "My filters");
      if (!name?.trim()) return;
      const tpl = { id: newId(), name: name.trim(), config: groupConfigSnapshot(group) };
      state.groupTemplates.push(tpl);
      saveGroupTemplatesToStorage();
      renderBoardGroups();
      showToast(`Saved template "${tpl.name}"`);
    });
    templateDropdown.appendChild(saveItem);

    // Divider + template list
    const divider1 = document.createElement("div");
    divider1.className = "template-dropdown-divider";
    templateDropdown.appendChild(divider1);

    if (state.groupTemplates.length) {
      for (const t of state.groupTemplates) {
        const item = document.createElement("button");
        item.type = "button";
        item.className = "template-dropdown-item";
        item.textContent = t.name;
        item.addEventListener("click", (e) => {
          e.stopPropagation();
          templateDropdown.classList.add("hidden");
          applyGroupTemplate(group, t);
          saveGroupsToStorage();
          renderBoardGroups();
          refreshGroup(group).catch((err) => showToast(err.message, true));
          showToast(`Applied template "${t.name}"`);
        });
        templateDropdown.appendChild(item);
      }
    } else {
      const empty = document.createElement("div");
      empty.className = "template-dropdown-item";
      empty.style.color = "var(--muted)";
      empty.style.cursor = "default";
      empty.textContent = "No templates saved";
      templateDropdown.appendChild(empty);
    }

    // Divider + delete
    const divider2 = document.createElement("div");
    divider2.className = "template-dropdown-divider";
    templateDropdown.appendChild(divider2);

    const deleteItem = document.createElement("button");
    deleteItem.type = "button";
    deleteItem.className = "template-dropdown-item template-dropdown-item--danger";
    deleteItem.innerHTML = `<span class="template-dropdown-icon">${TILE_ICON_TRASH}</span> Delete templates…`;
    if (!state.groupTemplates.length) {
      deleteItem.style.opacity = "0.4";
      deleteItem.style.pointerEvents = "none";
    }
    deleteItem.addEventListener("click", (e) => {
      e.stopPropagation();
      templateDropdown.classList.add("hidden");
      openTemplateDeleteModal();
    });
    templateDropdown.appendChild(deleteItem);
  };

  templateBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    renderTemplateDropdown();
    templateDropdown.classList.toggle("hidden");
    if (!templateDropdown.classList.contains("hidden")) {
      const close = (ev) => {
        if (!templateDropdown.contains(ev.target) && ev.target !== templateBtn) {
          templateDropdown.classList.add("hidden");
          document.removeEventListener("click", close);
        }
      };
      setTimeout(() => document.addEventListener("click", close), 0);
    }
  });

  const removeBtn = createTileRemoveButton("Remove this grouping from the board", "btn-remove-group");

  const { actions } = buildTileToolbarShell();
  actions.appendChild(removeBtn);

  toolbar.appendChild(hint);
  toolbar.appendChild(nameDisplay);
  toolbar.appendChild(nameInput);
  toolbar.appendChild(toggleFiltersBtn);
  toolbar.appendChild(templateBtn);
  toolbar.appendChild(templateDropdown);
  toolbar.appendChild(countAndSummary);
  toolbar.appendChild(actions);

  section.prepend(toolbar);
  wrapTileBodyContent(section);
  bindTileDragDrop(section, tileId, toolbar);
  attachTileCollapseButton(section, tileId);
  addResizeHandles(section, tileId);

  const setFiltersCollapsed = (collapsed) => {
    group.filtersCollapsed = collapsed;
    section.classList.toggle("filters-collapsed", collapsed);
    toggleFiltersBtn.setAttribute("aria-expanded", String(!collapsed));
    toggleFiltersBtn.innerHTML = collapsed ? TILE_ICON_FILTER : TILE_ICON_FILTER_FILLED;
    toggleFiltersBtn.title = collapsed ? "Show filters" : "Hide filters";
    saveGroupsToStorage();
  };
  setFiltersCollapsed(!!group.filtersCollapsed);
  toggleFiltersBtn.addEventListener("click", () => setFiltersCollapsed(!group.filtersCollapsed));

  removeBtn.addEventListener("click", async () => {
    if (state.groups.length <= 1) {
      showToast("Keep at least one group", true);
      return;
    }
    const label = group.name?.trim() || "this group";
    const ok = await confirmDialog({
      title: "Remove grouping?",
      message: `Remove "${label}" from the board? This cannot be undone.`,
      confirmLabel: "Remove",
      danger: true,
    });
    if (!ok) return;
    const tid = `group-${group.id}`;
    state.groups = state.groups.filter((g) => g.id !== group.id);
    state.tileLayout.order = state.tileLayout.order.filter((id) => id !== tid);
    delete state.tileLayout.widths[tid];
    delete state.tileLayout.heights[tid];
    saveGroupsToStorage();
    saveLayoutToStorage();
    saveUserProfileToServer({ quiet: true }).catch(() => {});
    renderBoardGroups();
  });

  group._setFiltersCollapsed = setFiltersCollapsed;
  group._syncNameDisplay = () => {
    nameDisplay.textContent = group.name || "Project group";
    nameInput.value = group.name || "";
    section.dataset.tileLabel = group.name || "Project group";
  };
}

function mountDashboardTiles() {
  const root = $("#dashboard-tiles");
  if (!root) return;
  ensureTileLayout();

  if (state.tileLayout.order.includes("tile-presence") && !document.querySelector('[data-tile-id="tile-presence"]')) {
    renderPresenceTile();
  }

  const nodes = collectDashboardTileNodes();
  const known = new Set(state.tileLayout.order);

  // Reorder in place — appendChild MOVES an already-attached node, preserving
  // event listeners, scroll positions, and iframe contents. No innerHTML=""
  // teardown (ISSUE-013).
  for (const tileId of state.tileLayout.order) {
    const node = nodes.get(tileId);
    if (!node) continue;
    root.appendChild(node);
    applyTileLayoutClasses(node, tileId);
    applyTileBodyCollapsed(node, tileId);
  }

  // Sweep stray tiles whose id is no longer in the layout (e.g. deleted groups),
  // plus any orphaned resize ghosts.
  for (const child of [...root.children]) {
    if (child.classList?.contains("tile-resize-ghost")) {
      child.remove();
    } else if (child.dataset?.tileId && !known.has(child.dataset.tileId)) {
      child.remove();
    }
  }

  // Create the Sortable instance ONCE. It binds to the container, not the
  // children, so external reorders via appendChild are fine.
  // forceFallback: false → native drag keeps the tile inside the grid flow, so
  // neighbours shift predictably instead of a detached clone floating over a
  // grid that holds the real tile in place (ISSUE-013).
  if (typeof Sortable !== "undefined" && !root._sortableInstance) {
    root._sortableInstance = Sortable.create(root, {
      animation: 200,
      handle: ".tile-drag-hint",
      ghostClass: "sortable-ghost",
      chosenClass: "sortable-chosen",
      dragClass: "sortable-drag",
      forceFallback: false,
      onEnd: (evt) => {
        const order = [];
        root.querySelectorAll(":scope > .dashboard-tile[data-tile-id]").forEach((el) => {
          order.push(el.dataset.tileId);
        });
        state.tileLayout.order = order;
        saveLayoutToStorage();
      }
    });
  }
}

function renderFeedTile() {
  const tileId = "tile-feed";
  let tile = document.querySelector(`[data-tile-id="${tileId}"]`);
  if (!tile) {
    tile = document.createElement("section");
    tile.className = "dashboard-tile panel feed-panel";
    tile.dataset.tileId = tileId;
    tile.dataset.tileLabel = "CRM notifications";
    tile.innerHTML = `
      <div class="panel-header panel-header-feed">
        <input type="search" id="feed-keyword-filter" class="feed-keyword-filter" placeholder="${escapeHtml(feedFilterPlaceholder())}" autocomplete="off" />
        <span class="feed-loading-indicator hidden" title="Loading notifications" aria-label="Loading notifications">${FEED_LOADING_SPINNER_HTML}</span>
        <span class="panel-sub feed-range-hint">Last ${FEED_DAYS} days</span>
      </div>
      <ul id="notification-feed" class="feed-list" aria-live="polite"></ul>
    `;
    $("#dashboard-tiles")?.appendChild(tile);
    bindTileChrome(tile, tileId);
    bindFeedInfiniteScroll();
    const kw = $("#feed-keyword-filter", tile);
    if (kw) {
      kw.value = state.feedKeywordFilter || "";
      kw.addEventListener("input", () => {
        state.feedKeywordFilter = kw.value;
        saveFeedKeywordToStorage();
        renderFeedNotificationList();
      });
    }
  }
  applyTileLayoutClasses(tile, tileId);
  ensureTileAutoRefreshButton(tile, tileId);
  ensureFeedHiddenToolbarButton(tile);
  syncFeedFilterPlaceholder();
  const kw = $("#feed-keyword-filter", tile);
  if (kw) {
    kw.value = state.feedKeywordFilter || "";
    if (!kw.dataset.bound) {
      kw.dataset.bound = "1";
      kw.addEventListener("input", () => {
        state.feedKeywordFilter = kw.value;
        saveFeedKeywordToStorage();
        renderFeedNotificationList();
      });
    }
  }
  bindFeedInfiniteScroll();
  return tile;
}

function renderTasksTile() {
  const tileId = "tile-tasks";
  let tile = document.querySelector(`[data-tile-id="${tileId}"]`);
  if (!tile) {
    tile = document.createElement("section");
    tile.className = "dashboard-tile panel tasks-panel";
    tile.dataset.tileId = tileId;
    tile.dataset.tileLabel = "Tasks";
    tile.innerHTML = `
      <div class="tasks-tabs" role="tablist" aria-label="Task lists">
        <button type="button" class="tasks-tab" data-tasks-tab="todos" role="tab">Todo <span class="tasks-tab-count">0</span></button>
        <button type="button" class="tasks-tab" data-tasks-tab="project" role="tab">Project Tasks <span class="tasks-tab-count">0</span></button>
      </div>
      <div class="tasks-quick-add">
        <input type="text" id="tasks-quick-add-input" placeholder="Add a todo, press Enter" autocomplete="off" />
      </div>
      <div id="tasks-by-user" class="tasks-by-user"></div>
    `;
    $("#dashboard-tiles")?.appendChild(tile);
    bindTileChrome(tile, tileId);
    // Drop the "Tasks" title + counter from the title bar (tabs carry the counts),
    // then move the list tabs up into the title bar at the front.
    const tasksToolbar = tile.querySelector(":scope > .tile-toolbar");
    if (tasksToolbar) {
      tasksToolbar.querySelector(".tile-toolbar-title")?.remove();
      tasksToolbar.querySelector(".tile-toolbar-count")?.remove();
      const tasksTabsEl = tile.querySelector(".tasks-tabs");
      if (tasksTabsEl) {
        const tasksHint = tasksToolbar.querySelector(".tile-drag-hint");
        if (tasksHint && tasksHint.nextSibling) {
          tasksToolbar.insertBefore(tasksTabsEl, tasksHint.nextSibling);
        } else {
          tasksToolbar.appendChild(tasksTabsEl);
        }
      }
    }
  }
  applyTileLayoutClasses(tile, tileId);
  ensureTileAutoRefreshButton(tile, tileId);
  ensureTasksNewTaskButton(tile);
  ensureTasksColumnsButton(tile);
  if (tile && !tile.dataset.tasksTabBound) {
    tile.dataset.tasksTabBound = "1";
    tile.querySelectorAll(".tasks-tab").forEach((btn) => {
      btn.addEventListener("click", () => {
        state.tasksTab = btn.dataset.tasksTab;
        renderTasksContent();
      });
    });
    const quickAdd = $("#tasks-quick-add-input", tile);
    if (quickAdd) {
      quickAdd.addEventListener("keydown", async (e) => {
        if (e.key !== "Enter") return;
        const title = quickAdd.value.trim();
        if (!title) return;
        quickAdd.value = "";
        try {
          await createTask({ title, opportunityId: null });
          showToast(`Added “${title}”`);
          confettiBurst(quickAdd);
        } catch (err) {
          showToast(err.message, true);
        }
      });
    }
  }
  return tile;
}

function refreshDashboardTileLayouts() {
  document.querySelectorAll(".dashboard-tile[data-tile-id]").forEach((el) => {
    const id = el.dataset.tileId;
    attachTileCollapseButton(el, id);
    applyTileBodyCollapsed(el, id);
    if (tileBodyCollapsed(id) && isCrmDataTileId(id)) {
      const msg =
        id === "tile-feed"
          ? "Minimized — expand to load notifications"
          : id === "tile-tasks"
            ? "Minimized — expand to load tasks"
            : id.startsWith("calendar-")
              ? "Minimized — expand to load calendar"
              : "Minimized — expand to load deals";
      showTileCollapsedHint(id, msg);
    }
  });
}

function parseApiError(body, status) {
  if (typeof body === "string") {
    if (/<!DOCTYPE\s+html|<html[\s>]/i.test(body)) {
      const clean = body.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
      return clean.slice(0, 200) || `CRM returned an HTML error page (HTTP ${status})`;
    }
    try {
      body = JSON.parse(body);
    } catch {
      return body.slice(0, 300) || `HTTP ${status}`;
    }
  }
  if (body?.message) return String(body.message);
  if (body?.error?.message) return String(body.error.message);
  if (body?.error) {
    const e = typeof body.error === "string" ? body.error : JSON.stringify(body.error);
    const st2 = Number(body.status || status) || 0;
    if (/unreachable|CRM unreachable/i.test(e) || st2 === 502 || st2 === 503 || st2 === 504) {
      return `Failed to reach server${st2 ? ` (HTTP ${st2})` : ""}. Check your connection or try again.`;
    }
    return e;
  }
  if (body?.detail) return typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail);
  const st = Number(status) || 0;
  if (st === 502 || st === 503 || st === 504) return `Failed to reach server (HTTP ${st}). Check your connection or try again.`;
  return `HTTP ${status}`;
}

async function api(path, options = {}) {
  const headers = { Accept: "application/json", ...options.headers };
  const maxRetries = options._retryCount != null ? options._retryCount : 3;
  const isMutation = options.method && options.method !== "GET" && options.method !== "HEAD";

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    let res;
    try {
      res = await fetch(path, {
        ...options,
        headers,
        credentials: "same-origin",
      });
    } catch (e) {
      // Network failure — retry if we have attempts left
      if (attempt < maxRetries && !isMutation) {
        _showReconnectBanner(`Reconnecting… (attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(r => setTimeout(r, 1000 * Math.pow(2, attempt)));
        continue;
      }
      _onServerFailure();
      _hideReconnectBanner();
      const err = new Error("Failed to reach server. Check your connection or try again.");
      err.status = 0;
      throw err;
    }
    const text = await res.text();
    let body;
    try {
      body = text ? JSON.parse(text) : {};
    } catch {
      if (!res.ok) {
        const isHtml = /<!DOCTYPE\s+html|<html[\s>]/i.test(text);
        // HTML response (WAF challenge, proxy error page) — retry once after delay
        if (isHtml && attempt < maxRetries && !isMutation) {
          _showReconnectBanner("Verifying connection…");
          await new Promise(r => setTimeout(r, 2000));
          continue;
        }
        const clean = isHtml
          ? text.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim().slice(0, 200)
          : text.slice(0, 300);
        const err = new Error(clean || res.statusText || `HTTP ${res.status}`);
        err.status = res.status;
        throw err;
      } else {
        body = {};
      }
    }
    if (!res.ok) {
      // 502/503/504 — transient, retry
      if ((res.status === 502 || res.status === 503 || res.status === 504) && attempt < maxRetries && !isMutation) {
        _showReconnectBanner(`Reconnecting… (attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(r => setTimeout(r, 1000 * Math.pow(2, attempt)));
        continue;
      }
      if (res.status === 502 || res.status === 503 || res.status === 504) _onServerFailure();
      const msg = parseApiError(body, res.status);
      const err = new Error(msg);
      err.status = res.status;
      throw err;
    }
    _onServerHealthy();
    _hideReconnectBanner();
    return body;
  }
  // Should not reach here, but just in case
  const err = new Error("Max retries exceeded");
  err.status = 0;
  throw err;
}

// ── Server Health Indicator ─────────────────────────────────────────────────
// Shows a small amber server icon in the header when the backend is unreachable.
// Hidden when healthy. Anti-false-positive: poller skips when tab is hidden;
// api() hook only fires on actual user-triggered calls.

const _serverHealth = { unreachable: false, consecutiveSuccesses: 0 };

function _showServerUnreachable() {
  if (_serverHealth.unreachable) return;
  _serverHealth.unreachable = true;
  _serverHealth.consecutiveSuccesses = 0;
  const el = $("#server-health-indicator");
  if (el) {
    el.classList.remove("hidden");
    el.classList.add("unreachable");
    el.title = "Server unreachable";
  }
}

function _hideServerUnreachable() {
  if (!_serverHealth.unreachable) return;
  _serverHealth.unreachable = false;
  _serverHealth.consecutiveSuccesses = 0;
  const el = $("#server-health-indicator");
  if (el) {
    el.classList.add("hidden");
    el.classList.remove("unreachable");
  }
}

function _onServerHealthy() {
  if (!_serverHealth.unreachable) return;
  _serverHealth.consecutiveSuccesses++;
  if (_serverHealth.consecutiveSuccesses >= 3) {
    _hideServerUnreachable();
    showToast("Server back online");
  }
}

function _onServerFailure() {
  _serverHealth.consecutiveSuccesses = 0;
  _showServerUnreachable();
}

// ── Reconnect Banner ──────────────────────────────────────────────────────
// Shows a visible banner during API retry attempts. Auto-hides on success.
let _reconnectBannerTimer = null;

function _showReconnectBanner(msg) {
  const el = $("#crm-crash-banner");
  if (!el) return;
  el.textContent = msg || "Connection lost. Reconnecting…";
  el.classList.remove("hidden");
  // Auto-hide after 15s max to avoid stuck state
  clearTimeout(_reconnectBannerTimer);
  _reconnectBannerTimer = setTimeout(() => _hideReconnectBanner(), 15000);
}

function _hideReconnectBanner() {
  clearTimeout(_reconnectBannerTimer);
  const el = $("#crm-crash-banner");
  if (el) el.classList.add("hidden");
}

// 60s health poller — skips when tab is hidden to avoid throttle false positives
let _healthPollTimer = null;
function _startHealthPoller() {
  if (_healthPollTimer) return;
  _healthPollTimer = setInterval(async () => {
    if (document.hidden) return;
    try {
      const res = await fetch("/api/health", { credentials: "same-origin" });
      if (res.ok) _onServerHealthy();
      else _onServerFailure();
    } catch {
      _onServerFailure();
    }
  }, 60000);
}

// Legacy stubs (called from various places, kept for compatibility)
function isTransientError() { return _serverHealth.unreachable; }
function addCompletedNoteQueueEntry() {}
function onCRMSuccess() { _onServerHealthy(); }
function showCrmCrashBanner() { _showServerUnreachable(); }
function hideCrmCrashBanner() { _hideServerUnreachable(); }
function showCRMSyncStatus() {}
function hideCRMSyncStatus() {}
function showRefreshingStatus() {}
function hideRefreshingStatus() {}
function clearConnectingTimer() {}
function setConnectionState() {}

function showSubmittingNote(button, message = 'Submitting — do not press the button again') {
  if (!button || !button.parentNode) return null;
  const prev = button.parentNode.querySelector('.submitting-note');
  if (prev) prev.remove();
  const note = document.createElement('div');
  note.className = 'submitting-note';
  note.textContent = message;
  note.style.cssText = 'color: #f59e0b; font-size: 0.75em; margin-top: 4px;';
  button.parentNode.insertBefore(note, button.nextSibling);
  return note;
}

/**
 * Thin wrapper — no longer queues on transient failure, just calls mutateFn directly.
 */
async function withCrmQueueOnTransient(mutateFn, descriptor) {
  return await mutateFn();
}

function newGroup(overrides = {}) {
  return {
    id: newId(),
    name: "New group",
    dealStatus: "open",
    tagTitles: [],
    contactId: "",
    contactLabel: "",
    stageId: "",
    stageType: "",
    search: "",
    groupBy: "stage",
    sortBy: "stage",
    sortOrder: "ascending",
    filtersCollapsed: false,
    visibleStageIds: [],
    stageColumnsConfigured: false,
    showEmptyStages: true,
    showOnlyRedOpportunities: false,
    stageColors: {},
    opportunities: [],
    ...overrides,
  };
}

function ensureVisibleStageIds(group) {
  if (!Array.isArray(group.visibleStageIds)) group.visibleStageIds = [];
  if (!group.stageColumnsConfigured && state.stages.length) {
    group.visibleStageIds = state.stages.map((s) => String(s.id));
  }
}

function isStageColumnVisible(group, stageId) {
  if (!group.stageColumnsConfigured) return true;
  return (group.visibleStageIds || []).includes(String(stageId));
}

function getOpportunityContactLabel(opp) {
  const contact = opp.contact || opp.Contact;
  if (contact && typeof contact === "object") {
    return (
      contact.displayName ||
      contact.DisplayName ||
      contact.title ||
      contact.Title ||
      contact.company ||
      ""
    ).trim();
  }
  return String(contact || opp.contactTitle || opp.ContactTitle || "").trim();
}

function loadGroupsFromStorage() {
  try {
    const raw = localStorage.getItem(GROUPS_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length) {
        return parsed.map((g) => stripGroupRuntimeFields(g));
      }
    }
  } catch {
    /* ignore */
  }
  return [
    newGroup({ name: "Open pipeline", dealStatus: "open", groupBy: "stage" }),
    newGroup({ name: "Tagged deals", dealStatus: "all", groupBy: "tag", tagTitles: [] }),
  ];
}

function saveGroupsToStorage() {
  const slim = state.groups.map((g) => {
    const { opportunities, ...rest } = stripGroupRuntimeFields(g);
    return rest;
  });
  localStorage.setItem(GROUPS_STORAGE_KEY, JSON.stringify(slim));
  scheduleUserProfileSave();
}

function stripCalendarRuntimeFields(cal) {
  const { _el, _loading, ...rest } = cal;
  return rest;
}

function newCalendarTile(overrides = {}) {
  const now = new Date();
  return {
    id: newId(),
    name: "Calendar",
    feedUrl: "",
    sourceId: null,
    view: "month",
    timezone: "",
    viewYear: now.getFullYear(),
    viewMonth: now.getMonth() + 1,
    ...overrides,
  };
}

const CALENDAR_TZ_COMMON = [
  "America/New_York",
  "America/Chicago",
  "America/Denver",
  "America/Los_Angeles",
  "America/Phoenix",
  "America/Anchorage",
  "Pacific/Honolulu",
  "America/Toronto",
  "America/Panama",
  "UTC",
  "Europe/London",
  "Europe/Paris",
  "Asia/Tokyo",
];

const CALENDAR_TZ_FALLBACK = [
  ...CALENDAR_TZ_COMMON,
  "America/Detroit",
  "America/Indiana/Indianapolis",
  "America/Boise",
  "America/Vancouver",
  "Europe/Berlin",
  "Australia/Sydney",
];

let calendarTimezoneOptionsCache = null;

function getBrowserTimezone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

function resolveCalendarTimezone(cal) {
  if (cal?.timezone) return cal.timezone;
  const tid = cal ? calendarTileId(cal) : "";
  const fromCache = tid ? state.calendarCache[tid]?.timezone : "";
  if (fromCache) return fromCache;
  return getBrowserTimezone();
}

function getCalendarTimezoneOptionList() {
  if (calendarTimezoneOptionsCache) return calendarTimezoneOptionsCache;
  let all = [];
  try {
    if (typeof Intl !== "undefined" && Intl.supportedValuesOf) {
      all = Intl.supportedValuesOf("timeZone");
    }
  } catch {
    /* ignore */
  }
  if (!all.length) all = [...CALENDAR_TZ_FALLBACK];
  const commonSet = new Set(CALENDAR_TZ_COMMON);
  const rest = all.filter((tz) => !commonSet.has(tz)).sort((a, b) => String(a).localeCompare(String(b)));
  calendarTimezoneOptionsCache = { common: [...CALENDAR_TZ_COMMON], rest };
  return calendarTimezoneOptionsCache;
}

function formatTimezoneLabel(tz) {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: tz,
      timeZoneName: "short",
    }).formatToParts(new Date());
    const abbr = parts.find((p) => p.type === "timeZoneName")?.value;
    const label = tz.replace(/_/g, " ");
    return abbr ? `${label} (${abbr})` : label;
  } catch {
    return tz.replace(/_/g, " ");
  }
}

function populateCalendarTimezoneSelect(select, selectedTz) {
  if (!select) return;
  const { common, rest } = getCalendarTimezoneOptionList();
  const selected = selectedTz || getBrowserTimezone();
  select.innerHTML = "";

  const addGroup = (label, zones) => {
    const og = document.createElement("optgroup");
    og.label = label;
    for (const tz of zones) {
      const opt = document.createElement("option");
      opt.value = tz;
      opt.textContent = formatTimezoneLabel(tz);
      if (tz === selected) opt.selected = true;
      og.appendChild(opt);
    }
    select.appendChild(og);
  };

  addGroup("Common", common);
  addGroup("All timezones", rest);
  if (![...common, ...rest].includes(selected)) {
    const opt = document.createElement("option");
    opt.value = selected;
    opt.textContent = formatTimezoneLabel(selected);
    opt.selected = true;
    select.insertBefore(opt, select.firstChild);
  }
}

function getZonedParts(utcMs, timeZone) {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone,
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    hour12: false,
  }).formatToParts(new Date(utcMs));
  const get = (type) => {
    const p = parts.find((x) => x.type === type);
    return p ? parseInt(p.value, 10) : 0;
  };
  return {
    year: get("year"),
    month: get("month"),
    day: get("day"),
    hour: get("hour"),
    minute: get("minute"),
  };
}

function wallTimeInZoneToUtc(year, month, day, hour, minute, timeZone) {
  let utc = Date.UTC(year, month - 1, day, hour, minute);
  for (let i = 0; i < 6; i++) {
    const p = getZonedParts(utc, timeZone);
    const target = Date.UTC(year, month - 1, day, hour, minute);
    const actual = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const delta = target - actual;
    if (Math.abs(delta) < 1000) break;
    utc += delta;
  }
  return utc;
}

function eventStartUtcMs(ev) {
  const s = ev?.start;
  if (!s || s.allDay) return null;
  if (s.iso && String(s.iso).endsWith("Z")) return new Date(s.iso).getTime();
  return wallTimeInZoneToUtc(
    s.year,
    s.month,
    s.day,
    s.hour ?? 0,
    s.minute ?? 0,
    s.tzid || "UTC"
  );
}

function eventEndUtcMs(ev) {
  const e = ev?.end || ev?.start;
  if (!e || e.allDay) return null;
  if (e.iso && String(e.iso).endsWith("Z")) return new Date(e.iso).getTime();
  return wallTimeInZoneToUtc(
    e.year,
    e.month,
    e.day,
    e.hour ?? 0,
    e.minute ?? 0,
    e.tzid || ev?.start?.tzid || "UTC"
  );
}

function allDayRangeFloating(ev) {
  const start = eventDateParts(ev.start);
  if (!start || start.y == null) return null;
  const end = eventDateParts(ev.end) || start;
  let ey = end.y ?? start.y;
  let em = end.m ?? start.m;
  let ed = end.d ?? start.d;
  if (ev.end?.allDay && ev.start?.allDay) {
    const endMs = Date.UTC(ey, em - 1, ed);
    const adj = new Date(endMs - 86400000);
    ey = adj.getUTCFullYear();
    em = adj.getUTCMonth() + 1;
    ed = adj.getUTCDate();
  }
  return { start, end: { y: ey, m: em, d: ed } };
}

function todayYmdInTimezone(timeZone) {
  return getZonedParts(Date.now(), timeZone);
}

function loadCalendarsFromStorage() {
  try {
    const raw = localStorage.getItem(CALENDARS_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        return parsed.map((c) => stripCalendarRuntimeFields(c));
      }
    }
  } catch {
    /* ignore */
  }
  return [];
}

function saveCalendarsToStorage() {
  const slim = state.calendarTiles.map((c) => stripCalendarRuntimeFields(c));
  localStorage.setItem(CALENDARS_STORAGE_KEY, JSON.stringify(slim));
  scheduleUserProfileSave();
}

const CALENDAR_MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

function calendarViewMonthLabel(cal) {
  const m = CALENDAR_MONTH_NAMES[(cal.viewMonth || 1) - 1] || "";
  return `${m} ${cal.viewYear || ""}`.trim();
}

function shiftCalendarViewMonth(cal, delta) {
  let y = cal.viewYear || new Date().getFullYear();
  let m = cal.viewMonth || new Date().getMonth() + 1;
  m += delta;
  while (m < 1) {
    m += 12;
    y -= 1;
  }
  while (m > 12) {
    m -= 12;
    y += 1;
  }
  cal.viewYear = y;
  cal.viewMonth = m;
  saveCalendarsToStorage();
}

function eventDateParts(dt) {
  if (!dt) return null;
  return { y: dt.year, m: dt.month, d: dt.day };
}

function eventOnCalendarDay(ev, year, month, day, timeZone) {
  if (ev.start?.allDay) {
    const range = allDayRangeFloating(ev);
    if (!range) return false;
    const cell = Date.UTC(year, month - 1, day);
    const s = Date.UTC(range.start.y, range.start.m - 1, range.start.d);
    const e = Date.UTC(range.end.y, range.end.m - 1, range.end.d);
    return cell >= s && cell <= e;
  }
  const startMs = eventStartUtcMs(ev);
  if (!Number.isFinite(startMs)) return false;
  let endMs = eventEndUtcMs(ev);
  if (!Number.isFinite(endMs)) endMs = startMs + 3600000;
  const dayStart = wallTimeInZoneToUtc(year, month, day, 0, 0, timeZone);
  const dayEnd = wallTimeInZoneToUtc(year, month, day, 23, 59, timeZone) + 60000;
  return startMs < dayEnd && endMs >= dayStart;
}

function eventSortKeyInTimezone(ev, timeZone) {
  if (ev.start?.allDay) return 0;
  const ms = eventStartUtcMs(ev);
  if (!Number.isFinite(ms)) return 0;
  const p = getZonedParts(ms, timeZone);
  return p.hour * 60 + p.minute;
}

function formatEventTimeInTimezone(ev, timeZone) {
  if (ev.start?.allDay) return "";
  const ms = eventStartUtcMs(ev);
  if (!Number.isFinite(ms)) return "";
  const p = getZonedParts(ms, timeZone);
  return `${String(p.hour).padStart(2, "0")}:${String(p.minute).padStart(2, "0")} `;
}

function eventsForCalendarDay(events, year, month, day, timeZone) {
  return events
    .filter((ev) => ev.status !== "CANCELLED" && eventOnCalendarDay(ev, year, month, day, timeZone))
    .sort((a, b) => {
      const sa = eventSortKeyInTimezone(a, timeZone);
      const sb = eventSortKeyInTimezone(b, timeZone);
      if (sa !== sb) return sa - sb;
      return String(a.summary || "").localeCompare(String(b.summary || ""));
    });
}

function buildCalendarMonthGrid(year, month) {
  const first = new Date(year, month - 1, 1);
  const startPad = first.getDay();
  const daysInMonth = new Date(year, month, 0).getDate();
  const cells = [];
  const prevMonthDays = new Date(year, month - 1, 0).getDate();
  for (let i = startPad - 1; i >= 0; i--) {
    const d = prevMonthDays - i;
    const pm = month === 1 ? 12 : month - 1;
    const py = month === 1 ? year - 1 : year;
    cells.push({ year: py, month: pm, day: d, outside: true });
  }
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({ year, month, day: d, outside: false });
  }
  while (cells.length % 7 !== 0) {
    const last = cells[cells.length - 1];
    let ny = last.year;
    let nm = last.month;
    let nd = last.day + 1;
    if (nd > new Date(ny, nm, 0).getDate()) {
      nd = 1;
      nm += 1;
      if (nm > 12) {
        nm = 1;
        ny += 1;
      }
    }
    cells.push({ year: ny, month: nm, day: nd, outside: true });
  }
  while (cells.length < 42) {
    const last = cells[cells.length - 1];
    let ny = last.year;
    let nm = last.month;
    let nd = last.day + 1;
    if (nd > new Date(ny, nm, 0).getDate()) {
      nd = 1;
      nm += 1;
      if (nm > 12) {
        nm = 1;
        ny += 1;
      }
    }
    cells.push({ year: ny, month: nm, day: nd, outside: true });
  }
  return cells;
}

function renderCalendarView(section, cal) {
  const view = cal.view || "month";
  const body = section?.querySelector(".calendar-month-body") || section?.querySelector(".tile-body-content");
  if (!body) return;
  // Clear existing view
  body.innerHTML = "";
  if (view === "week") renderCalendarWeekView(body, section, cal);
  else if (view === "day") renderCalendarDayView(body, section, cal);
  else if (view === "agenda") renderCalendarAgendaView(body, section, cal);
  else renderCalendarMonthBody(section, cal);
}

function renderCalendarWeekView(body, section, cal) {
  const tid = calendarTileId(cal);
  const events = state.calendarCache[tid]?.events || [];
  const tz = resolveCalendarTimezone(cal);
  const today = todayYmdInTimezone(tz);
  const y = cal.viewYear || today.year;
  const m = cal.viewMonth || today.month;
  const d = cal.viewDay || today.day;
  const weekStart = new Date(y, m - 1, d);
  weekStart.setDate(weekStart.getDate() - weekStart.getDay());

  const hours = [];
  for (let h = 6; h <= 22; h++) hours.push(h);

  let html = '<div class="calendar-week-grid">';
  for (let i = 0; i < 7; i++) {
    const day = new Date(weekStart);
    day.setDate(day.getDate() + i);
    const dayY = day.getFullYear();
    const dayM = day.getMonth() + 1;
    const dayD = day.getDate();
    const isToday = dayY === today.year && dayM === today.month && dayD === today.day;
    const dayEvents = eventsForCalendarDay(events, dayY, dayM, dayD, tz);

    html += `<div class="calendar-time-col">`;
    html += `<div class="calendar-time-header${isToday ? " calendar-time-today" : ""}">${["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][day.getDay()]} ${dayD}</div>`;
    html += `<div class="calendar-time-slots">`;
    for (const h of hours) {
      const slotEvents = dayEvents.filter(ev => {
        if (ev.start?.allDay) return false;
        const ms = eventStartUtcMs(ev);
        if (!ms) return false;
        const p = getZonedParts(ms, tz);
        return p.hour === h;
      });
      html += `<div class="calendar-time-slot" data-date="${dayY}-${String(dayM).padStart(2,"0")}-${String(dayD).padStart(2,"0")}" data-hour="${h}">`;
      for (const ev of slotEvents) {
        const color = ev.color || "#5b8abf";
        const startMs = eventStartUtcMs(ev);
        const p = startMs ? getZonedParts(startMs, tz) : { hour: h, minute: 0 };
        const timeStr = `${String(p.hour).padStart(2,"0")}:${String(p.minute).padStart(2,"0")}`;
        html += `<div class="calendar-time-event" style="--event-color:${escapeHtml(color)}" data-event-uid="${escapeHtml(ev.uid || "")}" title="${escapeHtml((ev.summary || "").replace(/"/g, "&quot;"))}">`;
        html += `<div class="calendar-time-event-title">${escapeHtml(ev.summary || "")}</div>`;
        html += `<div class="calendar-time-event-time">${timeStr}</div>`;
        html += `</div>`;
      }
      html += `</div>`;
    }
    html += `</div></div>`;
  }
  html += '</div>';
  body.innerHTML = html;
  bindCalendarEventClicks(body.closest(".dashboard-tile") || section, cal);
}

function renderCalendarDayView(body, section, cal) {
  const tid = calendarTileId(cal);
  const events = state.calendarCache[tid]?.events || [];
  const tz = resolveCalendarTimezone(cal);
  const today = todayYmdInTimezone(tz);
  const y = cal.viewYear || today.year;
  const m = cal.viewMonth || today.month;
  const d = cal.viewDay || today.day;
  const isToday = y === today.year && m === today.month && d === today.day;
  const dayEvents = eventsForCalendarDay(events, y, m, d, tz);

  const hours = [];
  for (let h = 6; h <= 22; h++) hours.push(h);

  let html = '<div class="calendar-day-grid"><div class="calendar-time-col">';
  html += `<div class="calendar-time-header${isToday ? " calendar-time-today" : ""}">${["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][new Date(y, m-1, d).getDay()]} ${m}/${d}/${y}</div>`;
  html += `<div class="calendar-time-slots">`;
  for (const h of hours) {
    const slotEvents = dayEvents.filter(ev => {
      if (ev.start?.allDay) return false;
      const ms = eventStartUtcMs(ev);
      if (!ms) return false;
      const p = getZonedParts(ms, tz);
      return p.hour === h;
    });
    html += `<div class="calendar-time-slot" data-date="${y}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}" data-hour="${h}">`;
    for (const ev of slotEvents) {
      const color = ev.color || "#5b8abf";
      const startMs = eventStartUtcMs(ev);
      const p = startMs ? getZonedParts(startMs, tz) : { hour: h, minute: 0 };
      const timeStr = `${String(p.hour).padStart(2,"0")}:${String(p.minute).padStart(2,"0")}`;
      html += `<div class="calendar-time-event" style="--event-color:${escapeHtml(color)}" data-event-uid="${escapeHtml(ev.uid || "")}" title="${escapeHtml((ev.summary || "").replace(/"/g, "&quot;"))}">`;
      html += `<div class="calendar-time-event-title">${escapeHtml(ev.summary || "")}</div>`;
      html += `<div class="calendar-time-event-time">${timeStr}</div>`;
      html += `</div>`;
    }
    html += `</div>`;
  }
  html += `</div></div></div>`;
  body.innerHTML = html;
  bindCalendarEventClicks(body.closest(".dashboard-tile") || section, cal);
}

function renderCalendarAgendaView(body, section, cal) {
  const tid = calendarTileId(cal);
  const events = state.calendarCache[tid]?.events || [];
  const tz = resolveCalendarTimezone(cal);
  const today = todayYmdInTimezone(tz);

  const futureEvents = events.filter(ev => {
    if (ev.status === "CANCELLED") return false;
    const endMs = eventEndUtcMs(ev);
    return endMs && endMs >= Date.now();
  }).sort((a, b) => {
    const aMs = eventStartUtcMs(a) || 0;
    const bMs = eventStartUtcMs(b) || 0;
    return aMs - bMs;
  }).slice(0, 50);

  if (!futureEvents.length) {
    body.innerHTML = '<div class="calendar-agenda-empty">No upcoming events</div>';
    return;
  }

  let html = '<div class="calendar-agenda">';
  let lastDay = "";
  for (const ev of futureEvents) {
    const startMs = eventStartUtcMs(ev);
    const p = startMs ? getZonedParts(startMs, tz) : null;
    const dayKey = p ? `${p.year}-${String(p.month).padStart(2,"0")}-${String(p.day).padStart(2,"0")}` : "";
    const isToday = dayKey === `${today.year}-${String(today.month).padStart(2,"0")}-${String(today.day).padStart(2,"0")}`;

    if (dayKey !== lastDay) {
      lastDay = dayKey;
      const dayDate = p ? new Date(p.year, p.month - 1, p.day) : new Date();
      const dayLabel = isToday ? "Today" : dayDate.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
      html += `<div class="calendar-agenda-day"><div class="calendar-agenda-day-header${isToday ? " agenda-today" : ""}">${escapeHtml(dayLabel)}</div>`;
    }
    const color = ev.color || "#5b8abf";
    const timeLabel = ev.start?.allDay ? "All day" : (p ? `${String(p.hour).padStart(2,"0")}:${String(p.minute).padStart(2,"0")}` : "");
    html += `<div class="calendar-agenda-event" data-event-uid="${escapeHtml(ev.uid || "")}">`;
    html += `<div class="calendar-agenda-dot" style="background:${escapeHtml(color)}"></div>`;
    html += `<div class="calendar-agenda-event-info"><div class="calendar-agenda-event-title">${escapeHtml(ev.summary || "")}</div>`;
    if (timeLabel) html += `<div class="calendar-agenda-event-time">${escapeHtml(timeLabel)}</div>`;
    html += `</div></div>`;
  }
  html += '</div>';
  body.innerHTML = html;
  bindCalendarEventClicks(body.closest(".dashboard-tile") || section, cal);
}

function renderCalendarMonthBody(section, cal) {
  const body = $(".calendar-month-body", section);
  if (!body) return;
  const tid = calendarTileId(cal);
  if (tileBodyCollapsed(tid)) {
    body.innerHTML = '<p class="tile-collapsed-hint">Minimized — expand to load calendar</p>';
    return;
  }
  const cache = state.calendarCache[tid];
  const events = cache?.events || [];
  const y = cal.viewYear || new Date().getFullYear();
  const m = cal.viewMonth || new Date().getMonth() + 1;
  const tz = resolveCalendarTimezone(cal);
  const today = todayYmdInTimezone(tz);
  const cells = buildCalendarMonthGrid(y, m);

  const weekdays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  let headerHtml = '<div class="calendar-month-grid" role="grid" aria-label="Monthly calendar">';
  headerHtml += '<div class="calendar-weekdays" role="row">';
  for (const wd of weekdays) {
    headerHtml += `<div class="calendar-weekday" role="columnheader">${escapeHtml(wd)}</div>`;
  }
  headerHtml += '</div><div class="calendar-days" role="rowgroup"></div></div>';

  body.innerHTML = headerHtml;
  const daysContainer = body.querySelector(".calendar-days");
  if (!daysContainer) return;

  const weeks = [];
  for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7));

  const maxShow = 3;

  function buildWeekHtml(week) {
    let html = "";
    for (const cell of week) {
      const isToday = cell.year === today.year && cell.month === today.month && cell.day === today.day;
      const dayEvents = eventsForCalendarDay(events, cell.year, cell.month, cell.day, tz);
      const cls = [
        "calendar-day",
        cell.outside ? "calendar-day-outside" : "",
        isToday ? "calendar-day-today" : "",
      ].filter(Boolean).join(" ");
      html += `<div class="${cls}" role="gridcell" data-date="${cell.year}-${String(cell.month).padStart(2, "0")}-${String(cell.day).padStart(2, "0")}">`;
      html += `<div class="calendar-day-num">${cell.day}</div>`;
      html += '<div class="calendar-day-events">';
      for (let i = 0; i < Math.min(dayEvents.length, maxShow); i++) {
        const ev = dayEvents[i];
        const color = ev.color || "#6e4bdb";
        const time = formatEventTimeInTimezone(ev, tz);
        const uidAttr = escapeHtml(ev.uid || "");
        html += `<button type="button" class="calendar-event-chip" data-event-uid="${uidAttr}" style="--event-color:${escapeHtml(color)}" title="${escapeHtml((time + ev.summary).trim())}">`;
        html += `<span class="calendar-event-dot" aria-hidden="true"></span>`;
        html += `<span class="calendar-event-label">${escapeHtml(time + (ev.summary || ""))}</span>`;
        html += "</button>";
      }
      if (dayEvents.length > maxShow) {
        html += `<div class="calendar-more-events">+${dayEvents.length - maxShow} more</div>`;
      }
      html += "</div></div>";
    }
    return html;
  }

  let weekIdx = 0;
  function renderNextWeek() {
    if (weekIdx >= weeks.length) {
      const monthLabel = $(".calendar-month-label", section);
      if (monthLabel) monthLabel.textContent = calendarViewMonthLabel(cal);
      const countEl = $(".calendar-tile-count", section);
      if (countEl) {
        const inMonth = events.filter((ev) => {
          if (ev.status === "CANCELLED") return false;
          for (const cell of cells) {
            if (!cell.outside && eventOnCalendarDay(ev, cell.year, cell.month, cell.day, tz)) return true;
          }
          return false;
        }).length;
        countEl.textContent = `${inMonth} events`;
      }
      bindCalendarEventClicks(section, cal);
      return;
    }
    daysContainer.insertAdjacentHTML("beforeend", buildWeekHtml(weeks[weekIdx]));
    weekIdx++;
    if (typeof requestIdleCallback === "function") {
      requestIdleCallback(renderNextWeek, { timeout: 50 });
    } else {
      setTimeout(renderNextWeek, 0);
    }
  }
  renderNextWeek();
}

function findCalendarEventByUid(cal, uid) {
  if (!uid) return null;
  const tid = calendarTileId(cal);
  const events = state.calendarCache[tid]?.events || [];
  return events.find((ev) => ev.uid === uid) || null;
}

function formatCalendarEventWhen(ev, timeZone) {
  const pad = (n) => String(n).padStart(2, "0");
  if (ev.start?.allDay) {
    const s = ev.start;
    const range = allDayRangeFloating(ev);
    const startLabel = `${s.year}-${pad(s.month)}-${pad(s.day)}`;
    if (range && (range.end.y !== s.year || range.end.m !== s.month || range.end.d !== s.day)) {
      return `All day · ${startLabel} – ${range.end.y}-${pad(range.end.m)}-${pad(range.end.d)}`;
    }
    return `All day · ${startLabel}`;
  }
  const startMs = eventStartUtcMs(ev);
  if (!Number.isFinite(startMs)) return "";
  const sp = getZonedParts(startMs, timeZone);
  let label = `${sp.year}-${pad(sp.month)}-${pad(sp.day)} ${pad(sp.hour)}:${pad(sp.minute)}`;
  const endMs = eventEndUtcMs(ev);
  if (Number.isFinite(endMs) && endMs > startMs) {
    const ep = getZonedParts(endMs, timeZone);
    label += ` – ${ep.year}-${pad(ep.month)}-${pad(ep.day)} ${pad(ep.hour)}:${pad(ep.minute)}`;
  }
  return label;
}

function openCalendarEventModal(ev, cal) {
  const modal = $("#calendar-event-modal");
  const titleEl = $("#calendar-event-modal-title");
  const bodyEl = $("#calendar-event-modal-body");
  if (!modal || !titleEl || !bodyEl) return;

  const tz = resolveCalendarTimezone(cal);
  const color = ev.color || "#6e4bdb";
  titleEl.innerHTML = `<span class="calendar-event-modal-dot" style="background:${escapeHtml(color)}"></span>${escapeHtml(ev.summary || "Event")}`;

  const rows = [];
  const when = formatCalendarEventWhen(ev, tz);
  if (when) rows.push({ label: "When", value: when });
  if (ev.status && ev.status !== "CONFIRMED") rows.push({ label: "Status", value: ev.status });
  if (ev.organizer) rows.push({ label: "Organizer", value: ev.organizer });
  if (ev.location) {
    const loc = ev.location;
    if (/^https?:\/\//i.test(loc)) {
      rows.push({
        label: "Location",
        html: `<a href="${escapeHtml(loc)}" target="_blank" rel="noopener noreferrer">${escapeHtml(loc)}</a>`,
      });
    } else {
      rows.push({ label: "Location", value: loc });
    }
  }
  if (ev.url) {
    rows.push({
      label: "Link",
      html: `<a href="${escapeHtml(ev.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(ev.url)}</a>`,
    });
  }
  const calName = state.calendarCache[calendarTileId(cal)]?.name;
  if (calName) rows.push({ label: "Calendar", value: calName });
  if (ev.categories?.length) rows.push({ label: "Categories", value: ev.categories.join(", ") });
  if (ev.recurrence || ev.rrule) {
    rows.push({ label: "Repeats", value: ev.recurrence || ev.rrule });
  }
  if (ev.attendees?.length) {
    const list = ev.attendees
      .map((a) => escapeHtml(a.label || a.name || a.email || ""))
      .filter(Boolean)
      .join("<br/>");
    if (list) {
      rows.push({ label: "Attendees", html: `<div class="calendar-event-attendees">${list}</div>` });
    }
  }
  if (ev.transparency) {
    const t = String(ev.transparency).toUpperCase();
    rows.push({
      label: "Show as",
      value: t === "TRANSPARENT" ? "Free" : t === "OPAQUE" ? "Busy" : ev.transparency,
    });
  }
  if (ev.visibility) rows.push({ label: "Visibility", value: ev.visibility });
  if (ev.priority != null && ev.priority !== "") {
    rows.push({ label: "Priority", value: String(ev.priority) });
  }
  if (ev.geo) rows.push({ label: "Location (coordinates)", value: ev.geo });
  if (ev.created) rows.push({ label: "Created", value: ev.created });
  if (ev.lastModified) rows.push({ label: "Modified", value: ev.lastModified });
  if (ev.dtstamp && ev.dtstamp !== ev.lastModified) rows.push({ label: "Stamp", value: ev.dtstamp });
  if (ev.sequence != null && ev.sequence !== "") rows.push({ label: "Sequence", value: String(ev.sequence) });

  let bodyHtml = "";
  for (const row of rows) {
    bodyHtml += `<div class="calendar-event-detail-row"><span class="calendar-event-detail-label">${escapeHtml(row.label)}</span>`;
    if (row.html) bodyHtml += `<div class="calendar-event-detail-value">${row.html}</div>`;
    else bodyHtml += `<div class="calendar-event-detail-value">${escapeHtml(row.value)}</div>`;
    bodyHtml += "</div>";
  }
  if (ev.description) {
    bodyHtml += `<div class="calendar-event-detail-row calendar-event-detail-description"><span class="calendar-event-detail-label">Description</span>`;
    bodyHtml += `<div class="calendar-event-detail-value calendar-event-detail-desc-text">${escapeHtml(ev.description)}</div></div>`;
  }
  if (!bodyHtml) bodyHtml = '<p class="calendar-event-detail-empty">No additional details.</p>';
  if (ev.uid) {
    bodyHtml += `<p class="calendar-event-detail-uid" title="Event UID">${escapeHtml(ev.uid)}</p>`;
  }
  bodyEl.innerHTML = bodyHtml;
  modal.classList.remove("hidden");
}

function closeCalendarEventModal() {
  $("#calendar-event-modal")?.classList.add("hidden");
}

function bindCalendarEventClicks(section, cal) {
  if (!section || section.dataset.calendarEventsBound) return;
  section.dataset.calendarEventsBound = "1";
  section.addEventListener("click", (e) => {
    const chip = e.target.closest(".calendar-event-chip");
    if (!chip) return;
    e.stopPropagation();
    const uid = chip.dataset.eventUid;
    const ev = findCalendarEventByUid(cal, uid);
    if (ev) openCalendarEventModal(ev, cal);
  });
}

/* ── Documents Modal ─────────────────────────────────────── */

const docsState = {
  scope: "projects",   // "projects" | "mydocs" | "company"
  currentProjectId: null,
  currentProjectTitle: null,
  currentFolderId: null,
  currentFolderPath: [], // [{id, name}, ...] for breadcrumbs
  folders: [],
  searchQuery: "",
  selected: new Set(),
  documents: [],
  loading: false,
  renamingId: null,
  renamingFolderId: null,
  sort: "recent",
  folderTree: [],        // flat list of {id, name, parentId} from /documents/folders/tree
  expandedFolders: new Set(), // expanded folder IDs in sidebar tree
  // Preview pane state — survives minimize/restore so the same doc is still
  // visible when the user re-opens the modal.
  previewOpen: false,
  previewDocId: null,
  previewDocTitle: null,
  previewActivity: [],   // last activities, refreshed when the pane is shown
};

function docsIconForMime(mimeType) {
  const sw = "2";
  if (!mimeType) return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M12 18h-2a2 2 0 0 1 -2 -2v-2a2 2 0 0 1 2 -2h2v6"/><path d="M15 13v6"/><path d="M18 15v3"/><path d="M15 18h6"/></svg>`;
  if (mimeType.includes("sheet") || mimeType.includes("excel") || mimeType.includes("csv"))
    return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4da377" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M4 15l4 6"/><path d="M4 21l4 -6"/><path d="M17 20.25c0 .414 .336 .75 .75 .75h1.25a1 1 0 0 0 1 -1v-1a1 1 0 0 0 -1 -1h-1a1 1 0 0 1 -1 -1v-1a1 1 0 0 1 1 -1h1.25a.75 .75 0 0 1 .75 .75"/><path d="M11 15v6h3"/></svg>`;
  if (mimeType.includes("word") || mimeType.includes("document"))
    return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6b9fd6" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M2 15v6h1a2 2 0 0 0 2 -2v-2a2 2 0 0 0 -2 -2h-1"/><path d="M17 16.5a1.5 1.5 0 0 0 -3 0v3a1.5 1.5 0 0 0 3 0"/><path d="M9.5 15a1.5 1.5 0 0 1 1.5 1.5v3a1.5 1.5 0 0 1 -3 0v-3a1.5 1.5 0 0 1 1.5 -1.5"/><path d="M19.5 15l3 6"/><path d="M19.5 21l3 -6"/></svg>`;
  if (mimeType.includes("pdf"))
    return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#cf7070" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M5 18h1.5a1.5 1.5 0 0 0 0 -3h-1.5v6"/><path d="M17 18h2"/><path d="M20 15h-3v6"/><path d="M11 15v6h1a2 2 0 0 0 2 -2v-2a2 2 0 0 0 -2 -2h-1"/></svg>`;
  if (mimeType.startsWith("image/"))
    return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#9b84c8" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M11 18h1.5a1.5 1.5 0 0 0 0 -3h-1.5v6"/><path d="M20 15h-1a2 2 0 0 0 -2 2v2a2 2 0 0 0 2 2h1v-3"/><path d="M5 15h3v4.5a1.5 1.5 0 0 1 -3 0"/></svg>`;
  if (mimeType.includes("text"))
    return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#8a9ab5" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M16.5 15h3"/><path d="M4.5 15h3"/><path d="M6 15v6"/><path d="M18 15v6"/><path d="M10 15l4 6"/><path d="M10 21l4 -6"/></svg>`;
  return `<svg class="doc-doc-icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M12 18h-2a2 2 0 0 1 -2 -2v-2a2 2 0 0 1 2 -2h2v6"/><path d="M15 13v6"/><path d="M18 15v3"/><path d="M15 18h6"/></svg>`;
}

function formatDocSize(bytes) {
  if (!bytes) return "—";
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(0) + " KB";
  return (bytes / (1024 * 1024)).toFixed(1) + " MB";
}

function openDocumentsModal() {
  const modal = $("#documents-modal");
  if (!modal) return;
  // If restoring from parked state, keep the restored values
  if (!minimizedDocsState) {
    docsState.scope = "projects";
    docsState.currentProjectId = null;
    docsState.currentProjectTitle = null;
    docsState.currentFolderId = null;
    docsState.currentFolderPath = [];
    docsState.folders = [];
    docsState.selected.clear();
    docsState.searchQuery = "";
    docsState.documents = [];
    docsState.loading = false;
    const searchInput = $("#documents-search-input");
    if (searchInput) searchInput.value = "";
    document.querySelectorAll(".documents-scope-btn").forEach(b => b.classList.toggle("active", b.dataset.scope === "projects"));
  } else {
    document.querySelectorAll(".documents-scope-btn").forEach(b => b.classList.toggle("active", b.dataset.scope === docsState.scope));
  }
  modal.classList.remove("hidden");
  // Collapse sidebar by default on narrow screens
  const sidebar = $("#documents-sidebar");
  const sidebarToggle = $("#documents-sidebar-toggle");
  if (sidebar && sidebarToggle && window.innerWidth <= 640) {
    sidebar.classList.add("documents-sidebar-collapsed");
    sidebarToggle.textContent = "▶";
    sidebarToggle.setAttribute("aria-label", "Show sidebar");
    sidebarToggle.setAttribute("title", "Show sidebar");
  }
  updateDocsToolbarForScope();
  loadDocumentsList();
  loadFolderTree();
  // Auto-refresh when editor signals save-as complete
  if (!openDocumentsModal._focusBound) {
    openDocumentsModal._focusBound = true;
    window.addEventListener("focus", () => {
      try {
        const ts = localStorage.getItem("crm-docs-refresh");
        if (ts && !modal.classList.contains("hidden")) {
          localStorage.removeItem("crm-docs-refresh");
          loadDocumentsList();
        }
      } catch {}
    });
  }
}

function closeDocumentsModal() {
  const modal = $("#documents-modal");
  if (!modal) return;
  modal.classList.add("hidden");
  docsState.selected.clear();
  docsState.searchQuery = "";
  docsState.scope = "projects";
  // Kill any active preview iframe session before clearing state.
  _documentsPreviewCleanupOnClose();
  // Clear parked state
  minimizedDocsState = null;
  try { localStorage.removeItem(DOCS_MINIMIZED_STORAGE_KEY); } catch {}
  const trigger = $("#documents-trigger");
  if (trigger) trigger.classList.add("trigger-hidden");
}

async function loadDocumentsList() {
  const list = $("#documents-list");
  if (!list) return;
  list.innerHTML = '<div class="documents-loading">Loading…</div>';
  docsState.loading = true;
  docsState.selected.clear();
  updateDocsToolbar();
  try {
    let data;
    if (docsState.scope === "mydocs") {
      const qs = new URLSearchParams();
      if (docsState.currentFolderId) qs.set("folder_id", String(docsState.currentFolderId));
      const path = "/api/v2/documents/personal" + (qs.toString() ? "?" + qs.toString() : "");
      data = await api(path);
      docsState.documents = data.documents || [];
      docsState.folders = data.folders || [];
    } else if (docsState.scope === "company") {
      const qs = new URLSearchParams();
      if (docsState.currentFolderId) qs.set("folder_id", String(docsState.currentFolderId));
      const path = "/api/v2/documents/company" + (qs.toString() ? "?" + qs.toString() : "");
      data = await api(path);
      docsState.documents = data.documents || [];
      docsState.folders = data.folders || [];
    } else {
      docsState.folders = [];
      const qs = new URLSearchParams();
      if (docsState.currentProjectId) {
        qs.set("project_id", String(docsState.currentProjectId));
      }
      if (docsState.searchQuery) {
        qs.set("q", docsState.searchQuery);
      }
      const path = "/api/v2/documents/search" + (qs.toString() ? "?" + qs.toString() : "");
      data = await api(path);
      docsState.documents = [];
      (data.results || []).forEach(group => {
        (group.documents || []).forEach(d => {
          d._projectTitle = group.project;
          d._projectId = group.projectId;
          docsState.documents.push(d);
        });
      });
    }
    renderDocumentsList();
  } catch (err) {
    list.innerHTML = `<div class="documents-empty"><div class="documents-empty-icon">⚠</div>${escapeHtml(err.message)}</div>`;
  } finally {
    docsState.loading = false;
  }
}

function sortDocuments(docs) {
  const sorted = [...docs];
  switch (docsState.sort) {
    case "recent":
      sorted.sort((a, b) => new Date(b.uploadedAt || 0) - new Date(a.uploadedAt || 0));
      break;
    case "oldest":
      sorted.sort((a, b) => new Date(a.uploadedAt || 0) - new Date(b.uploadedAt || 0));
      break;
    case "largest":
      sorted.sort((a, b) => (b.fileSize || 0) - (a.fileSize || 0));
      break;
    case "smallest":
      sorted.sort((a, b) => (a.fileSize || 0) - (b.fileSize || 0));
      break;
    case "name-asc":
      sorted.sort((a, b) => String(a.title || "").localeCompare(String(b.title || ""), undefined, { sensitivity: "base" }));
      break;
    case "name-desc":
      sorted.sort((a, b) => String(b.title || "").localeCompare(String(a.title || ""), undefined, { sensitivity: "base" }));
      break;
  }
  return sorted;
}

function renderDocumentRow(d) {
  const checked = docsState.selected.has(d.id) ? "checked" : "";
  const selClass = docsState.selected.has(d.id) ? " selected" : "";
  const isRenaming = docsState.renamingId === d.id;
  const titleHtml = isRenaming
    ? `<input type="text" class="doc-doc-title-input" value="${escapeHtml(d.title)}" data-rename-input data-doc-id="${d.id}" />
       <span class="doc-rename-actions">
         <button type="button" class="btn-icon-only doc-rename-confirm" data-doc-id="${d.id}" title="Save">
           <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 5a2 2 0 0 1 2 -2h14a2 2 0 0 1 2 2v14a2 2 0 0 1 -2 2h-14a2 2 0 0 1 -2 -2v-14" /><path d="M9 12l2 2l4 -4" /></svg>
         </button>
         <button type="button" class="btn-icon-only doc-rename-cancel" title="Cancel">
           <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M18 6l-12 12" /><path d="M6 6l12 12" /></svg>
         </button>
       </span>`
    : `<span class="doc-doc-title" data-doc-title data-doc-id="${d.id}" title="${escapeHtml(d.title)}">${escapeHtml(d.title)}</span>`;
  const isDraggable = docsState.scope !== "projects";
  // Eye-icon only shown when not renaming (renaming inline replaces eye area anyway).
  const previewBtnHtml = isRenaming
    ? ""
    : `<button type="button" class="doc-preview-btn" data-doc-id="${d.id}" title="Preview" aria-label="Preview ${escapeHtml(d.title)}">
         <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 12a2 2 0 1 0 4 0a2 2 0 1 0 -4 0"/><path d="M21 12c-2.4 4 -5.4 6 -9 6c-3.6 0 -6.6 -2 -9 -6c2.4 -4 5.4 -6 9 -6c3.6 0 6.6 2 9 6"/></svg>
       </button>`;
  return `<div class="documents-list-row${selClass}" data-doc-id="${d.id}" draggable="${isDraggable ? "true" : "false"}">
    <input type="checkbox" class="doc-cb" data-id="${d.id}" ${checked} />
    ${docsIconForMime(d.mimeType)}
    ${titleHtml}
    ${previewBtnHtml}
    <span class="doc-doc-meta">
      <span class="doc-doc-size">${formatDocSize(d.fileSize)}</span>
      <span class="doc-doc-date">${d.uploadedAt ? escapeHtml(d.uploadedAt.split("T")[0]) : "—"}</span>
    </span>
  </div>`;
}

function renderDocumentsList() {
  const list = $("#documents-list");
  if (!list) return;
  const docs = sortDocuments(docsState.documents);
  const hasFolders = docsState.folders && docsState.folders.length > 0;
  const isFolderScope = docsState.scope === "mydocs" || docsState.scope === "company";

  let html = "";

  // Breadcrumb for folder scopes (rendered even when empty)
  if (isFolderScope) {
    html += '<div class="documents-breadcrumb">';
    const scopeLabel = docsState.scope === "mydocs" ? "My Documents" : "Company";
    if (docsState.currentFolderPath.length === 0) {
      html += `<span class="documents-breadcrumb-item documents-breadcrumb-current">${escapeHtml(scopeLabel)}</span>`;
    } else {
      html += `<span class="documents-breadcrumb-item documents-breadcrumb-link" data-breadcrumb-root>${escapeHtml(scopeLabel)}</span>`;
      docsState.currentFolderPath.forEach((seg, idx) => {
        html += '<span class="documents-breadcrumb-sep">/</span>';
        const isLast = idx === docsState.currentFolderPath.length - 1;
        if (isLast) {
          html += `<span class="documents-breadcrumb-item documents-breadcrumb-current">${escapeHtml(seg.name)}</span>`;
        } else {
          html += `<span class="documents-breadcrumb-item documents-breadcrumb-link" data-breadcrumb-idx="${idx}">${escapeHtml(seg.name)}</span>`;
        }
      });
    }
    html += '</div>';
  }

  if (!docs.length && !hasFolders) {
    const scopeMessages = {
      mydocs: "No personal documents yet. Upload files or create new ones.",
      company: "No company documents yet. Upload shared resources here.",
      projects: docsState.currentProjectId ? "No documents in this project. Upload files or drag them here." : "No documents found.",
    };
    html += `<div class="documents-empty"><div class="documents-empty-icon"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></div>${scopeMessages[docsState.scope] || "No documents."}</div>`;
    list.innerHTML = html;
    bindDocumentsListEvents(list);
    return;
  }

  // Folder rows
  if (hasFolders) {
    docsState.folders.forEach(f => {
      const isRenaming = docsState.renamingFolderId === f.id;
      const nameHtml = isRenaming
        ? `<input type="text" class="doc-doc-title-input" value="${escapeHtml(f.name)}" data-rename-folder-input data-folder-id="${f.id}" />
           <span class="doc-rename-actions">
             <button type="button" class="btn-icon-only doc-rename-folder-confirm" data-folder-id="${f.id}" title="Save">
               <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 5a2 2 0 0 1 2 -2h14a2 2 0 0 1 2 2v14a2 2 0 0 1 -2 2h-14a2 2 0 0 1 -2 -2v-14" /><path d="M9 12l2 2l4 -4" /></svg>
             </button>
             <button type="button" class="btn-icon-only doc-rename-folder-cancel" title="Cancel">
               <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M18 6l-12 12" /><path d="M6 6l12 12" /></svg>
             </button>
           </span>`
        : `<span class="doc-doc-title documents-folder-name" data-folder-id="${f.id}" title="${escapeHtml(f.name)}">${escapeHtml(f.name)}</span>`;
      html += `<div class="documents-list-row documents-folder-row" data-folder-id="${f.id}" data-folder-name="${escapeHtml(f.name)}">
        <span class="documents-folder-icon">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
        </span>
        ${nameHtml}
      </div>`;
    });
  }

  // Projects scope: group by project with discrete header dividers
  if (docsState.scope === "projects") {
    const grouped = {};
    docs.forEach(d => {
      const key = d._projectTitle || "Unknown project";
      if (!grouped[key]) grouped[key] = { projectId: d._projectId, documents: [] };
      grouped[key].documents.push(d);
    });
    html += Object.entries(grouped).map(([projectTitle, group]) => {
      return `<div class="documents-project-group">
        <div class="documents-project-header">
          <span class="documents-project-title">${escapeHtml(projectTitle)}</span>
          <span class="documents-project-count">${group.documents.length} file${group.documents.length !== 1 ? "s" : ""}</span>
        </div>
        <div class="documents-project-files">
          ${group.documents.map(d => renderDocumentRow(d)).join("")}
        </div>
      </div>`;
    }).join("");
  } else {
    html += docs.map(d => renderDocumentRow(d)).join("");
  }

  list.innerHTML = html;
  bindDocumentsListEvents(list);
}

function bindDocumentsListEvents(list) {
  // Bind folder click to navigate (skip when renaming)
  list.querySelectorAll(".documents-folder-row").forEach(row => {
    row.addEventListener("click", e => {
      if (e.target.tagName === "INPUT") return;
      if (e.target.closest(".doc-rename-actions")) return;
      const folderId = Number(row.dataset.folderId);
      if (docsState.renamingFolderId === folderId) return;
      e.stopPropagation();
      const folderName = row.dataset.folderName;
      navigateToFolder(folderId, folderName);
    });
  });

  // Drag-and-drop: folder rows accept drops
  list.querySelectorAll(".documents-folder-row").forEach(row => {
    row.addEventListener("dragover", e => {
      if (docsState.scope === "projects") return;
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      row.classList.add("drag-over");
    });
    row.addEventListener("dragleave", () => {
      row.classList.remove("drag-over");
    });
    row.addEventListener("drop", async e => {
      e.preventDefault();
      row.classList.remove("drag-over");
      const docId = Number(e.dataTransfer.getData("text/doc-id"));
      const targetFolderId = Number(row.dataset.folderId);
      if (!docId || !targetFolderId) return;
      try {
        await api(`/api/v2/documents/${docId}`, {
          method: "PATCH",
          headers: {"Content-Type": "application/json"},
          body: JSON.stringify({ folder_id: targetFolderId }),
        });
        showToast("Document moved");
        loadDocumentsList();
      } catch (err) {
        showToast(err.message, true);
      }
    });
  });

  // Drag-and-drop: document rows set drag data
  list.querySelectorAll(".documents-list-row:not(.documents-folder-row)[draggable='true']").forEach(row => {
    row.addEventListener("dragstart", e => {
      e.dataTransfer.setData("text/doc-id", row.dataset.docId);
      e.dataTransfer.effectAllowed = "move";
      row.classList.add("dragging");
    });
    row.addEventListener("dragend", () => {
      row.classList.remove("dragging");
    });
  });

  // Bind folder rename confirm/cancel
  list.querySelectorAll(".doc-rename-folder-confirm").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      const folderId = Number(btn.dataset.folderId);
      const input = document.querySelector(`[data-rename-folder-input][data-folder-id="${folderId}"]`);
      confirmRenameFolder(folderId, input ? input.value : "");
    });
  });
  list.querySelectorAll(".doc-rename-folder-cancel").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      cancelRenameFolder();
    });
  });
  list.querySelectorAll("[data-rename-folder-input]").forEach(input => {
    input.addEventListener("keydown", e => {
      if (e.key === "Enter") {
        e.preventDefault();
        const folderId = Number(input.dataset.folderId);
        confirmRenameFolder(folderId, input.value);
      } else if (e.key === "Escape") {
        e.preventDefault();
        cancelRenameFolder();
      }
    });
  });

  // Bind breadcrumb clicks
  list.querySelectorAll("[data-breadcrumb-root]").forEach(el => {
    el.addEventListener("click", e => { e.stopPropagation(); navigateToRoot(); });
  });
  list.querySelectorAll("[data-breadcrumb-idx]").forEach(el => {
    el.addEventListener("click", e => {
      e.stopPropagation();
      navigateToBreadcrumb(Number(el.dataset.breadcrumbIdx));
    });
  });

  list.querySelectorAll(".doc-cb").forEach(cb => {
    cb.addEventListener("click", e => {
      e.stopPropagation();
      toggleDocSelect(Number(cb.dataset.id));
    });
  });
  list.querySelectorAll(".documents-list-row:not(.documents-folder-row)").forEach(row => {
    row.addEventListener("click", e => {
      if (e.target.tagName === "INPUT") return;
      if (e.target.closest(".doc-doc-title")) return;
      if (e.target.closest(".doc-preview-btn")) return;
      const id = Number(row.dataset.docId);
      if (docsState.selected.has(id)) {
        docsState.selected.delete(id);
        row.classList.remove("selected");
        row.querySelector(".doc-cb").checked = false;
      } else {
        docsState.selected.add(id);
        row.classList.add("selected");
        row.querySelector(".doc-cb").checked = true;
      }
      updateDocsToolbar();
    });
  });
  // Eye-icon preview button — opens the preview pane without consuming the
  // multi-select. e.stopPropagation keeps it from also toggling the row.
  list.querySelectorAll(".doc-preview-btn").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      const id = Number(btn.dataset.docId);
      if (!id) return;
      openDocumentPreview(id);
    });
  });
  list.querySelectorAll(".doc-doc-title[data-doc-id]").forEach(titleEl => {
    titleEl.addEventListener("click", e => {
      e.stopPropagation();
      const id = Number(titleEl.dataset.docId);
      if (id) openDocEditor(id);
    });
  });
  list.querySelectorAll(".doc-rename-confirm").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      const id = Number(btn.dataset.docId);
      const input = document.querySelector(`.documents-list-row[data-doc-id="${id}"] .doc-doc-title-input`);
      if (input) confirmRenameDoc(id, input.value);
    });
  });
  list.querySelectorAll(".doc-rename-cancel").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      cancelRenameDoc();
    });
  });
  list.querySelectorAll(".doc-doc-title-input").forEach(input => {
    input.addEventListener("keydown", e => {
      if (e.key === "Enter") {
        e.preventDefault();
        confirmRenameDoc(Number(input.dataset.docId), input.value);
      } else if (e.key === "Escape") {
        cancelRenameDoc();
      }
    });
    input.addEventListener("click", e => e.stopPropagation());
  });
  updateDocsToolbar();
}

function navigateToFolder(folderId, folderName) {
  // Don't push if already at this folder
  if (docsState.currentFolderId === folderId) return;
  docsState.currentFolderId = folderId;
  docsState.currentFolderPath.push({ id: folderId, name: folderName });
  docsState.selected.clear();
  loadDocumentsList();
  renderFolderTree();
}

function navigateToRoot() {
  docsState.currentFolderId = null;
  docsState.currentFolderPath = [];
  docsState.selected.clear();
  loadDocumentsList();
  renderFolderTree();
}

function navigateToBreadcrumb(idx) {
  docsState.currentFolderPath = docsState.currentFolderPath.slice(0, idx);
  docsState.currentFolderId = docsState.currentFolderPath.length > 0 ? docsState.currentFolderPath[docsState.currentFolderPath.length - 1].id : null;
  docsState.selected.clear();
  loadDocumentsList();
  renderFolderTree();
}

async function loadFolderTree() {
  const isFolderScope = docsState.scope === "mydocs" || docsState.scope === "company";
  if (!isFolderScope) {
    docsState.folderTree = [];
    renderFolderTree();
    return;
  }
  try {
    const scope = docsState.scope === "company" ? "company" : "personal";
    const data = await api(`/api/v2/documents/folders/tree?scope=${scope}`);
    docsState.folderTree = data.folders || [];
    renderFolderTree();
  } catch {
    docsState.folderTree = [];
    renderFolderTree();
  }
}

function buildFolderTreeNodes(flat, parentId) {
  return flat
    .filter(f => f.parentId === parentId)
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(f => ({
      ...f,
      children: buildFolderTreeNodes(flat, f.id),
    }));
}

function renderFolderTree() {
  const sidebar = $("#documents-sidebar");
  if (!sidebar) return;
  let treeContainer = sidebar.querySelector(".documents-folder-tree");
  const isFolderScope = docsState.scope === "mydocs" || docsState.scope === "company";

  if (!isFolderScope) {
    if (treeContainer) treeContainer.remove();
    return;
  }

  const tree = buildFolderTreeNodes(docsState.folderTree, null);

  if (!treeContainer) {
    treeContainer = document.createElement("div");
    treeContainer.className = "documents-folder-tree";
  }
  // Always reposition after the active scope button
  const activeBtn = sidebar.querySelector(".documents-scope-btn.active");
  if (activeBtn) {
    activeBtn.parentNode.insertBefore(treeContainer, activeBtn.nextSibling);
  } else {
    sidebar.appendChild(treeContainer);
  }

  if (tree.length === 0) {
    treeContainer.innerHTML = `<div style="padding:0.2rem 0.6rem;font-size:0.78rem;color:var(--muted);font-style:italic;">No folders yet</div>`;
    return;
  }

  const chevronSvg = `<svg class="documents-folder-tree-chevron" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>`;
  const folderIcon = `<svg class="documents-folder-tree-icon" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>`;

  function renderNode(node, depth) {
    const hasChildren = node.children.length > 0;
    const isExpanded = docsState.expandedFolders.has(node.id);
    const isActive = docsState.currentFolderId === node.id;
    const chevronClass = hasChildren ? (isExpanded ? " expanded" : "") : " no-children";
    let html = `<li class="documents-folder-tree-item">
      <div class="documents-folder-tree-row${isActive ? " active" : ""}" data-tree-folder-id="${node.id}" data-tree-folder-name="${escapeHtml(node.name)}" style="--tree-depth:${depth}">
        <span class="documents-folder-tree-chevron${chevronClass}" data-tree-chevron="${node.id}">${chevronSvg}</span>
        ${folderIcon}
        <span class="documents-folder-tree-name" title="${escapeHtml(node.name)}">${escapeHtml(node.name)}</span>
      </div>`;
    if (hasChildren && isExpanded) {
      html += `<ul class="documents-folder-tree-children">${node.children.map(c => renderNode(c, depth + 1)).join("")}</ul>`;
    }
    html += `</li>`;
    return html;
  }

  treeContainer.innerHTML = `<ul class="documents-folder-tree-list">${tree.map(n => renderNode(n, 0)).join("")}</ul>`;

  // Bind click handlers
  treeContainer.querySelectorAll(".documents-folder-tree-chevron").forEach(chevron => {
    chevron.addEventListener("click", e => {
      e.stopPropagation();
      const folderId = Number(chevron.dataset.treeChevron);
      if (docsState.expandedFolders.has(folderId)) {
        docsState.expandedFolders.delete(folderId);
      } else {
        docsState.expandedFolders.add(folderId);
      }
      renderFolderTree();
    });
  });
  treeContainer.querySelectorAll(".documents-folder-tree-row").forEach(row => {
    row.addEventListener("click", e => {
      e.stopPropagation();
      const folderId = Number(row.dataset.treeFolderId);
      const folderName = row.dataset.treeFolderName;
      // Build full path from tree structure
      const path = [];
      let current = docsState.folderTree.find(f => f.id === folderId);
      while (current) {
        path.unshift({ id: current.id, name: current.name });
        current = current.parentId ? docsState.folderTree.find(f => f.id === current.parentId) : null;
      }
      docsState.currentFolderPath = path;
      docsState.currentFolderId = folderId;
      docsState.selected.clear();
      loadDocumentsList();
    });
  });
}

function updateFolderTreeHighlight() {
  const sidebar = $("#documents-sidebar");
  if (!sidebar) return;
  sidebar.querySelectorAll(".documents-folder-tree-row").forEach(row => {
    const id = Number(row.dataset.treeFolderId);
    row.classList.toggle("active", id === docsState.currentFolderId);
  });
}

let folderRenamingId = null;

async function createFolder() {
  try {
    const data = await api("/api/v2/documents/folders", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        name: "New Folder",
        scope: docsState.scope === "company" ? "company" : "personal",
        parent_id: docsState.currentFolderId || null,
      }),
    });
    showToast("Folder created");
    await loadDocumentsList();
    loadFolderTree();
    if (data && data.id) {
      startRenameFolder(data.id);
    }
  } catch (err) {
    showToast(err.message, true);
  }
}

function renameFolder(folderId) {
  const folder = docsState.folders.find(f => f.id === folderId);
  if (!folder) return;
  startRenameFolder(folderId);
}

function startRenameFolder(folderId) {
  docsState.renamingFolderId = folderId;
  renderDocumentsList();
  const input = document.querySelector(`[data-rename-folder-input][data-folder-id="${folderId}"]`);
  if (input) {
    input.focus();
    input.select();
  }
}

function cancelRenameFolder() {
  docsState.renamingFolderId = null;
  renderDocumentsList();
}

async function confirmRenameFolder(folderId, newName) {
  const name = (newName || "").trim();
  if (!name) { showToast("Folder name is required", true); return; }
  const oldFolder = docsState.folders.find(f => f.id === folderId);
  if (oldFolder && oldFolder.name === name) {
    docsState.renamingFolderId = null;
    renderDocumentsList();
    return;
  }
  try {
    await api(`/api/v2/documents/folders/${folderId}`, {
      method: "PATCH",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ name }),
    });
    docsState.renamingFolderId = null;
    showToast("Folder renamed");
    loadDocumentsList();
    loadFolderTree();
  } catch (err) {
    showToast(err.message, true);
  }
}

async function deleteFolder(folderId) {
  const folder = docsState.folders.find(f => f.id === folderId);
  if (!folder) return;
  const ok = await confirmDialog({
    title: "Delete folder",
    message: `Delete folder "${folder.name}" and everything inside it? This cannot be undone.`,
    confirmLabel: "Delete",
    danger: true,
  });
  if (!ok) return;
  try {
    await api(`/api/v2/documents/folders/${folderId}`, { method: "DELETE" });
    showToast("Folder deleted");
    loadDocumentsList();
    loadFolderTree();
  } catch (err) {
    showToast(err.message, true);
  }
}

async function createBlankDocument(type, oppId) {
  const defaultName = type === "word" ? "New Document" : "New Spreadsheet";
  try {
    const body = {
      type,
      title: defaultName,
      scope: oppId ? "project" : (docsState.scope === "company" ? "company" : "personal"),
      folder_id: oppId ? null : (docsState.currentFolderId || null),
      opportunity_id: oppId || null,
    };
    const data = await api("/api/v2/documents/create", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(body),
    });
    showToast(`${type === "word" ? "Word" : "Excel"} document created`);
    // Always refresh the relevant list and auto-open the editor in a new tab.
    if (oppId) {
      // Project-scoped: refresh the project's Documents tab and notify any
      // listeners via the same CustomEvent pattern used by invoice/COC saves.
      document.dispatchEvent(new CustomEvent("document-created", {
        detail: { oppId, docId: data.id, mimeType: data.mimeType },
      }));
    } else {
      await loadDocumentsList();
    }
    if (data && data.id) {
      // Auto-open the new doc in a new tab (both standalone + project paths).
      if (data.editUrl) {
        try { window.open(data.editUrl, "_blank"); } catch (e) { /* popup blocked */ }
      }
      // Inline rename for the standalone path only (project path stays toast-only
      // since the user is opening the editor and will rename from there).
      if (!oppId) {
        startRenameDoc(data.id);
      }
    }
  } catch (err) {
    showToast(err.message, true);
  }
}

function updateDocsToolbarForScope() {
  const isProjects = docsState.scope === "projects";
  const uploadBtn = $("#documents-upload-btn");
  const newWrap = document.querySelector(".documents-new-wrap");
  if (uploadBtn) uploadBtn.classList.toggle("hidden", isProjects);
  if (newWrap) newWrap.classList.toggle("hidden", isProjects);
}

function toggleDocSelect(id) {
  if (docsState.selected.has(id)) {
    docsState.selected.delete(id);
  } else {
    docsState.selected.add(id);
  }
  const row = document.querySelector(`.documents-list-row[data-doc-id="${id}"]`);
  if (row) row.classList.toggle("selected", docsState.selected.has(id));
  updateDocsToolbar();
}

function updateDocsToolbar() {
  const n = docsState.selected.size;
  const countEl = $("#documents-selected-count");
  const actionsBtn = $("#documents-actions-btn");
  const clearBtn = $("#documents-clear-selection-btn");
  const renameBtn = $("#documents-rename-btn");
  if (countEl) {
    countEl.textContent = n ? `${n} selected` : "0 selected";
    countEl.classList.toggle("hidden", !n);
  }
  if (actionsBtn) actionsBtn.disabled = !n;
  if (clearBtn) clearBtn.classList.toggle("hidden", !n);
  if (renameBtn) renameBtn.classList.toggle("hidden", n !== 1);
}

async function deleteSelectedDocs() {
  if (!docsState.selected.size) return;
  const n = docsState.selected.size;
  const ok = await confirmDialog({
    title: "Delete documents",
    message: `Delete ${n} document${n > 1 ? "s" : ""}? This cannot be undone.`,
    confirmLabel: "Delete",
    danger: true,
  });
  if (!ok) return;
  try {
    await api("/api/v2/documents/batch-delete", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ ids: Array.from(docsState.selected) }),
    });
    docsState.selected.clear();
    showToast(`Deleted ${n} document${n > 1 ? "s" : ""}`);
    loadDocumentsList();
  } catch (err) {
    showToast(err.message, true);
  }
}

function startRenameDoc(docId) {
  docsState.renamingId = docId;
  // Select only the renamed doc
  docsState.selected.clear();
  docsState.selected.add(docId);
  renderDocumentsList();
  const input = document.querySelector(`.documents-list-row[data-doc-id="${docId}"] .doc-doc-title-input`);
  if (input) {
    input.focus();
    input.select();
  }
  updateDocsToolbar();
}

function cancelRenameDoc() {
  docsState.renamingId = null;
  renderDocumentsList();
  updateDocsToolbar();
}

async function confirmRenameDoc(docId, newTitle) {
  const title = (newTitle || "").trim();
  if (!title) { showToast("File name is required", true); return; }
  const oldDoc = docsState.documents.find(d => d.id === docId);
  if (oldDoc && oldDoc.title === title) {
    docsState.renamingId = null;
    renderDocumentsList();
    updateDocsToolbar();
    return;
  }
  try {
    await api(`/api/v2/documents/${docId}`, {
      method: "PATCH",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ title }),
    });
    docsState.renamingId = null;
    showToast("Document renamed");
    loadDocumentsList();
  } catch (err) {
    showToast(err.message, true);
  }
}

let moveCopyPanelMode = null; // 'move' | 'copy'
let moveCopyPanelTargetProjectId = null;
let moveCopyPanelJustOpened = false;

function hideMoveCopyPanel() {
  const panel = $("#documents-move-copy-panel");
  if (panel) panel.classList.add("hidden");
  moveCopyPanelMode = null;
  moveCopyPanelTargetProjectId = null;
  const input = $("#documents-move-copy-project-input");
  if (input) input.value = "";
  const results = $("#documents-move-copy-project-results");
  if (results) results.classList.add("hidden");
  updateMoveCopyConfirmState();
}

function updateMoveCopyConfirmState() {
  const dest = $("#documents-move-copy-dest")?.value || "project";
  const confirmBtn = $("#documents-move-copy-confirm");
  if (!confirmBtn) return;
  const disabled = dest === "project" && !moveCopyPanelTargetProjectId;
  confirmBtn.disabled = disabled;
}

async function searchProjectsForMoveCopy(q) {
  if (!q || q.length < 2) return [];
  try {
    const data = await api(`/api/v2/projects/simple?q=${encodeURIComponent(q)}`);
    return data.projects || [];
  } catch {
    return [];
  }
}

function showMoveCopyPanel(mode) {
  if (!docsState.selected.size) return;
  moveCopyPanelMode = mode;
  moveCopyPanelTargetProjectId = null;
  moveCopyPanelJustOpened = true;
  const panel = $("#documents-move-copy-panel");
  const title = $("#documents-move-copy-title");
  const dest = $("#documents-move-copy-dest");
  const projectWrap = $("#documents-move-copy-project-wrap");
  const input = $("#documents-move-copy-project-input");
  const results = $("#documents-move-copy-project-results");
  if (!panel) return;
  if (title) title.textContent = mode === "move" ? "Move to" : "Copy to";
  if (dest) dest.value = "project";
  if (input) input.value = "";
  if (results) results.classList.add("hidden");
  if (projectWrap) projectWrap.classList.remove("hidden");
  panel.classList.remove("hidden");
  updateMoveCopyConfirmState();
  if (input) input.focus();
  setTimeout(() => { moveCopyPanelJustOpened = false; }, 100);
}

async function executeMoveCopyPanel() {
  const dest = $("#documents-move-copy-dest")?.value || "project";
  const ids = Array.from(docsState.selected);
  let body;
  if (dest === "project") {
    if (!moveCopyPanelTargetProjectId) return;
    body = { ids, opportunity_id: moveCopyPanelTargetProjectId };
  } else if (dest === "company") {
    body = { ids, company_scope: true };
  } else {
    body = { ids };
  }
  const endpoint = moveCopyPanelMode === "move" ? "/api/v2/documents/batch-move" : "/api/v2/documents/batch-copy";
  const successMsg = moveCopyPanelMode === "move" ? "Documents moved" : "Documents copied";
  try {
    await api(endpoint, {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(body),
    });
    docsState.selected.clear();
    docsState.renamingId = null;
    hideMoveCopyPanel();
    showToast(successMsg);
    loadDocumentsList();
  } catch (err) {
    showToast(err.message, true);
  }
}

function bindMoveCopyPanel() {
  const panel = $("#documents-move-copy-panel");
  const dest = $("#documents-move-copy-dest");
  const input = $("#documents-move-copy-project-input");
  const results = $("#documents-move-copy-project-results");
  const confirmBtn = $("#documents-move-copy-confirm");
  const cancelBtn = $("#documents-move-copy-cancel");
  const closeBtn = $("#documents-move-copy-close");
  if (!panel || panel.dataset.bound) return;
  panel.dataset.bound = "1";

  if (dest) {
    dest.addEventListener("change", () => {
      const isProject = dest.value === "project";
      $("#documents-move-copy-project-wrap")?.classList.toggle("hidden", !isProject);
      if (isProject) {
        moveCopyPanelTargetProjectId = null;
        if (input) input.value = "";
        if (results) results.classList.add("hidden");
      }
      updateMoveCopyConfirmState();
    });
  }

  if (input) {
    let debounce;
    input.addEventListener("input", () => {
      clearTimeout(debounce);
      const q = input.value.trim();
      if (!q || q.length < 2) {
        if (results) results.classList.add("hidden");
        moveCopyPanelTargetProjectId = null;
        updateMoveCopyConfirmState();
        return;
      }
      debounce = setTimeout(async () => {
        const projects = await searchProjectsForMoveCopy(q);
        if (!results) return;
        results.innerHTML = "";
        if (!projects.length) {
          results.innerHTML = '<button type="button" disabled>No matches</button>';
          results.classList.remove("hidden");
          return;
        }
        projects.forEach(p => {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.textContent = p.title || `Project ${p.id}`;
          btn.addEventListener("click", () => {
            moveCopyPanelTargetProjectId = p.id;
            input.value = p.title || `Project ${p.id}`;
            results.classList.add("hidden");
            updateMoveCopyConfirmState();
          });
          results.appendChild(btn);
        });
        results.classList.remove("hidden");
      }, 250);
    });

    input.addEventListener("keydown", e => {
      if (e.key === "Escape") {
        if (results) results.classList.add("hidden");
      }
    });
  }

  document.addEventListener("click", e => {
    if (moveCopyPanelJustOpened) return;
    if (!panel.classList.contains("hidden") && !panel.contains(e.target)) {
      hideMoveCopyPanel();
    }
  });

  confirmBtn?.addEventListener("click", () => executeMoveCopyPanel());
  cancelBtn?.addEventListener("click", hideMoveCopyPanel);
  closeBtn?.addEventListener("click", hideMoveCopyPanel);
}

async function moveSelectedDocs() {
  showMoveCopyPanel("move");
}

async function copySelectedDocs() {
  showMoveCopyPanel("copy");
}

function openDocEditor(docId) {
  window.open(`/doc-editor.html?id=${docId}`, "_blank");
}

// ── Document preview pane ──────────────────────────────────────────────────

function _setPreviewOpen(open) {
  const pane = $("#documents-preview-pane");
  if (!pane) return;
  docsState.previewOpen = !!open;
  if (open) {
    pane.classList.remove("documents-preview-pane-collapsed");
    // Auto-collapse the left directory sidebar so the preview pane gets more
    // width. Leave it collapsed on preview close — user can re-open via toggle.
    const sidebar = $("#documents-sidebar");
    const sidebarToggle = $("#documents-sidebar-toggle");
    if (sidebar && sidebarToggle && !sidebar.classList.contains("documents-sidebar-collapsed")) {
      sidebar.classList.add("documents-sidebar-collapsed");
      sidebarToggle.textContent = "▶";
      sidebarToggle.setAttribute("aria-label", "Show sidebar");
      sidebarToggle.setAttribute("title", "Show sidebar");
    }
  } else {
    pane.classList.add("documents-preview-pane-collapsed");
    // Reset iframe to release the editor session when fully hidden.
    const iframe = $("#documents-preview-iframe");
    if (iframe) iframe.src = "about:blank";
    const empty = $("#documents-preview-empty");
    const frame = $("#documents-preview-iframe");
    if (empty) empty.style.display = "flex";
    if (frame) frame.classList.add("hidden");
    docsState.previewDocId = null;
    docsState.previewDocTitle = null;
  }
}

function _renderPreviewActivity(events) {
  const el = $("#documents-preview-activity");
  if (!el) return;
  if (!events || !events.length) {
    // Collapse to zero height when empty so the preview pane doesn't show a
    // dark band between the file-name header and the toolbar.
    el.innerHTML = "";
    el.style.display = "none";
    return;
  }
  el.style.display = "";
  // Header line: who opened most recently (or last save/rename).
  const latest = events[0];
  const actionVerb = {
    opened: "opened",
    saved: "edited",
    renamed: "renamed",
    closed: "closed",
  }[latest.action] || latest.action;
  let html = `<div class="documents-preview-activity-row">`;
  html += `<span class="documents-preview-activity-avatar">${escapeHtml((latest.userName || "?").slice(0, 1).toUpperCase())}</span>`;
  html += `<span class="documents-preview-activity-meta">Last ${actionVerb} by <strong>${escapeHtml(latest.userName || "—")}</strong> · ${escapeHtml(formatRelativeTime(latest.createdAt))}</span>`;
  html += `</div>`;
  // Group "opened" by user → "X editors today"
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const opens = events.filter(e => e.action === "opened" && new Date(e.createdAt) >= today);
  const uniqueEditorsToday = new Set(opens.map(e => e.userId).filter(Boolean)).size;
  if (uniqueEditorsToday > 1) {
    html += `<div class="documents-preview-activity-row" style="margin-top:0.25rem;"><span class="documents-preview-activity-meta" style="padding-left:1.9rem;">👥 ${uniqueEditorsToday} editors today</span></div>`;
  }
  el.innerHTML = html;
}

async function _refreshPreviewActivity(docId) {
  if (!docId) return;
  try {
    const data = await api(`/api/v2/documents/${docId}/activity?limit=20`);
    docsState.previewActivity = data.events || [];
    _renderPreviewActivity(docsState.previewActivity);
  } catch (err) {
    const el = $("#documents-preview-activity");
    if (el) el.textContent = "";
    // Preview pane still works without activity; just leave it silent.
    logger && logger.debug && logger.debug("preview activity fetch failed", err);
  }
}

async function openDocumentPreview(docId) {
  const pane = $("#documents-preview-pane");
  const iframe = $("#documents-preview-iframe");
  const empty = $("#documents-preview-empty");
  const titleText = $("#documents-preview-title-text");
  const openBtn = $("#documents-preview-open");
  if (!pane || !iframe || !empty || !titleText || !openBtn) return;

  // If user clicked the same doc again, treat as no-op (pane is already showing it).
  if (docsState.previewDocId === docId && docsState.previewOpen) {
    // Just refresh activity in case more events came in.
    _refreshPreviewActivity(docId);
    return;
  }

  // Look up title in current docsState first; fall back to no title.
  const doc = (docsState.documents || []).find(d => String(d.id) === String(docId));
  const title = doc?.title || docsState.previewDocTitle || "Document";
  docsState.previewDocId = docId;
  docsState.previewDocTitle = title;
  titleText.textContent = title.length > 60 ? title.slice(0, 57) + "…" : title;
  openBtn.disabled = false;
  empty.style.display = "none";
  iframe.classList.remove("hidden");
  // Lightweight viewer by default; doc-preview.html falls back to OnlyOffice
  // automatically for legacy formats or files > 15 MB (via postMessage).
  iframe.src = `/doc-preview.html?id=${docId}&embedded=1&title=${encodeURIComponent(title)}`;
  _setPreviewOpen(true);
  _refreshPreviewActivity(docId);
}

function closeDocumentPreview() {
  _setPreviewOpen(false);
}

async function bindDocumentsPreviewPane() {
  const closeBtn = $("#documents-preview-close");
  if (closeBtn && !closeBtn.dataset.bound) {
    closeBtn.dataset.bound = "1";
    closeBtn.addEventListener("click", closeDocumentPreview);
  }
  const openBtn = $("#documents-preview-open");
  if (openBtn && !openBtn.dataset.bound) {
    openBtn.dataset.bound = "1";
    openBtn.addEventListener("click", () => {
      if (!docsState.previewDocId) return;
      openDocEditor(docsState.previewDocId);
    });
  }
  // Listen for fallback requests from doc-preview.html (lightweight viewer).
  // When a doc is > 15 MB or in a legacy format, the lightweight viewer
  // postMessages here and we swap the iframe to the existing OnlyOffice
  // view-only editor (preserves the "stay-in-pane" UX).
  if (!window._docsPreviewFallbackBound) {
    window._docsPreviewFallbackBound = true;
    window.addEventListener("message", (ev) => {
      if (ev.origin !== window.location.origin) return;
      const data = ev.data;
      if (!data || data.type !== "docs-preview-fallback") return;
      if (!docsState.previewDocId || String(data.docId) !== String(docsState.previewDocId)) return;
      const iframe = $("#documents-preview-iframe");
      if (!iframe) return;
      iframe.src = `/doc-editor.html?id=${docsState.previewDocId}&embedded=1&mode=view`;
    });
  }
}

function _documentsPreviewCleanupOnClose() {
  // Reset preview pane state when the modal fully closes (not on minimize —
  // minimize keeps the doc, restore re-renders it).
  const iframe = $("#documents-preview-iframe");
  if (iframe) iframe.src = "about:blank";
  docsState.previewDocId = null;
  docsState.previewDocTitle = null;
  docsState.previewActivity = [];
  _setPreviewOpen(false);
}

function _docsPreviewCurrentPayload() {
  // Snapshot for the minimize/restore payloads so we can restore the same doc.
  return {
    previewOpen: docsState.previewOpen,
    previewDocId: docsState.previewDocId,
    previewDocTitle: docsState.previewDocTitle,
  };
}

function _docsPreviewRestoreFromPayload(p) {
  if (!p || !p.previewDocId) return;
  docsState.previewDocTitle = p.previewDocTitle || null;
  // Defer DOM updates until next tick — the modal element may not be visible yet.
  setTimeout(() => {
    openDocumentPreview(p.previewDocId);
  }, 50);
}

// Human-friendly "5m ago / 2h ago / yesterday" — falls back to date if >7d.
function formatRelativeTime(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  const diff = Date.now() - d.getTime();
  const sec = Math.max(1, Math.floor(diff / 1000));
  if (sec < 60) return `${sec}s ago`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const day = Math.floor(hr / 24);
  if (day < 7) return day === 1 ? "yesterday" : `${day}d ago`;
  return d.toLocaleDateString();
}



function downloadDoc(docId, title) {
  const a = document.createElement("a");
  a.href = `/api/v2/documents/${docId}`;
  a.download = title || "document";
  a.click();
}

async function uploadDocsToCurrentScope(files) {
  if (!files || !files.length) return;
  const isCompany = docsState.scope === "company";
  const isPersonal = docsState.scope === "mydocs";
  const uploadEndpoint = isCompany ? "/api/v2/documents/company/upload" : isPersonal ? "/api/v2/documents/personal/upload" : docsState.currentProjectId ? `/api/v2/projects/${docsState.currentProjectId}/documents` : null;
  if (!uploadEndpoint) { showToast("Select a project first", true); return; }
  let ok = 0, fail = 0;
  for (const file of files) {
    const formData = new FormData();
    formData.append("file", file);
    if ((isCompany || isPersonal) && docsState.currentFolderId) {
      formData.append("folder_id", String(docsState.currentFolderId));
    }
    try {
      await fetch(uploadEndpoint, { method: "POST", credentials: "same-origin", body: formData });
      ok++;
    } catch {
      fail++;
    }
  }
  if (ok) showToast(`Uploaded ${ok} file${ok > 1 ? "s" : ""}`);
  if (fail) showToast(`Failed to upload ${fail} file${fail > 1 ? "s" : ""}`, true);
  loadDocumentsList();
}

function bindDocumentsModal() {
  const modal = $("#documents-modal");
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = "1";

  // Preview pane (eye-icon + header buttons + toggle strip)
  bindDocumentsPreviewPane();

  // Backdrop click -> minimize instead of close
  const docsBackdrop = modal.querySelector(".modal-backdrop");
  if (docsBackdrop) {
    docsBackdrop.addEventListener("click", minimizeDocsModal);
  }
  $("#documents-modal-close")?.addEventListener("click", closeDocumentsModal);
  $("#documents-modal-minimize")?.addEventListener("click", minimizeDocsModal);
  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && !modal.classList.contains("hidden")) closeDocumentsModal();
  });

  // Scope sidebar
  document.querySelectorAll(".documents-scope-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      docsState.scope = btn.dataset.scope;
      docsState.currentProjectId = null;
      docsState.currentProjectTitle = null;
      docsState.currentFolderId = null;
      docsState.currentFolderPath = [];
      docsState.folders = [];
      docsState.selected.clear();
      docsState.searchQuery = "";
      const searchInput = $("#documents-search-input");
      if (searchInput) searchInput.value = "";
      document.querySelectorAll(".documents-scope-btn").forEach(b => b.classList.toggle("active", b === btn));
      updateDocsToolbarForScope();
      loadDocumentsList();
      loadFolderTree();
    });
  });

  // Sidebar toggle (like mail modal)
  const sidebarToggle = $("#documents-sidebar-toggle");
  const sidebar = $("#documents-sidebar");
  if (sidebarToggle && sidebar) {
    sidebarToggle.addEventListener("click", () => {
      const collapsed = sidebar.classList.toggle("documents-sidebar-collapsed");
      sidebarToggle.textContent = collapsed ? "▶" : "◀";
      sidebarToggle.setAttribute("aria-label", collapsed ? "Show sidebar" : "Hide sidebar");
      sidebarToggle.setAttribute("title", collapsed ? "Show sidebar" : "Hide sidebar");
    });
  }

  // Search
  const searchInput = $("#documents-search-input");
  if (searchInput) {
    let t = null;
    searchInput.addEventListener("input", () => {
      clearTimeout(t);
      t = setTimeout(() => {
        docsState.searchQuery = searchInput.value.trim();
        loadDocumentsList();
      }, 300);
    });
  }

  // Toolbar actions — custom dropdown
  const actionsBtn = $("#documents-actions-btn");
  const actionsMenu = $("#documents-actions-menu");
  if (actionsBtn && actionsMenu) {
    actionsBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (actionsBtn.disabled) return;
      actionsMenu.classList.toggle("hidden");
      // Position fixed on mobile
      if (!actionsMenu.classList.contains("hidden") && window.innerWidth <= 600) {
        const r = actionsBtn.getBoundingClientRect();
        actionsMenu.style.position = "fixed";
        actionsMenu.style.top = (r.bottom + 4) + "px";
        actionsMenu.style.left = r.left + "px";
        actionsMenu.style.right = "auto";
      }
    });
    actionsMenu.querySelectorAll(".documents-actions-option").forEach(opt => {
      opt.addEventListener("click", () => {
        const val = opt.dataset.action;
        if (val === "delete") deleteSelectedDocs();
        else if (val === "move") moveSelectedDocs();
        else if (val === "copy") copySelectedDocs();
        actionsMenu.classList.add("hidden");
      });
    });
    document.addEventListener("click", (e) => {
      if (!actionsMenu.classList.contains("hidden") && !actionsBtn.contains(e.target) && !actionsMenu.contains(e.target)) {
        actionsMenu.classList.add("hidden");
      }
    });
  }

  // Sort button + custom menu
  const sortBtn = $("#documents-sort-btn");
  const sortMenu = $("#documents-sort-menu");
  function updateSortMenu() {
    if (!sortMenu) return;
    sortMenu.querySelectorAll(".documents-sort-option").forEach(btn => {
      const selected = btn.dataset.sort === docsState.sort;
      btn.classList.toggle("selected", selected);
      btn.setAttribute("aria-checked", String(selected));
    });
  }
  function toggleSortMenu(show) {
    if (!sortMenu) return;
    if (typeof show === "boolean") {
      sortMenu.classList.toggle("hidden", !show);
    } else {
      sortMenu.classList.toggle("hidden");
    }
    // Reset inline positioning styles when closing
    if (sortMenu.classList.contains("hidden")) {
      sortMenu.style.position = "";
      sortMenu.style.top = "";
      sortMenu.style.left = "";
      sortMenu.style.right = "";
    }
    updateSortMenu();
  }
  if (sortBtn && sortMenu) {
    updateSortMenu();
    sortBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleSortMenu();
      // On mobile, position the menu fixed below the button
      if (!sortMenu.classList.contains("hidden") && window.innerWidth <= 600) {
        const r = sortBtn.getBoundingClientRect();
        sortMenu.style.position = "fixed";
        sortMenu.style.top = (r.bottom + 4) + "px";
        sortMenu.style.left = r.left + "px";
        sortMenu.style.right = "auto";
      }
    });
    sortMenu.querySelectorAll(".documents-sort-option").forEach(btn => {
      btn.addEventListener("click", () => {
        docsState.sort = btn.dataset.sort;
        renderDocumentsList();
        updateSortMenu();
        toggleSortMenu(false);
      });
    });
    document.addEventListener("click", e => {
      if (!sortMenu.classList.contains("hidden") && !sortBtn.contains(e.target) && !sortMenu.contains(e.target)) {
        toggleSortMenu(false);
      }
    });
  }
  $("#documents-clear-selection-btn")?.addEventListener("click", () => {
    docsState.selected.clear();
    docsState.renamingId = null;
    document.querySelectorAll(".doc-cb").forEach(cb => { cb.checked = false; });
    document.querySelectorAll(".documents-list-row").forEach(row => row.classList.remove("selected"));
    renderDocumentsList();
    updateDocsToolbar();
  });
  $("#documents-rename-btn")?.addEventListener("click", () => {
    if (docsState.selected.size !== 1) return;
    const id = Array.from(docsState.selected)[0];
    startRenameDoc(id);
  });

  // Upload
  const uploadBtn = $("#documents-upload-btn");
  if (uploadBtn) {
    uploadBtn.addEventListener("click", () => {
      const input = document.createElement("input");
      input.type = "file";
      input.multiple = true;
      input.accept = ".doc,.docx,.xls,.xlsx,.ppt,.pptx,.pdf,.txt,.csv,.png,.jpg,.jpeg,.gif,.zip,.rar";
      input.onchange = () => uploadDocsToCurrentScope(Array.from(input.files));
      input.click();
    });
  }

  // Drag and drop upload
  const dropOverlay = $("#documents-drop-overlay");
  if (dropOverlay) {
    modal.addEventListener("dragover", e => {
      e.preventDefault();
      dropOverlay.classList.remove("hidden");
    });
    modal.addEventListener("dragleave", e => {
      if (!modal.contains(e.relatedTarget)) dropOverlay.classList.add("hidden");
    });
    modal.addEventListener("drop", e => {
      e.preventDefault();
      dropOverlay.classList.add("hidden");
      const files = Array.from(e.dataTransfer.files).filter(f => f.size > 0);
      if (files.length) uploadDocsToCurrentScope(files);
    });
  }

  // Move/Copy popup panel
  bindMoveCopyPanel();

  // Right-click context menu
  const ctxMenu = $("#documents-ctx");
  let ctxDocId = null;
  let ctxDocTitle = null;
  let ctxFolderId = null;

  function showDocCtxMenu(e, docId, title) {
    e.preventDefault();
    ctxDocId = docId;
    ctxDocTitle = title;
    ctxFolderId = null;
    // Hide folder items, show doc items
    ctxMenu.querySelectorAll(".ctx-folder-item").forEach(i => i.classList.add("hidden"));
    ctxMenu.querySelectorAll("[data-folder-divider]").forEach(d => d.classList.add("hidden"));
    ctxMenu.querySelectorAll(".ctx-menu-item[data-doc-ctx]").forEach(item => {
      if (!item.classList.contains("ctx-folder-item")) {
        item.classList.remove("hidden");
        item.dataset.docId = String(docId);
      }
    });
    positionCtxMenu(e);
  }

  function showFolderCtxMenu(e, folderId, folderName) {
    e.preventDefault();
    ctxFolderId = folderId;
    ctxDocId = null;
    ctxDocTitle = null;
    // Hide doc items, show folder items
    ctxMenu.querySelectorAll(".ctx-menu-item[data-doc-ctx]:not(.ctx-folder-item)").forEach(i => i.classList.add("hidden"));
    ctxMenu.querySelectorAll("[data-folder-divider]").forEach(d => d.classList.remove("hidden"));
    ctxMenu.querySelectorAll(".ctx-folder-item").forEach(item => {
      item.classList.remove("hidden");
      item.dataset.folderId = String(folderId);
    });
    positionCtxMenu(e);
  }

  function positionCtxMenu(e) {
    const rect = modal.getBoundingClientRect();
    let x = e.clientX - rect.left + modal.scrollLeft;
    let y = e.clientY - rect.top + modal.scrollTop;
    const mw = 200, mh = ctxMenu.offsetHeight || 240;
    if (x + mw > modal.clientWidth) x = modal.clientWidth - mw - 8;
    if (y + mh > modal.clientHeight) y = modal.clientHeight - mh - 8;
    ctxMenu.style.left = x + "px";
    ctxMenu.style.top = y + "px";
    ctxMenu.classList.remove("hidden");
  }

  function hideDocCtxMenu() {
    ctxMenu.classList.add("hidden");
    ctxDocId = null;
    ctxDocTitle = null;
    ctxFolderId = null;
  }

  document.getElementById("documents-list")?.addEventListener("contextmenu", e => {
    const folderRow = e.target.closest(".documents-folder-row");
    if (folderRow) {
      e.preventDefault();
      const id = Number(folderRow.dataset.folderId);
      const name = folderRow.dataset.folderName || "";
      showFolderCtxMenu(e, id, name);
      return;
    }
    const row = e.target.closest(".documents-list-row");
    if (!row) return;
    e.preventDefault();
    const id = Number(row.dataset.docId);
    const title = row.querySelector(".doc-doc-title")?.textContent || "";
    showDocCtxMenu(e, id, title);
  });

  ctxMenu.addEventListener("click", async e => {
    const btn = e.target.closest(".ctx-menu-item");
    if (!btn) return;
    const action = btn.dataset.docCtx;
    // Folder actions
    if (action === "rename-folder") {
      const fid = Number(btn.dataset.folderId);
      hideDocCtxMenu();
      renameFolder(fid);
      return;
    }
    if (action === "delete-folder") {
      const fid = Number(btn.dataset.folderId);
      hideDocCtxMenu();
      deleteFolder(fid);
      return;
    }
    // Document actions
    const docId = ctxDocId;
    hideDocCtxMenu();
    if (!docId) return;
    if (action === "preview") {
      openDocumentPreview(docId);
    } else if (action === "open") {
      openDocEditor(docId);
    } else if (action === "download") {
      downloadDoc(docId, ctxDocTitle);
    } else if (action === "rename") {
      startRenameDoc(docId);
    } else if (action === "move") {
      docsState.selected.clear();
      docsState.selected.add(docId);
      renderDocumentsList();
      updateDocsToolbar();
      showMoveCopyPanel("move");
    } else if (action === "copy") {
      docsState.selected.clear();
      docsState.selected.add(docId);
      renderDocumentsList();
      updateDocsToolbar();
      showMoveCopyPanel("copy");
    } else if (action === "delete") {
      const ok = await confirmDialog({
        title: "Delete document",
        message: `Delete "${ctxDocTitle || "this document"}"? This cannot be undone.`,
        confirmLabel: "Delete",
        danger: true,
      });
      if (!ok) return;
      try {
        await api(`/api/v2/documents/batch-delete`, {
          method: "POST",
          headers: {"Content-Type": "application/json"},
          body: JSON.stringify({ ids: [docId] }),
        });
        showToast("Document deleted");
        loadDocumentsList();
      } catch (err) {
        showToast(err.message, true);
      }
    }
  });

  document.addEventListener("click", e => {
    if (!ctxMenu.classList.contains("hidden") && !ctxMenu.contains(e.target)) {
      hideDocCtxMenu();
    }
  });

  document.addEventListener("keydown", e => {
    if (e.key === "Escape" && !ctxMenu.classList.contains("hidden")) hideDocCtxMenu();
  });

  // New button + menu
  const newBtn = $("#documents-new-btn");
  const newMenu = $("#documents-new-menu");
  if (newBtn && newMenu) {
    newBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      newMenu.classList.toggle("hidden");
    });
    newMenu.querySelectorAll(".documents-new-option").forEach(opt => {
      opt.addEventListener("click", () => {
        newMenu.classList.add("hidden");
        const action = opt.dataset.new;
        if (action === "word" || action === "excel") {
          createBlankDocument(action);
        } else if (action === "folder") {
          createFolder();
        } else if (action === "invoice") {
          openInvoiceModal(null, "standalone");
        } else if (action === "coc") {
          openCocModal(null, "standalone");
        }
      });
    });
    document.addEventListener("click", (e) => {
      if (!newMenu.classList.contains("hidden") && !newBtn.contains(e.target) && !newMenu.contains(e.target)) {
        newMenu.classList.add("hidden");
      }
    });
  }
}

// ── Calendar Settings Modal ──────────────────────────────────────────────────

function openCalendarSettingsModal() {
  const modal = $("#calendar-settings-modal");
  if (!modal) return;
  loadCalendarSourcesList();
  modal.classList.remove("hidden");
}

function closeCalendarSettingsModal() {
  $("#calendar-settings-modal")?.classList.add("hidden");
}

async function loadCalendarSourcesList() {
  const list = $("#calendar-settings-sources-list");
  if (!list) return;
  try {
    const data = await api("/api/v2/calendar/sources");
    const sources = data.sources || [];
    if (!sources.length) {
      list.innerHTML = '<p class="calendar-settings-empty">No calendars connected yet.</p>';
      return;
    }
    list.innerHTML = sources.map(s => `
      <div class="calendar-settings-source-row" data-source-id="${s.id}">
        <div class="source-color-dot" style="background:${escapeHtml(s.color || "#5b8abf")}"></div>
        <div class="source-info">
          <div class="source-name">${escapeHtml(s.name || "Calendar")}</div>
          <div class="source-detail">${escapeHtml(s.oauth_email || s.ics_url || s.caldav_url || s.source_type)}</div>
        </div>
        <button type="button" class="source-remove" title="Remove" data-remove-source="${s.id}"><i class="ti ti-trash"></i></button>
      </div>
    `).join("");
    list.querySelectorAll("[data-remove-source]").forEach(btn => {
      btn.addEventListener("click", async () => {
        const id = btn.dataset.removeSource;
        if (!confirm("Remove this calendar source?")) return;
        try {
          await api(`/api/v2/calendar/sources/${id}`, { method: "DELETE" });
          loadCalendarSourcesList();
        } catch (e) { showToast(e.message, true); }
      });
    });
  } catch (e) {
    list.innerHTML = `<p class="calendar-settings-empty">Failed to load: ${escapeHtml(e.message)}</p>`;
  }
}

function bindCalendarSettingsModal() {
  const modal = $("#calendar-settings-modal");
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = "1";
  modal.querySelectorAll("[data-calendar-settings-dismiss]").forEach(el => {
    el.addEventListener("click", closeCalendarSettingsModal);
  });
  const addBtn = $("#calendar-settings-add-source");
  const addForm = $("#calendar-settings-add-form");
  const cancelBtn = $("#cal-settings-add-cancel");
  const saveBtn = $("#cal-settings-add-save");
  addBtn?.addEventListener("click", () => addForm?.classList.toggle("hidden"));
  cancelBtn?.addEventListener("click", () => addForm?.classList.add("hidden"));

  // Source type switching in settings modal
  modal.querySelectorAll(".calendar-source-type-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      modal.querySelectorAll(".calendar-source-type-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      const t = btn.dataset.sourceType;
      $("#cal-settings-ics-fields")?.classList.toggle("hidden", t !== "ics");
      $("#cal-settings-caldav-fields")?.classList.toggle("hidden", t !== "caldav");
      $("#cal-settings-oauth-info")?.classList.toggle("hidden", t !== "google_oauth" && t !== "microsoft_oauth");
    });
  });

  saveBtn?.addEventListener("click", async () => {
    const activeType = modal.querySelector(".calendar-source-type-btn.active")?.dataset.sourceType || "ics";
    const name = $("#cal-settings-src-name")?.value?.trim() || "Calendar";
    let body = { name, source_type: activeType };
    if (activeType === "ics") body.ics_url = $("#cal-settings-ics-url")?.value?.trim();
    else if (activeType === "caldav") {
      body.caldav_url = $("#cal-settings-caldav-url")?.value?.trim();
      body.caldav_username = $("#cal-settings-caldav-user")?.value?.trim();
      body.caldav_password = $("#cal-settings-caldav-pass")?.value;
    } else if (activeType === "google_oauth" || activeType === "microsoft_oauth") {
      const provider = activeType === "google_oauth" ? "google" : "microsoft";
      try {
        const data = await api(`/api/v2/calendar/oauth/authorize?provider=${provider}`, { method: "POST" });
        if (data.url) { window.location.href = data.url; return; }
      } catch (e) { showToast(e.message, true); return; }
    }
    try {
      const data = await api("/api/v2/calendar/sources", {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
      });
      if (data.ok) {
        addForm?.classList.add("hidden");
        loadCalendarSourcesList();
        showToast("Calendar connected");
      } else {
        showToast(data.error || "Failed", true);
      }
    } catch (e) { showToast(e.message, true); }
  });

  // Notification preference checkboxes
  const browserCb = $("#cal-settings-browser-notif");
  const telegramCb = $("#cal-settings-telegram-notif");
  async function loadCalendarSettings() {
    try {
      const data = await api("/api/v2/calendar/settings");
      if (browserCb) browserCb.checked = data.browser_notifications !== false;
      if (telegramCb) telegramCb.checked = data.telegram_notifications !== false;
    } catch { /* ignore */ }
  }
  async function saveCalendarNotifPref() {
    try {
      await api("/api/v2/calendar/settings", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          browser_notifications: browserCb?.checked,
          telegram_notifications: telegramCb?.checked,
        }),
      });
    } catch { /* ignore */ }
  }
  browserCb?.addEventListener("change", saveCalendarNotifPref);
  telegramCb?.addEventListener("change", saveCalendarNotifPref);
  // Load settings when modal opens
  const observer = new MutationObserver(() => {
    if (!modal.classList.contains("hidden")) loadCalendarSettings();
  });
  observer.observe(modal, { attributes: true, attributeFilter: ["class"] });
}

// ── Calendar Event Edit Modal ────────────────────────────────────────────────

function openCalendarEventEditModal(ev, cal) {
  const modal = $("#calendar-event-edit-modal");
  if (!modal) return;
  const isEdit = !!ev;
  $("#cal-edit-title").textContent = isEdit ? "Edit Event" : "New Event";
  $("#cal-edit-id").value = isEdit ? (ev._dbId || "") : "";
  $("#cal-edit-summary").value = isEdit ? (ev.summary || "") : "";
  $("#cal-edit-allday").checked = isEdit ? !!ev.start?.allDay : false;
  $("#cal-edit-location").value = isEdit ? (ev.location || "") : "";
  $("#cal-edit-description").value = isEdit ? (ev.description || "") : "";
  $("#cal-edit-delete").classList.toggle("hidden", !isEdit);

  const tz = resolveCalendarTimezone(cal || {});
  if (isEdit && ev.start) {
    if (ev.start.allDay) {
      $("#cal-edit-start-date").value = `${ev.start.year}-${String(ev.start.month).padStart(2,"0")}-${String(ev.start.day).padStart(2,"0")}`;
      $("#cal-edit-start-time").value = "";
      if (ev.end) {
        const adj = new Date(ev.end.year, ev.end.month - 1, ev.end.day - 1);
        $("#cal-edit-end-date").value = `${adj.getFullYear()}-${String(adj.getMonth()+1).padStart(2,"0")}-${String(adj.getDate()).padStart(2,"0")}`;
      }
    } else {
      const startMs = eventStartUtcMs(ev);
      const endMs = eventEndUtcMs(ev);
      if (startMs) {
        const sp = getZonedParts(startMs, tz);
        $("#cal-edit-start-date").value = `${sp.year}-${String(sp.month).padStart(2,"0")}-${String(sp.day).padStart(2,"0")}`;
        $("#cal-edit-start-time").value = `${String(sp.hour).padStart(2,"0")}:${String(sp.minute).padStart(2,"0")}`;
      }
      if (endMs) {
        const ep = getZonedParts(endMs, tz);
        $("#cal-edit-end-date").value = `${ep.year}-${String(ep.month).padStart(2,"0")}-${String(ep.day).padStart(2,"0")}`;
        $("#cal-edit-end-time").value = `${String(ep.hour).padStart(2,"0")}:${String(ep.minute).padStart(2,"0")}`;
      }
    }
  } else {
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`;
    $("#cal-edit-start-date").value = today;
    $("#cal-edit-start-time").value = `${String(now.getHours()+1).padStart(2,"0")}:00`;
    $("#cal-edit-end-date").value = today;
    $("#cal-edit-end-time").value = `${String(now.getHours()+2).padStart(2,"0")}:00`;
  }

  // Populate source dropdown
  const srcSel = $("#cal-edit-source");
  srcSel.innerHTML = '<option value="">Local</option>';
  api("/api/v2/calendar/sources").then(data => {
    for (const s of (data.sources || [])) {
      const opt = document.createElement("option");
      opt.value = s.id;
      opt.textContent = s.name;
      srcSel.appendChild(opt);
    }
    if (isEdit && ev._sourceId) srcSel.value = ev._sourceId;
  }).catch(() => {});

  modal.classList.remove("hidden");
  setTimeout(() => $("#cal-edit-summary")?.focus(), 100);
}

function closeCalendarEventEditModal() {
  $("#calendar-event-edit-modal")?.classList.add("hidden");
}

function bindCalendarEventEditModal() {
  const modal = $("#calendar-event-edit-modal");
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = "1";
  modal.querySelectorAll("[data-calendar-edit-dismiss]").forEach(el => {
    el.addEventListener("click", closeCalendarEventEditModal);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !modal.classList.contains("hidden")) closeCalendarEventEditModal();
  });
  $("#cal-edit-cancel")?.addEventListener("click", closeCalendarEventEditModal);

  // All-day toggle
  $("#cal-edit-allday")?.addEventListener("change", (e) => {
    const timeEls = modal.querySelectorAll(".cal-edit-time");
    timeEls.forEach(el => el.style.display = e.target.checked ? "none" : "");
  });

  // Save
  $("#cal-edit-save")?.addEventListener("click", async () => {
    const summary = $("#cal-edit-summary")?.value?.trim();
    if (!summary) { showToast("Title is required", true); return; }
    const allDay = $("#cal-edit-allday")?.checked;
    const startDate = $("#cal-edit-start-date")?.value;
    const startTime = $("#cal-edit-start-time")?.value;
    const endDate = $("#cal-edit-end-date")?.value;
    const endTime = $("#cal-edit-end-time")?.value;
    let dtstart, dtend;
    if (allDay) {
      dtstart = startDate;
      dtend = endDate || startDate;
    } else {
      dtstart = startDate + "T" + (startTime || "09:00");
      dtend = endDate + "T" + (endTime || "10:00");
    }
    const body = {
      summary, all_day: allDay, dtstart, dtend,
      location: $("#cal-edit-location")?.value?.trim() || "",
      description: $("#cal-edit-description")?.value?.trim() || "",
      source_id: $("#cal-edit-source")?.value || null,
      reminder_minutes: parseInt($("#cal-edit-reminder")?.value) || null,
    };
    const editId = $("#cal-edit-id")?.value;
    try {
      if (editId) {
        await api(`/api/v2/calendar/events/${editId}`, {
          method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
        });
      } else {
        await api("/api/v2/calendar/events", {
          method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
        });
      }
      closeCalendarEventEditModal();
      // Refresh all calendar tiles
      for (const cal of state.calendarTiles) {
        if (cal._el) loadCalendarForTile(cal, { quiet: true }).catch(() => {});
      }
      showToast(editId ? "Event updated" : "Event created");
    } catch (e) { showToast(e.message, true); }
  });

  // Delete
  $("#cal-edit-delete")?.addEventListener("click", async () => {
    const editId = $("#cal-edit-id")?.value;
    if (!editId) return;
    if (!confirm("Delete this event?")) return;
    try {
      await api(`/api/v2/calendar/events/${editId}`, { method: "DELETE" });
      closeCalendarEventEditModal();
      for (const cal of state.calendarTiles) {
        if (cal._el) loadCalendarForTile(cal, { quiet: true }).catch(() => {});
      }
      showToast("Event deleted");
    } catch (e) { showToast(e.message, true); }
  });
}

