// Keep legacy alias so mail-account picker still works.
const MAIL_TAB_ICON_OPTIONS = TABLER_ICON_OPTIONS;
const MAIL_TAB_COLOR_OPTIONS = ['var(--accent)', '#e74c3c', '#e67e22', '#f1c40f', '#2ecc71', '#3498db', '#9b59b6', '#e91e63', '#795548', '#607d8b', '#8b95a8'];

// Runtime cache: subset of TABLER_ICON_OPTIONS that actually render a glyph in
// the loaded Tabler webfont. The webfont is loaded from a CDN and gets
// updated over time, so some names we ship may not exist in the current
// version. openTablerIconPicker validates the set on first open and caches
// the result here so subsequent opens are O(1).
let _validTablerIconSet = null;
function _getValidTablerIconSet() {
  if (_validTablerIconSet) return _validTablerIconSet;
  if (typeof document === "undefined") {
    _validTablerIconSet = new Set(TABLER_ICON_OPTIONS);
    return _validTablerIconSet;
  }
  // Render every candidate into a hidden test container, measure each.
  // The Tabler webfont uses ::before pseudo-elements with unicode content;
  // an icon that doesn't exist in the font renders with zero width.
  const test = document.createElement("div");
  test.style.cssText = "position:absolute;visibility:hidden;left:-9999px;top:-9999px;pointer-events:none;";
  document.body.appendChild(test);
  const valid = new Set();
  try {
    for (const ic of TABLER_ICON_OPTIONS) {
      const el = document.createElement("i");
      el.className = `ti ti-${ic}`;
      test.appendChild(el);
      // Force layout, then measure.
      const w = el.getBoundingClientRect().width;
      if (w > 0) valid.add(ic);
      el.remove();
    }
  } finally {
    test.remove();
  }
  // If validation removed everything (font not loaded yet, CDN outage),
  // fall back to the full set so the picker is still usable.
  _validTablerIconSet = valid.size > 0 ? valid : new Set(TABLER_ICON_OPTIONS);
  return _validTablerIconSet;
}

// ── Avatar helpers (used by users + contacts + anywhere else we show a chip) ──

/** Two-letter initials from first + last name, fallback to email, then '?' */
function userInitials(u) {
  const f = (u && (u.first_name || u.firstName) || '').toString().trim();
  const l = (u && (u.last_name || u.lastName) || '').toString().trim();
  if (f && l) return (f[0] + l[0]).toUpperCase();
  if (f) return f.slice(0, 2).toUpperCase();
  if (l) return l.slice(0, 2).toUpperCase();
  const email = (u && u.email || '').toString().trim();
  if (email) return email[0].toUpperCase();
  return '?';
}

/** Initials for contacts: same logic as users (handles persons + companies). */
function contactInitials(c) {
  if (!c) return '?';
  if (c.is_company || c.isCompany) {
    const company = (c.company || c.displayName || c.companyName || '').toString().trim();
    if (company) return company.slice(0, 2).toUpperCase();
  }
  const f = (c.first_name || c.firstName || '').toString().trim();
  const l = (c.last_name || c.lastName || '').toString().trim();
  if (f && l) return (f[0] + l[0]).toUpperCase();
  if (f) return f.slice(0, 2).toUpperCase();
  if (l) return l.slice(0, 2).toUpperCase();
  const company = (c.company || c.displayName || c.companyName || '').toString().trim();
  if (company) return company.slice(0, 2).toUpperCase();
  return '?';
}

/**
 * Render a user avatar chip.
 * Priority:  uploaded avatar_url > avatar_icon (Tabler) > initials
 * Returns HTML safe to drop into a template.
 */
function renderUserAvatar(u, size) {
  const initials = userInitials(u);
  if (u && u.avatarUrl) {
    return `<span class="user-avatar-chip" data-size="${size || 'md'}"><img src="${escapeHtml(u.avatarUrl)}" alt="" onerror="this.replaceWith(document.createTextNode(${JSON.stringify(initials)}))" /></span>`;
  }
  if (u && u.avatar_icon && _getValidTablerIconSet().has(u.avatar_icon)) {
    return `<span class="user-avatar-chip user-avatar-icon" data-size="${size || 'md'}" style="background:var(--accent);color:#fff;"><i class="ti ti-${escapeHtml(u.avatar_icon)}"></i></span>`;
  }
  return `<span class="user-avatar-chip user-avatar-initials" data-size="${size || 'md'}">${escapeHtml(initials)}</span>`;
}

/** Render a contact avatar chip. Prefers avatar_local_path (downloaded file)
 *  over avatar_url (remote — usually broken), falls back to initials. */
function renderContactAvatar(c, size) {
  const initials = contactInitials(c);
  // avatar_local_path looks like "data/contact-avatars/15.jpg"; rewrite to API route
  let src = null;
  if (c && c.avatar_local_path) {
    const m = c.avatar_local_path.match(/contact-avatars\/([^/]+)$/);
    if (m) src = `/api/v2/contact-avatars/${encodeURIComponent(m[1])}`;
  }
  if (!src && c && c.avatarUrl) src = c.avatarUrl;
  if (src) {
    return `<span class="contact-avatar-chip" data-size="${size || 'md'}"><img src="${escapeHtml(src)}" alt="" onerror="this.replaceWith(document.createTextNode(${JSON.stringify(initials)}))" /></span>`;
  }
  return `<span class="contact-avatar-chip contact-avatar-initials" data-size="${size || 'md'}">${escapeHtml(initials)}</span>`;
}

function renderAccountTabPickers() {
  const iconBox = $('#account-settings-tab-icons');
  const colorBox = $('#account-settings-tab-colors');
  if (!iconBox || !colorBox) return;
  let currentIcon = (iconBox.dataset.value || 'user');
  let currentColor = (colorBox.dataset.value || 'var(--accent)');
  iconBox.innerHTML = MAIL_TAB_ICON_OPTIONS.map(ic => `
    <button type="button" class="acct-icon-pick ${ic === currentIcon ? 'selected' : ''}" data-icon="${ic}" title="${ic}">
      <i class="ti ti-${ic}"></i>
    </button>`).join('');
  colorBox.innerHTML = MAIL_TAB_COLOR_OPTIONS.map(c => `
    <button type="button" class="acct-color-pick ${c === currentColor ? 'selected' : ''}" data-color="${c}" style="background:${c};">
    </button>`).join('');
  iconBox.querySelectorAll('.acct-icon-pick').forEach(b => {
    b.addEventListener('click', () => {
      iconBox.querySelectorAll('.acct-icon-pick').forEach(x => x.classList.remove('selected'));
      b.classList.add('selected');
      iconBox.dataset.value = b.dataset.icon;
    });
  });
  colorBox.querySelectorAll('.acct-color-pick').forEach(b => {
    b.addEventListener('click', () => {
      colorBox.querySelectorAll('.acct-color-pick').forEach(x => x.classList.remove('selected'));
      b.classList.add('selected');
      colorBox.dataset.value = b.dataset.color;
    });
  });
}

// Reconcile an OAuth connect that finished in a popup window. The server
// creates/updates the mail_accounts row during the OAuth callback; this finds
// that row by email, persists any values the user typed into the Add modal
// onto it (the OAuth INSERT only stores provider defaults), then closes the
// modal and refreshes the tabs. Called from the postMessage listener AND from
// the closed-popup poll fallback, because the message can be lost when the
// popup lives on a different host than this window (tunnel URL vs LAN URL).
async function reconcileOAuthConnect(email) {
  const modal = $('#account-settings-modal');
  const modalOpen = !!(modal && !modal.classList.contains('hidden'));
  try {
    const data = await api('/api/v2/mail/accounts');
    const needle = (email || '').trim().toLowerCase();
    const acct = (data.accounts || []).find(a => ((a.email || '').toLowerCase() === needle));
    if (!acct) {
      showToast('OAuth completed but the account was not found — check the server log', true);
      return;
    }
    // Add modal still open for this email (no id yet): push the user's typed
    // values onto the server-created row. Only user-intent fields — never
    // hosts/ports/passwords/tokens, which the OAuth callback set from the provider.
    const modalEmail = modalOpen ? ($('#account-settings-email')?.value || '').trim().toLowerCase() : '';
    const modalId = modalOpen ? ($('#account-settings-id')?.value || '') : '';
    if (modalOpen && modalId === '' && modalEmail && modalEmail === (acct.email || '').toLowerCase()) {
      try {
        const folderCbs = $('#account-settings-folders')?.querySelectorAll('input[type="checkbox"]:checked');
        await api(`/api/v2/mail/accounts/${acct.id}`, { method: 'PUT', body: JSON.stringify({
          display_name: ($('#account-settings-name')?.value || '').trim() || acct.email,
          smtp_from_name: ($('#account-settings-from-name')?.value || '').trim(),
          monitored_folders: folderCbs ? Array.from(folderCbs).map(cb => cb.value) : ['INBOX'],
          auto_bcc_addr: ($('#account-settings-auto-bcc')?.value || '').trim(),
          retention_days: parseInt($('#account-settings-retention-days')?.value) || 90,
          signature_html: $('#account-settings-signature')?.value || '',
          tab_icon: $('#account-settings-tab-icons')?.dataset.value || 'user',
          tab_color: $('#account-settings-tab-colors')?.dataset.value || 'var(--accent)',
        }) });
      } catch (e) { /* keep the connected account even if the field sync fails */ }
    }
    if (modal) {
      modal.dataset.oauthDone = '1';
      modal.classList.add('hidden');
    }
    showToast(`Mail account connected: ${acct.email || email}`);
    await renderMailTabs();
  } catch (e) {
    showToast('OAuth connected, but refresh failed: ' + (e.message || e), true);
  }
}

function openAccountSettingsModal(editAccountId, opts) {
  const modal = $('#account-settings-modal');
  if (!modal) return;
  modal.classList.remove('hidden');
  opts = opts || {};
  const isCrmMail = !!opts.isCrmMail;
  modal.dataset.crmMail = isCrmMail ? '1' : '0';
  delete modal.dataset.oauthDone;

  const titleEl = $('#account-settings-title');
  const deleteBtn = $('#account-settings-delete');
  const idField = $('#account-settings-id');
  const manualSection = $('#account-settings-manual-section');
  const oauthSection = $('#account-settings-oauth-section');
  const oauthConnectBtn = $('#account-settings-oauth-connect');
  const oauthStatusEl = $('#account-settings-oauth-status');
  const oauthLabelEl = $('#account-settings-oauth-provider-label');
  const sharingSection = $('#account-settings-sharing-section');
  const authRadios = modal.querySelectorAll('input[name="account-auth-method"]');

  const serversReadonly = $('#account-settings-servers-readonly');
  const editServersBtn = $('#account-settings-edit-servers');

  function setAuthMode(mode) {
    const isOauth = mode === 'microsoft' || mode === 'google';
    // For OAuth: show read-only servers, hide editable fields (unless user clicked "Edit servers")
    if (serversReadonly) {
      serversReadonly.classList.toggle('hidden', !isOauth || editServersBtn?.dataset.editing === '1');
    }
    if (manualSection) manualSection.classList.toggle('hidden', isOauth && editServersBtn?.dataset.editing !== '1');
    if (oauthSection) oauthSection.classList.toggle('hidden', !isOauth);
    if (oauthLabelEl) oauthLabelEl.textContent = mode === 'microsoft' ? 'Microsoft 365' : 'Google';
    if (oauthStatusEl) oauthStatusEl.textContent = '';
    // Change connect button icon
    const icon = oauthConnectBtn?.querySelector('i');
    if (icon) icon.className = mode === 'microsoft' ? 'ti ti-brand-windows' : 'ti ti-brand-google';
  }

  // "Edit servers" button: toggle from read-only to editable
  if (editServersBtn && !editServersBtn.dataset.bound) {
    editServersBtn.dataset.bound = '1';
    editServersBtn.addEventListener('click', () => {
      editServersBtn.dataset.editing = '1';
      if (serversReadonly) serversReadonly.classList.add('hidden');
      if (manualSection) manualSection.classList.remove('hidden');
    });
  }

  // Password input: clear "Saved" indicator when user types a new password
  const imapPwInput = $('#account-settings-imap-password');
  const smtpPwInput = $('#account-settings-smtp-password');
  if (imapPwInput && !imapPwInput.dataset.bound) {
    imapPwInput.dataset.bound = '1';
    imapPwInput.addEventListener('input', () => {
      const s = $('#account-settings-imap-pw-status');
      if (s && imapPwInput.value) s.textContent = '';
    });
  }
  if (smtpPwInput && !smtpPwInput.dataset.bound) {
    smtpPwInput.dataset.bound = '1';
    smtpPwInput.addEventListener('input', () => {
      const s = $('#account-settings-smtp-pw-status');
      if (s && smtpPwInput.value) s.textContent = '';
    });
  }

  // Listen for auth method radio changes (bind once)
  if (!modal.dataset.authRadioBound) {
    modal.dataset.authRadioBound = '1';
    authRadios.forEach(radio => {
      radio.addEventListener('change', () => {
        if (radio.checked) setAuthMode(radio.value);
      });
    });
  }

  if (editAccountId) {
    if (titleEl) titleEl.textContent = 'Edit Mail Account';
    if (deleteBtn) deleteBtn.style.display = '';
    if (idField) idField.value = editAccountId;
    api(`/api/v2/mail/accounts`).then(data => {
      const acct = (data.accounts || []).find(a => a.id == editAccountId);
      if (acct) {
        $('#account-settings-name').value = acct.display_name || '';
        $('#account-settings-email').value = acct.email || '';
        $('#account-settings-imap-host').value = acct.imap_host || '';
        $('#account-settings-imap-port').value = acct.imap_port || 993;
        const imapSec = $('#account-settings-imap-security');
        if (imapSec) imapSec.value = (acct.imap_port || 993) === 993 ? 'ssl' : 'starttls';
        $('#account-settings-smtp-host').value = acct.smtp_host || '';
        $('#account-settings-smtp-port').value = acct.smtp_port || 587;
        $('#account-settings-from-name').value = acct.smtp_from_name || '';
        $('#account-settings-auto-bcc').value = acct.auto_bcc_addr || '';
        $('#account-settings-retention-days').value = acct.retention_days || 90;
        const iconBox = $('#account-settings-tab-icons');
        const colorBox = $('#account-settings-tab-colors');
        if (iconBox) iconBox.dataset.value = acct.tab_icon || 'user';
        if (colorBox) colorBox.dataset.value = acct.tab_color || 'var(--accent)';
        renderAccountTabPickers();
        // Hide tab appearance for CRM mail (shared company inbox — no personalization)
        const tabAppearance = $('#account-settings-tab-appearance');
        if (tabAppearance) tabAppearance.style.display = acct.is_crm_mail ? 'none' : '';
        const sigField = $('#account-settings-signature');
        if (sigField) sigField.value = '';
        if (acct.signature_html) {
          sigField.value = acct.signature_html;
        } else {
          api(`/api/v2/mail/accounts/${editAccountId}/signature`).then(sdata => {
            if (sigField) sigField.value = sdata.signature_html || '';
          }).catch(() => {});
        }
        const monitored = (acct.monitored_folders || 'INBOX').split(',').map(s => s.trim());
        const folderContainer = $('#account-settings-folders');
        if (folderContainer) {
          folderContainer.querySelectorAll('input[type="checkbox"]').forEach(cb => {
            cb.checked = monitored.includes(cb.value);
          });
        }
        // Populate read-only server view
        if ($('#ro-imap-host')) $('#ro-imap-host').textContent = acct.imap_host || '—';
        if ($('#ro-imap-port')) $('#ro-imap-port').textContent = acct.imap_port || '—';
        if ($('#ro-smtp-host')) $('#ro-smtp-host').textContent = acct.smtp_host || '—';
        if ($('#ro-smtp-port')) $('#ro-smtp-port').textContent = acct.smtp_port || '—';
        // Reset "Edit servers" toggle
        if (editServersBtn) delete editServersBtn.dataset.editing;
        // Populate password status indicators
        const imapPwStatus = $('#account-settings-imap-pw-status');
        const smtpPwStatus = $('#account-settings-smtp-pw-status');
        if (imapPwStatus) imapPwStatus.textContent = acct.password_encrypted ? 'Saved' : '';
        if (smtpPwStatus) smtpPwStatus.textContent = acct.smtp_password_encrypted ? 'Saved' : '';
        // Set auth mode based on account type
        const authType = acct.authType || 'password';
        const radioToCheck = modal.querySelector(`input[name="account-auth-method"][value="${authType}"]`);
        if (radioToCheck) {
          radioToCheck.checked = true;
          setAuthMode(authType);
        }
        if (authType !== 'password' && oauthStatusEl) {
          oauthStatusEl.textContent = acct.oauthStatus === 'expired' ? 'Token expired — reconnect' : `Connected as ${acct.email}`;
        }
        // Graph sendMail status (Microsoft only). Drives the connect/disconnect UI
        // and the compose-window banner.
        updateGraphStatusBlock(acct, editAccountId);
        // Sharing section
        if (sharingSection) {
          if (acct.is_crm_mail === true) {
            sharingSection.classList.remove('hidden');
            const note = $('#account-settings-share-note');
            if (note) note.textContent = 'Company inbox — already shared with all users.';
            $('#account-settings-shared-with').innerHTML = '';
            $('#account-settings-share-add-row').style.display = 'none';
            const status = $('#account-settings-share-status');
            if (status) status.textContent = '';
          } else if (acct.canManage === true || acct.isOwner === true) {
            sharingSection.classList.remove('hidden');
            const note = $('#account-settings-share-note');
            if (note) note.textContent = 'Share this account with other dashboard users.';
            $('#account-settings-share-add-row').style.display = '';
            loadAccountShares(editAccountId);
          } else {
            sharingSection.classList.add('hidden');
          }
        }
      }
    }).catch(() => {});
  } else {
    if (titleEl) titleEl.textContent = 'Add Mail Account';
    if (deleteBtn) deleteBtn.style.display = 'none';
    if (idField) idField.value = '';
    ['account-settings-name','account-settings-email','account-settings-imap-host','account-settings-imap-password','account-settings-smtp-host','account-settings-smtp-password','account-settings-from-name','account-settings-auto-bcc','account-settings-signature'].forEach(id => {
      const el = $(`#${id}`);
      if (el) el.value = '';
    });
    // NOTE: the field id was renamed to account-settings-retention-days in
    // 478eb6e; the stale id below threw on null and aborted every binding
    // after it (X/Cancel/Test/Save/Connect). Always null-guard here.
    const retentionNew = $('#account-settings-retention-days');
    if (retentionNew) retentionNew.value = 90;
    const iconBox = $('#account-settings-tab-icons');
    const colorBox = $('#account-settings-tab-colors');
    if (iconBox) iconBox.dataset.value = 'user';
    if (colorBox) colorBox.dataset.value = 'var(--accent)';
    renderAccountTabPickers();
    // Hide tab appearance for CRM mail (shared company inbox)
    const tabAppearance = $('#account-settings-tab-appearance');
    if (tabAppearance) tabAppearance.style.display = isCrmMail ? 'none' : '';
    const imapPortNew = $('#account-settings-imap-port');
    if (imapPortNew) imapPortNew.value = 993;
    const imapSecNew = $('#account-settings-imap-security');
    if (imapSecNew) imapSecNew.value = 'ssl';
    const smtpPortNew = $('#account-settings-smtp-port');
    if (smtpPortNew) smtpPortNew.value = 587;
    const folderContainer = $('#account-settings-folders');
    if (folderContainer) {
      folderContainer.querySelectorAll('input[type="checkbox"]').forEach(cb => {
        cb.checked = cb.value === 'INBOX';
      });
    }
    // Reset auth mode to password
    const pwRadio = modal.querySelector('input[name="account-auth-method"][value="password"]');
    if (pwRadio) { pwRadio.checked = true; setAuthMode('password'); }
    // Clear read-only server view and password status for new accounts
    if ($('#ro-imap-host')) $('#ro-imap-host').textContent = '—';
    if ($('#ro-imap-port')) $('#ro-imap-port').textContent = '—';
    if ($('#ro-smtp-host')) $('#ro-smtp-host').textContent = '—';
    if ($('#ro-smtp-port')) $('#ro-smtp-port').textContent = '—';
    if (serversReadonly) serversReadonly.classList.add('hidden');
    if (editServersBtn) delete editServersBtn.dataset.editing;
    const imapPwSt = $('#account-settings-imap-pw-status');
    const smtpPwSt = $('#account-settings-smtp-pw-status');
    if (imapPwSt) imapPwSt.textContent = '';
    if (smtpPwSt) smtpPwSt.textContent = '';
    // Hide sharing section for new accounts
    if (sharingSection) sharingSection.classList.add('hidden');
  }

  // Bind dismiss
  modal.querySelectorAll('[data-account-settings-dismiss]').forEach(el => {
    el.addEventListener('click', () => modal.classList.add('hidden'), { once: true });
  });

  // Bind OAuth connect button
  if (oauthConnectBtn && !oauthConnectBtn.dataset.bound) {
    oauthConnectBtn.dataset.bound = '1';
    oauthConnectBtn.addEventListener('click', async () => {
      const selectedRadio = modal.querySelector('input[name="account-auth-method"]:checked');
      const provider = selectedRadio?.value;
      if (!provider || provider === 'password') return;
      // Open the popup SYNCHRONOUSLY from the click gesture. Awaiting the
      // API first breaks the user-gesture stack and browsers silently block
      // the popup (window.open returns null). Navigate it once we have the URL.
      const popup = window.open('about:blank', 'mail_oauth', 'width=600,height=700');
      if (!popup) {
        showToast('Popup blocked — allow popups for this site and try again', true);
        return;
      }
      try { popup.document.title = 'Connecting…'; } catch (e) { /* cross-browser */ }
      try {
        const crmFlag = modal.dataset.crmMail === '1' ? '&is_crm_mail=1' : '';
        const res = await api(`/api/v2/mail/oauth/authorize?provider=${provider}${crmFlag}`);
        if (res.authUrl) {
          // The popup loads the provider consent screen, redirects back to
          // the dashboard URL with ?mailOAuth=..., and the dashboard's
          // callback handler notifies this window via postMessage then closes.
          popup.location = res.authUrl;
          // Fallback: the postMessage can be lost when the popup ends up on a
          // different host than this window (tunnel URL vs LAN URL). When the
          // popup closes, reconcile by email — a no-op if the message path
          // already completed (modal hidden / oauthDone set).
          const fallbackEmail = ($('#account-settings-email')?.value || '').trim();
          const tick = setInterval(() => {
            let closed = true;
            try { closed = !popup || popup.closed; } catch (_e) { /* treat as closed */ }
            if (!closed) return;
            clearInterval(tick);
            if (modal.dataset.oauthDone !== '1' && !modal.classList.contains('hidden')) {
              modal.dataset.oauthDone = '1';
              const currentEmail = ($('#account-settings-email')?.value || '').trim() || fallbackEmail;
              if (currentEmail) {
                reconcileOAuthConnect(currentEmail).catch(() => {});
              } else {
                showToast('OAuth window closed — click Connect to try again');
              }
            }
          }, 500);
        } else {
          try { popup.close(); } catch (_e) { /* ignore */ }
          showToast('Failed to get OAuth URL', true);
        }
      } catch (e) {
        try { popup.close(); } catch (_e) { /* ignore */ }
        showToast('Failed to start OAuth: ' + e.message, true);
      }
    });
  }

  // Bind save
  const saveBtn = $('#account-settings-save');
  if (saveBtn && !saveBtn.dataset.bound) {
    saveBtn.dataset.bound = '1';
    saveBtn.addEventListener('click', async () => {
      const id = $('#account-settings-id').value;
      const selectedRadio = modal.querySelector('input[name="account-auth-method"]:checked');
      const authMethod = selectedRadio?.value || 'password';

      if (!id && (authMethod === 'microsoft' || authMethod === 'google')) {
        showToast('Use the "Connect" button above to authenticate via OAuth');
        return;
      }

        const folderCbs = $('#account-settings-folders')?.querySelectorAll('input[type="checkbox"]:checked');
        const folders = folderCbs ? Array.from(folderCbs).map(cb => cb.value) : ["INBOX"];
        const payload = {
          display_name: $('#account-settings-name').value.trim(),
          email: $('#account-settings-email').value.trim(),
          imap_host: $('#account-settings-imap-host').value.trim(),
          imap_port: parseInt($('#account-settings-imap-port').value) || 993,
          password: $('#account-settings-imap-password').value,
          smtp_host: $('#account-settings-smtp-host').value.trim(),
          smtp_port: parseInt($('#account-settings-smtp-port').value) || 587,
          smtp_password: $('#account-settings-smtp-password').value,
          smtp_from_name: $('#account-settings-from-name').value.trim(),
          monitored_folders: folders,
          auto_bcc_addr: $('#account-settings-auto-bcc').value.trim(),
          retention_days: parseInt($('#account-settings-retention-days').value) || 90,
          signature_html: $('#account-settings-signature').value,
          tab_icon: $('#account-settings-tab-icons')?.dataset.value || 'user',
          tab_color: $('#account-settings-tab-colors')?.dataset.value || 'var(--accent)',
        };
        if (modal.dataset.crmMail === '1') payload.is_crm_mail = true;
      if (!payload.email || !payload.imap_host) { showToast('Email and IMAP host required', true); return; }
      try {
        if (id) {
          await api(`/api/v2/mail/accounts/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
          showToast('Account updated');
        } else {
          await api('/api/v2/mail/accounts', { method: 'POST', body: JSON.stringify(payload) });
          showToast('Account added');
        }
        modal.classList.add('hidden');
        await renderMailTabs();
      } catch (e) { showToast('Failed: ' + e.message, true); }
    });
  }

  // Bind security dropdown — auto-set port
  const secSelect = $('#account-settings-imap-security');
  const imapPortInput = $('#account-settings-imap-port');
  if (secSelect && imapPortInput && !secSelect.dataset.bound) {
    secSelect.dataset.bound = '1';
    secSelect.addEventListener('change', () => {
      if (secSelect.value === 'ssl') imapPortInput.value = 993;
      else imapPortInput.value = 143;
    });
    imapPortInput.addEventListener('change', () => {
      const port = parseInt(imapPortInput.value);
      if (port === 993) secSelect.value = 'ssl';
      else if (port === 143) secSelect.value = 'starttls';
    });
  }

  // Bind test connection
  const testBtn = $('#account-settings-test');
  if (testBtn && !testBtn.dataset.bound) {
    testBtn.dataset.bound = '1';
    testBtn.addEventListener('click', async () => {
      // OAuth accounts have no password to test with until connected via the
      // Connect button (same guard as Save below).
      const selRadio = modal.querySelector('input[name="account-auth-method"]:checked');
      const am = selRadio?.value || 'password';
      const tid = $('#account-settings-id').value;
      if (!tid && (am === 'microsoft' || am === 'google')) {
        showToast('Use the "Connect" button above to authenticate via OAuth');
        return;
      }
      const host = $('#account-settings-imap-host').value.trim();
      const port = parseInt($('#account-settings-imap-port').value) || 993;
      const email = $('#account-settings-email').value.trim();
      const password = $('#account-settings-imap-password').value;
      if (!host || !email) { showToast('Host and email required', true); return; }
      testBtn.disabled = true;
      testBtn.innerHTML = '<i class="ti ti-loader"></i> Testing...';
      try {
        const res = await api('/api/v2/mail/accounts/test', {
          method: 'POST',
          body: JSON.stringify({ host, port, email, password })
        });
        if (res.ok) {
          showToast('Connection successful');
          testBtn.innerHTML = '<i class="ti ti-check" style="color:#22c55e;"></i> Connected';
        } else {
          showToast('Connection failed: ' + (res.error || 'unknown error'), true);
          testBtn.innerHTML = '<i class="ti ti-x" style="color:#ef4444;"></i> Failed';
        }
      } catch (e) {
        showToast('Test failed: ' + (e.message || e), true);
        testBtn.innerHTML = '<i class="ti ti-x" style="color:#ef4444;"></i> Failed';
      }
      testBtn.disabled = false;
      setTimeout(() => { testBtn.innerHTML = '<i class="ti ti-plug-connected"></i> Test'; }, 3000);
    });
  }

  // Bind delete
  const delBtn = $('#account-settings-delete');
  if (delBtn && !delBtn.dataset.bound) {
    delBtn.dataset.bound = '1';
    delBtn.addEventListener('click', async () => {
      const id = $('#account-settings-id').value;
      if (!id) return;
      if (!confirm('Delete this mail account? All messages will be removed.')) return;
      try {
        await api(`/api/v2/mail/accounts/${id}`, { method: 'DELETE' });
        showToast('Account deleted');
        modal.classList.add('hidden');
        await renderMailTabs();
      } catch (e) { showToast('Failed: ' + e.message, true); }
    });
  }

  // Bind share add (bind once)
  const shareAddBtn = $('#account-settings-share-add');
  if (shareAddBtn && !shareAddBtn.dataset.bound) {
    shareAddBtn.dataset.bound = '1';
    shareAddBtn.addEventListener('click', async () => {
      const id = $('#account-settings-id').value;
      const sel = $('#account-settings-share-user');
      const userId = sel?.value;
      const statusEl = $('#account-settings-share-status');
      if (!id || !userId) {
        if (statusEl) statusEl.textContent = 'Select a user first';
        return;
      }
      try {
        await api(`/api/v2/mail/accounts/${id}/share`, {
          method: 'POST',
          body: JSON.stringify({ user_id: parseInt(userId) }),
        });
        if (statusEl) { statusEl.textContent = 'Shared'; statusEl.style.color = '#3fb950'; }
        setTimeout(() => { if (statusEl) statusEl.textContent = ''; }, 2500);
        await loadAccountShares(parseInt(id));
      } catch (e) {
        if (statusEl) { statusEl.textContent = e.message; statusEl.style.color = '#f85149'; }
        else showToast('Failed: ' + e.message, true);
      }
    });
  }
}

function updateGraphStatusBlock(acct, accountId) {
  const section = $('#account-settings-graph-section');
  if (!section) return;
  // Only Microsoft OAuth accounts can use Graph sendMail.
  const isMicrosoft = (acct.authType || '').toLowerCase() === 'microsoft';
  if (!isMicrosoft) {
    section.classList.add('hidden');
    return;
  }
  section.classList.remove('hidden');
  const statusEl = $('#account-settings-graph-status');
  const connectBtn = $('#account-settings-graph-connect');
  const disconnectBtn = $('#account-settings-graph-disconnect');
  if (!statusEl || !connectBtn || !disconnectBtn) return;
  const graphStatus = acct.graphStatus;
  if (graphStatus === 'connected') {
    statusEl.textContent = '<span style="color:#22c55e;">●</span> Connected via Microsoft Graph';
    statusEl.style.color = 'var(--text)';
    connectBtn.classList.add('hidden');
    disconnectBtn.classList.remove('hidden');
  } else if (graphStatus === 'expired') {
    statusEl.textContent = '<span style="color:#ff9800;">●</span> Token expired — reconnect';
    statusEl.style.color = 'var(--text)';
    connectBtn.classList.remove('hidden');
    connectBtn.textContent = 'Reconnect Graph';
    disconnectBtn.classList.remove('hidden');
  } else {
    statusEl.textContent = '<span style="color:var(--muted);">●</span> Not connected';
    statusEl.style.color = 'var(--text)';
    connectBtn.classList.remove('hidden');
    connectBtn.textContent = 'Connect Graph';
    disconnectBtn.classList.add('hidden');
  }
  // Wire click handlers (idempotent — safe to re-call on each modal open).
  if (!connectBtn.dataset.bound) {
    connectBtn.dataset.bound = '1';
    connectBtn.addEventListener('click', () => connectGraphSend(accountId));
  }
  if (!disconnectBtn.dataset.bound) {
    disconnectBtn.dataset.bound = '1';
    disconnectBtn.addEventListener('click', () => disconnectGraphSend(accountId));
  }
}

async function connectGraphSend(accountId) {
  // Open the popup SYNCHRONOUSLY from the click gesture (same reason as
  // oauthConnectBtn above): awaiting the API first gets the popup blocked.
  const popup = window.open('about:blank', 'graph_oauth', 'width=600,height=700');
  if (!popup) {
    showToast('Popup blocked — allow popups for this site and try again', true);
    return;
  }
  try { popup.document.title = 'Connecting…'; } catch (e) { /* cross-browser */ }
  try {
    const data = await api(`/api/v2/mail/oauth/microsoft/graph/authorize?account_id=${accountId}`);
    if (!data.authUrl) {
      try { popup.close(); } catch (_e) { /* ignore */ }
      showToast('Failed to get Graph authorize URL', true);
      return;
    }
    popup.location = data.authUrl;
    const tick = setInterval(async () => {
      if (popup && popup.closed) {
        clearInterval(tick);
        // Re-fetch account list and refresh the Graph status block.
        try {
          const data = await api(`/api/v2/mail/accounts`);
          const acct = (data.accounts || []).find(a => a.id == accountId);
          if (acct) {
            updateGraphStatusBlock(acct, accountId);
            updateComposeGraphBanner();
          }
        } catch (e) { /* ignore */ }
      }
    }, 500);
  } catch (e) {
    try { popup.close(); } catch (_e) { /* ignore */ }
    showToast('Graph connect failed: ' + (e.message || ''), true);
  }
}

async function disconnectGraphSend(accountId) {
  if (!confirm('Disconnect Microsoft Graph sendMail? Mail will fall back to SMTP for this account.')) return;
  try {
    await api(`/api/v2/mail/oauth/microsoft/graph/disconnect/${accountId}`, { method: 'GET' });
    showToast('Graph sendMail disconnected');
    try {
      const data = await api(`/api/v2/mail/accounts`);
      const acct = (data.accounts || []).find(a => a.id == accountId);
      if (acct) {
        updateGraphStatusBlock(acct, accountId);
        updateComposeGraphBanner();
      }
    } catch (e) { /* ignore */ }
  } catch (e) {
    showToast('Graph disconnect failed: ' + (e.message || ''), true);
  }
}

// Show the amber banner at the top of the compose modal when the active
// from-account is a Microsoft OAuth account without a connected Graph token.
// Re-run on every send failure + every modal open.
function updateComposeGraphBanner() {
  const banner = $('#compose-graph-banner');
  if (!banner) return;
  const select = $('#compose-from-account');
  const accountId = select ? parseInt(select.value) : null;
  if (!accountId) {
    banner.classList.add('hidden');
    return;
  }
  api(`/api/v2/mail/accounts`).then(data => {
    const acct = (data.accounts || []).find(a => a.id == accountId);
    if (!acct || (acct.authType || '').toLowerCase() !== 'microsoft') {
      banner.classList.add('hidden');
      return;
    }
    if (acct.graphStatus === 'connected') {
      banner.classList.add('hidden');
    } else {
      banner.classList.remove('hidden');
    }
  }).catch(() => banner.classList.add('hidden'));
}

function loadAccountShares(accountId) {
  const sharedList = $('#account-settings-shared-with');
  const userSel = $('#account-settings-share-user');
  const statusEl = $('#account-settings-share-status');
  if (!sharedList) return Promise.resolve();
  const currentUserId = state.currentUserId;
  return Promise.all([
    api(`/api/v2/mail/accounts/${accountId}/share`),
    api('/api/v2/users'),
  ]).then(([sharesData, usersData]) => {
    const shares = sharesData.shares || [];
    const allUsers = usersData || [];
    // Render shared-with list
    if (!shares.length) {
      sharedList.innerHTML = '<div style="font-size:0.8rem; color:var(--muted);">Not shared with anyone yet.</div>';
    } else {
      sharedList.innerHTML = shares.map(s => `
        <div style="display:flex; justify-content:space-between; align-items:center; gap:0.4rem; font-size:0.82rem; background:var(--surface); border:1px solid var(--border); border-radius:4px; padding:0.25rem 0.4rem;">
          <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">
            <i class="ti ti-user" style="margin-right:0.25rem;"></i>${escapeHtml(s.display_name || s.email)}
          </span>
          <button type="button" class="btn btn-ghost btn-sm share-remove" data-share-user-id="${s.user_id}" title="Remove access" style="font-size:0.75rem; color:var(--danger); flex-shrink:0;"><i class="ti ti-x"></i></button>
        </div>`).join('');
      sharedList.querySelectorAll('.share-remove').forEach(btn => {
        btn.addEventListener('click', async () => {
          const userId = btn.dataset.shareUserId;
          try {
            await api(`/api/v2/mail/accounts/${accountId}/share/${userId}`, { method: 'DELETE' });
            if (statusEl) { statusEl.textContent = 'Access removed'; statusEl.style.color = '#3fb950'; }
            setTimeout(() => { if (statusEl) statusEl.textContent = ''; }, 2500);
            await loadAccountShares(accountId);
          } catch (e) {
            if (statusEl) { statusEl.textContent = e.message; statusEl.style.color = '#f85149'; }
            else showToast('Failed: ' + e.message, true);
          }
        });
      });
    }
    // Populate user dropdown (exclude current user, owner handled by backend, exclude already shared)
    const sharedIds = new Set(shares.map(s => s.user_id));
    if (userSel) {
      const options = allUsers
        .filter(u => u.id !== currentUserId && !sharedIds.has(u.id))
        .map(u => `<option value="${u.id}">${escapeHtml(u.displayName || u.email)}${u.isAdmin ? ' (admin)' : ''}</option>`);
      userSel.innerHTML = options.length ? `<option value="">Select user…</option>` + options.join('') : `<option value="">No other users available</option>`;
    }
  }).catch(e => {
    sharedList.innerHTML = `<div style="font-size:0.8rem; color:var(--danger);">Failed to load shares: ${escapeHtml(e.message)}</div>`;
  });
}

function bindComposeEmailModal() {
  const modal = $('#compose-email-modal');
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = '1';

  // Move to tab button
  const moveToTabBtn = $('#compose-move-to-tab');
  if (moveToTabBtn) {
    moveToTabBtn.addEventListener('click', () => moveComposeToTab());
  }

  // Graph sendMail banner (shown when active from-account is MS OAuth
  // without a connected Graph token).
  const graphBannerBtn = $('#compose-graph-banner-btn');
  const graphBannerDismiss = $('#compose-graph-banner-dismiss');
  if (graphBannerBtn && !graphBannerBtn.dataset.bound) {
    graphBannerBtn.dataset.bound = '1';
    graphBannerBtn.addEventListener('click', async () => {
      const select = $('#compose-from-account');
      const accountId = select ? parseInt(select.value) : null;
      if (accountId) await connectGraphSend(accountId);
    });
  }
  if (graphBannerDismiss && !graphBannerDismiss.dataset.bound) {
    graphBannerDismiss.dataset.bound = '1';
    graphBannerDismiss.addEventListener('click', () => {
      $('#compose-graph-banner').classList.add('hidden');
    });
  }
  if (fromSelect && !fromSelect.dataset.graphBannerBound) {
    fromSelect.dataset.graphBannerBound = '1';
    fromSelect.addEventListener('change', () => updateComposeGraphBanner());
  }

  // Reload signature when the From account changes
  const fromSelect = $('#compose-from-account');
  if (fromSelect && !fromSelect.dataset.sigBound) {
    fromSelect.dataset.sigBound = '1';
    fromSelect.addEventListener('change', async () => {
      const bodyDiv = $('#compose-body');
      if (!bodyDiv || !fromSelect.value) return;
      const oldSig = bodyDiv.querySelector('.compose-signature-block');
      try {
        const sig = await api(`/api/v2/mail/accounts/${fromSelect.value}/signature`);
        if (sig.signature_html) {
          if (oldSig) {
            oldSig.outerHTML = `<br><br><div class="compose-signature-block" style="border-top:1px solid var(--border); padding-top:0.5rem; color:var(--muted); font-size:0.85rem;">${sig.signature_html}</div>`;
          } else {
            const hasBodyText = bodyDiv.textContent.trim().length > 0;
            bodyDiv.innerHTML += `<br><br><div class="compose-signature-block" style="border-top:1px solid var(--border); padding-top:0.5rem; color:var(--muted); font-size:0.85rem;">${sig.signature_html}</div>`;
            if (!hasBodyText) {
              // Clean up the leading empty lines when body is otherwise empty
              bodyDiv.innerHTML = bodyDiv.innerHTML.replace(/^<br><br>/, '');
            }
          }
        } else if (oldSig) {
          oldSig.remove();
        }
      } catch { /* no signature */ }
    });
  }

  modal.querySelectorAll('[data-compose-email-dismiss]').forEach(el => {
    el.addEventListener('click', () => {
      // Discard confirmation if content exists
      const to = $('#compose-to')?.value.trim();
      const subject = $('#compose-subject')?.value.trim();
      const body = $('#compose-body')?.innerText?.trim();
      if ((to || subject || body) && !confirm('Discard unsaved draft?')) return;
      modal.classList.add('hidden');
      clearInterval(composeAutoSaveTimer);
      composeAutoSaveTimer = null;
      const inboxTab = document.querySelector('.mail-inbox-tab[data-mailtab="inbox"]');
      if (inboxTab) switchMailTab(inboxTab);
    });
  });
  modal.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const to = $('#compose-to')?.value.trim();
      const subject = $('#compose-subject')?.value.trim();
      const body = $('#compose-body')?.innerText?.trim();
      if ((to || subject || body) && !confirm('Discard unsaved draft?')) return;
      modal.classList.add('hidden');
      clearInterval(composeAutoSaveTimer);
      composeAutoSaveTimer = null;
      const inboxTab = document.querySelector('.mail-inbox-tab[data-mailtab="inbox"]');
      if (inboxTab) switchMailTab(inboxTab);
    }
  });

  // Auto-save draft every 30 seconds if content changed
  if (composeAutoSaveTimer) clearInterval(composeAutoSaveTimer);
  let lastAutoSaveContent = '';
  composeAutoSaveTimer = setInterval(async () => {
    const to = $('#compose-to')?.value.trim();
    const subject = $('#compose-subject')?.value.trim();
    const body = $('#compose-body')?.innerHTML || '';
    const current = `${to}|${subject}|${body}`;
    if (!to && !subject && !body) return; // nothing to save
    if (current === lastAutoSaveContent) return; // no change
    lastAutoSaveContent = current;
    const statusEl = $('#compose-save-status');
    if (statusEl) { statusEl.textContent = 'Saving…'; statusEl.style.color = 'var(--accent)'; }
    try {
      const accountId = parseInt($('#compose-from-account')?.value) || null;
      await api('/api/v2/mail/drafts', {
        method: 'POST',
        body: JSON.stringify({ account_id: accountId, to, subject, body })
      });
      if (statusEl) { statusEl.textContent = 'Saved ' + new Date().toLocaleTimeString('en-US', {hour12:false, hour:'2-digit', minute:'2-digit'}); statusEl.style.color = '#3fb950'; }
      showToast('Draft auto-saved');
    } catch {
      if (statusEl) { statusEl.textContent = 'Save failed'; statusEl.style.color = '#f85149'; }
    }
  }, 30000);
}

function updateMailToolbarSettingsBtn() {
  const ovf = $("#ovf-account-settings");
  if (!ovf) return;
  const acctId = mailState.activeAccount;
  const acct = (mailState.accounts || []).find(a => String(a.id) === String(acctId));
  ovf.style.display = (acct && acct.canManage === true) ? '' : 'none';
}

function attachMailModalListeners() {
  const modal = $("#mail-inbox-modal");
  if (!modal || modal.dataset.listenersBound) return;
  modal.dataset.listenersBound = "1";

  // Close (X button and footer Close button)
  function closeMailModal() {
    modal.classList.add("hidden");
    minimizedEmailState = null;
    if (_mailInboxAutoRefreshTimer) { clearInterval(_mailInboxAutoRefreshTimer); _mailInboxAutoRefreshTimer = null; }
    try { localStorage.removeItem(EMAIL_MINIMIZED_STORAGE_KEY); } catch {}
    const trigger = $("#email-trigger");
    if (trigger) trigger.classList.add("trigger-hidden");
  }
  $("#mail-inbox-close")?.addEventListener("click", closeMailModal);
  $("#mail-inbox-close-footer")?.addEventListener("click", closeMailModal);

  // Backdrop click -> minimize instead of close
  const backdrop = modal.querySelector(".modal-backdrop");
  if (backdrop) {
    backdrop.addEventListener("click", minimizeEmailModal);
  }

  // minimize
  $("#mail-inbox-minimize")?.addEventListener("click", minimizeEmailModal);

  // search
  const searchIn = $("#mail-search-input");
  let searchT = null;
  if (searchIn) {
    searchIn.addEventListener("input", () => {
      clearTimeout(searchT);
      searchT = setTimeout(() => {
        loadMailMessagesForModal();
      }, 350);
    });
  }

  // select all
  const selAll = $("#mail-select-all");
  if (selAll) {
    selAll.addEventListener("click", () => {
      const cbs = modal.querySelectorAll(".mail-cb");
      const allChecked = Array.from(cbs).every(cb => cb.checked);
      cbs.forEach(cb => {
        cb.checked = !allChecked;
        const id = cb.dataset.id;
        if (cb.checked) mailState.selected.add(id);
        else mailState.selected.delete(id);
      });
      updateMailSelectedInfo();
    });
  }

  // clear selection
  const clearSelBtn = $("#mail-clear-selection");
  if (clearSelBtn) {
    clearSelBtn.addEventListener("click", () => {
      mailState.selected.clear();
      renderMailList(mailState.messages);
      updateMailSelectedInfo();
    });
  }

  // mark read // Mail API removed in v2 — local only
  const markBtn = $("#mail-mark-read");
  if (markBtn) {
    markBtn.addEventListener("click", async () => {
      if (!mailState.selected.size) return;
      const ids = Array.from(mailState.selected);
      let ok = 0;
      for (const mid of ids) {
        try {
          await api(`/api/v2/mail/messages/${mid}/read`, { method: "PUT" });
          ok++;
        } catch { /* best-effort */ }
        mailDashboardReadIds.add(String(mid));
        saveMailDashboardReadIds();
      }
      mailState.messages.forEach(m => {
        const mid = String(m.id || m.ID);
        if (ids.includes(mid)) m.read = true;
      });
      mailState.selected.clear();
      renderMailList(mailState.messages);
      updateMailSelectedInfo();
      renderMailUnreadBadge();
      showToast(`Marked ${ok} of ${ids.length} conversation(s) as read`);
    });
  }

  // mark unread
  const markUnreadBtn = $("#mail-mark-unread");
  if (markUnreadBtn) {
    markUnreadBtn.addEventListener("click", async () => {
      if (!mailState.selected.size) return;
      const ids = Array.from(mailState.selected);
      let ok = 0;
      for (const mid of ids) {
        try {
          await api(`/api/v2/mail/messages/${mid}/unread`, { method: "PUT" });
          ok++;
        } catch { /* best-effort */ }
        mailDashboardReadIds.delete(String(mid));
        saveMailDashboardReadIds();
      }
      mailState.messages.forEach(m => {
        const mid = String(m.id || m.ID);
        if (ids.includes(mid)) m.read = false;
      });
      mailState.selected.clear();
      renderMailList(mailState.messages);
      updateMailSelectedInfo();
      renderMailUnreadBadge();
      showToast(`Marked ${ok} of ${ids.length} conversation(s) as unread`);
    });
  }

  // delete
  const delBtn = $("#mail-delete");
  if (delBtn) {
    delBtn.addEventListener("click", async () => {
      if (!mailState.selected.size) return;
      if (!confirm(`Delete ${mailState.selected.size} conversation(s)?`)) return;
      const ids = Array.from(mailState.selected);
      let ok = 0;
      for (const mid of ids) {
        try {
          const msg = mailState.messages.find(m => String(m.id || m.ID) === String(mid));
          if (msg && msg.isDraft) {
            await api(`/api/v2/mail/drafts/${mid}`, { method: "DELETE" });
          } else {
            await api(`/api/v2/mail/messages/${mid}`, { method: "DELETE" });
          }
          ok++;
        } catch (e) {
          console.warn("[mail-inbox] delete failed for", mid, e);
        }
      }
      showToast(`Deleted ${ok} of ${ids.length} conversation(s)`);
      mailState.selected.clear();
      await loadMailMessagesForModal();
    });
  }

  // mark all loaded as read
  const markAllBtn = $("#mail-mark-all-read");
  if (markAllBtn) {
    markAllBtn.addEventListener("click", async () => {
      const ids = mailState.messages.map(m => String(m.id || m.ID)).filter(Boolean);
      if (!ids.length) return;
      let ok = 0;
      for (const mid of ids) {
        try {
          await api(`/api/v2/mail/messages/${mid}/read`, { method: "PUT" });
          ok++;
        } catch {
          // best-effort
        }
        mailDashboardReadIds.add(mid);
        saveMailDashboardReadIds();
      }
      mailState.messages.forEach(m => { m.read = true; });
      renderMailList(mailState.messages);
      renderMailUnreadBadge();
      showToast(`Marked ${ok} of ${ids.length} as read`);
    });
  }

  // refresh
  const refBtn = $("#mail-refresh");
  if (refBtn) {
    refBtn.addEventListener("click", () => loadMailMessagesForModal());
  }

  // account settings gear (toolbar)
  const acctSettingsBtn = $("#mail-account-settings-btn");
  if (acctSettingsBtn && !acctSettingsBtn.dataset.bound) {
    acctSettingsBtn.dataset.bound = "1";
    acctSettingsBtn.addEventListener("click", () => {
      const acctId = mailState.activeAccount;
      const acct = (mailState.accounts || []).find(a => String(a.id) === String(acctId));
      if (acct) openAccountSettingsModal(Number(acct.id));
    });
  }

  // account settings gear (overflow menu)
  const ovfAcctSettings = $("#ovf-account-settings");
  if (ovfAcctSettings && !ovfAcctSettings.dataset.bound) {
    ovfAcctSettings.dataset.bound = "1";
    ovfAcctSettings.addEventListener("click", () => {
      const acctId = mailState.activeAccount;
      const acct = (mailState.accounts || []).find(a => String(a.id) === String(acctId));
      if (acct) openAccountSettingsModal(Number(acct.id));
      // Close overflow menu
      const menu = $("#mail-toolbar-overflow-menu");
      if (menu) menu.classList.add("hidden");
    });
  }

  // compose button
  const composeBtn = $("#mail-compose-btn");
  if (composeBtn) {
    composeBtn.addEventListener("click", () => openComposeModal());
  }

  // thread view toggle
  const threadToggle = $("#mail-thread-toggle");
  if (threadToggle && !threadToggle.dataset.bound) {
    threadToggle.dataset.bound = "1";
    threadToggle.addEventListener("click", () => {
      mailState.threaded = !mailState.threaded;
      threadToggle.classList.toggle("active", mailState.threaded);
      if (mailState.threaded) loadMailThreads();
      else loadMailMessagesForModal();
    });
  }

  // Link to deal dropdown
  const linkDealBtn = $("#mail-link-deal-btn");
  const linkDealDropdown = $("#mail-link-deal-dropdown");
  if (linkDealBtn && linkDealDropdown) {
    linkDealBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      linkDealDropdown.classList.toggle("hidden");
      if (!linkDealDropdown.classList.contains("hidden")) {
        const search = $("#mail-link-deal-search");
        if (search) search.focus();
      }
    });
    document.addEventListener("click", (e) => {
      if (!linkDealBtn.contains(e.target) && !linkDealDropdown.contains(e.target)) {
        linkDealDropdown.classList.add("hidden");
      }
    });
  }

  // Tag assignment dropdown
  const tagBtn = $("#mail-tag-btn");
  const tagDropdown = $("#mail-tag-dropdown");
  if (tagBtn && tagDropdown) {
    tagBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      if (!mailState.selected.size) return;
      tagDropdown.classList.toggle("hidden");
      if (tagDropdown.classList.contains("hidden")) return;
      try {
        const [allData, msgData] = await Promise.all([
          api("/api/v2/mail/tags"),
          api(`/api/v2/mail/messages/${Array.from(mailState.selected)[0]}`),
        ]);
        const allTags = allData.tags || [];
        const msgTagTitles = new Set((msgData.tags || []).map(t => t.title));
        const list = $("#mail-tag-dropdown-list");
        if (!list) return;
        list.innerHTML = allTags.length
          ? allTags.map(t => {
              const has = msgTagTitles.has(t.title);
              return `<button type="button" class="mail-tag-assign-btn" data-tag-id="${t.id}" data-tag-title="${escapeHtml(t.title)}" style="display:flex;align-items:center;gap:0.4rem;width:100%;text-align:left;padding:0.3rem 0.5rem;border:none;background:none;cursor:pointer;font-size:0.85rem;color:var(--text);">
                <span class="mail-tag-dot" style="background:${escapeHtml(t.color || '#6c757d')};width:8px;height:8px;border-radius:50%;flex-shrink:0;"></span>
                ${escapeHtml(t.title)}
                ${has ? '<span style="margin-left:auto;font-size:0.7rem;color:var(--accent);">✓</span>' : ''}
              </button>`;
            }).join("")
          : '<div style="padding:0.5rem;color:var(--muted);font-size:0.8rem;">No tags yet. Create one in the sidebar.</div>';
        list.querySelectorAll(".mail-tag-assign-btn").forEach(btn => {
          btn.addEventListener("click", async () => {
            const tagTitle = btn.dataset.tagTitle;
            const tagId = parseInt(btn.dataset.tagId);
            const currentlyHas = btn.querySelector("span:last-child")?.textContent === "✓";
            const ids = Array.from(mailState.selected);
            let ok = 0;
            for (const mid of ids) {
              try {
                if (currentlyHas) {
                  await api(`/api/v2/mail/messages/${mid}/tags/${tagId}`, { method: "DELETE" });
                } else {
                  await api(`/api/v2/mail/messages/${mid}/tags`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ title: tagTitle }),
                  });
                }
                ok++;
              } catch (_) {}
            }
            showToast(ok ? `${currentlyHas ? "Removed" : "Added"} tag "${tagTitle}" from ${ok} message(s)` : "Failed to update tags");
            tagDropdown.classList.add("hidden");
            // Refresh list and any open detail panels
            try { await loadMailMessagesForModal(); } catch (err) { console.error("Failed to refresh mail list", err); }
            refreshOpenMailPanels();
          });
        });
      } catch (e) {
        const list = $("#mail-tag-dropdown-list");
        if (list) list.innerHTML = '<div style="padding:0.5rem;color:var(--danger);font-size:0.8rem;">Failed to load tags</div>';
      }
    });
    document.addEventListener("click", (e) => {
      if (!tagBtn.contains(e.target) && !tagDropdown.contains(e.target)) {
        tagDropdown.classList.add("hidden");
      }
    });
  }

  const dealSearch = $("#mail-link-deal-search");
  let dealT = null;
  if (dealSearch) {
    dealSearch.addEventListener("input", () => {
      clearTimeout(dealT);
      dealT = setTimeout(() => searchDealsForMailLink(dealSearch.value.trim()), 300);
    });
  }

  const linkSubmitBtn = $("#mail-link-deal-submit");
  if (linkSubmitBtn) {
    linkSubmitBtn.addEventListener("click", async () => {
      const results = $("#mail-link-deal-results");
      const dealId = results && results.dataset.selectedDealId;
      if (!dealId || !mailState.selected.size) return;
      const ids = Array.from(mailState.selected);
      let ok = 0;
      let lastErr = '';
      for (const mid of ids) {
        try {
          await api(`/api/v2/mail/messages/${mid}/link`, {
            method: "POST",
            body: JSON.stringify({ opportunityId: Number(dealId) })
          });
          ok++;
        } catch (e) {
          lastErr = e.message || e.error || 'unknown error';
          console.warn('[mail-inbox] link failed for', mid, lastErr);
        }
      }
      if (ok === ids.length) {
        showToast(`Linked ${ok} email(s) to deal`);
      } else if (ok > 0) {
        showToast(`Linked ${ok}/${ids.length} — errors: ${lastErr}`, true);
      } else {
        showToast(`Link failed: ${lastErr}`, true);
      }
      const idsToMark = Array.from(mailState.selected);
      for (const mid of idsToMark) {
        await markMailMessageRead(mid).catch(() => {});
      }
      mailState.selected.clear();
      resetLinkDealDropdown();
      updateMailSelectedInfo();
      await loadMailMessagesForModal();
    });
  }

  // Star button
  const starBtn = $("#mail-star");
  if (starBtn) {
    starBtn.addEventListener("click", async () => {
      if (!mailState.selected.size) {
        showToast("Select messages first (click checkboxes)");
        return;
      }
      for (const mid of mailState.selected) {
        try { await api(`/api/v2/mail/messages/${mid}/star`, { method: 'PUT' }); } catch {}
      }
      await loadMailMessagesForModal();
    });
  }

  // Archive button
  const archiveBtn = $("#mail-archive");
  if (archiveBtn) {
    archiveBtn.addEventListener("click", async () => {
      if (!mailState.selected.size) return;
      for (const mid of mailState.selected) {
        try { await api(`/api/v2/mail/messages/${mid}/archive`, { method: 'PUT' }); } catch {}
      }
      mailState.selected.clear();
      await loadMailMessagesForModal();
    });
  }

  // Move folder dropdown
  const moveBtn = $("#mail-move-folder-btn");
  const moveDropdown = $("#mail-move-dropdown");
  if (moveBtn && moveDropdown) {
    moveBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      moveDropdown.classList.toggle("hidden");
    });
    document.addEventListener("click", () => moveDropdown.classList.add("hidden"));
    moveDropdown.addEventListener("click", async (e) => {
      const opt = e.target.closest(".move-folder-option");
      if (!opt) return;
      const folder = opt.dataset.folder;
      moveDropdown.classList.add("hidden");
      if (!folder || !mailState.selected.size) return;
      for (const mid of mailState.selected) {
        try { await api(`/api/v2/mail/messages/${mid}/move`, { method: 'PUT', body: JSON.stringify({ folder }) }); } catch {}
      }
      mailState.selected.clear();
      await loadMailMessagesForModal();
    });
  }

  // Keyboard shortcuts
  document.addEventListener("keydown", (e) => {
    if (!modal || modal.classList.contains("hidden")) return;
    if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA" || e.target.isContentEditable) return;

    if (e.key === "j" || e.key === "k") {
      const items = Array.from(modal.querySelectorAll(".mail-item .mail-row"));
      if (!items.length) return;
      let currentIdx = -1;
      items.forEach((row, idx) => {
        if (row.classList.contains("selected") || row.querySelector(".mail-cb")?.checked) currentIdx = idx;
      });
      const nextIdx = e.key === "j"
        ? Math.min(currentIdx + 1, items.length - 1)
        : Math.max(currentIdx - 1, 0);
      if (currentIdx >= 0) {
        const prevRow = items[currentIdx];
        const prevCb = prevRow.querySelector(".mail-cb");
        const prevId = prevCb?.dataset.id;
        if (prevId) {
          mailState.selected.delete(prevId);
          prevRow.classList.remove("selected");
          if (prevCb) prevCb.checked = false;
        }
      }
      const row = items[nextIdx];
      const cb = row.querySelector(".mail-cb");
      const id = cb?.dataset.id;
      if (id) {
        mailState.selected.add(id);
        row.classList.add("selected");
        if (cb) cb.checked = true;
      }
      row.scrollIntoView({ block: "nearest" });
      updateMailSelectedInfo();
    }

    if (e.key === "Escape") {
      mailState.selected.clear();
      renderMailList(mailState.messages);
      updateMailSelectedInfo();
    }
  });

  // sidebar toggle
  const toggleBtn = $("#mail-sidebar-toggle");
  const sideBar = $(".mail-right-sidebar", modal);
  if (toggleBtn && sideBar) {
    toggleBtn.addEventListener("click", () => {
      const collapsed = sideBar.classList.toggle("mail-sidebar-collapsed");
      toggleBtn.innerHTML = collapsed ? '<i class="ti ti-chevron-left"></i>' : '<i class="ti ti-chevron-right"></i>';
    });
  }

  // folder click handlers
  const folderList = $("#mail-folder-list");
  if (folderList && !folderList.dataset.bound) {
    folderList.dataset.bound = "1";
    folderList.addEventListener("click", (e) => {
      const btn = e.target.closest(".mail-folder-btn");
      if (!btn) return;
      folderList.querySelectorAll(".mail-folder-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      mailState.activeFolder = btn.dataset.folder || "INBOX";
      mailState.page = 1;
      loadMailMessagesForModal();
    });
    // Folder context menu
    const folderCtx = $('#mail-trash-context-menu');
    if (folderCtx) {
      document.addEventListener('click', () => { folderCtx.style.display = 'none'; });
      $('#mail-folder-rename-btn')?.addEventListener('click', () => {
        const id = folderCtx.dataset.folderId;
        const btn = folderList.querySelector(`[data-folder-id="${id}"]`);
        folderCtx.style.display = 'none';
        if (btn) startFolderRename(btn);
      });
      $('#mail-folder-delete-btn')?.addEventListener('click', async () => {
        const id = folderCtx.dataset.folderId;
        const name = folderCtx.dataset.folderName;
        folderCtx.style.display = 'none';
        if (!id) return;
        if (!confirm(`Delete folder "${name}"? Messages will be moved to Inbox.`)) return;
        try {
          await api(`/api/v2/mail/folders/${id}`, { method: 'DELETE' });
          showToast('Folder deleted');
          await renderMailFolderList();
        } catch (e) { showToast('Failed: ' + e.message, true); }
      });
    }
  }

  // --- Mobile: Toolbar overflow menu ---
  const overflowBtn = $("#mail-toolbar-overflow");
  const overflowMenu = $("#mail-toolbar-overflow-menu");
  if (overflowBtn && overflowMenu) {
    overflowBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      overflowMenu.classList.toggle("hidden");
    });
    document.addEventListener("click", (e) => {
      if (!overflowBtn.contains(e.target) && !overflowMenu.contains(e.target)) {
        overflowMenu.classList.add("hidden");
      }
    });
    // Wire overflow menu items
    $("#ovf-star")?.addEventListener("click", async () => {
      overflowMenu.classList.add("hidden");
      if (!mailState.selected.size) return;
      for (const mid of mailState.selected) {
        try { await api(`/api/v2/mail/messages/${mid}/star`, { method: 'PUT' }); } catch {}
      }
      loadMailMessagesForModal();
    });
    $("#ovf-archive")?.addEventListener("click", async () => {
      overflowMenu.classList.add("hidden");
      if (!mailState.selected.size) return;
      for (const mid of mailState.selected) {
        try { await api(`/api/v2/mail/messages/${mid}/archive`, { method: 'PUT' }); } catch {}
      }
      mailState.selected.clear();
      loadMailMessagesForModal();
    });
    $("#ovf-delete")?.addEventListener("click", () => { overflowMenu.classList.add("hidden"); $("#mail-delete")?.click(); });
    $("#ovf-thread")?.addEventListener("click", () => { overflowMenu.classList.add("hidden"); $("#mail-thread-toggle")?.click(); });
    $("#ovf-mark-all-read")?.addEventListener("click", () => { overflowMenu.classList.add("hidden"); $("#mail-mark-all-read")?.click(); });
    $("#ovf-tags")?.addEventListener("click", () => { overflowMenu.classList.add("hidden"); $("#mail-tag-btn")?.click(); });
  }

  // --- Mobile: Collapsible search ---
  const searchIcon = $("#mail-search-icon");
  const searchInput = $("#mail-search-input");
  if (searchIcon && searchInput) {
    searchIcon.addEventListener("click", () => {
      searchInput.classList.add("expanded");
      searchInput.focus();
    });
    searchInput.addEventListener("blur", () => {
      if (!searchInput.value) searchInput.classList.remove("expanded");
    });
  }
}

async function loadMailAccountsForModal() {
  const sel = $("#mail-account-select");
  if (!sel) return;
  try {
    const data = await api("/api/v2/mail/accounts");
    const accounts = data.accounts || [];
    if (!accounts.length) {
      sel.innerHTML = '<option value="">No mail accounts configured</option>';
      return;
    }
    sel.innerHTML = accounts
      .map(a => `<option value="${escapeHtml(String(a.id))}">${escapeHtml(a.email || a.email_address || "Account")}</option>`)
      .join("");
  } catch (e) {
    sel.innerHTML = '<option value="">Mail unavailable</option>';
  }
}

async function loadMailMessagesForModal(background) {
  if (mailState.threaded) return loadMailThreads();
  const list = $("#mail-list");
  if (!list) return;
  if (!background) list.innerHTML = '<div class="mail-empty">Loading emails…</div>';

  // Save scroll position + expanded state for background refresh
  const scrollContainer = list.parentElement;
  let savedScrollTop = 0;
  if (background) {
    savedScrollTop = scrollContainer ? scrollContainer.scrollTop : 0;
  } else {
    // Non-background: clear expanded tracking (full manual reload)
    mailState.expandedIds.clear();
    mailState.expandedContent = {};
  }

  // Handle Drafts folder — load from drafts endpoint
  if (mailState.activeFolder === 'Drafts') {
    try {
      const params = [];
      if (mailState.activeAccount) params.push(`account_id=${mailState.activeAccount === 'crm' ? 'crm' : mailState.activeAccount}`);
      const url = '/api/v2/mail/drafts' + (params.length ? '?' + params.join('&') : '');
      const data = await api(url);
      const drafts = data.drafts || [];
      mailState.messages = drafts.map(d => ({
        id: d.id,
        from: d.to_addr ? `To: ${d.to_addr}` : (d.from_addr || ''),
        subject: d.subject || '(no subject)',
        date: d.created_at || d.updated_at || '',
        isDraft: true,
        body: d.body_text || d.body_html || '',
        snippet: (d.body_text || '').slice(0, 80),
      }));
      renderMailList(mailState.messages);
      if (background) { restoreExpandedState(); if (scrollContainer) scrollContainer.scrollTop = savedScrollTop; }
    } catch (e) {
      if (!background) list.innerHTML = `<div class="mail-empty">Failed to load drafts: ${escapeHtml(e.message)}</div>`;
    }
    return;
  }

  try {
    let url = "/api/v2/mail/messages";
    const params = [];
    if (mailState.activeAccount) params.push(`account_id=${mailState.activeAccount === 'crm' ? 'crm' : mailState.activeAccount}`);
    if (mailState.activeFolder && mailState.activeFolder !== "INBOX") params.push(`folder=${encodeURIComponent(mailState.activeFolder)}`);
    if (mailState.search) params.push(`search=${encodeURIComponent(mailState.search)}`);
    if (mailState.activeTag) params.push(`tag=${encodeURIComponent(mailState.activeTag)}`);
    params.push(`page=${mailState.page || 1}`);
    params.push(`page_size=${mailState.pageSize || 50}`);
    if (params.length) url += '?' + params.join('&');
    const data = await api(url);
    mailState.messages = data.messages || [];
    mailState.page = data.page || 1;
    mailState.total = data.total || mailState.messages.length;
    mailState.pages = Math.ceil(mailState.total / (mailState.pageSize || 50));
    renderMailList(mailState.messages);
    renderMailPagination();
    if (background) { restoreExpandedState(); if (scrollContainer) scrollContainer.scrollTop = savedScrollTop; }
  } catch (e) {
    if (!background) list.innerHTML = `<div class="mail-empty">Failed to load emails: ${escapeHtml(e.message)}</div>`;
  }
}

async function loadMailThreads() {
  const list = $("#mail-list");
  if (!list) return;
  list.innerHTML = '<div class="mail-empty">Loading threads…</div>';
  try {
    let url = "/api/v2/mail/threads";
    const params = [];
    if (mailState.activeAccount) params.push(`account_id=${mailState.activeAccount === 'crm' ? 'crm' : mailState.activeAccount}`);
    if (params.length) url += '?' + params.join('&');
    const data = await api(url);
    const threads = data.threads || [];
    if (!threads.length) {
      list.innerHTML = '<div class="mail-empty">No conversations yet. Emails with matching subjects or In-Reply-To headers are grouped into threads.</div>';
      return;
    }
    list.innerHTML = threads.map(t => `
      <div class="mail-row" data-conversation-id="${escapeHtml(t.conversation_id)}">
        <div class="mail-star"></div>
        <div class="mail-from" title="${escapeHtml(t.from_addr || '')}">${escapeHtml((t.from_addr || '').slice(0, 28))}</div>
        <div class="mail-subject" title="${escapeHtml(t.subject || '')}">${escapeHtml((t.subject || '').slice(0, 80))}</div>
        <div class="mail-date">${t.message_count > 1 ? `<span style="color:var(--muted);">(${t.message_count})</span> ` : ''}${escapeHtml(t.latest_date ? new Date(t.latest_date).toLocaleDateString() : '')}</div>
      </div>
    `).join('');
  } catch (e) {
    list.innerHTML = `<div class="mail-empty">Failed to load threads: ${escapeHtml(e.message)}</div>`;
  }
}

async function renderMailFolders() {
  const tagList = $("#mail-tag-list");
  if (!tagList) return;
  try {
    const data = await api("/api/v2/mail/tags");
    const tags = data.tags || [];
    if (!tags.length) {
      tagList.innerHTML = '<p style="font-size:0.75rem; color:var(--muted); padding:0.25rem 0.5rem;">No tags yet</p>';
    } else {
      tagList.innerHTML = tags.map(t => `
        <div class="mail-tag-item" data-tag-id="${t.id}" data-tag-title="${escapeHtml(t.title)}" data-tag-color="${escapeHtml(t.color || '#6c757d')}">
          <span class="mail-tag-dot" style="background:${escapeHtml(t.color || '#6c757d')}"></span>
          ${escapeHtml(t.title)}
        </div>
      `).join("");
      tagList.querySelectorAll(".mail-tag-item").forEach(el => {
        el.addEventListener("click", () => {
          if (el.classList.contains("active")) {
            el.classList.remove("active");
            mailState.activeTag = null;
          } else {
            tagList.querySelectorAll(".mail-tag-item").forEach(x => x.classList.remove("active"));
            el.classList.add("active");
            mailState.activeTag = el.dataset.tagTitle;
          }
          loadMailMessagesForModal();
        });
        el.addEventListener("contextmenu", (e) => {
          e.preventDefault();
          const ctx = $("#mail-tag-context-menu");
          if (!ctx) return;
          ctx.dataset.tagId = el.dataset.tagId;
          ctx.dataset.tagTitle = el.dataset.tagTitle;
          ctx.dataset.tagColor = el.dataset.tagColor;
          ctx.style.display = "block";
          ctx.style.left = e.clientX + "px";
          ctx.style.top = e.clientY + "px";
        });
      });
    }
  } catch (e) {
    tagList.innerHTML = '<p style="font-size:0.75rem; color:var(--muted); padding:0.25rem 0.5rem;">Tags unavailable</p>';
  }

  // Tag context menu handlers
  const tagCtx = $("#mail-tag-context-menu");
  if (tagCtx && !tagCtx.dataset.bound) {
    tagCtx.dataset.bound = "1";
    document.addEventListener("click", () => { tagCtx.style.display = "none"; });
    $("#mail-tag-edit-btn")?.addEventListener("click", async () => {
      const id = tagCtx.dataset.tagId;
      const oldTitle = tagCtx.dataset.tagTitle;
      const oldColor = tagCtx.dataset.tagColor;
      tagCtx.style.display = "none";
      if (!id) return;
      const tagList = $("#mail-tag-list");
      if (!tagList) return;
      // Remove existing edit form
      tagList.querySelector(".tag-edit-form")?.remove();
      const form = document.createElement("div");
      form.className = "tag-edit-form";
      form.style.cssText = "padding:0.3rem 0.4rem; border-bottom:1px solid var(--border);";
      form.innerHTML = `
        <input type="text" value="${escapeHtml(oldTitle)}" class="tag-edit-title" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;">
        <div style="display:flex;gap:0.3rem;align-items:center;margin-bottom:0.2rem;">
          <input type="color" class="tag-edit-color" value="${escapeHtml(oldColor || '#6c757d')}" style="width:24px;height:24px;padding:0;border:none;cursor:pointer;border-radius:3px;">
          <span style="font-size:0.7rem;color:var(--muted);">${escapeHtml(oldColor || '#6c757d')}</span>
        </div>
        <div style="display:flex;gap:0.3rem;">
          <button type="button" class="btn btn-primary btn-small tag-edit-save" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Save</button>
          <button type="button" class="btn btn-ghost btn-small tag-edit-cancel" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Cancel</button>
        </div>`;
      const tagItem = tagList.querySelector(`[data-tag-id="${id}"]`);
      if (tagItem) tagItem.after(form);
      else tagList.prepend(form);
      form.querySelector(".tag-edit-color").addEventListener("input", (e) => {
        form.querySelector("span").textContent = e.target.value;
      });
      form.querySelector(".tag-edit-save").addEventListener("click", async () => {
        const newTitle = form.querySelector(".tag-edit-title").value.trim();
        const newColor = form.querySelector(".tag-edit-color").value;
        if (!newTitle) { showToast("Tag name required", true); return; }
        try {
          await api(`/api/v2/mail/tags/${id}`, { method: "PUT", body: JSON.stringify({ title: newTitle, color: newColor }) });
          showToast("Tag updated");
          form.remove();
          await renderMailFolders();
        } catch (e) { showToast("Failed: " + e.message, true); }
      });
      form.querySelector(".tag-edit-cancel").addEventListener("click", () => form.remove());
    });
    $("#mail-tag-delete-btn")?.addEventListener("click", async () => {
      const id = tagCtx.dataset.tagId;
      const title = tagCtx.dataset.tagTitle;
      tagCtx.style.display = "none";
      if (!id) return;
      if (!confirm(`Delete tag "${title}"?`)) return;
      try {
        await api(`/api/v2/mail/tags/${id}`, { method: "DELETE" });
        showToast("Tag deleted");
        if (mailState.activeTag === title) mailState.activeTag = null;
        await renderMailFolders();
        await loadMailMessagesForModal();
      } catch (e) { showToast("Failed: " + e.message, true); }
    });
  }

  // New Tag button
  const addBtn = $("#mail-tag-add-btn");
  if (addBtn && !addBtn.dataset.bound) {
    addBtn.dataset.bound = "1";
    addBtn.addEventListener("click", async () => {
      const tagList = $("#mail-tag-list");
      if (!tagList) return;
      // Remove existing form
      tagList.querySelector(".tag-add-form")?.remove();
      const form = document.createElement("div");
      form.className = "tag-add-form";
      form.style.cssText = "padding:0.3rem 0.4rem; border-bottom:1px solid var(--border);";
      form.innerHTML = `
        <input type="text" placeholder="Tag name" class="tag-add-title" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;">
        <div style="display:flex;gap:0.3rem;align-items:center;margin-bottom:0.2rem;">
          <input type="color" class="tag-add-color" value="#6c757d" style="width:24px;height:24px;padding:0;border:none;cursor:pointer;border-radius:3px;">
          <span style="font-size:0.7rem;color:var(--muted);">#6c757d</span>
        </div>
        <div style="display:flex;gap:0.3rem;">
          <button type="button" class="btn btn-primary btn-small tag-add-save" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Save</button>
          <button type="button" class="btn btn-ghost btn-small tag-add-cancel" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Cancel</button>
        </div>`;
      tagList.prepend(form);
      form.querySelector(".tag-add-title").focus();
      // Update color label on change
      form.querySelector(".tag-add-color").addEventListener("input", (e) => {
        form.querySelector("span").textContent = e.target.value;
      });
      form.querySelector(".tag-add-save").addEventListener("click", async () => {
        const title = form.querySelector(".tag-add-title").value.trim();
        const color = form.querySelector(".tag-add-color").value;
        if (!title) { showToast("Tag name required", true); return; }
        try {
          await api("/api/v2/mail/tags", { method: "POST", body: JSON.stringify({ title, color }) });
          showToast("Tag created");
          form.remove();
          await renderMailFolders();
        } catch (e) { showToast("Failed: " + e.message, true); }
      });
      form.querySelector(".tag-add-cancel").addEventListener("click", () => form.remove());
    });
  }
}

async function renderMailTemplates() {
  const tplList = $("#mail-template-list");
  if (!tplList) return;
  try {
    const data = await api("/api/v2/mail/templates");
    const templates = data.templates || [];
    if (!templates.length) {
      tplList.innerHTML = '<p style="font-size:0.75rem; color:var(--muted); padding:0.25rem 0.5rem;">No templates yet</p>';
      return;
    }
    tplList.innerHTML = templates.map(t => `
      <div class="mail-template-item" data-template-id="${t.id}" style="display:flex; justify-content:space-between; align-items:center; padding:2px 0.5rem; cursor:pointer; border-radius:3px;" title="${escapeHtml(t.subject || '')}">
        <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(t.title)}</span>
        <button type="button" class="btn btn-ghost btn-small mail-tpl-delete" data-id="${t.id}" data-title="${escapeHtml(t.title)}" style="font-size:0.65rem; padding:0; color:var(--danger); flex-shrink:0;"><i class="ti ti-x"></i></button>
      </div>
    `).join("");
    tplList.querySelectorAll(".mail-template-item").forEach(el => {
      el.addEventListener("click", async (e) => {
        if (e.target.closest(".mail-tpl-delete")) return;
        const tid = parseInt(el.dataset.templateId);
        const tpl = templates.find(t => t.id === tid);
        if (tpl) {
          openComposeModal({
            subject: tpl.subject || "",
            body: tpl.body_html || "",
            title: "New email from template",
          });
        }
      });
    });
    tplList.querySelectorAll(".mail-tpl-delete").forEach(btn => {
      btn.addEventListener("click", async (e) => {
        e.stopPropagation();
        const id = btn.dataset.id;
        const title = btn.dataset.title;
        if (!confirm(`Delete template "${title}"?`)) return;
        try {
          await api(`/api/v2/mail/templates/${id}`, { method: "DELETE" });
          showToast("Template deleted");
          await renderMailTemplates();
        } catch (e) { showToast("Failed: " + e.message, true); }
      });
    });
  } catch (e) {
    tplList.innerHTML = '<p style="font-size:0.75rem; color:var(--muted);">Templates unavailable</p>';
  }
}

async function renderMailContacts() {
  // Wire collapsible toggle headers
  document.querySelectorAll(".mail-contacts-toggle").forEach(btn => {
    if (btn.dataset.bound) return;
    btn.dataset.bound = "1";
    btn.addEventListener("click", () => {
      const targetId = btn.dataset.target;
      const list = document.getElementById(targetId);
      if (!list) return;
      const isExpanded = list.classList.contains("expanded");
      if (isExpanded) {
        list.classList.remove("expanded");
        list.style.maxHeight = "0";
        btn.setAttribute("aria-expanded", "false");
      } else {
        // Lazy load contacts on first expand
        if (!list.dataset.loaded) {
          list.dataset.loaded = "1";
          if (targetId === "crm-contact-list") loadCrmContacts(list);
          else loadUserContacts(list);
        }
        list.classList.add("expanded");
        btn.setAttribute("aria-expanded", "true");
      }
    });
  });

  // Wire import/export/add buttons
  const importBtn = $("#mail-contact-import");
  if (importBtn && !importBtn.dataset.bound) {
    importBtn.dataset.bound = "1";
    importBtn.addEventListener("click", () => importMailContacts());
  }
  const exportBtn = $("#mail-contact-export");
  if (exportBtn && !exportBtn.dataset.bound) {
    exportBtn.dataset.bound = "1";
    exportBtn.addEventListener("click", () => exportMailContacts());
  }
  const addBtn = $("#mail-contact-add");
  if (addBtn && !addBtn.dataset.bound) {
    addBtn.dataset.bound = "1";
    addBtn.addEventListener("click", () => addNewContact());
  }

  // Contact context menu
  const contactCtx = $("#mail-contact-context-menu");
  if (contactCtx && !contactCtx.dataset.bound) {
    contactCtx.dataset.bound = "1";
    document.addEventListener("click", () => { contactCtx.style.display = "none"; });
    $("#mail-contact-edit-btn")?.addEventListener("click", async () => {
      const id = contactCtx.dataset.contactId;
      const oldEmail = contactCtx.dataset.contactEmail;
      const oldName = contactCtx.dataset.contactName;
      contactCtx.style.display = "none";
      if (!id) return;
      const listEl = $("#mail-contact-list");
      listEl?.querySelector(".contact-edit-form")?.remove();
      const form = document.createElement("div");
      form.className = "contact-edit-form";
      form.style.cssText = "padding:0.3rem 0.4rem; border-bottom:1px solid var(--border);";
      form.innerHTML = `
        <input type="email" value="${escapeHtml(oldEmail)}" class="contact-edit-email" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;">
        <input type="text" value="${escapeHtml(oldName)}" class="contact-edit-name" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;">
        <div style="display:flex;gap:0.3rem;">
          <button type="button" class="btn btn-primary btn-small contact-edit-save" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Save</button>
          <button type="button" class="btn btn-ghost btn-small contact-edit-cancel" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Cancel</button>
        </div>`;
      const contactItem = listEl?.querySelector(`[data-contact-id="${id}"]`);
      if (contactItem) {
        contactItem.after(form);
        form.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
      form.querySelector(".contact-edit-save").addEventListener("click", async () => {
        const email = form.querySelector(".contact-edit-email").value.trim();
        const name = form.querySelector(".contact-edit-name").value.trim();
        if (!email) { showToast("Email required", true); return; }
        try {
          await api(`/api/v2/mail/contacts/${id}`, { method: "PUT", body: JSON.stringify({ email, name }) });
          showToast("Contact updated");
          form.remove();
          loadUserContacts(listEl);
        } catch (e) { showToast("Failed: " + e.message, true); }
      });
      form.querySelector(".contact-edit-cancel").addEventListener("click", () => form.remove());
    });
    $("#mail-contact-delete-btn")?.addEventListener("click", async () => {
      const id = contactCtx.dataset.contactId;
      const email = contactCtx.dataset.contactEmail;
      contactCtx.style.display = "none";
      if (!id) return;
      if (!confirm(`Delete contact "${email}"?`)) return;
      try {
        await api(`/api/v2/mail/contacts/${id}`, { method: "DELETE" });
        showToast("Contact deleted");
        const listEl = $("#mail-contact-list");
        if (listEl) loadUserContacts(listEl);
      } catch (e) { showToast("Failed: " + e.message, true); }
    });
  }
}

async function loadCrmContacts(listEl) {
  listEl.innerHTML = '<p style="color:var(--muted);font-size:0.7rem;padding:0.2rem 0.4rem;">Loading…</p>';
  try {
    const data = await api("/api/v2/contacts");
    const contacts = Array.isArray(data) ? data : (data.contacts || data || []);
    const valid = contacts.filter(c => c.email && c.email.trim());
    if (!valid.length) {
      listEl.innerHTML = '<p style="color:var(--muted);font-size:0.7rem;padding:0.2rem 0.4rem;">No CRM contacts with email addresses</p>';
      return;
    }
    listEl.innerHTML = valid.map(c => {
      const name = [c.first_name, c.last_name].filter(Boolean).join(" ") || c.displayName || c.email || "";
      return `<div class="mail-contact-item" data-email="${escapeHtml(c.email || "")}" data-name="${escapeHtml(name)}">
        <div class="mail-contact-name">${escapeHtml(name || c.email || "")}</div>
        <div class="mail-contact-email">${escapeHtml(c.email || "")}</div>
      </div>`;
    }).join("");
    wireContactClicks(listEl);
  } catch (e) {
    listEl.innerHTML = `<p style="color:var(--danger);font-size:0.7rem;padding:0.2rem 0.4rem;">Failed to load</p>`;
  }
}

async function loadUserContacts(listEl) {
  // Preserve the button bar (first child)
  const btnBar = listEl.querySelector("div:first-child");
  try {
    const data = await api("/api/v2/mail/contacts");
    const contacts = data.contacts || [];
    // Remove old contact items (keep button bar)
    listEl.querySelectorAll(".mail-contact-item, .mail-contact-add-form, p").forEach(el => el.remove());
    if (!contacts.length) {
      const empty = document.createElement("p");
      empty.style.cssText = "color:var(--muted);font-size:0.7rem;padding:0.2rem 0.4rem;";
      empty.textContent = "No contacts yet";
      listEl.appendChild(empty);
      return;
    }
    contacts.forEach(c => {
      const div = document.createElement("div");
      div.className = "mail-contact-item";
      div.dataset.contactId = c.id || "";
      div.dataset.email = c.email || "";
      div.dataset.name = c.name || c.email || "";
      div.innerHTML = `<div class="mail-contact-name">${escapeHtml(c.name || c.email || "")}</div><div class="mail-contact-email">${escapeHtml(c.email || "")}</div>`;
      listEl.appendChild(div);
    });
    wireContactClicks(listEl);
    // Add right-click context menu to contacts
    listEl.querySelectorAll(".mail-contact-item").forEach(item => {
      item.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        const ctx = $("#mail-contact-context-menu");
        if (!ctx) return;
        ctx.dataset.contactId = item.dataset.contactId;
        ctx.dataset.contactEmail = item.dataset.email;
        ctx.dataset.contactName = item.dataset.name;
        ctx.style.display = "block";
        ctx.style.left = e.clientX + "px";
        ctx.style.top = e.clientY + "px";
      });
    });
  } catch (e) {
    listEl.querySelectorAll(".mail-contact-item, p").forEach(el => el.remove());
    const err = document.createElement("p");
    err.style.cssText = "color:var(--danger);font-size:0.7rem;padding:0.2rem 0.4rem;";
    err.textContent = "Failed to load";
    listEl.appendChild(err);
  }
}

function wireContactClicks(container) {
  container.querySelectorAll(".mail-contact-item").forEach(item => {
    item.addEventListener("click", () => {
      const email = item.dataset.email;
      const name = item.dataset.name;
      if (!email) return;
      const addr = name ? `${name} <${email}>` : email;
      const composeModal = $("#compose-email-modal");
      if (composeModal && !composeModal.classList.contains("hidden")) {
        const active = document.activeElement;
        if (active && (active.id === "compose-to" || active.id === "compose-cc" || active.id === "compose-bcc")) {
          const parts = active.value.split(",").map(s => s.trim());
          parts[parts.length - 1] = parts[parts.length - 1] ? parts[parts.length - 1] + ", " + addr : addr;
          active.value = parts.join(", ");
        } else {
          const toInput = $("#compose-to");
          if (toInput) toInput.value = toInput.value ? toInput.value + ", " + addr : addr;
        }
      } else {
        openComposeModal({ to: addr });
      }
    });
  });
}

function importMailContacts() {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".csv";
  input.addEventListener("change", async () => {
    const file = input.files[0];
    if (!file) return;
    const text = await file.text();
    try {
      const result = await api("/api/v2/mail/contacts/import", {
        method: "POST",
        body: JSON.stringify({ csv: text }),
      });
      showToast(`Imported ${result.imported || 0} contacts`);
      // Reload expanded lists
      const userList = $("#mail-contact-list");
      if (userList && userList.dataset.loaded) loadUserContacts(userList);
    } catch (e) { showToast("Import failed: " + e.message, true); }
  });
  input.click();
}

function exportMailContacts() {
  window.open("/api/v2/mail/contacts/export", "_blank");
}

function addNewContact() {
  // Always expand My Contacts list first
  const listEl = $("#mail-contact-list");
  if (!listEl) return;
  const toggle = document.querySelector('.mail-contacts-toggle[data-target="mail-contact-list"]');
  if (toggle && !listEl.classList.contains("expanded")) {
    toggle.click(); // expand the list
  }
  // Ensure contacts are loaded
  if (!listEl.dataset.loaded) {
    listEl.dataset.loaded = "1";
    loadUserContacts(listEl);
  }
  // Remove existing form if any
  const existing = listEl.querySelector(".mail-contact-add-form");
  if (existing) { existing.remove(); return; }
  const form = document.createElement("div");
  form.className = "mail-contact-add-form";
  form.style.cssText = "padding:0.3rem 0.4rem; border-bottom:1px solid var(--border);";
  form.innerHTML = `
    <input type="email" placeholder="Email" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;" class="new-contact-email">
    <input type="text" placeholder="Name (optional)" style="width:100%;font-size:0.75rem;padding:0.2rem;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--text);margin-bottom:0.2rem;" class="new-contact-name">
    <div style="display:flex;gap:0.3rem;">
      <button type="button" class="btn btn-primary btn-small new-contact-save" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Save</button>
      <button type="button" class="btn btn-ghost btn-small new-contact-cancel" style="font-size:0.7rem;padding:0.15rem 0.4rem;">Cancel</button>
    </div>`;
  listEl.prepend(form);
  form.querySelector(".new-contact-email").focus();
  form.querySelector(".new-contact-save").addEventListener("click", async () => {
    const email = form.querySelector(".new-contact-email").value.trim();
    const name = form.querySelector(".new-contact-name").value.trim();
    if (!email || !email.includes("@")) { showToast("Valid email required", true); return; }
    try {
      await api("/api/v2/mail/contacts", {
        method: "POST",
        body: JSON.stringify({ email, name }),
      });
      showToast("Contact added");
      form.remove();
      loadUserContacts(listEl);
    } catch (e) { showToast("Failed: " + e.message, true); }
  });
  form.querySelector(".new-contact-cancel").addEventListener("click", () => form.remove());
}

async function renderMailFolderList() {
  const folderList = $("#mail-folder-list");
  if (!folderList) return;
  try {
    const acctId = mailState.activeAccount === 'crm' ? 'crm' : (mailState.activeAccount || '');
    const data = await api(`/api/v2/mail/folders?account_id=${encodeURIComponent(acctId)}`);
    const folders = data.folders || [];
    folderList.innerHTML = folders.map(f => {
      const icon = f.icon || 'folder';
      const isSystem = f.is_system;
      const activeClass = mailState.activeFolder === f.name ? ' active' : '';
      return `<button type="button" class="mail-folder-btn${activeClass}" data-folder="${escapeHtml(f.name)}" data-folder-id="${f.id}" ${isSystem ? 'data-system="true"' : ''}>
        <i class="ti ti-${icon}"></i> ${escapeHtml(f.name)}
        ${f.name === 'INBOX' ? '<span class="mail-folder-badge" id="mail-inbox-unread"></span>' : ''}
        ${f.name === 'Trash' ? '<span class="mail-folder-badge" id="mail-trash-count"></span>' : ''}
      </button>`;
    }).join('') + '<button type="button" id="mail-folder-add-btn" class="btn btn-ghost btn-small" style="margin-top:0.3rem; font-size:0.75rem;"><i class="ti ti-plus"></i> New Folder</button>';
    folderList.querySelectorAll('.mail-folder-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        folderList.querySelectorAll('.mail-folder-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        mailState.activeFolder = btn.dataset.folder || 'INBOX';
        loadMailMessagesForModal();
      });
      if (!btn.dataset.system) {
        btn.addEventListener('dblclick', () => startFolderRename(btn));
        btn.addEventListener('contextmenu', (e) => {
          e.preventDefault();
          const ctx = $('#mail-trash-context-menu');
          if (ctx) {
            ctx.style.display = 'block';
            ctx.style.left = e.clientX + 'px';
            ctx.style.top = e.clientY + 'px';
            ctx.dataset.folderId = btn.dataset.folderId;
            ctx.dataset.folderName = btn.dataset.folder;
          }
        });
      }
    });
    const addBtn = $('#mail-folder-add-btn');
    if (addBtn) addBtn.addEventListener('click', () => createNewFolder());
    const moveDropdown = $('#mail-move-dropdown');
    if (moveDropdown) {
      moveDropdown.innerHTML = folders.map(f => `
        <button type="button" class="move-folder-option" data-folder="${escapeHtml(f.name)}" style="display:block;width:100%;text-align:left;padding:0.3rem 0.5rem;border:none;background:none;cursor:pointer;font-size:0.85rem;color:var(--text);">
          <i class="ti ti-${f.icon || 'folder'}" style="margin-right:0.3rem;"></i>${escapeHtml(f.name)}
        </button>`).join('');
    }
    renderMailUnreadBadge();
    updateTrashCount();
  } catch (e) {
    folderList.innerHTML = '<p style="font-size:0.75rem; color:var(--muted);">Failed to load folders</p>';
  }
}

function startFolderRename(btn) {
  const name = btn.dataset.folder;
  const id = btn.dataset.folderId;
  if (!id || !name) return;
  const input = document.createElement('input');
  input.type = 'text';
  input.value = name;
  input.style.cssText = 'width:100%; padding:0.2rem 0.3rem; font-size:0.82rem; border:1px solid var(--accent); border-radius:3px; background:var(--bg); color:var(--text);';
  btn.textContent = '';
  btn.appendChild(input);
  input.focus();
  input.select();
  const save = async () => {
    const newName = input.value.trim();
    if (newName && newName !== name) {
      try { await api(`/api/v2/mail/folders/${id}`, { method: 'PUT', body: JSON.stringify({ name: newName }) }); } catch (e) { showToast('Failed to rename: ' + e.message, true); }
    }
    await renderMailFolderList();
  };
  input.addEventListener('blur', save);
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') save(); if (e.key === 'Escape') renderMailFolderList(); });
}

async function createNewFolder() {
  const name = prompt('Folder name:');
  if (!name || !name.trim()) return;
  try {
    await api('/api/v2/mail/folders', { method: 'POST', body: JSON.stringify({ name: name.trim() }) });
    await renderMailFolderList();
  } catch (e) { showToast('Failed to create folder: ' + e.message, true); }
}

async function renderMailUnreadBadge() {
  const badge = $("#mail-inbox-unread");
  if (!badge) return;
  try {
    const acctId = mailState.activeAccount === 'crm' ? 'crm' : (mailState.activeAccount || '');
    const data = await api(`/api/v2/mail/unread-count?account_id=${encodeURIComponent(acctId)}`);
    const count = data.count || 0;
    badge.textContent = count > 0 ? count : '';
    badge.style.display = count > 0 ? 'inline' : 'none';
  } catch { badge.style.display = 'none'; }
}

function renderMailPagination() {
  const existing = $("#mail-pagination");
  if (existing) existing.remove();
  if (!mailState.pages || mailState.pages <= 1) return;
  const list = $("#mail-list");
  if (!list) return;
  const bar = document.createElement("div");
  bar.id = "mail-pagination";
  bar.className = "mail-pagination";
  bar.innerHTML = `
    <button type="button" class="btn btn-ghost btn-small" id="mail-prev-page" ${mailState.page <= 1 ? 'disabled' : ''}><i class="ti ti-chevron-left"></i> Newer</button>
    <span class="mail-page-info">Page ${mailState.page} of ${mailState.pages} (${mailState.total || 0} emails)</span>
    <button type="button" class="btn btn-ghost btn-small" id="mail-next-page" ${mailState.page >= mailState.pages ? 'disabled' : ''}>Older <i class="ti ti-chevron-right"></i></button>
  `;
  list.parentElement.appendChild(bar);
  $("#mail-prev-page")?.addEventListener("click", () => { if (mailState.page > 1) { mailState.page--; loadMailMessagesForModal(); } });
  $("#mail-next-page")?.addEventListener("click", () => { if (mailState.page < mailState.pages) { mailState.page++; loadMailMessagesForModal(); } });
}

async function updateTrashCount() {
  const badge = $('#mail-trash-count');
  if (!badge) return;
  try {
    const data = await api('/api/v2/mail/trash-count');
    const count = data.count || 0;
    badge.textContent = count > 0 ? count : '';
    badge.style.display = count > 0 ? 'inline' : 'none';
  } catch { badge.style.display = 'none'; }
}

function renderMailList(msgs) {
  const list = $("#mail-list");
  if (!list) return;
  list.innerHTML = "";
  if (!msgs || !msgs.length) {
    list.innerHTML = '<div class="mail-empty">No emails in this inbox/page.</div>';
    return;
  }

  // header
  const header = document.createElement("div");
  header.className = "mail-row mail-header";
  header.innerHTML = `
    <input type="checkbox" id="mail-cb-all" />
    <div class="mail-star"></div>
    <div class="mail-from"><strong>From</strong></div>
    <div class="mail-subject"><strong>Subject</strong></div>
    <div class="mail-date"><strong>Date</strong></div>
  `;
  list.appendChild(header);

  const cbAll = header.querySelector("#mail-cb-all");
  if (cbAll) {
    cbAll.checked = msgs.length > 0 && msgs.every(m => mailState.selected.has(String(m.id || m.ID)));
    cbAll.addEventListener("change", () => {
      msgs.forEach(m => {
        const id = String(m.id || m.ID);
        if (cbAll.checked) mailState.selected.add(id);
        else mailState.selected.delete(id);
      });
      renderMailList(msgs); // re-render to sync cbs
      updateMailSelectedInfo();
    });
  }

  msgs.forEach(m => {
    const id = String(m.id || m.ID);
    const from = (m.from_addr || m.from || m.fromEmail || "").toString();
    const subj = (m.subject || m.Subject || "(no subject)").toString();
    const date = m.date || m.date_received || m.receivedDate || m.Date || "";
    const dateStr = date ? new Date(date).toLocaleDateString('en-US') + " " + new Date(date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : "";

    const item = document.createElement("div");
    item.className = "mail-item";
    item.dataset.id = id;

    const row = document.createElement("div");
    row.className = "mail-row";
    if (mailState.selected.has(id)) row.classList.add("selected");
    // Use tolerant server read detection (list summary may use read/isRead/seen/IsNew etc or nestings)
    // OR our local dashboard overrides (for marks we performed here + any server-read we promoted).
    // This makes the darker .mail-row-read rows reflect native CRM mail status when the API provides it,
    // while our local Set ensures persistence across modal close/reopen even if a list response drops the flag.
    const isRead = getMailMessageIsRead(m) || mailDashboardReadIds.has(id);
    if (isRead) row.classList.add('mail-row-read');

    row.innerHTML = `
      <input type="checkbox" class="mail-cb" data-id="${escapeHtml(id)}" ${mailState.selected.has(id) ? "checked" : ""} />
    `;

    // Star indicator
    const starEl = document.createElement("div");
    starEl.className = "mail-star";
    starEl.innerHTML = '<i class="ti ti-star"></i>';
    if (m.starred) starEl.classList.add('starred');
    starEl.style.cursor = "pointer";
    starEl.style.flexShrink = "0";
    starEl.addEventListener("click", async (e) => {
      e.stopPropagation();
      try {
        const res = await api(`/api/v2/mail/messages/${id}/star`, { method: 'PUT' });
        starEl.innerHTML = '<i class="ti ti-star"></i>';
        if (res.starred) starEl.classList.add('starred'); else starEl.classList.remove('starred');
      } catch {}
    });
    row.appendChild(starEl);

    const fromDiv = document.createElement("div");
    fromDiv.className = "mail-from";
    const fromSnippet = from.slice(0, 28);
    fromDiv.title = from;
    fromDiv.textContent = fromSnippet;
    row.appendChild(fromDiv);

    const subjDiv = document.createElement("div");
    subjDiv.className = "mail-subject";
    const draftBadge = m.isDraft ? '<span style="background:var(--warning-subtle,#fef3c7); color:var(--warning,#d97706); padding:0.1rem 0.3rem; border-radius:3px; font-size:0.7rem; margin-right:0.3rem;">Draft</span>' : '';
    const bodySnippet = (m.body_text || m.snippet || '').replace(/<[^>]+>/g, '').trim().slice(0, 100);
    subjDiv.title = `${from}\n${subj}\n${bodySnippet}`;
    // Subject text (wrapped for ellipsis)
    const subjText = document.createElement('span');
    subjText.className = 'mail-subject-text';
    subjText.innerHTML = draftBadge + escapeHtml(subj.slice(0, 80));
    subjDiv.appendChild(subjText);
    row.appendChild(subjDiv);

    // Body snippet
    const snippet = (m.body_text || "").replace(/<[^>]+>/g, "").trim().slice(0, 60);
    if (snippet) {
      const snippetDiv = document.createElement("div");
      snippetDiv.className = "mail-snippet";
      snippetDiv.textContent = snippet;
      row.appendChild(snippetDiv);
    }

    // Tag badges (to the right of the body snippet)
    if (m.tags && m.tags.length) {
      const tagsWrap = document.createElement('span');
      tagsWrap.className = 'mail-row-tags';
      m.tags.slice(0, 3).forEach(t => {
        const badge = document.createElement('span');
        badge.className = 'mail-tag-badge-inline';
        badge.style.cssText = `background:${escapeHtml(t.color || '#6c757d')};`;
        badge.textContent = t.title;
        tagsWrap.appendChild(badge);
      });
      row.appendChild(tagsWrap);
    }

    // Auto-link status icon (after subject, before expand button)
    if (m.linked_deals && m.linked_deals.length > 0) {
      const linkIcon = document.createElement("span");
      linkIcon.className = "mail-link-icon linked";
      linkIcon.title = "Linked: " + m.linked_deals.map(d => `${d.title} (#${d.deal_id})`).join(", ");
      linkIcon.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M9 15l6 -6"/><path d="M11 6l.463 -.536a5 5 0 0 1 7.071 7.072l-.534 .464"/><path d="M13 18l-.397 .534a5.068 5.068 0 0 1 -7.127 0a4.972 4.972 0 0 1 0 -7.071l.524 -.463"/></svg>';
      row.appendChild(linkIcon);
    } else if (m.unlinked_reason) {
      const robotIcon = document.createElement("span");
      robotIcon.className = "mail-link-icon unlinked";
      robotIcon.title = "Unable to link: " + m.unlinked_reason;
      robotIcon.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M7 16a4 4 0 0 1 -2.5 -7.5"/><path d="M10 16a4 4 0 0 1 -2.5 -7.5"/><path d="M13 16a4 4 0 0 1 -2.5 -7.5"/><path d="M16 16a4 4 0 0 1 -2.5 -7.5"/><path d="M4 8h16"/><path d="M8 12h8"/></svg>';
      row.appendChild(robotIcon);
    }

    // Attachment icon
    if (m.attachment_count > 0 || (m.attachments && m.attachments.length > 0)) {
      const attIcon = document.createElement("span");
      attIcon.className = "mail-link-icon has-attachments";
      attIcon.title = `${m.attachment_count || m.attachments.length} attachment(s)`;
      attIcon.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M15 7l-6.5 6.5a1.5 1.5 0 0 0 3 3l6.5 -6.5a3 3 0 0 0 -6 -6l-6.5 6.5a4.5 4.5 0 0 0 9 9l6.5 -6.5"/></svg>';
      row.appendChild(attIcon);
    }

    const dateDiv = document.createElement("div");
    dateDiv.className = "mail-date";
    dateDiv.textContent = dateStr;
    row.appendChild(dateDiv);

    // Expand button for viewing full email (lazy load, copy from deal preview modal)
    const expBtn = document.createElement("button");
    expBtn.type = "button";
    expBtn.className = "mail-expand-btn";
    expBtn.title = "View email";
    expBtn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M16 4l4 0l0 4"/><path d="M14 10l6 -6"/><path d="M8 20l-4 0l0 -4"/><path d="M4 20l6 -6"/><path d="M16 20l4 0l0 -4"/><path d="M14 14l6 6"/><path d="M8 4l-4 0l0 4"/><path d="M4 4l6 6"/></svg>';
    row.appendChild(expBtn);

    const cb = row.querySelector(".mail-cb");
    cb.addEventListener("click", (e) => {
      e.stopImmediatePropagation();
      if (cb.checked) mailState.selected.add(id);
      else mailState.selected.delete(id);
      if (cb.checked) row.classList.add("selected");
      else row.classList.remove("selected");
      updateMailSelectedInfo();
    });

    row.addEventListener("click", (e) => {
      if (e.target.tagName === "INPUT" || e.target.closest('.mail-expand-btn')) return;
      // Clicking row expands the email inline
      const isHidden = detail.classList.contains("hidden");
      detail.classList.toggle("hidden");
      if (!isHidden) {
        // Collapsing — remove from tracking
        mailState.expandedIds.delete(id);
        delete mailState.expandedContent[id];
        return;
      }
      // Expanding — track it
      mailState.expandedIds.add(id);
      if (item._mailLoaded) return;
      item._mailLoaded = true;
      fetchMailMessage(id).then(fullMail => {
        if (getMailMessageIsRead(fullMail)) {
          mailDashboardReadIds.add(id);
          saveMailDashboardReadIds();
        }
        markMailMessageRead(id).catch(() => {});
        row.classList.add('mail-row-read');
        detail.innerHTML = "";
        const embed = document.createElement("div");
        embed.className = "opp-preview-mail-embed";
        detail.appendChild(embed);
        renderMailEmbedPanel(embed, fullMail, id, { openUrl: portalMailMessageUrl(id) });
        // Cache for background refresh restoration
        mailState.expandedContent[id] = fullMail;
      }).catch(err => {
        detail.innerHTML = `<div class="mail-empty">Failed to load: ${escapeHtml(err.message || err)}</div>`;
      });
    });

    // Right-click context menu for email actions
    item.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      // Remove any existing context menu
      document.querySelectorAll('.mail-context-menu').forEach(m => m.remove());

      // Select this message for link/tag operations
      mailState.selected.add(id);
      updateMailSelectedInfo();

      const menu = document.createElement('div');
      menu.className = 'mail-context-menu';

      const menuItems = [
        { icon: 'ti ti-arrow-back-up', label: 'Reply', click: () => { openEmailPreviewModal(id); setTimeout(() => { const btn = document.querySelector('.email-preview-action[data-action="reply"]'); if (btn) btn.click(); }, 200); } },
        { icon: 'ti ti-arrow-forward-up', label: 'Forward', click: () => { openEmailPreviewModal(id); setTimeout(() => { const btn = document.querySelector('.email-preview-action[data-action="forward"]'); if (btn) btn.click(); }, 200); } },
        'separator',
        { icon: getMailMessageIsRead(m) ? 'ti ti-mail' : 'ti ti-mail-opened', label: getMailMessageIsRead(m) ? 'Mark unread' : 'Mark read', click: async () => { if (getMailMessageIsRead(m)) { try { await api(`/api/v2/mail/messages/${id}/unread`, { method: 'PUT' }); } catch {} } else { await markMailMessageRead(id); } loadMailMessagesForModal(); } },
        { icon: 'ti ti-star', label: 'Star', click: async () => { try { await api(`/api/v2/mail/messages/${id}/star`, { method: 'PUT' }); loadMailMessagesForModal(); } catch {} } },
        { icon: 'ti ti-archive', label: 'Archive', click: async () => { try { await api(`/api/v2/mail/messages/${id}/move`, { method: 'POST', body: JSON.stringify({ folder: 'Archive' }) }); loadMailMessagesForModal(); } catch {} } },
        { icon: 'ti ti-trash', label: 'Delete', click: async () => { if (!confirm('Delete this email?')) return; try { await api(`/api/v2/mail/messages/${id}`, { method: 'DELETE' }); loadMailMessagesForModal(); } catch {} } },
        'separator',
        { icon: 'ti ti-link', label: 'Link to deal', click: () => {
          setTimeout(() => {
            const linkDropdown = document.querySelector('#mail-link-deal-dropdown');
            if (linkDropdown) {
              linkDropdown.classList.remove('hidden');
              const search = document.querySelector('#mail-link-deal-search');
              if (search) { search.value = ''; search.focus(); }
            }
          }, 50);
        }},
        { icon: 'ti ti-tag', label: 'Tag', hasSubmenu: true, loadSubmenu: async (parentEl) => {
          try {
            const data = await api('/api/v2/mail/tags');
            const tags = data.tags || [];
            if (!tags.length) {
              const empty = document.createElement('div');
              empty.style.cssText = 'padding:0.4rem 0.75rem; color:var(--muted); font-size:0.8rem;';
              empty.textContent = 'No tags yet';
              parentEl.appendChild(empty);
              return;
            }
            tags.forEach(tag => {
              const btn = document.createElement('button');
              btn.type = 'button';
              btn.className = 'mail-context-subitem';
              btn.innerHTML = `<span class="mail-tag-dot" style="background:${escapeHtml(tag.color || '#6c757d')}; width:8px; height:8px; border-radius:50%; flex-shrink:0;"></span>${escapeHtml(tag.title)}`;
              btn.addEventListener('click', async (ev) => {
                ev.stopPropagation();
                try {
                  await api(`/api/v2/mail/messages/${id}/tags`, {
                    method: 'POST',
                    body: JSON.stringify({ title: tag.title }),
                  });
                  showToast(`Tagged "${tag.title}"`);
                  menu.remove();
                } catch (err) { showToast('Failed to tag: ' + err.message, true); return; }
                try { await loadMailMessagesForModal(); } catch (err) { console.error('Failed to refresh mail list', err); }
              });
              parentEl.appendChild(btn);
            });
          } catch { /* ignore */ }
        }},
      ];

      menuItems.forEach(item => {
        if (item === 'separator') {
          const sep = document.createElement('div');
          sep.className = 'mail-context-separator';
          menu.appendChild(sep);
          return;
        }
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'mail-context-item';
        btn.innerHTML = `<i class="${item.icon}"></i><span>${item.label}</span>`;
        if (item.hasSubmenu) {
          const arrow = document.createElement('i');
          arrow.className = 'ti ti-chevron-right';
          arrow.style.cssText = 'margin-left:auto; font-size:0.7rem; opacity:0.5;';
          btn.appendChild(arrow);
          const submenu = document.createElement('div');
          submenu.className = 'mail-context-submenu';
          btn.addEventListener('mouseenter', () => {
            submenu.innerHTML = '';
            submenu.classList.add('visible');
            item.loadSubmenu(submenu);
          });
          btn.addEventListener('mouseleave', () => {
            setTimeout(() => { if (!submenu.matches(':hover')) submenu.classList.remove('visible'); }, 100);
          });
          submenu.addEventListener('mouseleave', () => {
            setTimeout(() => { if (!btn.matches(':hover')) submenu.classList.remove('visible'); }, 100);
          });
          submenu.addEventListener('mouseenter', () => submenu.classList.add('visible'));
          btn.appendChild(submenu);
        } else {
          btn.addEventListener('click', () => { menu.remove(); item.click(); });
        }
        menu.appendChild(btn);
      });

      menu.style.left = Math.min(e.clientX, window.innerWidth - 200) + 'px';
      menu.style.top = Math.min(e.clientY, window.innerHeight - 300) + 'px';
      document.body.appendChild(menu);
      const closeMenu = (ev) => { if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener('click', closeMenu); } };
      setTimeout(() => document.addEventListener('click', closeMenu), 0);
    });

    // Note: attachments display handled inside renderMailEmbedPanel (expanded view)

    const detail = document.createElement("div");
    detail.className = "mail-detail hidden";
    item.appendChild(row);
    item.appendChild(detail);

    expBtn.addEventListener("click", async (e) => {
      e.stopImmediatePropagation();
      // Drafts: open compose pre-filled
      if (m.isDraft) {
        try {
          const draft = await api(`/api/v2/mail/drafts/${id}`);
          openComposeModal({
            to: draft.to_addr || '',
            subject: draft.subject || '',
            body: draft.body_html || draft.body_text || '',
            title: 'Edit Draft',
            draftId: draft.id,
          });
        } catch (err) { showToast('Failed to load draft: ' + err.message, true); }
        return;
      }
      // Open the full email preview modal
      if (getMailMessageIsRead(m)) {
        mailDashboardReadIds.add(id);
        saveMailDashboardReadIds();
      }
      markMailMessageRead(id).catch(() => {});
      row.classList.add('mail-row-read');
      openEmailPreviewModal(id);
    });

    list.appendChild(item);
  });
}

// Restore inline-expanded emails after a background re-render.
// For each ID that was expanded before the refresh, find the new DOM row,
// show its detail panel, and inject the cached content.
function restoreExpandedState() {
  if (!mailState.expandedIds.size) return;
  const list = $("#mail-list");
  if (!list) return;
  for (const id of mailState.expandedIds) {
    const cached = mailState.expandedContent[id];
    if (!cached) continue;
    const item = list.querySelector(`.mail-item[data-id="${id}"]`);
    if (!item) continue;
    const detail = item.querySelector(".mail-detail");
    if (!detail) continue;
    detail.classList.remove("hidden");
    detail.innerHTML = "";
    const embed = document.createElement("div");
    embed.className = "opp-preview-mail-embed";
    detail.appendChild(embed);
    renderMailEmbedPanel(embed, cached, id, { openUrl: portalMailMessageUrl(id) });
    item._mailLoaded = true;
  }
}

function updateMailSelectedInfo() {
  const n = mailState.selected.size;
  const hasSel = n > 0;
  const markReadBtn = $("#mail-mark-read");
  const markUnreadBtn = $("#mail-mark-unread");
  const delBtn = $("#mail-delete");
  const clearSelBtn = $("#mail-clear-selection");
  const linkDealBtn = $("#mail-link-deal-btn");
  const starBtn = $("#mail-star");
  const archiveBtn = $("#mail-archive");
  const moveBtn = $("#mail-move-folder-btn");
  if (markReadBtn) markReadBtn.disabled = !hasSel;
  if (markUnreadBtn) markUnreadBtn.disabled = !hasSel;
  if (delBtn) delBtn.disabled = !hasSel;
  if (clearSelBtn) clearSelBtn.disabled = !hasSel;
  if (linkDealBtn) linkDealBtn.disabled = !hasSel;
  if (starBtn) starBtn.disabled = !hasSel;
  if (archiveBtn) archiveBtn.disabled = !hasSel;
  if (moveBtn) moveBtn.disabled = !hasSel;
  const tagBtn = $("#mail-tag-btn");
  if (tagBtn) {
    tagBtn.disabled = !hasSel;
    if (!hasSel) {
      const tagDropdown = $("#mail-tag-dropdown");
      if (tagDropdown) tagDropdown.classList.add("hidden");
    }
  }
}

async function markMailMessageRead(messageId) {
  const id = String(messageId);
  mailDashboardReadIds.add(id);
  saveMailDashboardReadIds();
  if (mailState && mailState.messages) {
    mailState.messages.forEach(m => {
      if (String(m.id || m.ID) === id) m.read = true;
    });
  }
  try {
    await api(`/api/v2/mail/messages/${id}/read`, { method: "PUT" });
  } catch {
    // best-effort, server mark is non-blocking
  }
}

 async function searchDealsForMailLink(query) {
  const resEl = $("#mail-link-deal-results");
  const linkBtn = $("#mail-link-deal-submit");
  if (!resEl) return;
  resEl.innerHTML = "";
  resEl.dataset.selectedDealId = "";
  if (linkBtn) linkBtn.disabled = true;
  const q = (query || "").trim();
  if (q.length < 1) {
    return;
  }
  try {
    const opps = await searchOpportunitiesByTitle(q, { limit: 8 });
    if (!opps.length) {
      const b = document.createElement("button");
      b.type = "button";
      b.disabled = true;
      b.textContent = "No matches";
      resEl.appendChild(b);
      return;
    }
    opps.forEach(opp => {
      const b = document.createElement("button");
      b.type = "button";
      b.textContent = opp.title;
      b.addEventListener("click", () => {
        resEl.querySelectorAll("button").forEach(x => x.classList.remove("selected"));
        b.classList.add("selected");
        resEl.dataset.selectedDealId = String(opp.id);
        if (linkBtn) linkBtn.disabled = mailState.selected.size === 0;
      });
      resEl.appendChild(b);
    });
  } catch (err) {
    showToast("Deal search failed: " + (err.message || err), true);
  }
}
window.searchDealsForMailLink = searchDealsForMailLink;

function bindCreateOpportunityModal() {
  const modal = $("#create-opportunity-modal");
  const form = $("#create-opportunity-form");
  if (!modal || !form || form.dataset.bound) return;
  form.dataset.bound = "1";

  form.addEventListener("submit", (e) => {
    submitCreateOpportunityForm(e).catch((err) => setCreateOpportunityError(err.message));
  });

  $("#create-opportunity-cancel")?.addEventListener("click", closeCreateOpportunityModal);
  modal.querySelectorAll("[data-create-opp-dismiss]").forEach((el) => {
    el.addEventListener("click", closeCreateOpportunityModal);
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !modal.classList.contains("hidden")) closeCreateOpportunityModal();
  });

  $("#create-opp-private")?.addEventListener("change", syncCreateOppPrivateFields);

  $("#create-opp-tag-add")?.addEventListener("change", (e) => {
    const title = e.target.value;
    if (!title) return;
    if (!state.createOppTags) state.createOppTags = [];
    if (!state.createOppTags.some(t => tagsEqual(t, title))) state.createOppTags.push(title);
    renderCreateOppTags();
  });

  bindCreateOppContactPicker();
}

async function loadTaskCategories({ force = false } = {}) {
  // Prefer in-memory cache
  if (state.taskCategories.length && !force) return;

  // Restore from localStorage cache (survives reloads / offline). We only hit the CRM server
  // to (re)validate the list on explicit login (see login paths).
  if (!state.taskCategories.length) {
    try {
      const cached = localStorage.getItem(TASK_CATEGORIES_KEY);
      if (cached) {
        const parsed = JSON.parse(cached);
        if (Array.isArray(parsed) && parsed.length) {
          state.taskCategories = parsed;
          if (!force) return;
        }
      }
    } catch {}
  }

  if (!force && state.taskCategories.length) return;

  try {
    const data = await api("/api/v2/history-categories");
    state.taskCategories = unwrap(data);
    try {
      localStorage.setItem(TASK_CATEGORIES_KEY, JSON.stringify(state.taskCategories));
    } catch {}
  } catch {
    if (!state.taskCategories.length) state.taskCategories = [];
  }
}

async function searchOpportunitiesByTitle(query, { limit = 30 } = {}) {
  const q = String(query || "").trim();
  const local = [];
  const seen = new Set();
  const qLower = q.toLowerCase();
  const isNumeric = /^\d+$/.test(q);

  for (const g of state.groups) {
    for (const o of g.opportunities || []) {
      const id = o.id ?? o.ID;
      if (id == null) continue;
      const title = (o.title || o.Title || `Project #${id}`).trim();
      const key = String(id);
      if (seen.has(key)) continue;
      // Match by title OR by ID (if query is numeric)
      if (!q || title.toLowerCase().includes(qLower) || (isNumeric && String(id) === q)) {
        seen.add(key);
        local.push({ id: Number(id), title });
      }
    }
  }

  if (q.length >= 2) {
    try {
      const params = new URLSearchParams({ startIndex: "0", count: "40", filterValue: q, stageType: "0" });
      const data = await api(`/api/v2/projects?${params}`);
      for (const o of unwrap(data)) {
        const id = o.id ?? o.ID;
        if (id == null) continue;
        const key = String(id);
        if (seen.has(key)) continue;
        seen.add(key);
        local.push({ id: Number(id), title: (o.title || o.Title || `Project #${id}`).trim() });
        indexOpportunity(o);
      }
    } catch {
      /* use local matches only */
    }
  }

  return local.sort((a, b) => String(a.title || "").localeCompare(String(b.title || ""))).slice(0, limit);
}

const ICON_EXTERNAL_LINK = `<svg class="crm-open-external-icon" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/></svg>`;

