function findGroupForOpportunity(oppId) {
  const id = Number(oppId);
  if (!Number.isFinite(id)) return null;
  for (const g of state.groups) {
    for (const col of groupOpportunities(g)) {
      for (const o of col.items || []) {
        if (Number(o.id ?? o.ID) === id) return g;
      }
    }
  }
  return null;
}

function setOpportunityPreviewContext(oppId, opp = null, group = null) {
  if (oppId == null) {
    oppPreviewContext = { oppId: null, opp: null, group: null };
    return;
  }
  const id = Number(oppId);
  oppPreviewContext = {
    oppId: Number.isFinite(id) ? id : null,
    opp: opp || null,
    group: group || null,
  };
}

async function openDealEditFromOpportunityPreview() {
  const { oppId, opp, group } = oppPreviewContext;
  if (oppId == null) {
    showToast("Project not loaded", true);
    return;
  }
  let deal = opp;
  if (!deal) {
    try {
      deal = await fetchOpportunityForUpdate(oppId);
    } catch (err) {
      showToast(err.message, true);
      return;
    }
  }
  const refreshGroup = group || findGroupForOpportunity(oppId);
  // Open deal-edit (incl. its note editor) as a side popup to the LEFT of preview (instead of on top).
  // Allows viewing/scrolling preview history + interacting with note (and deal fields) simultaneously.
  // Escape in preview prefers closing the side editor first.
  try {
    await openDealEditModal(deal, refreshGroup);
  } catch (err) {
    showToast(err.message, true);
  }
}

function closeOpportunityPreviewModal() {
  if (_previewDirty) {
    confirmDialog({
      title: "Discard unsaved changes?",
      message: "You have unsaved changes that will be lost.",
      confirmLabel: "Discard",
      danger: true,
    }).then((ok) => {
      if (ok) {
        _previewDirty = false;
        _doClosePreviewModal();
      }
    });
    return;
  }
  _doClosePreviewModal();
}

function _doClosePreviewModal() {
  _previewDirty = false;
  restoreSideBySideCards();
  oppPreviewMailCache.clear();
  setOpportunityPreviewContext(null);
  // Notify any open document-preview pane to reset its state (so the iframe
  // doesn't keep a session alive after the modal is hidden).
  window.dispatchEvent(new CustomEvent("opp-preview-modal-closing"));
  $("#opp-preview-modal")?.classList.add("hidden");
}

function layoutSideBySideDealEditAndPreview() {
  const previewModal = $("#opp-preview-modal");
  // Support either deal-edit or quick-note as the side editor popup
  let sideModal = $("#deal-edit-modal");
  let isQuick = false;
  if (!sideModal || sideModal.classList.contains("hidden")) {
    sideModal = $("#quick-note-modal");
    isQuick = true;
  }
  if (!previewModal || previewModal.classList.contains("hidden") || !sideModal || sideModal.classList.contains("hidden")) return;
  const pCard = previewModal.querySelector(".modal-card");
  const sCard = sideModal.querySelector(".modal-card");
  if (!pCard || !sCard) return;

  // hook resize once for re-layout on orientation/resize
  if (!window._sideBySideResizeHooked) {
    window._sideBySideResizeHooked = true;
    window.addEventListener("resize", () => {
      const p = $("#opp-preview-modal");
      const d = $("#deal-edit-modal");
      const q = $("#quick-note-modal");
      if (p && !p.classList.contains("hidden") && ((d && !d.classList.contains("hidden")) || (q && !q.classList.contains("hidden")))) {
        layoutSideBySideDealEditAndPreview();
      }
    }, { passive: true });
  }

  if (pCard.dataset.origStyle == null) pCard.dataset.origStyle = pCard.getAttribute("style") || "";
  if (sCard.dataset.origStyle == null) sCard.dataset.origStyle = sCard.getAttribute("style") || "";

  const isMobile = window.innerWidth < 700;
  const gap = 12;
  let sideW, previewW, sideLeft, previewLeft, sideTop, previewTop;
  const baseTop = 20;

  if (isMobile) {
    // On mobile: fix the quick edit popup to the TOP of the deal preview modal (stacked vertically)
    // side on top, preview shifted below so both remain visible and interactive.
    const w = Math.min(720, window.innerWidth - 24);
    sideW = w;
    previewW = w;
    sideLeft = 12;
    previewLeft = 12;
    sideTop = baseTop;
    previewTop = baseTop + 180 + gap;  // lower initial guess; dynamic adjust will snap
  } else {
    // Desktop: side (left) + preview (right) side-by-side
    sideW = Math.min(440, Math.floor(window.innerWidth * 0.38));
    previewW = Math.min(680, Math.floor(window.innerWidth * 0.48));
    const total = sideW + previewW + gap;
    const left = Math.max(12, Math.floor((window.innerWidth - total) / 2));
    sideLeft = left;
    previewLeft = left + sideW + gap;
    sideTop = 36;
    previewTop = 36;
  }

  sCard.style.cssText = `position:fixed!important; left:${sideLeft}px!important; top:${sideTop}px!important; width:${sideW}px!important; height:${isMobile ? "40vh" : "92vh"}!important; max-height:${isMobile ? "40vh" : "92vh"}!important; overflow:auto!important; z-index:2100!important; margin:0!important; box-shadow:var(--shadow); pointer-events:auto!important;`;
  pCard.style.cssText = `position:fixed!important; left:${previewLeft}px!important; top:${previewTop}px!important; width:${previewW}px!important; height:${isMobile ? "55vh" : "92vh"}!important; max-height:${isMobile ? "55vh" : "92vh"}!important; overflow:auto!important; z-index:2005!important; margin:0!important; box-shadow:var(--shadow);`;

  if (isMobile) {
    // Improved mobile vertical stacking: side (edit/quick) fixed near top, preview pushed below it
    // with ~4px gap. Uses longer delay + rAF + ResizeObserver so dynamic content (note body, selects, tags)
    // doesn't cause the side to grow over the preview after initial measure. Constrains side max-height too.
    const adjustMobileVerticalStack = () => {
      if (!sCard || !pCard || sideModal.classList.contains("hidden") || previewModal.classList.contains("hidden")) return;
      const sRect = sCard.getBoundingClientRect();
      const desiredPTop = Math.max(baseTop + 80, sRect.bottom + 4);
      pCard.style.top = `${desiredPTop}px`;
      pCard.style.maxHeight = `calc(100vh - ${desiredPTop + 20}px)`;
      // keep side from growing infinitely over the preview area
      sCard.style.maxHeight = `min(45vh, calc(100vh - ${baseTop + 30}px))`;
    };

    // First paint adjust (longer than 25ms to let rich note, categories, tags fully layout)
    setTimeout(adjustMobileVerticalStack, 120);
    requestAnimationFrame(adjustMobileVerticalStack);

    // Live re-adjust if side resizes (user typing note, adding tags, etc.)
    if (!sCard._stackObserver) {
      sCard._stackObserver = new ResizeObserver(() => {
        clearTimeout(sCard._adjustT || 0);
        sCard._adjustT = setTimeout(adjustMobileVerticalStack, 40);
      });
      sCard._stackObserver.observe(sCard);
    }
  }

  // Hide side backdrop (preview's remains for dim)
  const sBack = sideModal.querySelector(".modal-backdrop");
  if (sBack) {
    sBack.style.display = "none";
    sBack.dataset.sideHidden = "1";
  }

  // Critical: allow interaction with preview while quick-edit is open.
  // The side .modal layer would otherwise block; pe:none on container + auto on its card lets events pass through except on the popup itself.
  sideModal.style.pointerEvents = "none";
  sideModal.style.zIndex = "2010";
  previewModal.style.zIndex = "2000";
}

/* Same layout logic but for search-popup modal instead of opp-preview-modal */
function layoutSideBySideDealEditAndSearchPopup() {
  const searchModal = $("#search-popup-modal");
  let sideModal = $("#deal-edit-modal");
  let isQuick = false;
  if (!sideModal || sideModal.classList.contains("hidden")) {
    sideModal = $("#quick-note-modal");
    isQuick = true;
  }
  if (!searchModal || searchModal.classList.contains("hidden") || !sideModal || sideModal.classList.contains("hidden")) return;
  const pCard = searchModal.querySelector(".modal-card");
  const sCard = sideModal.querySelector(".modal-card");
  if (!pCard || !sCard) return;

  if (pCard.dataset.origStyle == null) pCard.dataset.origStyle = pCard.getAttribute("style") || "";
  if (sCard.dataset.origStyle == null) sCard.dataset.origStyle = sCard.getAttribute("style") || "";

  const isMobile = window.innerWidth < 700;
  const gap = 12;
  let sideW, previewW, sideLeft, previewLeft, sideTop, previewTop;
  const baseTop = 20;

  if (isMobile) {
    const w = Math.min(900, window.innerWidth - 24);
    sideW = w;
    previewW = w;
    sideLeft = 12;
    previewLeft = 12;
    sideTop = baseTop;
    previewTop = baseTop + 180 + gap;
  } else {
    sideW = Math.min(440, Math.floor(window.innerWidth * 0.38));
    previewW = Math.min(900, Math.floor(window.innerWidth * 0.48));
    const total = sideW + previewW + gap;
    const left = Math.max(12, Math.floor((window.innerWidth - total) / 2));
    sideLeft = left;
    previewLeft = left + sideW + gap;
    sideTop = 36;
    previewTop = 36;
  }

  sCard.style.cssText = `position:fixed!important; left:${sideLeft}px!important; top:${sideTop}px!important; width:${sideW}px!important; height:${isMobile ? "40vh" : "92vh"}!important; max-height:${isMobile ? "40vh" : "92vh"}!important; overflow:auto!important; z-index:2100!important; margin:0!important; box-shadow:var(--shadow); pointer-events:auto!important;`;
  pCard.style.cssText = `position:fixed!important; left:${previewLeft}px!important; top:${previewTop}px!important; width:${previewW}px!important; height:${isMobile ? "55vh" : "92vh"}!important; max-height:${isMobile ? "55vh" : "92vh"}!important; overflow:auto!important; z-index:2005!important; margin:0!important; box-shadow:var(--shadow);`;

  if (isMobile) {
    const adjustMobileVerticalStack = () => {
      if (!sCard || !pCard || sideModal.classList.contains("hidden") || searchModal.classList.contains("hidden")) return;
      const sRect = sCard.getBoundingClientRect();
      const desiredPTop = Math.max(baseTop + 80, sRect.bottom + 4);
      pCard.style.top = `${desiredPTop}px`;
      pCard.style.maxHeight = `calc(100vh - ${desiredPTop + 20}px)`;
      sCard.style.maxHeight = `min(45vh, calc(100vh - ${baseTop + 30}px))`;
    };
    setTimeout(adjustMobileVerticalStack, 120);
    requestAnimationFrame(adjustMobileVerticalStack);
    if (!sCard._stackObserver) {
      sCard._stackObserver = new ResizeObserver(() => {
        clearTimeout(sCard._adjustT || 0);
        sCard._adjustT = setTimeout(adjustMobileVerticalStack, 40);
      });
      sCard._stackObserver.observe(sCard);
    }
  }

  const sBack = sideModal.querySelector(".modal-backdrop");
  if (sBack) {
    sBack.style.display = "none";
    sBack.dataset.sideHidden = "1";
  }
  sideModal.style.pointerEvents = "none";
  sideModal.style.zIndex = "2010";
  searchModal.style.zIndex = "2000";
}

function restoreSideBySideCards() {
  const previewModal = $("#opp-preview-modal");
  const searchModal = $("#search-popup-modal");
  const editModal = $("#deal-edit-modal");
  [previewModal, searchModal, editModal].forEach((modal) => {
    if (!modal) return;
    const card = modal.querySelector(".modal-card");
    if (card && card.dataset.origStyle != null) {
      card.setAttribute("style", card.dataset.origStyle);
      delete card.dataset.origStyle;
    }
  });
  if (editModal) {
    editModal.style.pointerEvents = "";
    editModal.style.zIndex = "";
    const eBack = editModal.querySelector(".modal-backdrop");
    if (eBack && eBack.dataset.sideHidden) {
      eBack.style.display = "";
      delete eBack.dataset.sideHidden;
    }
  }
  if (previewModal) {
    previewModal.style.zIndex = "";
  }
  if (searchModal) {
    searchModal.style.zIndex = "";
  }
}

function updatePreviewModalBookmarkButton(oppId) {
  const btn = $("#opp-preview-bookmark");
  if (!btn) return;
  const id = Number(oppId);
  const bookmarked = isDealBookmarked(id);
  btn.classList.toggle("bookmarked", bookmarked);
  btn.title = bookmarked ? "Remove bookmark" : "Bookmark deal";
  btn.setAttribute("aria-label", btn.title);
  btn.innerHTML = bookmarkRibbonSvg(bookmarked);
}

async function openOpportunityPreviewModal(oppId, titleHint = "", group = null, quick = false) {
  const modal = $("#opp-preview-modal");
  const body = $("#opp-preview-body");
  const titleEl = $("#opp-preview-title");
  if (!modal || !body || !titleEl) return;

  const id = Number(oppId);
  oppPreviewMailCache.clear();
  setOpportunityPreviewContext(id, null, group);
  titleEl.textContent = titleHint || "Project";
  body.innerHTML = '<p class="opp-preview-loading">Loading project…</p>';
  modal.classList.remove("hidden");
  updatePreviewModalBookmarkButton(id);

  try {
    const data = await fetchOpportunityPreviewData(id, quick);
    const resolvedGroup = group || findGroupForOpportunity(id);
    setOpportunityPreviewContext(id, data.opp, resolvedGroup);
    titleEl.textContent = data.opp.title || data.opp.Title || titleHint || `Project #${id}`;
    setOpportunityPreviewCrmLink(id, data.opp.project_number);

    // Project number badge
    const existingBadge = titleEl.parentElement?.querySelector('.opp-project-number-badge');
    if (existingBadge) existingBadge.remove();
    const projNum = data.opp.project_number || id;
    if (projNum) {
      const badge = document.createElement("span");
      badge.className = "opp-project-number-badge";
      badge.textContent = `#${projNum}`;
      badge.title = "Click to copy project number";
      badge.style.cssText = "background:var(--bg-elevated); padding:0.2rem 0.5rem; border-radius:4px; cursor:pointer; font-size:0.85rem; color:var(--text); margin-left:0.5rem;";
      badge.addEventListener("click", () => {
        safeCopyToClipboard(`#${projNum}`).then(() => showToast("Copied to clipboard")).catch(() => {});
      });
      const actionsEl = titleEl.parentElement?.querySelector('.opp-preview-head-actions');
      if (actionsEl) titleEl.parentElement.insertBefore(badge, actionsEl);
      else titleEl.parentElement.appendChild(badge);
    }

    renderOpportunityPreviewBody(data);
    linkifyPhonesAndEmails(body);
    updateInferredStatus("preview", data.opp.title || data.opp.Title || titleHint || "");
  } catch (err) {
    body.innerHTML = `<p class="opp-preview-error">${escapeHtml(err.message)}</p>`;
    showToast(err.message, true);
  }
}

function bindOpportunityPreviewModal() {
  const modal = $("#opp-preview-modal");
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = "1";
  $("#opp-preview-edit")?.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    openDealEditFromOpportunityPreview();
  });
  $("#opp-preview-bookmark")?.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const ctx = oppPreviewContext;
    if (!ctx || ctx.oppId == null) return;
    const id = Number(ctx.oppId);
    const title = ctx.opp ? (ctx.opp.title || ctx.opp.Title || "") : "";
    if (isDealBookmarked(id)) {
      removeBookmarkDeal(id);
    } else {
      addBookmarkDeal(id, title);
    }
    updatePreviewModalBookmarkButton(id);
  });
  modal.querySelectorAll("[data-opp-preview-dismiss]").forEach((el) => {
    el.addEventListener("click", closeOpportunityPreviewModal);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && modal && !modal.classList.contains("hidden")) {
      const editM = $("#deal-edit-modal");
      if (editM && !editM.classList.contains("hidden")) {
        closeDealEditModal(); // close side note/edit popup first, keep preview
      } else {
        closeOpportunityPreviewModal();
      }
    }
  });
}

function bindGlobalOpportunitySearch() {
  const wrap = $("#global-opp-search");
  const input = $("#global-opp-search-input");
  const results = $("#global-opp-search-results");
  if (!wrap || !input || !results || input.dataset.bound) return;
  input.dataset.bound = "1";

  let debounce;
  const hideResults = () => results.classList.add("hidden");

  const renderResults = (opps, q) => {
    results.innerHTML = "";
    if (!q.length) {
      hideResults();
      return;
    }
    results.classList.remove("hidden");
    if (q.length < 2 && !opps.length) {
      results.innerHTML = '<span class="search-empty">Type 2+ characters to search CRM</span>';
      return;
    }
    if (!opps.length) {
      results.innerHTML = '<span class="search-empty">No opportunities found</span>';
      return;
    }
    for (const o of opps) {
      const row = document.createElement("div");
      row.className = "global-opp-search-item";
      row.setAttribute("role", "option");

      const titleBtn = document.createElement("button");
      titleBtn.type = "button";
      titleBtn.className = "global-opp-search-item-title";
      titleBtn.textContent = o.title;
      titleBtn.addEventListener("click", (e) => {
        e.preventDefault();
        input.value = "";
        hideResults();
        openOpportunityPreviewModal(o.id, o.title).catch((err) => showToast(err.message, true));
      });

      row.appendChild(titleBtn);
      results.appendChild(row);
    }
  };

  input.addEventListener("input", () => {
    clearTimeout(debounce);
    debounce = setTimeout(async () => {
      const q = input.value.trim();
      if (!q.length) {
        hideResults();
        return;
      }
      try {
        const opps = await searchOpportunitiesByTitle(q);
        renderResults(opps, q);
      } catch (err) {
        showToast(err.message, true);
      }
    }, 300);
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      input.value = "";
      hideResults();
      input.blur();
    }
  });

  document.addEventListener("click", (e) => {
    if (!wrap.contains(e.target)) hideResults();
  });
}

/* ================================================================================
   Search popup modal — large search with tabbed preview (max 5 tabs)
   ================================================================================ */

function bindSearchPopupBtn() {
  const btn = $("#search-popup-btn");
  if (!btn || btn.dataset.bound) return;
  btn.dataset.bound = "1";
  btn.addEventListener("click", () => openSearchPopupModal());
}

async function openSearchPopupModal() {
  const modal = $("#search-popup-modal");
  if (!modal) return;
  // Clear minimized flag whenever the popup is opened
  searchMinimized = false;
  try { localStorage.removeItem(SEARCH_MINIMIZED_FLAG_KEY); } catch {}
  const trigger = $("#search-trigger");
  if (trigger) trigger.classList.add("trigger-hidden");

  // Ensure dependencies are loaded before rendering filters
  if (!state.customFieldDefs.length) await loadOpportunityCustomFieldDefs();
  if (!state.allTags.length) await loadAllTags();
  if (!state.portalUsers.length) await loadPortalUsers();

  populateSearchFilterDropdowns();
  renderSearchPopupCustomFilters();

  // If modal is closed, no live tabs exist, and we have parked tabs — restore them
  if (modal.classList.contains("hidden") && searchPopupPreviewTabs.size === 0 && hasMinimizedSearchTabs()) {
    restoreMinimizedSearchTabs();
    modal.classList.remove("hidden");
    const input = $("#search-popup-input");
    if (input) { input.focus(); input.select(); }
    return;
  }
  modal.classList.remove("hidden");
  const input = $("#search-popup-input");
  if (input) {
    input.focus();
    input.select();
  }
  activateSearchPopupTab("projects");
}

function closeSearchPopupModal() {
  const modal = $("#search-popup-modal");
  if (!modal) return;
  modal.classList.add("hidden");
  // Clear all preview tabs
  for (const oppId of Array.from(searchPopupPreviewTabs.keys())) {
    closeSearchPreviewTab(oppId);
  }
  const input = $("#search-popup-input");
  if (input) input.value = "";
  const tagFilter = $("#search-popup-tag-filter");
  if (tagFilter) tagFilter.value = "";
  const stageFilter = $("#search-popup-stage-filter");
  if (stageFilter) stageFilter.value = "";
  const respFilter = $("#search-popup-responsible-filter");
  if (respFilter) respFilter.value = "";
  const sortSel = $("#search-popup-sort");
  if (sortSel) sortSel.value = "date_created:descending";
  const results = $("#search-popup-results");
  if (results) results.innerHTML = "";
  const resultsCount = $("#search-popup-results-count");
  if (resultsCount) resultsCount.textContent = "";
  hideSearchPopupError();
  searchPopupCurrentOpps = [];
  searchPopupCurrentTagLabel = null;
  searchPopupCustomFilters = [];
  searchPopupStartIndex = 0;
  searchPopupTotal = 0;
  clearSearchPopupSelection();
  renderSearchPopupCustomFilters();
  updateSearchPopupPagination();
  // Also clear parked/minimized tabs (close = discard)
  clearMinimizedSearchTabs();
}

/* ── Minimized search tabs (parked tabs, persisted like bookmarks) ─────────── */

function hasMinimizedSearchTabs() {
  return Array.isArray(minimizedSearchTabs) && minimizedSearchTabs.length > 0;
}

function clearMinimizedSearchTabs() {
  minimizedSearchTabs = [];
  saveMinimizedSearchTabsToStorage();
  searchMinimized = false;
  try { localStorage.removeItem(SEARCH_MINIMIZED_FLAG_KEY); } catch {}
  const trigger = $("#search-trigger");
  if (trigger) trigger.classList.add("trigger-hidden");
}

function minimizeSearchPopup() {
  const modal = $("#search-popup-modal");
  if (!modal) return;

  // Collect current preview tabs
  const parked = [];
  for (const [oppId, tab] of searchPopupPreviewTabs) {
    parked.push({ oppId, title: tab.title || "" });
  }
  // Enforce limit: keep at most MAX_SEARCH_PREVIEW_TABS entries (minus 1 for the search tab)
  minimizedSearchTabs = parked.slice(0, MAX_SEARCH_PREVIEW_TABS);

  // Clear live tabs (remove buttons/containers, clear the Map)
  for (const oppId of Array.from(searchPopupPreviewTabs.keys())) {
    closeSearchPreviewTab(oppId);
  }

  // Save and hide modal
  saveMinimizedSearchTabsToStorage();
  searchMinimized = true;
  try { localStorage.setItem(SEARCH_MINIMIZED_FLAG_KEY, "1"); } catch {}
  modal.classList.add("hidden");

  // Show search trigger unless sidebar is open
  const sidebar = $("#bookmark-sidebar");
  const searchTrigger = $("#search-trigger");
  if (searchTrigger) {
    if (sidebar && !sidebar.classList.contains("sidebar-hidden")) {
      searchTrigger.classList.add("trigger-hidden");
    } else {
      searchTrigger.classList.remove("trigger-hidden");
    }
  }
}

function restoreMinimizedSearchTabs() {
  if (!hasMinimizedSearchTabs() && !searchMinimized) return;
  const toRestore = [...minimizedSearchTabs];
  minimizedSearchTabs = [];
  saveMinimizedSearchTabsToStorage();
  searchMinimized = false;
  try { localStorage.removeItem(SEARCH_MINIMIZED_FLAG_KEY); } catch {}

  // Recreate each preview tab
  for (const t of toRestore) {
    if (Number.isFinite(t.oppId) && t.oppId > 0) {
      openSearchPreviewTab(t.oppId, t.title);
    }
  }
  // Land on search tab
  activateSearchPopupTab("search");
}

// ── Email modal minimize/restore ──────────────────────────────────────────────
let minimizedEmailState = null;
let _mailInboxAutoRefreshTimer = null;
const EMAIL_MINIMIZED_STORAGE_KEY = "oo_email_minimized_v1";

function minimizeEmailModal() {
  const modal = $("#mail-inbox-modal");
  if (!modal) return;
  if (_mailInboxAutoRefreshTimer) { clearInterval(_mailInboxAutoRefreshTimer); _mailInboxAutoRefreshTimer = null; }
  const scrollEl = $("#mail-list-container");
  const selectedEl = document.querySelector(".mail-list-row.selected, .mail-row.selected");
      minimizedEmailState = {
    scroll: scrollEl ? scrollEl.scrollTop : 0,
    selectedId: selectedEl ? selectedEl.dataset.id || selectedEl.dataset.convId || null : null,
    composeTabs: [],
  };
  // Save open compose tabs
  const tabBar = $('#mail-inbox-tabs');
  if (tabBar) {
    tabBar.querySelectorAll('.compose-tab').forEach(tabBtn => {
      const tabId = tabBtn.dataset.tabId;
      const pane = $(`#mail-compose-tab-${tabId}`);
      if (pane) {
        minimizedEmailState.composeTabs.push({
          tabId,
          title: tabBtn.querySelector('.compose-tab-title')?.textContent || '',
          from: pane.querySelector('.compose-tab-from')?.value || '',
          to: pane.querySelector('.compose-tab-to')?.value || '',
          cc: pane.querySelector('.compose-tab-cc')?.value || '',
          bcc: pane.querySelector('.compose-tab-bcc')?.value || '',
          subject: pane.querySelector('.compose-tab-subject')?.value || '',
          body: pane.querySelector('.compose-tab-body')?.innerHTML || '',
          dealId: pane.querySelector('.compose-tab-deal-selected')?.dataset?.dealId || null,
        });
      }
    });
  }
  try { localStorage.setItem(EMAIL_MINIMIZED_STORAGE_KEY, JSON.stringify(minimizedEmailState)); } catch {}
  // Save to server for cross-device persistence
  api('/api/v2/minimized-state', {
    method: 'PUT',
    body: JSON.stringify({ email: minimizedEmailState }),
  }).catch(() => {});
  modal.classList.add("hidden");
  const trigger = $("#email-trigger");
  if (trigger) {
    const sidebar = $("#bookmark-sidebar");
    if (sidebar && !sidebar.classList.contains("sidebar-hidden")) {
      trigger.classList.add("trigger-hidden");
    } else {
      trigger.classList.remove("trigger-hidden");
    }
  }
}

function restoreEmailModal() {
  let state = minimizedEmailState;
  minimizedEmailState = null;
  try { localStorage.removeItem(EMAIL_MINIMIZED_STORAGE_KEY); } catch {}
  // If no local state, try loading from server (cross-device restore)
  const doRestore = (s) => {
    const trigger = $("#email-trigger");
    if (trigger) trigger.classList.add("trigger-hidden");
    openMailInboxModal().then(async () => {
      if (!s) return;
      const scrollEl = $("#mail-list-container");
      if (scrollEl && s.scroll) scrollEl.scrollTop = s.scroll;
      if (s.selectedId) {
        const row = document.querySelector(`.mail-list-row[data-id="${s.selectedId}"], .mail-row[data-id="${s.selectedId}"]`);
        if (row) row.click();
      }
      // Restore compose tabs
      if (s.composeTabs && s.composeTabs.length) {
        for (const ct of s.composeTabs) {
          composeTabCounter++;
          const newTabId = `compose-${composeTabCounter}`;
          const tabBar = $('#mail-inbox-tabs');
          if (tabBar) {
            const tabBtn = document.createElement('button');
            tabBtn.className = 'mail-inbox-tab compose-tab';
            tabBtn.dataset.mailtab = newTabId;
            tabBtn.dataset.tabId = newTabId;
            const tabTitle = ct.title || (ct.subject ? ct.subject.slice(0, 25) : `Compose ${composeTabCounter}`);
            tabBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-right:0.2rem;vertical-align:middle;"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M3 7a2 2 0 0 1 2 -2h14a2 2 0 0 1 2 2v10a2 2 0 0 1 -2 2h-14a2 2 0 0 1 -2 -2v-10" /><path d="M6.36 5a2 2 0 0 1 1.962 1.608l.356 1.784a2 2 0 0 0 1.962 1.608h8.36a2 2 0 0 1 2 2" /><path d="M12.36 5a2 2 0 0 1 1.962 1.608l.356 1.784a2 2 0 0 0 1.962 1.608" /></svg><span class="compose-tab-title">${escapeHtml(tabTitle)}</span><button type="button" class="compose-tab-close" title="Close tab">&times;</button>`;
            tabBtn.addEventListener('click', (e) => {
              if (e.target.closest('.compose-tab-close')) { closeComposeTab(newTabId); return; }
              switchToComposeTab(newTabId);
            });
            tabBar.appendChild(tabBtn);
          }
          let contentPane = document.getElementById(`mail-compose-tab-${newTabId}`);
          if (!contentPane) contentPane = document.querySelector('.compose-tab-content');
          if (!contentPane) contentPane = document.getElementById('mail-compose-tab-content');
          if (contentPane) {
            contentPane.id = `mail-compose-tab-${newTabId}`;
            contentPane.classList.remove('hidden');
            renderComposeTabContent(contentPane, newTabId, { from: ct.from, to: ct.to, cc: ct.cc, bcc: ct.bcc, subject: ct.subject, body: ct.body, dealId: ct.dealId });
          }
          switchToComposeTab(newTabId);
        }
      }
    }).catch(() => {});
  };
  if (state) {
    doRestore(state);
  } else {
    // Load from server
    api('/api/v2/minimized-state').then(serverState => {
      if (serverState && serverState.email) {
        minimizedEmailState = serverState.email;
        doRestore(serverState.email);
        // Clear server state after restore
        api('/api/v2/minimized-state', { method: 'PUT', body: JSON.stringify({}) }).catch(() => {});
      }
    }).catch(() => {});
  }
}

// ── Presence modal minimize/restore ─────────────────────────────────────────
const PRESENCE_MINIMIZED_STORAGE_KEY = "oo_presence_minimized_v1";
let minimizedPresenceState = null;

function minimizePresenceModal() {
  const modal = $("#presence-modal");
  if (!modal) return;
  const activeTab = state.presenceTab || "team";
  const selectedUser = state.presenceSelectedUserId || null;
  const dmText = $("#presence-dm-text")?.value || "";
  const scrollEl = $("#presence-list");
  minimizedPresenceState = {
    tab: activeTab,
    selectedUser,
    dmText,
    scroll: scrollEl ? scrollEl.scrollTop : 0,
  };
  try { localStorage.setItem(PRESENCE_MINIMIZED_STORAGE_KEY, JSON.stringify(minimizedPresenceState)); } catch {}
  api("/api/v2/minimized-state", {
    method: "PUT",
    body: JSON.stringify({ presence: minimizedPresenceState }),
  }).catch(() => {});
  modal.classList.add("hidden");
  state.presenceModalOpen = false;
  stopPresencePolling();
  const trigger = $("#presence-trigger");
  if (trigger) {
    const sidebar = $("#bookmark-sidebar");
    if (sidebar && !sidebar.classList.contains("sidebar-hidden")) {
      trigger.classList.add("trigger-hidden");
    } else {
      trigger.classList.remove("trigger-hidden");
    }
  }
}

function restorePresenceModal() {
  let saved = minimizedPresenceState;
  minimizedPresenceState = null;
  try { localStorage.removeItem(PRESENCE_MINIMIZED_STORAGE_KEY); } catch {}
  const doRestore = (s) => {
    const trigger = $("#presence-trigger");
    if (trigger) trigger.classList.add("trigger-hidden");
    if (s?.tab) state.presenceTab = s.tab;
    if (s?.selectedUser) state.presenceSelectedUserId = s.selectedUser;
    openPresenceModal().then(() => {
      if (s?.dmText) {
        const ta = $("#presence-dm-text");
        if (ta) ta.value = s.dmText;
      }
      const scrollEl = $("#presence-list");
      if (scrollEl && s?.scroll) scrollEl.scrollTop = s.scroll;
    }).catch(() => {});
  };
  if (saved) {
    doRestore(saved);
  } else {
    api("/api/v2/minimized-state").then(serverState => {
      if (serverState?.presence) {
        minimizedPresenceState = serverState.presence;
        doRestore(serverState.presence);
        api("/api/v2/minimized-state", { method: "PUT", body: JSON.stringify({}) }).catch(() => {});
      }
    }).catch(() => {});
  }
}

function initPresenceTrigger() {
  const trigger = $("#presence-trigger");
  if (!trigger || trigger.dataset.bound) return;
  trigger.dataset.bound = "1";
  trigger.addEventListener("click", () => {
    trigger.classList.add("trigger-hidden");
    restorePresenceModal();
  });
  const sidebar = $("#bookmark-sidebar");
  const stored = tryParseJSON(localStorage.getItem(PRESENCE_MINIMIZED_STORAGE_KEY));
  if (stored && (!sidebar || sidebar.classList.contains("sidebar-hidden"))) {
    minimizedPresenceState = stored;
    trigger.classList.remove("trigger-hidden");
  }
}

// ── Documents modal minimize/restore ─────────────────────────────────────────
let minimizedDocsState = null;
const DOCS_MINIMIZED_STORAGE_KEY = "oo_docs_minimized_v1";

function minimizeDocsModal() {
  const modal = $("#documents-modal");
  if (!modal) return;
  minimizedDocsState = {
    scope: docsState.scope,
    searchQuery: docsState.searchQuery,
    currentProjectId: docsState.currentProjectId,
    currentProjectTitle: docsState.currentProjectTitle,
    ..._docsPreviewCurrentPayload(),
  };
  // When minimized, the iframe loses the live editor session anyway. Clear it
  // so we don't leak a "blank page loading" state while the modal is parked.
  closeDocumentPreview();
  try { localStorage.setItem(DOCS_MINIMIZED_STORAGE_KEY, JSON.stringify(minimizedDocsState)); } catch {}
  // Save to server for cross-device persistence
  api('/api/v2/minimized-state', {
    method: 'PUT',
    body: JSON.stringify({ docs: minimizedDocsState }),
  }).catch(() => {});
  modal.classList.add("hidden");
  const trigger = $("#documents-trigger");
  if (trigger) {
    const sidebar = $("#bookmark-sidebar");
    if (sidebar && !sidebar.classList.contains("sidebar-hidden")) {
      trigger.classList.add("trigger-hidden");
    } else {
      trigger.classList.remove("trigger-hidden");
    }
  }
}

function restoreDocsModal() {
  const state = minimizedDocsState;
  minimizedDocsState = null;
  try { localStorage.removeItem(DOCS_MINIMIZED_STORAGE_KEY); } catch {}
  const trigger = $("#documents-trigger");
  if (trigger) trigger.classList.add("trigger-hidden");
  // Restore state before opening
  if (state) {
    docsState.scope = state.scope || "projects";
    docsState.searchQuery = state.searchQuery || "";
    docsState.currentProjectId = state.currentProjectId || null;
    docsState.currentProjectTitle = state.currentProjectTitle || null;
    const searchInput = $("#documents-search-input");
    if (searchInput) searchInput.value = state.searchQuery || "";
    document.querySelectorAll(".documents-scope-btn").forEach(b => b.classList.toggle("active", b.dataset.scope === docsState.scope));
  }
  openDocumentsModal();
  // Restore preview pane after the list has had a chance to render.
  if (state && state.previewDocId) {
    _docsPreviewRestoreFromPayload(state);
  }
}

// ── Sidebar trigger coordination ─────────────────────────────────────────────
function hideAllModalTriggers() {
  ["search-trigger", "email-trigger", "documents-trigger"].forEach(id => {
    const el = $(`#${id}`);
    if (el) el.classList.add("trigger-hidden");
  });
}

function showActiveModalTriggers() {
  const sidebar = $("#bookmark-sidebar");
  const sidebarOpen = sidebar && !sidebar.classList.contains("sidebar-hidden");
  if (sidebarOpen) return;
  if (searchMinimized || hasMinimizedSearchTabs()) {
    const st = $("#search-trigger");
    if (st) st.classList.remove("trigger-hidden");
  }
  if (minimizedEmailState) {
    const et = $("#email-trigger");
    if (et) et.classList.remove("trigger-hidden");
  }
  if (minimizedDocsState) {
    const dt = $("#documents-trigger");
    if (dt) dt.classList.remove("trigger-hidden");
  }
}

// ── Contacts search tab ───────────────────────────────────────────────────

function activateContactsSearchTab() {
  performSearchContactsQuery();
  const input = $("#search-popup-contacts-input");
  if (input) input.focus();
}

async function performSearchContactsQuery() {
  const container = $("#search-popup-contacts-results");
  const countEl = $("#search-popup-contacts-results-count");
  const errorEl = $("#search-popup-contacts-error");
  if (!container) return;
  if (errorEl) errorEl.classList.add("hidden");
  const input = $("#search-popup-contacts-input");
  const typeFilter = $("#search-popup-contacts-type-filter");
  const contactTypeFilter = $("#search-popup-contacts-contact-type-filter");
  const q = input ? input.value.trim() : "";
  const type = typeFilter ? typeFilter.value : "";
  const ct = contactTypeFilter ? contactTypeFilter.value : "";
  let qs = [];
  if (q) qs.push(`q=${encodeURIComponent(q)}`);
  if (type) qs.push(`type=${type}`);
  if (ct) qs.push(`contact_type=${encodeURIComponent(ct)}`);
  qs.push(`count=${SEARCH_POPUP_CONTACTS_PAGE_SIZE}`);
  qs.push(`startIndex=${searchPopupContactsStartIndex}`);
  try {
    const data = await api(`/api/v2/contacts?${qs.join("&")}`);
    const contacts = unwrap(data) || data || [];
    if (countEl) countEl.textContent = `${contacts.length} contact${contacts.length !== 1 ? 's' : ''}`;
    container.innerHTML = contacts.map(c => renderSearchContactRow(c)).join("") ||
      '<div style="padding:1rem; color:var(--muted); text-align:center;">No contacts found.</div>';
  } catch (e) {
    if (errorEl) {
      errorEl.textContent = "Failed to load contacts: " + (e.message || e);
      errorEl.classList.remove("hidden");
    }
  }
}

function renderSearchContactRow(c) {
  const initials = ((c.firstName || '')[0] || '') + ((c.lastName || '')[0] || '');
  const name = c.isCompany ? (c.company || c.displayName) : `${c.firstName || ''} ${c.lastName || ''}`.trim();
  const typeBadge = c.contactType ? `<span class="contact-type-badge">${escapeHtml(c.contactType)}</span>` : '';
  const companyLabel = !c.isCompany && c.company ? `<span class="contact-row-company">${escapeHtml(c.company)}</span>` : '';
  const avatarContent = renderContactAvatar(c);
  return `<div class="search-popup-contact-row" data-contact-id="${c.id}">
    <div class="contact-avatar">${avatarContent}</div>
    <div class="search-popup-contact-info">
      <div class="search-popup-contact-name">${c.isCompany ? '🏢 ' : '👤 '}${escapeHtml(name || 'Contact')}</div>
      <div class="search-popup-contact-meta">${typeBadge} ${c.email ? escapeHtml(c.email) : ''} ${c.phone ? escapeHtml(c.phone) : ''} ${companyLabel}</div>
    </div>
  </div>`;
}

function showSearchPopupError(msg) {
  const tabs = document.querySelectorAll("#search-popup-modal .search-popup-tab-content");
  let el = $("#search-popup-error");
  for (const tab of tabs) {
    if (tab.style.display !== "none" && !tab.classList.contains("hidden")) {
      const err = tab.querySelector(".search-popup-error");
      if (err) { el = err; break; }
    }
  }
  if (!el) return;
  el.textContent = msg;
  el.classList.remove("hidden");
  setTimeout(() => hideSearchPopupError(), 5000);
}

function hideSearchPopupError() {
  const els = document.querySelectorAll("#search-popup-modal .search-popup-error");
  for (const el of els) {
    el.classList.add("hidden");
    el.textContent = "";
  }
}

function bindSearchPopupModal() {
  const modal = $("#search-popup-modal");
  if (!modal || modal.dataset.bound) return;
  modal.dataset.bound = "1";

  $("#search-popup-close")?.addEventListener("click", closeSearchPopupModal);
  // Backdrop click -> minimize instead of close
  const searchBackdrop = modal.querySelector(".modal-backdrop");
  if (searchBackdrop) {
    searchBackdrop.addEventListener("click", minimizeSearchPopup);
  }

  // Escape closes
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !modal.classList.contains("hidden")) {
      // Prefer closing deal-edit side modal first if open
      const editM = $("#deal-edit-modal");
      if (editM && !editM.classList.contains("hidden")) {
        closeDealEditModal();
        return;
      }
      closeSearchPopupModal();
    }
  });

  // Live search input (debounced)
  const input = $("#search-popup-input");
  if (input) {
    input.addEventListener("input", () => {
      if (searchPopupQueryAbort) {
        try { searchPopupQueryAbort.abort(); } catch {}
      }
      searchPopupQueryAbort = new AbortController();
      const signal = searchPopupQueryAbort.signal;
      setTimeout(() => {
        if (!signal.aborted) {
          searchPopupStartIndex = 0;
          performSearchPopupQuery();
        }
      }, 300);
    });
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (searchPopupQueryAbort) {
          try { searchPopupQueryAbort.abort(); } catch {}
          searchPopupQueryAbort = null;
        }
        searchPopupStartIndex = 0;
        performSearchPopupQuery();
      }
    });
  }

  // Tab bar click delegation
  const tabBar = $("#search-popup-tabs");
  if (tabBar) {
    tabBar.addEventListener("click", (e) => {
      const tabBtn = e.target.closest(".search-popup-tab");
      if (!tabBtn) return;
      const tabId = tabBtn.dataset.tab;
      if (!tabId) return;

      // Close button on preview tab
      const closeEl = e.target.closest(".search-popup-tab-close");
      if (closeEl) {
        const closeId = closeEl.dataset.closeTab;
        const closeContactId = closeEl.dataset.closeContactTab;
        if (closeContactId != null) {
          closeSearchContactTab(Number(closeContactId));
          return;
        }
        if (closeId != null) {
          closeSearchPreviewTab(Number(closeId));
          return;
        }
      }

      activateSearchPopupTab(tabId);
    });
  }

  // Minimize button — save tabs and hide modal
  $("#search-popup-minimize")?.addEventListener("click", minimizeSearchPopup);

  // Filters
  $("#search-popup-status-filter")?.addEventListener("change", () => {
    searchPopupStartIndex = 0;
    performSearchPopupQuery();
  });
  $("#search-popup-stage-filter")?.addEventListener("change", () => {
    searchPopupStartIndex = 0;
    performSearchPopupQuery();
  });
  $("#search-popup-responsible-filter")?.addEventListener("change", () => {
    searchPopupStartIndex = 0;
    performSearchPopupQuery();
  });
  $("#search-popup-tag-filter")?.addEventListener("change", () => {
    searchPopupStartIndex = 0;
    performSearchPopupQuery();
  });
  $("#search-popup-sort")?.addEventListener("change", () => {
    searchPopupStartIndex = 0;
    performSearchPopupQuery();
  });
  $("#search-popup-clear-filters")?.addEventListener("click", clearSearchPopupFilters);

  // Add custom field filter
  $("#search-popup-add-custom-filter")?.addEventListener("click", () => {
    addSearchPopupCustomFilter();
  });

  // Pagination
  $("#search-popup-prev")?.addEventListener("click", () => performSearchPopupPageChange(-1));
  $("#search-popup-next")?.addEventListener("click", () => performSearchPopupPageChange(1));

  // Batch ops
  $("#search-popup-batch-apply")?.addEventListener("click", applySearchPopupBatchAction);
  $("#search-popup-batch-export")?.addEventListener("click", exportSearchPopupSelected);
  $("#search-popup-batch-clear")?.addEventListener("click", clearSearchPopupSelection);

  // Contacts search bindings
  const contactsInput = $("#search-popup-contacts-input");
  if (contactsInput) {
    let ct;
    contactsInput.addEventListener("input", () => {
      clearTimeout(ct);
      ct = setTimeout(() => { searchPopupContactsStartIndex = 0; performSearchContactsQuery(); }, 300);
    });
    contactsInput.addEventListener("keydown", e => {
      if (e.key === "Enter") {
        e.preventDefault();
        searchPopupContactsStartIndex = 0;
        performSearchContactsQuery();
      }
    });
  }
  $("#search-popup-contacts-type-filter")?.addEventListener("change", () => { searchPopupContactsStartIndex = 0; performSearchContactsQuery(); });
  $("#search-popup-contacts-contact-type-filter")?.addEventListener("change", () => { searchPopupContactsStartIndex = 0; performSearchContactsQuery(); });
  $("#search-popup-contacts-clear-filters")?.addEventListener("click", () => {
    const input = $("#search-popup-contacts-input");
    const typeF = $("#search-popup-contacts-type-filter");
    const ctF = $("#search-popup-contacts-contact-type-filter");
    if (input) input.value = "";
    if (typeF) typeF.value = "";
    if (ctF) ctF.value = "";
    searchPopupContactsStartIndex = 0;
    performSearchContactsQuery();
  });
  // Contacts row click delegation
  const contactsResults = $("#search-popup-contacts-results");
  if (contactsResults) {
    contactsResults.addEventListener("click", e => {
      const row = e.target.closest(".search-popup-contact-row");
      if (row && row.dataset.contactId) {
        const contactId = parseInt(row.dataset.contactId);
        const name = row.querySelector(".search-popup-contact-name")?.textContent?.trim() || "Contact";
        openSearchContactTab(contactId, name);
      }
    });
  }
}

/* ── Contact preview tab in search modal ─────────────────────────────────── */

async function openSearchContactTab(contactId, titleHint) {
  const id = Number(contactId);
  if (!Number.isFinite(id) || id <= 0) return;
  const tabKey = `contact-${id}`;

  // If already open, just activate
  if (searchPopupPreviewTabs.has(tabKey)) {
    activateSearchPopupTab(tabKey);
    return;
  }

  // Enforce max tabs
  if (searchPopupPreviewTabs.size >= MAX_SEARCH_PREVIEW_TABS) {
    showSearchPopupError(`Maximum ${MAX_SEARCH_PREVIEW_TABS} tabs reached. Close a tab to open another.`);
    return;
  }

  // Create tab button
  const tabBar = $("#search-popup-tabs");
  const tabBtn = document.createElement("button");
  tabBtn.type = "button";
  tabBtn.className = "search-popup-tab";
  tabBtn.dataset.tab = tabKey;
  const shortTitle = titleHint.length > 24 ? titleHint.slice(0, 22) + "…" : titleHint;
  tabBtn.innerHTML = `
    <span class="search-popup-tab-title">${escapeHtml(shortTitle)}</span>
    <span class="search-popup-tab-close" data-close-contact-tab="${id}" title="Close tab">×</span>
  `;
  tabBar.appendChild(tabBtn);

  // Create content container
  const containers = $("#search-popup-preview-containers");
  const container = document.createElement("div");
  container.className = "search-popup-tab-content";
  container.dataset.tabContent = tabKey;
  container.style.display = "none";
  container.innerHTML = `
    <div class="search-popup-preview-container">
      <div class="search-popup-preview-head">
        <h3 class="search-popup-preview-title">${escapeHtml(titleHint)}</h3>
        <div class="search-popup-preview-actions">
          <button type="button" class="search-popup-preview-contact-edit" data-contact-id="${id}" title="Edit contact" style="${state.currentUserIsAdmin ? '' : 'display:none;'}">✎</button>
        </div>
      </div>
      <div class="search-popup-preview-body" data-contact-preview-body="${id}">
        <p class="opp-preview-loading">Loading contact…</p>
      </div>
    </div>
  `;
  containers.appendChild(container);

  // Edit button
  const editBtn = container.querySelector(".search-popup-preview-contact-edit");
  if (editBtn) {
    editBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openAdminConsoleModal("contacts");
      setTimeout(() => openAdminContactDetail(id), 300);
    });
  }

  // Close button
  const closeBtn = container.querySelector(".search-popup-tab-close");
  if (closeBtn) {
    closeBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      closeSearchContactTab(id);
    });
  }

  // Store tab
  searchPopupPreviewTabs.set(tabKey, { title: titleHint, data: null, container, button: tabBtn });

  // Activate the tab
  activateSearchPopupTab(tabKey);

  // Fetch contact data + history
  try {
    const [contactsData, historyData] = await Promise.all([
      api(`/api/v2/contacts?q=&count=500`),
      api(`/api/v2/contacts/${id}/history?count=100`).catch(() => [])
    ]);
    const contacts = unwrap(contactsData) || contactsData || [];
    const contact = contacts.find(c => c.id === id);
    const history = unwrap(historyData) || historyData || [];
    if (contact) {
      renderSearchContactDetail(container, contact, history);
    } else {
      const body = container.querySelector(`[data-contact-preview-body="${id}"]`);
      if (body) body.innerHTML = `<p style="color:var(--muted);">Contact not found.</p>`;
    }
  } catch (e) {
    const body = container.querySelector(`[data-contact-preview-body="${id}"]`);
    if (body) body.innerHTML = `<p style="color:#b00;">Failed to load contact: ${escapeHtml(e.message)}</p>`;
  }
}

function renderSearchContactDetail(container, contact, history) {
  const body = container.querySelector(`[data-contact-preview-body="${contact.id}"]`);
  if (!body) return;
  const c = contact;
  const initials = ((c.firstName || '')[0] || '') + ((c.lastName || '')[0] || '');
  const name = c.isCompany ? (c.company || c.displayName) : `${c.firstName || ''} ${c.lastName || ''}`.trim();
  const typeBadge = c.contactType ? `<span class="contact-type-badge">${escapeHtml(c.contactType)}</span>` : '';
  // Use the helper that prefers avatar_local_path over the broken remote URL.
  const avatarHtml = renderContactAvatar(c, 'lg');

  const fieldRow = (label, val) => val ? `<div class="contact-detail-field"><span class="contact-detail-label">${label}</span> <span>${escapeHtml(val)}</span></div>` : '';
  const address = [c.addressStreet, c.addressCity, c.addressState, c.addressZip, c.addressCountry].filter(Boolean).join(', ');

  let historyHtml = '';
  if (history.length > 0) {
    historyHtml = history.map(ev => {
      const catTitle = ev.category?.title || 'Note';
      const dateStr = ev.backdatedCreated || ev.created || '';
      const date = dateStr ? new Date(dateStr).toLocaleString() : '';
      const content = (ev.content || '').replace(/<[^>]+>/g, '').substring(0, 300);
      return `<div class="contact-history-item">
        <div class="contact-history-meta"><strong>${escapeHtml(catTitle)}</strong> &mdash; ${escapeHtml(ev.author || '')} &mdash; ${escapeHtml(date)}</div>
        <div class="contact-history-content">${escapeHtml(content)}</div>
      </div>`;
    }).join("");
  } else {
    historyHtml = '<p style="color:var(--muted); font-size:0.85rem;">No history yet.</p>';
  }

  body.innerHTML = `
    <div style="display:flex; gap:1rem; align-items:flex-start; margin-bottom:1rem;">
      <div class="contact-avatar" style="width:64px;height:64px;font-size:1.2rem;">${avatarHtml}</div>
      <div>
        <div style="font-size:1.1rem;font-weight:600;">${c.isCompany ? '🏢 ' : '👤 '}${escapeHtml(name || 'Contact')}</div>
        <div>${typeBadge}</div>
      </div>
    </div>
    <div class="contact-detail-fields">
      ${fieldRow('Email', c.email)}
      ${fieldRow('Phone', c.phone)}
      ${fieldRow('Mobile', c.mobilePhone)}
      ${fieldRow('Website', c.website)}
      ${fieldRow('Industry', c.industry)}
      ${fieldRow('Currency', c.currency)}
      ${fieldRow('Status', c.contactStatus)}
      ${fieldRow('Job Title', c.jobTitle)}
      ${fieldRow('Company', !c.isCompany ? c.company : null)}
      ${address ? fieldRow('Address', address) : ''}
      ${c.about ? fieldRow('Description', c.about) : ''}
    </div>
    <div style="margin-top:1rem; border-top:1px solid var(--border); padding-top:0.75rem;">
      <div style="font-weight:600; margin-bottom:0.5rem;">History & Notes</div>
      <div id="search-contact-history-add-${c.id}" style="display:none; margin-bottom:0.5rem;">
        <div id="search-contact-history-body-${c.id}" class="note-editor" contenteditable="true" data-placeholder="Write a note..." style="min-height:60px;"></div>
        <div style="margin-top:0.25rem; display:flex; gap:0.25rem;">
          <button type="button" class="btn btn-primary btn-small search-contact-history-submit" data-contact-id="${c.id}">Add Note</button>
          <button type="button" class="btn btn-ghost btn-small search-contact-history-cancel" data-contact-id="${c.id}">Cancel</button>
        </div>
      </div>
      <button type="button" class="btn btn-ghost btn-small search-contact-history-toggle" data-contact-id="${c.id}" style="margin-bottom:0.5rem;">+ Add Note</button>
      <div class="admin-contact-history-list">${historyHtml}</div>
    </div>
  `;

  // Bind history toggle
  body.querySelector(`.search-contact-history-toggle`)?.addEventListener("click", () => {
    const editor = body.querySelector(`#search-contact-history-add-${c.id}`);
    if (editor) editor.style.display = editor.style.display === "none" ? "" : "none";
  });
  body.querySelector(`.search-contact-history-cancel`)?.addEventListener("click", () => {
    const editor = body.querySelector(`#search-contact-history-add-${c.id}`);
    if (editor) editor.style.display = "none";
  });
  body.querySelector(`.search-contact-history-submit`)?.addEventListener("click", async () => {
    const noteBody = body.querySelector(`#search-contact-history-body-${c.id}`);
    const content = noteBody?.innerHTML?.trim();
    if (!content || content === "<br>") { showToast("Write a note first", true); return; }
    try {
      await api(`/api/v2/contacts/${c.id}/history`, { method: "POST", body: JSON.stringify({ content, categoryId: 1 }) });
      showToast("Note added");
      noteBody.innerHTML = "";
      // Refresh history
      const freshHistory = await api(`/api/v2/contacts/${c.id}/history?count=100`).catch(() => []);
      const list = body.querySelector(".admin-contact-history-list");
      if (list && freshHistory.length) {
        list.innerHTML = (unwrap(freshHistory) || freshHistory).map(ev => {
          const catTitle = ev.category?.title || 'Note';
          const dateStr = ev.backdatedCreated || ev.created || '';
          const date = dateStr ? new Date(dateStr).toLocaleString() : '';
          const content = (ev.content || '').replace(/<[^>]+>/g, '').substring(0, 300);
          return `<div class="contact-history-item">
            <div class="contact-history-meta"><strong>${escapeHtml(catTitle)}</strong> &mdash; ${escapeHtml(ev.author || '')} &mdash; ${escapeHtml(date)}</div>
            <div class="contact-history-content">${escapeHtml(content)}</div>
          </div>`;
        }).join("");
      }
    } catch (e) {
      showToast("Failed to add note: " + (e.message || e), true);
    }
  });
}

function closeSearchContactTab(contactId) {
  const tabKey = `contact-${contactId}`;
  const tab = searchPopupPreviewTabs.get(tabKey);
  if (!tab) return;
  tab.button?.remove();
  tab.container?.remove();
  searchPopupPreviewTabs.delete(tabKey);
  // Fall back to contacts tab
  activateSearchPopupTab("contacts");
}

/* ── Search trigger (right-side vertical tab, shown when search is minimized) ─ */

function initSearchTrigger() {
  const trigger = $("#search-trigger");
  if (!trigger || trigger.dataset.bound) return;
  trigger.dataset.bound = "1";

  trigger.addEventListener("click", () => {
    trigger.classList.add("trigger-hidden");
    searchMinimized = false;
    try { localStorage.removeItem(SEARCH_MINIMIZED_FLAG_KEY); } catch {}
    openSearchPopupModal();
  });

  // Initial visibility: show if search was minimized and sidebar is hidden
  try {
    searchMinimized = localStorage.getItem(SEARCH_MINIMIZED_FLAG_KEY) === "1";
  } catch { searchMinimized = false; }
  const sidebar = $("#bookmark-sidebar");
  if ((searchMinimized || hasMinimizedSearchTabs()) && (!sidebar || sidebar.classList.contains("sidebar-hidden"))) {
    trigger.classList.remove("trigger-hidden");
  }
}

function initEmailTrigger() {
  const trigger = $("#email-trigger");
  if (!trigger || trigger.dataset.bound) return;
  trigger.dataset.bound = "1";

  trigger.addEventListener("click", () => {
    trigger.classList.add("trigger-hidden");
    restoreEmailModal();
  });

  // Initial visibility: show if parked state exists and sidebar is hidden
  const sidebar = $("#bookmark-sidebar");
  const stored = tryParseJSON(localStorage.getItem(EMAIL_MINIMIZED_STORAGE_KEY));
  if (stored && (!sidebar || sidebar.classList.contains("sidebar-hidden"))) {
    minimizedEmailState = stored;
    trigger.classList.remove("trigger-hidden");
  }
}

function initDocumentsTrigger() {
  const trigger = $("#documents-trigger");
  if (!trigger || trigger.dataset.bound) return;
  trigger.dataset.bound = "1";

  trigger.addEventListener("click", () => {
    trigger.classList.add("trigger-hidden");
    restoreDocsModal();
  });

  // Initial visibility: show if parked state exists and sidebar is hidden
  const sidebar = $("#bookmark-sidebar");
  const stored = tryParseJSON(localStorage.getItem(DOCS_MINIMIZED_STORAGE_KEY));
  if (stored && (!sidebar || sidebar.classList.contains("sidebar-hidden"))) {
    minimizedDocsState = stored;
    trigger.classList.remove("trigger-hidden");
  }
}

function tryParseJSON(str) {
  try { return JSON.parse(str); } catch { return null; }
}

function getSearchPopupQueryParams() {
  const params = new URLSearchParams({
    startIndex: String(searchPopupStartIndex),
    count: String(SEARCH_POPUP_PAGE_SIZE),
  });

  // Deal status filter — 'open' = stageType 0, 'closed' = Won (1) + Lost (2)
  // (merged via two parallel fetches in performSearchPopupQuery), 'all' = no
  // stageType so the server returns open + won + lost.
  const statusFilter = $("#search-popup-status-filter")?.value || "all";
  if (statusFilter === "open") {
    params.set("stageType", "0");
  }

  const q = $("#search-popup-input")?.value.trim();
  if (q) params.set("filterValue", q);

  const stageFilter = $("#search-popup-stage-filter")?.value;
  if (stageFilter) params.set("stageId", stageFilter);

  const respFilter = $("#search-popup-responsible-filter")?.value;
  if (respFilter) params.set("responsibleUserId", respFilter);

  const tagFilter = $("#search-popup-tag-filter")?.value;
  if (tagFilter) {
    const tagId = tagIdForTitle(tagFilter);
    if (tagId) params.set("tagId", String(tagId));
  }

  const sortVal = $("#search-popup-sort")?.value || "date_created:descending";
  const [sortBy, sortOrder] = sortVal.split(":");
  if (sortBy) params.set("sort_by", sortBy);
  if (sortOrder) params.set("sort_order", sortOrder);

  const cfFilters = getSearchPopupCustomFilters();
  if (cfFilters.length) params.set("customFieldFilters", JSON.stringify(cfFilters));

  return params;
}

async function performSearchPopupQuery() {
  const results = $("#search-popup-results");
  if (!results) return;
  hideSearchPopupError();

  const abortController = searchPopupQueryAbort;
  results.innerHTML = '<p class="search-popup-results-empty">Loading…</p>';

  // Closed deals = Won (1) + Lost (2). Run two parallel fetches (one per
  // stageType) and merge. All + Open go through a single fetch.
  const statusFilter = $("#search-popup-status-filter")?.value || "all";
  const isClosed = statusFilter === "closed";
  const stageTypes = isClosed ? ["1", "2"] : null;

  try {
    if (!isClosed) {
      const params = getSearchPopupQueryParams();
      const [data, countData] = await Promise.all([
        api(`/api/v2/projects?${params}`),
        api(`/api/v2/projects/count?${params}`),
      ]);
      if (abortController && abortController.aborted) return;
      let opps = unwrap(data);
      searchPopupTotal = countData?.count ?? opps.length;
      searchPopupCurrentOpps = opps;
      searchPopupCurrentTagLabel = null;
      searchPopupSelected.clear();
      updateSearchPopupBatchBar();
      updateSearchPopupPagination();
      renderSearchPopupResults(opps);
    } else {
      // Closed: fetch Won + Lost in parallel, merge by id (de-dup if a deal
      // somehow appears in both — shouldn't happen because stageType is
      // mutually exclusive server-side, but defensive). We fetch ALL closed
      // matches per stageType (no per-stageType page limit) so pagination
      // works across the merged client-side list.
      const baseParams = getSearchPopupQueryParams();
      const wonParams = new URLSearchParams(baseParams);
      wonParams.set("stageType", "1");
      wonParams.set("count", "500");
      const wonParamsStr = wonParams.toString();
      const lostParams = new URLSearchParams(baseParams);
      lostParams.set("stageType", "2");
      lostParams.set("count", "500");
      const lostParamsStr = lostParams.toString();
      const [
        [wonData, wonCount],
        [lostData, lostCount],
      ] = await Promise.all([
        Promise.all([
          api(`/api/v2/projects?${wonParamsStr}`),
          api(`/api/v2/projects/count?${wonParamsStr}`),
        ]),
        Promise.all([
          api(`/api/v2/projects?${lostParamsStr}`),
          api(`/api/v2/projects/count?${lostParamsStr}`),
        ]),
      ]);
      if (abortController && abortController.aborted) return;
      const wonOpps = unwrap(wonData) || [];
      const lostOpps = unwrap(lostData) || [];
      const seen = new Set();
      const opps = [];
      for (const o of wonOpps) {
        const id = Number(o.id ?? o.ID);
        if (id != null && !seen.has(id)) { seen.add(id); opps.push(o); }
      }
      for (const o of lostOpps) {
        const id = Number(o.id ?? o.ID);
        if (id != null && !seen.has(id)) { seen.add(id); opps.push(o); }
      }
      searchPopupTotal = (wonCount?.count ?? wonOpps.length) + (lostCount?.count ?? lostOpps.length);
      // Slice the merged list to the current page (client-side pagination).
      const start = searchPopupStartIndex;
      const end = start + SEARCH_POPUP_PAGE_SIZE;
      const pageSlice = opps.slice(start, end);
      searchPopupCurrentOpps = opps;
      searchPopupCurrentTagLabel = null;
      searchPopupSelected.clear();
      updateSearchPopupBatchBar();
      updateSearchPopupPagination();
      renderSearchPopupResults(pageSlice);
    }
  } catch (err) {
    if (abortController && abortController.aborted) return;
    results.innerHTML = `<p class="search-popup-results-empty">${escapeHtml(err.message)}</p>`;
  }
}

function performSearchPopupPageChange(direction) {
  const totalPages = Math.max(1, Math.ceil(searchPopupTotal / SEARCH_POPUP_PAGE_SIZE));
  const currentPage = Math.floor(searchPopupStartIndex / SEARCH_POPUP_PAGE_SIZE) + 1;
  const newPage = currentPage + direction;
  if (newPage < 1 || newPage > totalPages) return;
  searchPopupStartIndex = (newPage - 1) * SEARCH_POPUP_PAGE_SIZE;
  performSearchPopupQuery();
}

function updateSearchPopupPagination() {
  const prev = $("#search-popup-prev");
  const next = $("#search-popup-next");
  const info = $("#search-popup-page-info");
  if (!prev || !next || !info) return;

  const totalPages = Math.max(1, Math.ceil(searchPopupTotal / SEARCH_POPUP_PAGE_SIZE));
  const currentPage = Math.floor(searchPopupStartIndex / SEARCH_POPUP_PAGE_SIZE) + 1;

  info.textContent = `Page ${currentPage} of ${totalPages}`;
  prev.disabled = currentPage <= 1;
  next.disabled = currentPage >= totalPages;
}

function renderSearchPopupResults(opps, container) {
  const results = container || $("#search-popup-results");
  if (!results) return;
  results.innerHTML = "";

  const statusFilter = $("#search-popup-status-filter")?.value || "all";
  const noun = statusFilter === "open" ? "open deals"
    : statusFilter === "closed" ? "closed deals"
    : "deals";

  const countEl = $("#search-popup-results-count");
  if (countEl) {
    if (searchPopupTotal > 0) {
      const start = searchPopupStartIndex + 1;
      const end = Math.min(searchPopupStartIndex + SEARCH_POPUP_PAGE_SIZE, searchPopupTotal);
      countEl.textContent = `Showing ${start}–${end} of ${searchPopupTotal} ${noun}`;
    } else {
      countEl.textContent = "";
    }
  }

  if (!opps.length) {
    const emptyNoun = statusFilter === "open" ? "open deals"
      : statusFilter === "closed" ? "closed deals"
      : "deals";
    results.innerHTML = `<p class="search-popup-results-empty">No ${emptyNoun} found</p>`;
    return;
  }

  const selectAll = document.createElement("div");
  selectAll.className = "search-popup-select-all";
  selectAll.innerHTML = `<label><input type="checkbox" id="search-popup-select-all"> Select all on page</label>`;
  results.appendChild(selectAll);
  const selAllCb = selectAll.querySelector("input");
  selAllCb.addEventListener("change", () => {
    for (const o of opps) {
      const id = Number(o.id ?? o.ID);
      if (selAllCb.checked) searchPopupSelected.add(id);
      else searchPopupSelected.delete(id);
    }
    document.querySelectorAll(".search-popup-result-checkbox").forEach((cb) => { cb.checked = selAllCb.checked; });
    updateSearchPopupBatchBar();
  });

  for (const o of opps) {
    const id = Number(o.id ?? o.ID);
    const title = (o.title || o.Title || `Deal #${id}`).trim();
    const stage = o.stage?.title || o.stage?.Title || o.Stage?.title || "";
    const due = formatOppDueLabel(o);
    const contact = getOpportunityContactLabel(o);
    const bid = formatMoney(o.bidValue || o.BidValue || 0);

    const metaParts = [stage, due, contact, bid].filter(Boolean);
    const meta = metaParts.join("  ·  ");

    const row = document.createElement("div");
    row.className = "search-popup-result-row";

    const chk = document.createElement("input");
    chk.type = "checkbox";
    chk.className = "search-popup-result-checkbox";
    chk.checked = searchPopupSelected.has(id);
    chk.title = "Select for batch action";
    chk.addEventListener("change", () => {
      if (chk.checked) searchPopupSelected.add(id);
      else searchPopupSelected.delete(id);
      updateSearchPopupBatchBar();
    });

    const titleEl = document.createElement("span");
    titleEl.className = "search-popup-result-title";
    titleEl.textContent = title;
    titleEl.title = title;

    const metaEl = document.createElement("span");
    metaEl.className = "search-popup-result-meta";
    metaEl.textContent = meta;
    metaEl.title = meta;

    const actions = document.createElement("span");
    actions.className = "search-popup-result-actions";

    // Bookmark ribbon button
    const isBookmarked = isDealBookmarked(id);
    const bookmarkBtn = document.createElement("button");
    bookmarkBtn.type = "button";
    bookmarkBtn.className = "search-popup-result-bookmark" + (isBookmarked ? " bookmarked" : "");
    bookmarkBtn.title = isBookmarked ? "Remove bookmark" : "Bookmark deal";
    bookmarkBtn.setAttribute("aria-label", bookmarkBtn.title);
    bookmarkBtn.dataset.oppId = id;
    bookmarkBtn.innerHTML = bookmarkRibbonSvg(isBookmarked);
    bookmarkBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (isDealBookmarked(id)) {
        removeBookmarkDeal(id);
      } else {
        addBookmarkDeal(id, title);
      }
    });

    const previewBtn = document.createElement("button");
    previewBtn.type = "button";
    previewBtn.className = "btn btn-primary";
    previewBtn.textContent = "+ Tab";
    previewBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openSearchPreviewTab(id, title, { activate: false });
    });

    row.addEventListener("click", (e) => {
      if (e.target.closest(".search-popup-result-checkbox") || e.target.closest(".search-popup-result-actions")) return;
      openSearchPreviewTab(id, title);
    });

    actions.appendChild(bookmarkBtn);
    actions.appendChild(previewBtn);
    row.appendChild(chk);
    row.appendChild(titleEl);
    row.appendChild(metaEl);
    row.appendChild(actions);
    results.appendChild(row);
  }

  // Add export CSV button at the bottom of results
  const exportBar = document.createElement("div");
  exportBar.className = "search-popup-export-bar";
  const exportBtn = document.createElement("button");
  exportBtn.type = "button";
  exportBtn.className = "btn btn-sm btn-ghost btn-icon-only";
  exportBtn.title = "Export results to CSV";
  exportBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M5 12v-7a2 2 0 0 1 2 -2h7l5 5v4"/><path d="M7 16.5a1.5 1.5 0 0 0 -3 0v3a1.5 1.5 0 0 0 3 0"/><path d="M10 20.25c0 .414 .336 .75 .75 .75h1.25a1 1 0 0 0 1 -1v-1a1 1 0 0 0 -1 -1h-1a1 1 0 0 1 -1 -1v-1a1 1 0 0 1 1 -1h1.25a.75 .75 0 0 1 .75 .75"/><path d="M16 15l2 6l2 -6"/></svg>`;
  exportBtn.addEventListener("click", () => exportSearchResultsToCsv(opps));
  exportBar.appendChild(exportBtn);
  results.appendChild(exportBar);
}

function populateSearchFilterDropdowns() {
  const stageSel = $('#search-popup-stage-filter');
  if (stageSel) {
    const val = stageSel.value;
    stageSel.innerHTML = '<option value=\'\'>All stages</option>';
    for (const s of state.stages || []) {
      const opt = document.createElement('option');
      opt.value = String(s.id ?? s.ID);
      opt.textContent = s.title || s.Title || `Stage ${s.id ?? s.ID}`;
      stageSel.appendChild(opt);
    }
    stageSel.value = val;
  }
  const respSel = $('#search-popup-responsible-filter');
  if (respSel) {
    const val = respSel.value;
    respSel.innerHTML = '<option value=\'\'>All owners</option>';
    for (const u of state.portalUsers || []) {
      const opt = document.createElement('option');
      opt.value = String(u.id);
      opt.textContent = u.displayName || u.id;
      respSel.appendChild(opt);
    }
    respSel.value = val;
  }
  const tagSel = $('#search-popup-tag-filter');
  if (tagSel) {
    const val = tagSel.value;
    tagSel.innerHTML = '<option value=\'\'>All tags</option>';
    const tags = state.allTags || [];
    const sorted = tags.map((t) => normalizeTagTitle(t.title ?? t)).filter(Boolean).sort((a, b) => String(a).localeCompare(String(b)));
    for (const title of sorted) {
      const opt = document.createElement('option');
      opt.value = title;
      opt.textContent = title;
      tagSel.appendChild(opt);
    }
    tagSel.value = val;
  }
  const addTag = $('#search-popup-batch-add-tag');
  const remTag = $('#search-popup-batch-remove-tag');
  const tagOptions = () => {
    const frag = document.createDocumentFragment();
    for (const t of state.allTags || []) {
      const title = normalizeTagTitle(t.title ?? t);
      if (!title) continue;
      const opt = document.createElement('option');
      opt.value = title;
      opt.textContent = title;
      frag.appendChild(opt);
    }
    return frag;
  };
  if (addTag) {
    const val = addTag.value;
    addTag.innerHTML = '<option value=\'\'>Add tag…</option>';
    addTag.appendChild(tagOptions());
    addTag.value = val;
  }
  if (remTag) {
    const val = remTag.value;
    remTag.innerHTML = '<option value=\'\'>Remove tag…</option>';
    remTag.appendChild(tagOptions());
    remTag.value = val;
  }
  const stageSet = $('#search-popup-batch-set-stage');
  if (stageSet) {
    const val = stageSet.value;
    stageSet.innerHTML = '<option value=\'\'>Set stage…</option>';
    for (const s of state.stages || []) {
      const opt = document.createElement('option');
      opt.value = String(s.id ?? s.ID);
      opt.textContent = s.title || s.Title || `Stage ${s.id ?? s.ID}`;
      stageSet.appendChild(opt);
    }
    stageSet.value = val;
  }
}

function clearSearchPopupFilters() {
  const input = $('#search-popup-input'); if (input) input.value = '';
  const stat = $('#search-popup-status-filter'); if (stat) stat.value = 'all';
  const sf = $('#search-popup-stage-filter'); if (sf) sf.value = '';
  const rf = $('#search-popup-responsible-filter'); if (rf) rf.value = '';
  const tf = $('#search-popup-tag-filter'); if (tf) tf.value = '';
  const sort = $('#search-popup-sort'); if (sort) sort.value = 'date_created:descending';
  searchPopupCustomFilters = [];
  renderSearchPopupCustomFilters();
  searchPopupStartIndex = 0;
  performSearchPopupQuery();
}

let searchPopupCustomFilterDebounce = null;

function renderSearchPopupCustomFilters() {
  const container = $("#search-popup-custom-filters");
  if (!container) return;
  container.innerHTML = "";

  for (const filter of searchPopupCustomFilters) {
    const row = document.createElement("div");
    row.className = "search-popup-custom-filter-row";
    row.dataset.filterId = String(filter.id);

    const fieldSelect = document.createElement("select");
    fieldSelect.className = "search-popup-custom-filter-field";
    fieldSelect.innerHTML = '<option value="">— Select field —</option>';
    for (const def of state.customFieldDefs || []) {
      const fid = customFieldDefinitionId(def);
      if (fid == null) continue;
      const opt = document.createElement("option");
      opt.value = String(fid);
      opt.textContent = customFieldLabel(def) || `Field ${fid}`;
      fieldSelect.appendChild(opt);
    }
    fieldSelect.value = String(filter.fieldId || "");
    fieldSelect.addEventListener("change", () => {
      filter.fieldId = Number(fieldSelect.value) || null;
      filter.value = "";
      renderSearchPopupCustomFilters();
      if (filter.fieldId) {
        searchPopupStartIndex = 0;
        performSearchPopupQuery();
      }
    });

    const valueControl = buildSearchPopupCustomFilterValueControl(filter);
    if (valueControl) {
      const onChange = () => {
        filter.value = readSearchPopupCustomFilterValue(filter, valueControl);
        searchPopupStartIndex = 0;
        performSearchPopupQuery();
      };
      valueControl.addEventListener("change", onChange);
      if (valueControl.tagName === "INPUT" && valueControl.type !== "checkbox" && valueControl.type !== "date") {
        valueControl.addEventListener("input", () => {
          if (searchPopupCustomFilterDebounce) clearTimeout(searchPopupCustomFilterDebounce);
          searchPopupCustomFilterDebounce = setTimeout(() => {
            const rowEl = valueControl.closest(".search-popup-custom-filter-row");
            const f = searchPopupCustomFilters.find((x) => String(x.id) === rowEl?.dataset.filterId);
            if (f) f.value = valueControl.value;
            searchPopupStartIndex = 0;
            performSearchPopupQuery();
          }, 300);
        });
      }
    }

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "search-popup-custom-filter-remove";
    removeBtn.textContent = "×";
    removeBtn.title = "Remove filter";
    removeBtn.addEventListener("click", () => {
      removeSearchPopupCustomFilter(filter.id);
    });

    row.appendChild(fieldSelect);
    if (valueControl) row.appendChild(valueControl);
    row.appendChild(removeBtn);
    container.appendChild(row);
  }
}

function buildSearchPopupCustomFilterValueControl(filter) {
  if (!filter.fieldId) return null;
  const def = state.customFieldById?.get(String(filter.fieldId));
  if (!def) return null;
  const kind = createOppCustomFieldInputKind(def);

  if (kind === "select") {
    const select = document.createElement("select");
    select.className = "search-popup-custom-filter-value";
    const empty = document.createElement("option");
    empty.value = "";
    empty.textContent = "—";
    select.appendChild(empty);
    for (const optText of parseCustomFieldSelectOptions(def)) {
      const opt = document.createElement("option");
      opt.value = optText;
      opt.textContent = optText;
      select.appendChild(opt);
    }
    select.value = filter.value || "";
    return select;
  }

  if (kind === "checkbox") {
    const select = document.createElement("select");
    select.className = "search-popup-custom-filter-value";
    select.innerHTML = '<option value="">—</option><option value="true">Yes</option><option value="false">No</option>';
    const val = String(filter.value || "").toLowerCase();
    select.value = val === "true" || val === "1" || val === "yes" ? "true" : val === "false" || val === "0" || val === "no" ? "false" : "";
    return select;
  }

  if (kind === "date") {
    const input = document.createElement("input");
    input.type = "date";
    input.className = "search-popup-custom-filter-value";
    input.value = filter.value || "";
    return input;
  }

  const input = document.createElement("input");
  input.type = "text";
  input.className = "search-popup-custom-filter-value";
  input.placeholder = "contains…";
  input.value = filter.value || "";
  return input;
}

function readSearchPopupCustomFilterValue(filter, control) {
  if (!control) return "";
  if (control.tagName === "SELECT") return control.value;
  if (control.type === "checkbox") return control.checked ? "true" : "false";
  return control.value || "";
}

function addSearchPopupCustomFilter() {
  const id = Date.now() + Math.random();
  searchPopupCustomFilters.push({ id, fieldId: null, value: "" });
  renderSearchPopupCustomFilters();
}

function removeSearchPopupCustomFilter(id) {
  searchPopupCustomFilters = searchPopupCustomFilters.filter((f) => f.id !== id);
  renderSearchPopupCustomFilters();
  searchPopupStartIndex = 0;
  performSearchPopupQuery();
}

function getSearchPopupCustomFilters() {
  const out = [];
  for (const f of searchPopupCustomFilters) {
    if (!f.fieldId || String(f.value).trim() === "") continue;
    const def = state.customFieldById?.get(String(f.fieldId));
    const kind = createOppCustomFieldInputKind(def);
    let operator = "equals";
    if (!def || kind === "text" || kind === "textarea") operator = "contains";
    out.push({ fieldId: f.fieldId, value: f.value, operator });
  }
  return out;
}

function updateSearchPopupBatchBar() {
  const bar = $('#search-popup-batch-bar');
  const count = $('#search-popup-selected-count');
  if (!bar || !count) return;
  const n = searchPopupSelected.size;
  count.textContent = `${n} selected`;
  bar.classList.toggle('hidden', n === 0);
}

async function applySearchPopupBatchAction() {
  const addTag = $('#search-popup-batch-add-tag')?.value;
  const remTag = $('#search-popup-batch-remove-tag')?.value;
  const stageId = $('#search-popup-batch-set-stage')?.value;
  const ids = Array.from(searchPopupSelected).map(Number).filter((id) => id > 0);
  if (!ids.length) return;
  if (!addTag && !remTag && !stageId) {
    showSearchPopupError('Choose a batch action first');
    return;
  }
  let done = 0;
  for (const id of ids) {
    try {
      if (addTag) { await addOpportunityTag(id, addTag); addEventLogEntry("update", id, "", `Tag added: ${addTag}`, true); }
      if (remTag) { await removeOpportunityTag(id, remTag); addEventLogEntry("update", id, "", `Tag removed: ${remTag}`, true); }
      if (stageId) { await updateOpportunityStage(id, Number(stageId)); addEventLogEntry("update", id, "", `Stage changed (batch)`, true); }
      done++;
    } catch (e) {
      showToast(`Batch failed on deal #${id}: ${e.message || e}`, true);
    }
  }
  showToast(`${done} deal(s) updated`);
  const a = $('#search-popup-batch-add-tag'); if (a) a.value = '';
  const r = $('#search-popup-batch-remove-tag'); if (r) r.value = '';
  const s = $('#search-popup-batch-set-stage'); if (s) s.value = '';
  clearSearchPopupSelection();
  await performSearchPopupQuery();
}

function exportSearchPopupSelected() {
  const opps = searchPopupCurrentOpps.filter((o) => searchPopupSelected.has(Number(o.id ?? o.ID)));
  if (!opps.length) return;
  exportSearchResultsToCsv(opps);
}

function clearSearchPopupSelection() {
  searchPopupSelected.clear();
  updateSearchPopupBatchBar();
  const selAll = $('#search-popup-select-all');
  if (selAll) selAll.checked = false;
  document.querySelectorAll('.search-popup-result-checkbox').forEach((cb) => { cb.checked = false; });
}

function exportSearchResultsToCsv(opps) {
  const rows = [["Deal Title", "Stage", "Due Date", "Contact", "Bid Value"]];
  for (const o of opps) {
    const title = (o.title || o.Title || "").trim();
    const stage = o.stage?.title || o.stage?.Title || o.Stage?.title || "";
    const due = formatOppDueLabel(o);
    const contact = getOpportunityContactLabel(o);
    const bid = formatMoney(o.bidValue || o.BidValue || 0);
    const esc = (v) => {
      const s = String(v ?? "");
      return /[,"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    rows.push([title, stage, due, contact, bid].map(esc));
  }
  const csv = rows.map((r) => r.join(",")).join("\n");
  const blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `search-results-${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

async function openSearchPreviewTab(oppId, titleHint, { activate = true } = {}) {
  const id = Number(oppId);
  if (!Number.isFinite(id) || id <= 0) return;

  // If already open, just activate
  if (searchPopupPreviewTabs.has(id)) {
    activateSearchPopupTab(`preview-${id}`);
    updateInferredStatus("preview", searchPopupPreviewTabs.get(id).title || titleHint);
    return;
  }

  // Enforce max 10 tabs (stop at 10, show error if trying to open more)
  if (searchPopupPreviewTabs.size >= MAX_SEARCH_PREVIEW_TABS) {
    showSearchPopupError(`Maximum ${MAX_SEARCH_PREVIEW_TABS} preview tabs reached. Close a tab to open another.`);
    return;
  }

  // Create tab button
  const tabBar = $("#search-popup-tabs");
  const tabBtn = document.createElement("button");
  tabBtn.type = "button";
  tabBtn.className = "search-popup-tab";
  tabBtn.dataset.tab = `preview-${id}`;
  const shortTitle = titleHint.length > 24 ? titleHint.slice(0, 22) + "…" : titleHint;
  tabBtn.innerHTML = `
    <span class="search-popup-tab-title">${escapeHtml(shortTitle)}</span>
    <span class="search-popup-tab-close" data-close-tab="${id}" title="Close tab">×</span>
  `;
  tabBar.appendChild(tabBtn);

  // Create content container
  const containers = $("#search-popup-preview-containers");
  const container = document.createElement("div");
  container.className = "search-popup-tab-content";
  container.dataset.tabContent = `preview-${id}`;
  container.style.display = "none";
  const bookmarkIcon = bookmarkRibbonSvg(isDealBookmarked(id));
  container.innerHTML = `
    <div class="search-popup-preview-container">
        <div class="search-popup-preview-head">
        <h3 class="search-popup-preview-title">${escapeHtml(titleHint)}</h3>
        <div class="search-popup-preview-actions">
          <button type="button" class="search-popup-preview-refresh" data-refresh-id="${id}" title="Refresh">⟳</button>
          <button type="button" class="search-popup-preview-edit" data-edit-id="${id}" title="Edit deal">✎</button>
          <button type="button" class="search-popup-preview-bookmark" data-opp-id="${id}" title="Bookmark deal">${bookmarkIcon}</button>
        </div>
      </div>
      <div class="search-popup-preview-body" data-preview-body="${id}">
        <p class="opp-preview-loading">Loading project…</p>
      </div>
    </div>
  `;
  containers.appendChild(container);

  // Refresh button
  const refreshBtn = container.querySelector(".search-popup-preview-refresh");
  if (refreshBtn) {
    refreshBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      refreshSearchPreviewTab(id);
    });
  }

  // Edit button
  const editBtn = container.querySelector(".search-popup-preview-edit");
  if (editBtn) {
    editBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      handleSearchPreviewEdit(id);
    });
  }

  // Bookmark button
  const bookmarkBtn = container.querySelector(".search-popup-preview-bookmark");
  if (bookmarkBtn) {
    bookmarkBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const bid = Number(bookmarkBtn.dataset.oppId);
      if (isDealBookmarked(bid)) {
        removeBookmarkDeal(bid);
      } else {
        const fullTitle = titleHint;
        addBookmarkDeal(bid, fullTitle);
      }
    });
  }

  // Store
  searchPopupPreviewTabs.set(id, {
    title: titleHint,
    container,
    button: tabBtn,
    data: null,
  });

  // Activate immediately if requested
  if (activate) {
    activateSearchPopupTab(`preview-${id}`);
  } else {
    tabBtn.classList.add("new-tab");
    setTimeout(() => tabBtn.classList.remove("new-tab"), 2400);
  }

  // Load data
  try {
    const data = await fetchOpportunityPreviewData(id, true);
    const body = container.querySelector(`[data-preview-body="${id}"]`);
    if (body) {
      body.innerHTML = "";
      renderOpportunityPreviewContent(body, data);
      linkifyPhonesAndEmails(body);
      if (activate) updateInferredStatus("preview", data.opp?.title || data.opp?.Title || titleHint);
    }
    // Update title if loaded
    const fullTitle = data.opp?.title || data.opp?.Title || titleHint;
    const titleEl = container.querySelector(".search-popup-preview-title");
    if (titleEl) titleEl.textContent = fullTitle;
    // Update tab button title
    const shortFull = fullTitle.length > 24 ? fullTitle.slice(0, 22) + "…" : fullTitle;
    const tabTitleEl = tabBtn.querySelector(".search-popup-tab-title");
    if (tabTitleEl) tabTitleEl.textContent = shortFull;
    // Set preview context so the reply submit (and any other preview-aware
    // code in renderOpportunityPreviewContent) knows which opp this preview
    // is showing. Without this, replies from the search popup submit against
    // /api/v2/projects/null/... and silently 404.
    setOpportunityPreviewContext(id, data.opp, null);
    // Store data for edit
    const tab = searchPopupPreviewTabs.get(id);
    if (tab) tab.data = data;
  } catch (err) {
    const body = container.querySelector(`[data-preview-body="${id}"]`);
    if (body) {
      body.innerHTML = `<p class="opp-preview-error">${escapeHtml(err.message)}</p>`;
    }
  }
}

async function refreshSearchPreviewTab(oppId) {
  const id = Number(oppId);
  const tab = searchPopupPreviewTabs.get(id);
  if (!tab) return;
  const body = tab.container.querySelector(`[data-preview-body="${id}"]`);
  if (body) {
    body.innerHTML = '<p class="opp-preview-loading">Refreshing…</p>';
  }
  try {
    const data = await fetchOpportunityPreviewData(id, true);
    if (body) {
      body.innerHTML = "";
      // Refresh preview context with the freshly loaded opp so any reply
      // posted in this tab still works (defense in depth — same as the
      // initial setOpportunityPreviewContext call in the opener).
      setOpportunityPreviewContext(id, data.opp, null);
      renderOpportunityPreviewContent(body, data);
      linkifyPhonesAndEmails(body);
    }
    // Update title
    const fullTitle = data.opp?.title || data.opp?.Title || tab.title;
    const titleEl = tab.container.querySelector(".search-popup-preview-title");
    if (titleEl) titleEl.textContent = fullTitle;
    const shortFull = fullTitle.length > 24 ? fullTitle.slice(0, 22) + "…" : fullTitle;
    const tabTitleEl = tab.button.querySelector(".search-popup-tab-title");
    if (tabTitleEl) tabTitleEl.textContent = shortFull;
    tab.data = data;
  } catch (err) {
    if (body) {
      body.innerHTML = `<p class="opp-preview-error">${escapeHtml(err.message)}</p>`;
    }
  }
}

function closeSearchPreviewTab(oppId) {
  const id = Number(oppId);
  const tab = searchPopupPreviewTabs.get(id);
  if (!tab) return;

  tab.button.remove();
  tab.container.remove();
  searchPopupPreviewTabs.delete(id);

  // If this was the active tab, switch to projects
  const tabBar = $("#search-popup-tabs");
  const activeBtn = tabBar?.querySelector(".search-popup-tab.active");
  if (!activeBtn || activeBtn.dataset.tab === `preview-${id}`) {
    activateSearchPopupTab("projects");
  }
}

function activateSearchPopupTab(tabId) {
  const tabBar = $("#search-popup-tabs");
  const contents = document.querySelectorAll("#search-popup-modal .search-popup-tab-content");

  // Update tab buttons
  tabBar?.querySelectorAll(".search-popup-tab").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.tab === tabId);
  });

  // Show/hide content
  contents.forEach((el) => {
    const isMatch = el.dataset.tabContent === tabId || el.dataset.tab === tabId;
    el.classList.toggle("active", isMatch);
    el.style.display = isMatch ? "" : "none";
  });

  // Hide preview containers wrapper when projects or contacts list tab is active
  // so it doesn't steal flex space (causing modal to shrink)
  const previewContainers = $("#search-popup-preview-containers");
  if (previewContainers) {
    const isPreviewTab = !["projects", "contacts", "search"].includes(tabId);
    previewContainers.style.display = isPreviewTab ? "" : "none";
  }

  // Load data for projects tab
  if (tabId === "projects") {
    performSearchPopupQuery();
  }
  // Load data for contacts tab
  if (tabId === "contacts") {
    activateContactsSearchTab();
  }
}

async function handleSearchPreviewEdit(oppId) {
  const id = Number(oppId);
  let deal = null;
  const tab = searchPopupPreviewTabs.get(id);
  if (tab && tab.data && tab.data.opp) {
    deal = tab.data.opp;
  } else {
    try {
      deal = await fetchOpportunityForUpdate(id);
    } catch (err) {
      showToast(err.message, true);
      return;
    }
  }
  // Set preview context so side-by-side layout works (same as opp-preview-modal)
  setOpportunityPreviewContext(id, deal, null);
  try {
    await openDealEditModal(deal, null);
  } catch (err) {
    showToast(err.message, true);
  }
}

/* ================================================================================
   Bookmark sidebar — collapsible right sidebar with bookmarked deal tabs
   ================================================================================ */

function isDealBookmarked(oppId) {
  return state.bookmarkedDeals.some((d) => d.type !== "divider" && Number(d.oppId) === Number(oppId));
}

function initBookmarkSidebar() {
  const sidebar = $("#bookmark-sidebar");
  const trigger = $("#bookmark-trigger");
  if (!sidebar || sidebar.dataset.bound) return;
  sidebar.dataset.bound = "1";

  renderBookmarkTabs();

  // Trigger tab click — open the sidebar (attached early in init() for robustness; skip if already)
  if (trigger && !trigger.dataset.earlyBound) {
    trigger.addEventListener("click", () => {
      sidebar.classList.remove("sidebar-hidden");
      trigger.classList.add("trigger-hidden");
      // Hide all modal triggers when sidebar opens
      hideAllModalTriggers();
    });
  }

  // Toggle button in sidebar header — close/hide the sidebar
  const toggleBtn = $("#bookmark-sidebar-toggle");
  if (toggleBtn) {
    toggleBtn.addEventListener("click", () => {
      hideBookmarkSidebar();
    });
  }

  // Add divider button in sidebar header
  const addDividerBtn = $("#bookmark-add-divider");
  if (addDividerBtn) {
    addDividerBtn.addEventListener("click", () => {
      addBookmarkDivider();
    });
  }

  // Tab bar delegation
  const tabBar = $("#bookmark-sidebar-tabs");
  if (tabBar) {
    tabBar.addEventListener("click", (e) => {
      const tabBtn = e.target.closest(".bookmark-tab");
      if (!tabBtn) return;
      const oppId = Number(tabBtn.dataset.oppId);
      if (!Number.isFinite(oppId) || oppId <= 0) return;

      // Bookmark icon on tab — click to remove bookmark
      if (e.target.closest(".bookmark-tab-icon")) {
        removeBookmarkDeal(oppId);
        return;
      }

      // Toggle: if already active, collapse; otherwise activate
      if (state.activeBookmarkTab === oppId) {
        closeBookmarkPreview();
      } else {
        activateBookmarkTab(oppId);
      }
    });
  }

  // Preview refresh
  const refreshBtn = $("#bookmark-preview-refresh");
  if (refreshBtn) {
    refreshBtn.addEventListener("click", () => {
      const id = state.activeBookmarkTab;
      if (id) refreshBookmarkTab(id);
    });
  }

  // Preview unbookmark
  const unbookmarkBtn = $("#bookmark-preview-unbookmark");
  if (unbookmarkBtn) {
    unbookmarkBtn.addEventListener("click", () => {
      const id = state.activeBookmarkTab;
      if (id) removeBookmarkDeal(id);
    });
  }

  // Preview edit button — opens deal edit modal
  const editBtn = $("#bookmark-preview-edit");
  if (editBtn) {
    editBtn.addEventListener("click", () => {
      const id = state.activeBookmarkTab;
      if (!id) return;
      const deal = state.bookmarkedDeals.find((d) => Number(d.oppId) === id);
      if (!deal?._cachedData?.opp) return;
      const group = findGroupForOpportunity(id);
      openDealEditModal(deal._cachedData.opp, group).catch(() => {});
    });
  }

  // Preview collapse chevron — same behavior as clicking the deal name tab
  const collapseBtn = $("#bookmark-preview-collapse");
  if (collapseBtn) {
    collapseBtn.addEventListener("click", () => {
      closeBookmarkPreview();
    });
  }

  // Recalculate mobile preview layout on resize
  window.addEventListener("resize", () => {
    updateMobileBookmarkPreview();
  });
}

function hideBookmarkSidebar() {
  const sidebar = $("#bookmark-sidebar");
  const trigger = $("#bookmark-trigger");
  if (sidebar) {
    closeBookmarkPreview();
    sidebar.classList.add("sidebar-hidden");
  }
  if (trigger) trigger.classList.remove("trigger-hidden");
  // Show active modal triggers when sidebar closes
  showActiveModalTriggers();
  updateBookmarkBodyClass();
  updateMobileBookmarkPreview();
}

function renderBookmarkTabs() {
  const tabBar = $("#bookmark-sidebar-tabs");
  if (!tabBar) return;
  tabBar.innerHTML = "";

  const dealCount = state.bookmarkedDeals.filter((d) => d.type !== "divider").length;
  if (!dealCount) {
    tabBar.innerHTML = '<div class="bookmark-tabs-empty">No bookmarked deals</div>';
    return;
  }

  for (let i = 0; i < state.bookmarkedDeals.length; i++) {
    const item = state.bookmarkedDeals[i];
    if (item.type === "divider") {
      renderBookmarkDivider(tabBar, item, i);
      continue;
    }

    const deal = item;
    const btn = document.createElement("button");
    btn.type = "button";
    // Check if this bookmarked deal is tagged High Priority
    const isHighPriority = (() => {
      if (deal._cachedData?.opp && oppHasTag(deal._cachedData.opp, "High Priority")) return true;
      for (const g of state.groups) {
        const opp = (g.opportunities || []).find(o => Number(o.id ?? o.ID) === Number(deal.oppId));
        if (opp && oppHasTag(opp, "High Priority")) return true;
      }
      return false;
    })();
    btn.className = "bookmark-tab" + (state.activeBookmarkTab === deal.oppId ? " active" : "") + (isHighPriority ? " bookmark-tab--high-priority" : "");
    btn.dataset.oppId = deal.oppId;
    btn.draggable = true;
    btn.dataset.index = i;

    attachBookmarkDragEvents(btn, i, tabBar);

    // Stage dot color
    const stageColor = getStageColorForOppId(deal.oppId) || "#4f8cff";

    // Stage title and due date (from cache if available, else placeholder)
    let stageLabel = "";
    let dueLabel = "";
    if (deal._cachedData?.opp) {
      const opp = deal._cachedData.opp;
      stageLabel = resolveStageTitle(opp);
      const raw = opportunityDueDateRaw(opp);
      const d = parseCrmDateOnly(raw);
      if (d && !Number.isNaN(d.getTime())) {
        dueLabel = "Due " + d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
      }
    }

    btn.innerHTML = `
      <span class="bookmark-tab-icon">${bookmarkRibbonSvg(true)}</span>
      <span class="bookmark-tab-stage-dot" style="background:${escapeHtml(stageColor)}"></span>
      <span class="bookmark-tab-title">${escapeHtml(deal.title)}</span>
      <span class="bookmark-tab-meta">${escapeHtml(stageLabel)}${stageLabel && dueLabel ? " · " : ""}${escapeHtml(dueLabel)}</span>
    `;
    tabBar.appendChild(btn);
  }

  // Highlight active if any
  if (state.activeBookmarkTab) {
    const activeEl = tabBar.querySelector(`.bookmark-tab[data-opp-id="${state.activeBookmarkTab}"]`);
    if (activeEl) activeEl.classList.add("active");
  }
}

function attachBookmarkDragEvents(el, index, tabBar) {
  el.draggable = true;
  el.dataset.index = index;

  el.addEventListener("dragstart", (e) => {
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", el.dataset.index);
    el.classList.add(el.classList.contains("bookmark-divider") ? "bookmark-divider-dragging" : "bookmark-tab-dragging");
  });
  el.addEventListener("dragend", () => {
    el.classList.remove("bookmark-tab-dragging", "bookmark-divider-dragging");
    tabBar.querySelectorAll(".bookmark-tab-drag-over, .bookmark-divider-drag-over").forEach((n) => {
      n.classList.remove("bookmark-tab-drag-over", "bookmark-divider-drag-over");
    });
  });
  el.addEventListener("dragover", (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    tabBar.querySelectorAll(".bookmark-tab-drag-over, .bookmark-divider-drag-over").forEach((n) => {
      n.classList.remove("bookmark-tab-drag-over", "bookmark-divider-drag-over");
    });
    el.classList.add(el.classList.contains("bookmark-divider") ? "bookmark-divider-drag-over" : "bookmark-tab-drag-over");
  });
  el.addEventListener("dragleave", () => {
    el.classList.remove("bookmark-tab-drag-over", "bookmark-divider-drag-over");
  });
  el.addEventListener("drop", (e) => {
    e.preventDefault();
    e.stopPropagation();
    el.classList.remove("bookmark-tab-drag-over", "bookmark-divider-drag-over");
    tabBar.querySelectorAll(".bookmark-tab-drag-over, .bookmark-divider-drag-over").forEach((n) => {
      n.classList.remove("bookmark-tab-drag-over", "bookmark-divider-drag-over");
    });

    const fromIdx = parseInt(e.dataTransfer.getData("text/plain"), 10);
    const toIdx = parseInt(el.dataset.index, 10);
    if (!Number.isFinite(fromIdx) || !Number.isFinite(toIdx) || fromIdx === toIdx) return;

    // Reorder array
    const [moved] = state.bookmarkedDeals.splice(fromIdx, 1);
    state.bookmarkedDeals.splice(toIdx, 0, moved);
    saveBookmarkedDealsToStorage();
    renderBookmarkTabs();
    // Re-activate the moved tab if it was active
    if (moved.type !== "divider" && state.activeBookmarkTab === moved.oppId) {
      const activeEl = tabBar.querySelector(`.bookmark-tab[data-opp-id="${moved.oppId}"]`);
      if (activeEl) {
        activeEl.classList.add("active");
        activeEl.scrollIntoView({ block: "nearest" });
      }
    }
  });
}

function renderBookmarkDivider(tabBar, divider, index) {
  const el = document.createElement("div");
  el.className = "bookmark-divider";
  el.dataset.dividerId = divider.id;
  el.draggable = true;
  el.dataset.index = index;

  attachBookmarkDragEvents(el, index, tabBar);

  const line = document.createElement("span");
  line.className = "bookmark-divider-line";

  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "bookmark-divider-delete";
  delBtn.title = "Remove divider";
  delBtn.innerHTML = "&times;";
  delBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    removeBookmarkDivider(divider.id);
  });

  el.appendChild(line);
  el.appendChild(delBtn);
  tabBar.appendChild(el);
}

function addBookmarkDivider() {
  const id = "div_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 7);
  state.bookmarkedDeals.push({ type: "divider", id });
  saveBookmarkedDealsToStorage();
  renderBookmarkTabs();
}

function removeBookmarkDivider(id) {
  state.bookmarkedDeals = state.bookmarkedDeals.filter((d) => !(d.type === "divider" && d.id === id));
  saveBookmarkedDealsToStorage();
  renderBookmarkTabs();
}

function getStageColorForOppId(oppId) {
  // Try cached data first
  const deal = state.bookmarkedDeals.find((d) => Number(d.oppId) === Number(oppId));
  if (deal?._cachedData?.opp?.stage?.id) {
    const stageId = String(deal._cachedData.opp.stage.id);
    const stage = state.stages.find((s) => String(s.id ?? s.ID) === stageId);
    return stage?.color || "#4f8cff";
  }
  // Try lookup in group opportunities
  for (const g of state.groups) {
    for (const opp of g.opportunities || []) {
      if (Number(opp.id ?? opp.ID) === Number(oppId)) {
        const stageId = String(opp.stage?.id ?? opp.stage?.ID);
        const stage = state.stages.find((s) => String(s.id ?? s.ID) === stageId);
        if (stage) return (g.stageColors && g.stageColors[stageId]) || stage.color || "#4f8cff";
      }
    }
  }
  return "#4f8cff";
}

async function activateBookmarkTab(oppId) {
  const id = Number(oppId);
  if (!Number.isFinite(id) || id <= 0) return;

  state.activeBookmarkTab = id;
  updateBookmarkBodyClass();
  updateMobileBookmarkPreview();
  const previewPanel = $("#bookmark-sidebar-preview");
  const titleEl = $("#bookmark-preview-title");
  const bodyEl = $("#bookmark-preview-body");
  if (!previewPanel || !titleEl || !bodyEl) return;

  // Show dimming backdrop
  const backdrop = $("#bookmark-preview-backdrop");
  if (backdrop) backdrop.classList.remove("hidden");

  previewPanel.classList.remove("hidden");
  const deal = state.bookmarkedDeals.find((d) => Number(d.oppId) === id);

  // Use cached data if available
  if (deal?._cachedData) {
    titleEl.textContent = deal.title;
    bodyEl.innerHTML = "";
    // Set preview context so reply submit (and any other preview-context-aware
    // code in renderOpportunityPreviewContent) knows which opp it's working
    // with. Without this, replies from the bookmark sidebar preview submit
    // against /api/v2/projects/null/... and 404 — bug surfaced when the user
    // tagged @crm bot in a bookmark-sidebar reply and saw no notification.
    setOpportunityPreviewContext(id, deal._cachedData.opp || null, null);
    renderOpportunityPreviewContent(bodyEl, deal._cachedData, "bookmark");
    linkifyPhonesAndEmails(bodyEl);
    setBookmarkPreviewCrmLink(id, deal._cachedData.opp?.project_number);
    updateInferredStatus("preview", deal.title || `Project #${id}`);
  } else {
    titleEl.textContent = deal?.title || `Project #${id}`;
    bodyEl.innerHTML = '<p class="opp-preview-loading">Loading project…</p>';
    // Set context with just the id so reply submit knows the opp even before
    // data is loaded.
    setOpportunityPreviewContext(id, null, null);
  }

  // Fetch data in background (always refresh if not cached, or on explicit refresh only)
  if (!deal?._cachedData) {
    try {
      const data = await fetchOpportunityPreviewData(id, false);
      if (state.activeBookmarkTab !== id) return; // tab changed while loading
      // Cache it
      if (deal) deal._cachedData = data;
      titleEl.textContent = data.opp?.title || data.opp?.Title || deal?.title || `Project #${id}`;
      bodyEl.innerHTML = "";
      // Update preview context with the now-loaded opp object (defense in depth
      // — setOpportunityPreviewContext was already called above with just the
      // id, this adds the opp reference).
      setOpportunityPreviewContext(id, data.opp, null);
      renderOpportunityPreviewContent(bodyEl, data, "bookmark");
      linkifyPhonesAndEmails(bodyEl);
      setBookmarkPreviewCrmLink(id, data.opp?.project_number);
      updateInferredStatus("preview", data.opp?.title || data.opp?.Title || deal?.title || `Project #${id}`);
      // Update tab's stage/due info
      renderBookmarkTabs();
    } catch (err) {
      if (state.activeBookmarkTab === id) {
        bodyEl.innerHTML = `<p class="opp-preview-error">${escapeHtml(err.message)}</p>`;
      }
    }
  }

  renderBookmarkTabs();
}

function closeBookmarkPreview() {
  state.activeBookmarkTab = null;
  updateBookmarkBodyClass();
  updateMobileBookmarkPreview();
  const previewPanel = $("#bookmark-sidebar-preview");
  if (previewPanel) previewPanel.classList.add("hidden");
  // Hide dimming backdrop
  const backdrop = $("#bookmark-preview-backdrop");
  if (backdrop) backdrop.classList.add("hidden");
  renderBookmarkTabs();
}

function addBookmarkDeal(oppId, title) {
  const id = Number(oppId);
  if (!Number.isFinite(id) || id <= 0) return;
  if (isDealBookmarked(id)) return;

  const dealCount = state.bookmarkedDeals.filter((d) => d.type !== "divider").length;
  if (dealCount >= MAX_BOOKMARKED_DEALS) {
    showToast(`Maximum ${MAX_BOOKMARKED_DEALS} bookmarked deals reached. Remove one to add another.`, true);
    return;
  }

  state.bookmarkedDeals.push({
    type: "deal",
    oppId: id,
    title: String(title || "").trim() || `Project #${id}`,
    addedAt: new Date().toISOString(),
  });

  saveBookmarkedDealsToStorage();
  closeBookmarkPreview(); // collapse if expanded
  renderBookmarkTabs();
  refreshAllBookmarkButtonStates();
}

function removeBookmarkDeal(oppId) {
  const id = Number(oppId);
  state.bookmarkedDeals = state.bookmarkedDeals.filter((d) => d.type === "divider" || Number(d.oppId) !== id);

  if (state.activeBookmarkTab === id) {
    closeBookmarkPreview();
  }

  saveBookmarkedDealsToStorage();
  renderBookmarkTabs();
  refreshAllBookmarkButtonStates();
}

async function refreshBookmarkTab(oppId, showLoading = true) {
  const id = Number(oppId);
  const deal = state.bookmarkedDeals.find((d) => Number(d.oppId) === id);
  if (!deal) return;

  const bodyEl = $("#bookmark-preview-body");
  if (bodyEl && showLoading) bodyEl.innerHTML = '<p class="opp-preview-loading">Refreshing…</p>';

  try {
    const data = await fetchOpportunityPreviewData(id, true);
    deal._cachedData = data;
    const titleEl = $("#bookmark-preview-title");
    if (titleEl) titleEl.textContent = data.opp?.title || data.opp?.Title || deal.title;
    if (bodyEl) {
      bodyEl.innerHTML = "";
      // Refresh preview context so replies from the refreshed bookmark
      // preview continue to submit against the right opp (defense in depth
      // — same as the initial setOpportunityPreviewContext call in
      // activateBookmarkTab).
      setOpportunityPreviewContext(id, data.opp, null);
      renderOpportunityPreviewContent(bodyEl, data, "bookmark");
      linkifyPhonesAndEmails(bodyEl);
    }
    setBookmarkPreviewCrmLink(id, data.opp?.project_number);
    renderBookmarkTabs();
  } catch (err) {
    if (bodyEl) {
      bodyEl.innerHTML = `<p class="opp-preview-error">${escapeHtml(err.message)}</p>`;
    }
  }
}

function refreshAllBookmarkButtonStates() {
  document.querySelectorAll(".card-bookmark-btn").forEach((btn) => {
    const oppId = Number(btn.dataset.oppId);
    const bookmarked = isDealBookmarked(oppId);
    btn.classList.toggle("bookmarked", bookmarked);
    btn.title = bookmarked ? "Remove bookmark" : "Bookmark deal";
    btn.setAttribute("aria-label", btn.title);
    btn.innerHTML = bookmarkRibbonSvg(bookmarked);
  });
  // Also update search popup preview bookmark buttons
  document.querySelectorAll(".search-popup-preview-bookmark").forEach((btn) => {
    const oppId = Number(btn.dataset.oppId);
    const bookmarked = isDealBookmarked(oppId);
    btn.classList.toggle("bookmarked", bookmarked);
    btn.title = bookmarked ? "Remove bookmark" : "Bookmark deal";
    btn.setAttribute("aria-label", btn.title);
    btn.innerHTML = bookmarkRibbonSvg(bookmarked);
  });
  // Also update search result row bookmark buttons
  document.querySelectorAll(".search-popup-result-bookmark").forEach((btn) => {
    const oppId = Number(btn.dataset.oppId);
    const bookmarked = isDealBookmarked(oppId);
    btn.classList.toggle("bookmarked", bookmarked);
    btn.title = bookmarked ? "Remove bookmark" : "Bookmark deal";
    btn.setAttribute("aria-label", btn.title);
    btn.innerHTML = bookmarkRibbonSvg(bookmarked);
  });
  const ctx = oppPreviewContext;
  if (ctx && ctx.oppId != null) {
    updatePreviewModalBookmarkButton(ctx.oppId);
  }
}

/* ================================================================================
   Event log
   ================================================================================ */

function renderEventLogEntries(entries, container) {
  if (!container) return;
  if (!entries || !entries.length) {
    container.innerHTML = '<div class="event-log-empty">No events logged yet.</div>';
    return;
  }
  container.innerHTML = entries.map((e) => {
    const ts = new Date(e.timestamp);
    const timeStr = Number.isNaN(ts.getTime()) ? "\u2014" : ts.toLocaleString(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
    const typeLabels = { edit: "[EDIT]", note: "[NOTE]", delete: "[DEL]", attach: "[ATTACH]" };
    const typeLabel = typeLabels[e.type] || "[INFO]";
    const cls = e.success ? "success" : "fail";
    const oppLabel = e.oppTitle ? escapeHtml(e.oppTitle) : e.oppId ? `#${e.oppId}` : "";
    return `<div class="event-log-entry ${cls}">
      <span class="event-log-entry-type">${typeLabel}</span>
      ${oppLabel ? `<span class="event-log-entry-opp">${oppLabel}</span>` : ""}
      <span class="event-log-entry-msg">${escapeHtml(e.message)}</span>
      <span class="event-log-entry-time">${timeStr}</span>
    </div>`;
  }).join("");
}

async function loadEventLogAdminUsers() {
  try {
    const res = await fetch("/api/event-log/users", { credentials: "same-origin" });
    if (!res.ok) return null;
    const data = await res.json();
    return Array.isArray(data.users) ? data.users : null;
  } catch {
    return null;
  }
}

async function loadEventLogAdminEvents(userId) {
  try {
    const res = await fetch(`/api/event-log/all?userId=${encodeURIComponent(userId)}`, { credentials: "same-origin" });
    if (!res.ok) return [];
    const data = await res.json();
    return Array.isArray(data.events) ? data.events : [];
  } catch {
    return [];
  }
}

function renderEventLogModal() {
  renderEventLogEntries(state.eventLog, $("#activity-log-list"));
}

/* ── Admin Console: Activity Tab ─────────────────────────────────────────── */

async function renderActivityLogTab() {
  const select = $("#activity-log-user-select");
  const list = $("#activity-log-list");
  if (!list) return;
  const userId = select ? select.value : null;
  if (!userId) {
    list.innerHTML = '<div class="event-log-empty">Select a user to view their activity.</div>';
    return;
  }
  list.innerHTML = '<div class="event-log-empty">Loading\u2026</div>';
  let events;
  const isOwnLog = String(userId) === String(state.currentUserId || "");
  if (isOwnLog) {
    // Non-admin endpoint — returns own log for any authenticated user
    try {
      const res = await fetch("/api/event-log", { credentials: "same-origin" });
      const data = await res.json();
      events = Array.isArray(data.events) ? data.events : [];
    } catch { events = []; }
  } else {
    events = await loadEventLogAdminEvents(userId);
  }
  renderEventLogEntries(events, list);
}

/* ── Activity / Time Sheet Modal (user-facing) ───────────────────────────── */

async function openActivityModal() {
  const modal = $("#activity-modal");
  if (!modal) return;
  modal.classList.remove("hidden");
  switchActivityTab("timesheet");
}

function switchActivityTab(tabName) {
  const tabs = $("#activity-tabs");
  if (!tabs) return;
  tabs.querySelectorAll(".presence-tab").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.tab === tabName);
  });
  const content = $("#activity-content");
  if (!content) return;
  content.innerHTML = "";
  if (tabName === "timesheet") {
    renderActivityTimesheet(content);
  } else if (tabName === "activity") {
    renderActivityLog(content);
  }
}

