// Delegated handler for toolbar overflow menu button (all note editors)
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-overflow-btn");
  if (!btn) return;
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  e.stopPropagation();
  // Close any existing dropdown and move buttons back
  const existing = document.querySelector(".note-format-overflow-dropdown.open");
  if (existing) {
    const prevToolbar = existing._ownerToolbar;
    existing.classList.remove("open");
    if (prevToolbar) {
      const anchor = prevToolbar.querySelector(".note-format-overflow-btn");
      existing.querySelectorAll("[data-overflow]").forEach(el => prevToolbar.insertBefore(el, anchor));
    }
    existing.remove();
    return;
  }
  // Create dropdown if not yet created
  let dd = document.createElement("div");
  dd.className = "note-format-overflow-dropdown";
  // Move overflow buttons into dropdown
  toolbar.querySelectorAll("[data-overflow]").forEach(el => {
    dd.appendChild(el);
  });
  // Append to body so CSS .note-format-toolbar [data-overflow] rules don't hide the items
  document.body.appendChild(dd);
  dd._ownerToolbar = toolbar;
  // Show dropdown
  dd.classList.add("open");
  // Position fixed below the ··· button, clamped to viewport
  dd.style.position = "fixed";
  const btnRect = btn.getBoundingClientRect();
  let top = btnRect.bottom + 4;
  let left = btnRect.left;
  // Clamp to viewport: if dropdown would go below screen, show above button
  requestAnimationFrame(() => {
    const ddRect = dd.getBoundingClientRect();
    if (top + ddRect.height > window.innerHeight - 8) {
      top = btnRect.top - ddRect.height - 4;
    }
    if (left + ddRect.width > window.innerWidth - 8) {
      left = window.innerWidth - ddRect.width - 8;
    }
    if (left < 8) left = 8;
    dd.style.top = top + "px";
    dd.style.left = left + "px";
    dd.style.right = "auto";
  });
  dd.style.top = top + "px";
  dd.style.left = left + "px";
  dd.style.right = "auto";
  // Move buttons back on any click inside dropdown
  dd.addEventListener("click", function() {
    setTimeout(() => {
      dd.classList.remove("open");
      const ownerToolbar = dd._ownerToolbar;
      if (ownerToolbar) {
        const anchor = ownerToolbar.querySelector(".note-format-overflow-btn");
        dd.querySelectorAll("[data-overflow]").forEach(el => {
          ownerToolbar.insertBefore(el, anchor);
        });
      }
      dd.remove();
    }, 50);
  });
});

// Close overflow dropdown on outside click and move buttons back
document.addEventListener("click", function (e) {
  if (!e.target.closest(".note-format-overflow-btn") && !e.target.closest(".note-format-overflow-dropdown")) {
    const dd = document.querySelector(".note-format-overflow-dropdown.open");
    if (dd) {
      dd.classList.remove("open");
      // Move buttons back to their original toolbar
      const ownerToolbar = dd._ownerToolbar;
      if (ownerToolbar) {
        const lastBtn = ownerToolbar.querySelector(".note-format-overflow-btn");
        dd.querySelectorAll("[data-overflow]").forEach(el => {
          ownerToolbar.insertBefore(el, lastBtn);
        });
      }
      dd.remove();
    }
  }
});

// Image upload button in note editor overflow menu
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-img-upload-btn");
  if (!btn) return;
  e.stopPropagation();
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  const editor = toolbar.parentElement?.querySelector(".note-editor") || toolbar.parentElement?.querySelector(".phtml-note-editor");
  if (!editor) return;
  // Create a temporary file input
  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.accept = "image/*";
  fileInput.style.display = "none";
  document.body.appendChild(fileInput);
  fileInput.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    if (!file) { fileInput.remove(); return; }
    if (!file.type.startsWith("image/")) { showToast("Please select an image file", true); fileInput.remove(); return; }
    if (file.size > 20 * 1024 * 1024) { showToast("Image too large (max 20 MB)", true); fileInput.remove(); return; }
    // Store pending image on the editor element
    if (!editor._pendingImages) editor._pendingImages = [];
    editor._pendingImages.push(file);
    // Insert placeholder thumbnail at cursor
    editor.focus();
    const placeholder = document.createElement("img");
    placeholder.className = "note-inline-img note-img-pending";
    placeholder.src = URL.createObjectURL(file);
    placeholder.title = file.name || "Attached image";
    const sel = window.getSelection();
    if (sel && sel.rangeCount) {
      const range = sel.getRangeAt(0);
      range.deleteContents();
      range.insertNode(placeholder);
      range.setStartAfter(placeholder);
      range.setEndAfter(placeholder);
      sel.removeAllRanges();
      sel.addRange(range);
    }
    showToast("Image attached — will upload when you save");
    fileInput.remove();
  });
  fileInput.click();
});

// Backdate icon button: dynamically creates a temp date input, positions it
// over the button, and opens the native picker. Works on mobile where
// input.click() on a visually-hidden element does not open the picker.
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-backdate-btn, .preview-note-backdate-btn");
  if (!btn) return;
  e.stopPropagation();
  e.preventDefault();
  const temp = document.createElement("input");
  temp.type = "date";
  // Pre-set to previously selected date so picker opens on that date
  if (btn.dataset.backdateValue) temp.value = btn.dataset.backdateValue;
  const r = btn.getBoundingClientRect();
  Object.assign(temp.style, {
    position: "fixed",
    left: r.left + "px",
    top: r.top + "px",
    width: r.width + "px",
    height: r.height + "px",
    opacity: "0",
    zIndex: "99999",
    pointerEvents: "auto",
  });
  document.body.appendChild(temp);
  const cleanup = () => { if (temp.parentNode) temp.remove(); };
  const openPicker = () => {
    try { if (temp.showPicker) { temp.showPicker(); return; } } catch (_) {}
    temp.click();
  };
  requestAnimationFrame(() => {
    openPicker();
    setTimeout(openPicker, 50);
  });
  temp.addEventListener("change", () => {
    btn.dataset.backdateValue = temp.value || "";
    // Update the display label next to the button
    const label = btn.parentElement?.querySelector(".backdate-display");
    if (label) {
      if (temp.value) {
        const parts = temp.value.split("-");
        label.textContent = `${parts[1]}/${parts[2]}/${parts[0]}`;
        label.classList.remove("hidden");
      } else {
        label.textContent = "";
        label.classList.add("hidden");
      }
    }
    cleanup();
  });
  // Safety cleanup only — do NOT clean on blur (opening the native date picker
  // fires blur which would remove the temp input before the user can pick a date)
  setTimeout(cleanup, 15000);
});

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Highlighter Dropdown
// ════════════════════════════════════════════════════════════════════════════
const _HIGHLIGHT_COLORS = [
  { name: "Green",  css: "rgba(102,187,106,.20)" },
  { name: "Yellow", css: "rgba(255,235,59,.20)" },
  { name: "Blue",   css: "rgba(66,165,245,.20)" },
  { name: "Pink",   css: "rgba(239,83,80,.20)" },
  { name: "Orange", css: "rgba(255,167,38,.20)" },
  { name: "Purple", css: "rgba(171,71,188,.20)" },
];

const _TEXT_COLORS = [
  { name: "Default", css: "" },
  { name: "Red",     css: "#ef5350" },
  { name: "Orange",  css: "#ff9800" },
  { name: "Green",   css: "#66bb6a" },
  { name: "Blue",    css: "#42a5f5" },
  { name: "Purple",  css: "#ab47bc" },
  { name: "Gray",    css: "#9e9e9e" },
];

function _toggleTextColorDropdown(btn, editor) {
  const existing = document.querySelector(".preview-textcolor-dropdown");
  if (existing) { existing.remove(); return; }
  const dd = document.createElement("div");
  dd.className = "preview-textcolor-dropdown preview-highlighter-dropdown";
  dd.tabIndex = -1;
  _TEXT_COLORS.forEach(c => {
    const sw = document.createElement("button");
    sw.type = "button";
    sw.className = "preview-highlighter-swatch";
    sw.style.background = c.css || "var(--text)";
    sw.title = c.name;
    sw.setAttribute("aria-label", c.name);
    sw.addEventListener("click", (e) => {
      e.stopPropagation();
      editor.focus();
      if (c.css) document.execCommand("foreColor", false, c.css);
      else document.execCommand("removeFormat", false, null);
      dd.remove();
    });
    dd.appendChild(sw);
  });
  document.body.appendChild(dd);
  const r = btn.getBoundingClientRect();
  dd.style.left = `${Math.min(r.left, window.innerWidth - 180)}px`;
  dd.style.top = `${r.bottom + 4}px`;
  const close = (e) => {
    if (!dd.contains(e.target) && !btn.contains(e.target)) {
      dd.remove();
      document.removeEventListener("click", close, true);
    }
  };
  requestAnimationFrame(() => document.addEventListener("click", close, true));
}

function _toggleHighlighterDropdown(btn, editor) {
  const existing = document.querySelector(".preview-highlighter-dropdown");
  if (existing) { existing.remove(); return; }
  const dd = document.createElement("div");
  dd.className = "preview-highlighter-dropdown";
  dd.tabIndex = -1;
  _HIGHLIGHT_COLORS.forEach(c => {
    const sw = document.createElement("button");
    sw.type = "button";
    sw.className = "preview-highlighter-swatch";
    sw.style.background = c.css;
    sw.title = c.name;
    sw.setAttribute("aria-label", c.name);
    sw.addEventListener("click", (e) => {
      e.stopPropagation();
      editor.focus();
      document.execCommand("hiliteColor", false, c.css);
      dd.remove();
    });
    dd.appendChild(sw);
  });
  document.body.appendChild(dd);
  const r = btn.getBoundingClientRect();
  dd.style.left = `${Math.min(r.left, window.innerWidth - 180)}px`;
  dd.style.top = `${r.bottom + 4}px`;
  const close = (e) => {
    if (!dd.contains(e.target) && !btn.contains(e.target)) {
      dd.remove();
      document.removeEventListener("click", close, true);
    }
  };
  requestAnimationFrame(() => document.addEventListener("click", close, true));
}

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Emoji Picker
// ════════════════════════════════════════════════════════════════════════════
function _showPreviewEmojiPicker(btn, editor) {
  const existing = document.querySelector("#notes-emoji-picker");
  if (existing) { existing.remove(); return; }
  if (typeof EMOJIS === "undefined" || !EMOJIS.length) return;
  const picker = document.createElement("div");
  picker.id = "notes-emoji-picker";
  picker.className = "presence-emoji-picker presence-emoji-picker-overlay";
  picker.tabIndex = -1;
  EMOJIS.forEach(em => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = em;
    b.className = "presence-emoji-btn";
    b.tabIndex = -1;
    b.setAttribute("role", "menuitem");
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      editor.focus();
      document.execCommand("insertText", false, em);
      picker.remove();
      requestAnimationFrame(() => { try { editor.focus({ preventScroll: true }); } catch { editor.focus(); } });
    });
    picker.appendChild(b);
  });
  document.body.appendChild(picker);
  const r = btn.getBoundingClientRect();
  const isMobile = window.innerWidth < 480;
  picker.style.position = "fixed";
  picker.style.zIndex = "99999";
  picker.style.width = "auto";
  picker.style.minWidth = "200px";
  picker.style.maxWidth = isMobile ? "none" : "calc(100vw - 16px)";
  if (isMobile) {
    picker.style.left = "8px";
    picker.style.right = "8px";
  } else {
    const nw = picker.offsetWidth || 220;
    let left = r.right - nw;
    if (left < 8) left = 8;
    if (left + nw > window.innerWidth - 8) left = window.innerWidth - nw - 8;
    picker.style.left = `${left}px`;
  }
  picker.style.top = `${r.bottom + 4}px`;
  picker.style.right = "auto";
  picker.style.bottom = "auto";
  const closePicker = (e) => {
    if (!picker.contains(e.target) && !btn.contains(e.target)) {
      picker.remove();
      document.removeEventListener("click", closePicker, true);
    }
  };
  requestAnimationFrame(() => document.addEventListener("click", closePicker, true));
}

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Link Insert
// ════════════════════════════════════════════════════════════════════════════
function _showPreviewLinkInput(btn, editor) {
  const existing = document.querySelector(".preview-link-input-wrap");
  if (existing) { existing.remove(); return; }
  const wrap = document.createElement("div");
  wrap.className = "preview-link-input-wrap";
  const input = document.createElement("input");
  input.type = "url";
  input.className = "preview-link-input";
  input.placeholder = "https://example.com";
  input.autocomplete = "off";
  const applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "btn btn-primary btn-sm";
  applyBtn.textContent = "Apply";
  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "btn btn-ghost btn-sm";
  cancelBtn.textContent = "Cancel";
  wrap.appendChild(input);
  wrap.appendChild(applyBtn);
  wrap.appendChild(cancelBtn);
  document.body.appendChild(wrap);
  const r = btn.getBoundingClientRect();
  wrap.style.position = "fixed";
  const wrapWidth = wrap.offsetWidth || 320;
  const maxLeft = window.innerWidth - wrapWidth - 8;
  let left = r.left;
  if (left > maxLeft) left = Math.max(8, maxLeft);
  if (left < 8) left = 8;
  wrap.style.left = `${left}px`;
  wrap.style.top = `${r.bottom + 4}px`;
  wrap.style.zIndex = "99999";
  input.focus();
  const close = () => { wrap.remove(); document.removeEventListener("click", onClickAway, true); };
  const onClickAway = (e) => {
    if (!wrap.contains(e.target) && !btn.contains(e.target)) { e.stopPropagation(); close(); }
  };
  requestAnimationFrame(() => document.addEventListener("click", onClickAway, true));
  applyBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const url = (input.value || "").trim();
    if (!url) { close(); return; }
    const fullUrl = /^https?:\/\//i.test(url) ? url : "https://" + url;
    editor.focus();
    const sel = window.getSelection();
    const text = sel && sel.toString().trim();
    if (text) {
      document.execCommand("createLink", false, fullUrl);
    } else {
      document.execCommand("insertHTML", false, `<a href="${fullUrl}" target="_blank" rel="noopener">${fullUrl}</a>`);
    }
    close();
  });
  cancelBtn.addEventListener("click", (e) => { e.stopPropagation(); close(); });
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") { e.preventDefault(); applyBtn.click(); }
    if (e.key === "Escape") { close(); }
  });
}

// ════════════════════════════════════════════════════════════════════════════
// Notification Drawer
// ════════════════════════════════════════════════════════════════════════════

let _notificationDrawerOpen = false;
let _notificationPopout = false;
let _notificationBadgePollTimer = null;
let _notificationCache = [];

function openNotificationDrawer() {
  const drawer = $("#notification-drawer");
  const backdrop = $("#notification-drawer-backdrop");
  if (!drawer || !backdrop) return;
  _notificationDrawerOpen = true;
  drawer.classList.remove("drawer-hidden");
  backdrop.classList.remove("hidden");
  _loadNotificationDrawerList();
}

function closeNotificationDrawer() {
  const drawer = $("#notification-drawer");
  const backdrop = $("#notification-drawer-backdrop");
  if (!drawer || !backdrop) return;
  _notificationDrawerOpen = false;
  drawer.classList.add("drawer-hidden");
  backdrop.classList.add("hidden");
}

function toggleNotificationDrawer() {
  if (_notificationDrawerOpen) closeNotificationDrawer();
  else openNotificationDrawer();
}

function toggleNotificationPopout() {
  const drawer = $("#notification-drawer");
  const btn = $("#notification-popout-btn");
  if (!drawer || !btn) return;
  _notificationPopout = !_notificationPopout;
  drawer.classList.toggle("popout-mode", _notificationPopout);
  btn.classList.toggle("popout-active", _notificationPopout);
  btn.title = _notificationPopout ? "Collapse" : "Expand";
  const expandIcon = btn.querySelector(".notification-popout-icon-expand");
  const collapseIcon = btn.querySelector(".notification-popout-icon-collapse");
  if (expandIcon) expandIcon.style.display = _notificationPopout ? "none" : "";
  if (collapseIcon) collapseIcon.style.display = _notificationPopout ? "" : "none";
}

async function _loadNotificationDrawerList() {
  const list = $("#notification-drawer-list");
  if (!list) return;
  list.innerHTML = `<div class="notification-drawer-empty">Loading…</div>`;
  try {
    const rows = await api("/api/v2/notifications");
    _notificationCache = rows || [];
    _renderNotificationDrawerList();
    _pollNotificationBadge();
  } catch (err) {
    list.innerHTML = `<div class="notification-drawer-empty">Failed to load notifications.</div>`;
  }
}

function _renderNotificationDrawerList() {
  const list = $("#notification-drawer-list");
  if (!list) return;
  if (!_notificationCache.length) {
    list.innerHTML = `<div class="notification-drawer-empty">No notifications yet.</div>`;
    return;
  }
  list.innerHTML = "";
  for (const n of _notificationCache) {
    list.appendChild(_renderNotificationDrawerItem(n));
  }
}

function _notifTypeIcon(type) {
  if (type === "task_assigned") {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M9 5h-2a2 2 0 0 0 -2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2 -2v-12a2 2 0 0 0 -2 -2h-2"/><path d="M9 14l2 2 4 -4"/></svg>`;
  }
  if (type === "note_tagged") {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M8 12a4 4 0 1 0 8 0a4 4 0 1 0 -8 0"/><path d="M16 12v1.5a2.5 2.5 0 0 0 5 0v-1.5a9 9 0 1 0 -5.5 8.28"/></svg>`;
  }
  if (type === "reply_tagged") {
    // Reply-on-tagged-note variant — same @-icon with a small reply bubble
    // in the corner to indicate "a reply" rather than a new note.
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M8 12a4 4 0 1 0 8 0a4 4 0 1 0 -8 0"/><path d="M16 12v1.5a2.5 2.5 0 0 0 5 0v-1.5a9 9 0 1 0 -5.5 8.28"/><path d="M4 20l1 -3"/></svg>`;
  }
  if (type === "service_feed") {
    // Cloud icon for third-party service status notifications.
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M17.5 19a4.5 4.5 0 1 0 0 -9a4.5 4.5 0 0 0 -8.5 -2a4.5 4.5 0 0 0 -4 11h12.5z"/></svg>`;
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M8 9l3 3l-2 1"/><path d="M10.5 17.5l-3.5 -2l-2 1"/><path d="M17 3l4 4"/><path d="M21 7l-6 6"/><path d="M16 3l0 5l5 0"/></svg>`;
}

function _renderNotificationDrawerItem(n) {
  const el = document.createElement("div");
  // Add a feed-specific class so the accent stripe CSS can target it.
  const typeClass = n.type === "service_feed" ? " service-feed" : "";
  el.className = "notification-drawer-item" + typeClass + (n.isRead ? "" : " unread");
  el.dataset.notifId = n.id;

  const typeIcon = _notifTypeIcon(n.type);
  const projectTitle = n.projectTitle || "";
  const time = _notifTimeAgo(n.created);
  // Both note_tagged and reply_tagged carry event_id in their payload and
  // are expandable to the parent event's content (which includes any replies).
  const hasPayload = (n.type === "note_tagged" || n.type === "reply_tagged") && n.payload && n.payload.event_id && n.opportunityId;
  const snippet = escapeHtml((n.snippet || "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&"));

  // Apply per-feed accent color as a CSS variable so the border + icon background tint.
  if (n.type === "service_feed" && n.payload && n.payload.color) {
    el.style.setProperty("--service-feed-accent", n.payload.color);
  }

  let msgHtml = escapeHtml(n.message || "");
  if (projectTitle && msgHtml.includes(escapeHtml(projectTitle))) {
    const escapedTitle = escapeHtml(projectTitle);
    const link = `<a href="#" class="notif-inline-link" data-notif-project="${n.opportunityId || ""}" data-notif-title="${escapedTitle}">${escapedTitle}</a>`;
    msgHtml = msgHtml.replace(escapedTitle, link);
  }

  el.innerHTML = `
    <div class="notification-drawer-item-row">
      <div class="notification-drawer-item-icon">${typeIcon}</div>
      <div class="notification-drawer-item-body">
        <div class="notification-drawer-item-actor">${msgHtml}</div>
        ${snippet ? `<div class="notification-drawer-item-message">${snippet}…</div>` : ""}
      </div>
      <div class="notification-drawer-item-time">${time}</div>
    </div>
    ${hasPayload ? `<button class="notification-drawer-item-expand" data-notif-expand="${n.id}" data-notif-event="${n.payload.event_id}" data-notif-opp="${n.opportunityId}">Show note</button>` : ""}
  `;

  // Mark as read on click
  el.addEventListener("click", (e) => {
    if (e.target.closest(".notification-drawer-item-expand") || e.target.closest(".notif-inline-link")) return;
    // Service-feed notifications: if the payload includes a URL, open it in a new tab.
    if (n.type === "service_feed" && n.payload && n.payload.url) {
      try { window.open(n.payload.url, "_blank", "noopener,noreferrer"); } catch (e) {}
    }
    if (!n.isRead) {
      n.isRead = true;
      el.classList.remove("unread");
      api(`/api/v2/notifications/${n.id}/read`, { method: "PUT" }).catch(() => {});
      _updateNotificationBadge();
    }
  });

  // Project link opens preview
  const projectLink = el.querySelector(".notif-inline-link");
  if (projectLink) {
    projectLink.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const oppId = parseInt(projectLink.dataset.notifProject, 10);
      if (oppId) openOpportunityPreviewModal(oppId, projectLink.dataset.notifTitle || "");
    });
  }

  // Expand button for full note
  const expandBtn = el.querySelector(".notification-drawer-item-expand");
  if (expandBtn) {
    expandBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const existing = el.querySelector(".notification-drawer-item-expanded");
      if (existing) {
        existing.remove();
        expandBtn.textContent = "Show note";
        return;
      }
      expandBtn.textContent = "Loading…";
      try {
        const oppId = parseInt(expandBtn.dataset.notifOpp, 10);
        const eventId = parseInt(expandBtn.dataset.notifEvent, 10);
        const history = await api(`/api/v2/projects/${oppId}/history`);
        const event = (history || []).find((h) => h.id === eventId);
        const content = event ? (event.content || event.text || event.message || "No content available.") : "Could not load note.";
        const div = document.createElement("div");
        div.className = "notification-drawer-item-expanded";
        div.innerHTML = content;
        el.appendChild(div);
        expandBtn.textContent = "Hide note";
      } catch {
        expandBtn.textContent = "Show note";
      }
    });
  }

  return el;
}

function _notifTimeAgo(isoStr) {
  if (!isoStr) return "";
  const diff = Date.now() - new Date(isoStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "now";
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  const days = Math.floor(hrs / 24);
  if (days < 7) return `${days}d`;
  return new Date(isoStr).toLocaleDateString();
}

// ── Badge polling ──────────────────────────────────────────────────────────

async function _pollNotificationBadge() {
  try {
    const res = await api("/api/v2/notifications/unread-count");
    _updateNotificationBadgeUI(res.count || 0);
  } catch { /* silent */ }
}

function _updateNotificationBadge() {
  // Optimistic update: count unread items in cache
  const unread = _notificationCache.filter((n) => !n.isRead).length;
  _updateNotificationBadgeUI(unread);
}

function _updateNotificationBadgeUI(count) {
  const badge = $("#notification-unread-badge");
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count > 99 ? "99+" : String(count);
    badge.classList.remove("hidden");
  } else {
    badge.classList.add("hidden");
  }
}

function startNotificationBadgePoll() {
  // One-shot initial fetch; SSE notification:new events handle ongoing updates
  _pollNotificationBadge();
}

function stopNotificationBadgePoll() {
  // No-op — no interval to clear (SSE handles updates)
}

// ── Mark all read ──────────────────────────────────────────────────────────

async function _markAllNotificationsRead() {
  const unread = _notificationCache.filter((n) => !n.isRead).length;
  if (unread === 0) return;
  const ok = await confirmDialog({
    title: "Mark all as read",
    message: `Mark all ${unread} unread notification${unread === 1 ? "" : "s"} as read?`,
    confirmLabel: "Mark all read",
    danger: false,
  });
  if (!ok) return;
  try {
    await api("/api/v2/notifications/read-all", { method: "PUT" });
    for (const n of _notificationCache) n.isRead = true;
    _renderNotificationDrawerList();
    _updateNotificationBadge();
  } catch (err) {
    showToast("Failed to mark notifications as read.", true);
  }
}

// ── Bind events ────────────────────────────────────────────────────────────

function bindNotificationDrawer() {
  const bellBtn = $("#notification-bell-btn");
  const closeBtn = $("#notification-drawer-close");
  const backdrop = $("#notification-drawer-backdrop");
  const markAllBtn = $("#notification-mark-all-btn");
  const popoutBtn = $("#notification-popout-btn");

  if (bellBtn) bellBtn.addEventListener("click", toggleNotificationDrawer);
  if (closeBtn) closeBtn.addEventListener("click", closeNotificationDrawer);
  if (backdrop) backdrop.addEventListener("click", closeNotificationDrawer);
  if (markAllBtn) markAllBtn.addEventListener("click", _markAllNotificationsRead);
  if (popoutBtn) popoutBtn.addEventListener("click", toggleNotificationPopout);

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && _notificationDrawerOpen) closeNotificationDrawer();
  });
}

// Initialize on DOM ready
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => {
    bindNotificationDrawer();
    connectSSE();
  });
} else {
  bindNotificationDrawer();
  connectSSE();
}

// ════════════════════════════════════════════════════════════════════════════

// Safety net: if *both* login and app screens are still hidden long after load
// (e.g. early JS error or init never reached a showApp/showLogin decision),
// force the login screen visible. Do *not* fight a real async login/restore that
// has already called showApp (even if refreshAll is still loading data).
setTimeout(() => {
  try {
    var login = document.getElementById('login-screen');
    var appEl = document.getElementById('app');
    const bothHidden = !!(login && login.classList && login.classList.contains('hidden') &&
                          appEl && appEl.classList && appEl.classList.contains('hidden'));
    if (bothHidden) {
      console.warn('[dashboard] Both screens still hidden after init; forcing login UI visible as fallback.');
      if (typeof showLogin === 'function') {
        showLogin();
      } else if (login) {
        login.classList.remove('hidden');
        if (appEl) appEl.classList.add('hidden');
      }
    }
  } catch (e) {
    // Last resort - pure vanilla
    try {
      document.body.innerHTML = '<div style="padding:2rem;font-family:sans-serif"><h1>Dashboard failed to load</h1><p>Server may be unreachable or there is a JS error. Check console (F12) and contact admin. <button onclick="location.reload()">Reload</button></p></div>';
    } catch(_) {}
  }
}, 4000);

/* roundRect polyfill for older browsers */
if (typeof CanvasRenderingContext2D !== "undefined" && !CanvasRenderingContext2D.prototype.roundRect) {
  CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
    if (typeof r === "number") r = [r, r, r, r];
    else if (!Array.isArray(r)) r = [0, 0, 0, 0];
    const [tl, tr, br, bl] = r;
    this.moveTo(x + tl, y);
    this.lineTo(x + w - tr, y);
    this.quadraticCurveTo(x + w, y, x + w, y + tr);
    this.lineTo(x + w, y + h - br);
    this.quadraticCurveTo(x + w, y + h, x + w - br, y + h);
    this.lineTo(x + bl, y + h);
    this.quadraticCurveTo(x, y + h, x, y + h - bl);
    this.lineTo(x, y + tl);
    this.quadraticCurveTo(x, y, x + tl, y);
    this.closePath();
  };
}

/* ═══════════════════════════════════════════════════════════════════════════
   FEAT-027 — Photo Markup Editor (Gradia-inspired canvas annotation)
   ═══════════════════════════════════════════════════════════════════════════ */

const _markupTools = [
  { id: "pen",         label: "Pen",         icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg>' },
  { id: "line",        label: "Line",         icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="5" y1="19" x2="19" y2="5"/></svg>' },
  { id: "arrow",       label: "Arrow",        icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>' },
  { id: "rect",        label: "Rectangle",    icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/></svg>' },
  { id: "circle",      label: "Circle",       icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' },
  { id: "text",        label: "Text",         icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 7 4 4 20 4 20 7"/><line x1="9.5" y1="20" x2="14.5" y2="20"/><line x1="12" y1="4" x2="12" y2="20"/></svg>' },
  { id: "highlighter", label: "Highlighter",  icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 11-6 6v3h9l3-3"/><path d="m22 12-4.6 4.6a2 2 0 0 1-2.8 0l-5.2-5.2a2 2 0 0 1 0-2.8L14 4"/></svg>' },
  { id: "censor",      label: "Censor",       icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="3" y1="15" x2="21" y2="15"/><line x1="9" y1="3" x2="9" y2="21"/><line x1="15" y1="3" x2="15" y2="21"/></svg>' },
  { id: "number",      label: "Number Stamp", icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><text x="12" y="16" text-anchor="middle" font-size="12" font-weight="bold" fill="currentColor" stroke="none">1</text></svg>' },
];

let _markupState = null;

function _markupScreenToImage(sx, sy) {
  const s = _markupState;
  if (!s || !s.canvas) return { x: 0, y: 0 };
  const rect = s.canvas.getBoundingClientRect();
  const displayW = rect.width;
  const displayH = rect.height;
  const scale = Math.min(displayW / s.natW, displayH / s.natH);
  const drawW = s.natW * scale;
  const drawH = s.natH * scale;
  const offX = (displayW - drawW) / 2;
  const offY = (displayH - drawH) / 2;
  return {
    x: (sx - rect.left - offX) / scale,
    y: (sy - rect.top - offY) / scale,
  };
}

function _markupRender() {
  const s = _markupState;
  if (!s || !s.ctx) return;
  const { ctx, canvas, natW, natH, img, actions, currentAction } = s;
  canvas.width = natW;
  canvas.height = natH;
  ctx.clearRect(0, 0, natW, natH);
  if (img) ctx.drawImage(img, 0, 0, natW, natH);
  for (const a of actions) _markupDrawAction(ctx, a, s);
  if (currentAction) _markupDrawAction(ctx, currentAction, s);
}

function _markupDrawAction(ctx, a, s) {
  ctx.save();
  const col = a.color || "#ff0000";
  const sz = a.size || 4;
  switch (a.type) {
    case "pen": {
      if (!a.points || a.points.length < 2) break;
      ctx.strokeStyle = col;
      ctx.lineWidth = sz;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(a.points[0].x, a.points[0].y);
      for (let i = 1; i < a.points.length - 1; i++) {
        const mx = (a.points[i].x + a.points[i + 1].x) / 2;
        const my = (a.points[i].y + a.points[i + 1].y) / 2;
        ctx.quadraticCurveTo(a.points[i].x, a.points[i].y, mx, my);
      }
      const last = a.points[a.points.length - 1];
      ctx.lineTo(last.x, last.y);
      ctx.stroke();
      break;
    }
    case "line": {
      if (!a.start || !a.end) break;
      ctx.strokeStyle = col;
      ctx.lineWidth = sz;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(a.start.x, a.start.y);
      ctx.lineTo(a.end.x, a.end.y);
      ctx.stroke();
      break;
    }
    case "arrow": {
      if (!a.start || !a.end) break;
      const dx = a.end.x - a.start.x;
      const dy = a.end.y - a.start.y;
      const angle = Math.atan2(dy, dx);
      const headLen = Math.max(sz * 3, 12);
      ctx.strokeStyle = col;
      ctx.fillStyle = col;
      ctx.lineWidth = sz;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(a.start.x, a.start.y);
      ctx.lineTo(a.end.x, a.end.y);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(a.end.x, a.end.y);
      ctx.lineTo(a.end.x - headLen * Math.cos(angle - Math.PI / 6), a.end.y - headLen * Math.sin(angle - Math.PI / 6));
      ctx.lineTo(a.end.x - headLen * Math.cos(angle + Math.PI / 6), a.end.y - headLen * Math.sin(angle + Math.PI / 6));
      ctx.closePath();
      ctx.fill();
      break;
    }
    case "rect": {
      if (!a.start || !a.end) break;
      const x = Math.min(a.start.x, a.end.x);
      const y = Math.min(a.start.y, a.end.y);
      const w = Math.abs(a.end.x - a.start.x);
      const h = Math.abs(a.end.y - a.start.y);
      if (a.fillColor) { ctx.fillStyle = a.fillColor; ctx.fillRect(x, y, w, h); }
      ctx.strokeStyle = col;
      ctx.lineWidth = sz;
      ctx.strokeRect(x, y, w, h);
      break;
    }
    case "circle": {
      if (!a.start || !a.end) break;
      const cx = (a.start.x + a.end.x) / 2;
      const cy = (a.start.y + a.end.y) / 2;
      const rx = Math.abs(a.end.x - a.start.x) / 2;
      const ry = Math.abs(a.end.y - a.start.y) / 2;
      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      if (a.fillColor) { ctx.fillStyle = a.fillColor; ctx.fill(); }
      ctx.strokeStyle = col;
      ctx.lineWidth = sz;
      ctx.stroke();
      break;
    }
    case "text": {
      if (!a.text || !a.position) break;
      const fontSize = Math.max(sz * 2.5, 18);
      ctx.font = `bold ${fontSize}px sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      const lines = a.text.split("\n");
      const lineHeight = fontSize * 1.25;
      const totalH = lines.length * lineHeight;
      const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
      const padH = 5, padV = 3;
      const bgX = a.position.x - maxW / 2 - padH;
      const bgY = a.position.y - totalH / 2 - padV;
      const bgW = maxW + padH * 2;
      const bgH = totalH + padV * 2;
      const bgR = Math.max(fontSize * 0.35, 4);
      ctx.fillStyle = "rgba(255,255,255,0.92)";
      ctx.beginPath();
      ctx.roundRect(bgX, bgY, bgW, bgH, bgR);
      ctx.fill();
      ctx.strokeStyle = "rgba(255,255,255,0.6)";
      ctx.lineWidth = 1.5;
      lines.forEach((line, i) => {
        const ly = a.position.y - totalH / 2 + lineHeight * i + lineHeight / 2;
        ctx.strokeText(line, a.position.x, ly);
      });
      ctx.fillStyle = "#000";
      lines.forEach((line, i) => {
        ctx.fillText(line, a.position.x, a.position.y - totalH / 2 + lineHeight * i + lineHeight / 2);
      });
      break;
    }
    case "highlighter": {
      if (!a.points || a.points.length < 2) break;
      ctx.globalCompositeOperation = "multiply";
      ctx.strokeStyle = col;
      ctx.lineWidth = sz * 3;
      ctx.lineCap = "butt";
      ctx.lineJoin = "round";
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.moveTo(a.points[0].x, a.points[0].y);
      for (let i = 1; i < a.points.length; i++) {
        ctx.lineTo(a.points[i].x, a.points[i].y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = "source-over";
      break;
    }
    case "censor": {
      if (!a.start || !a.end) break;
      const cx1 = Math.min(a.start.x, a.end.x);
      const cy1 = Math.min(a.start.y, a.end.y);
      const cw = Math.abs(a.end.x - a.start.x);
      const ch = Math.abs(a.end.y - a.start.y);
      if (cw < 2 || ch < 2) break;
      const blockSz = Math.max(6, sz * 2);
      const tmpC = document.createElement("canvas");
      tmpC.width = Math.max(1, Math.ceil(cw / blockSz));
      tmpC.height = Math.max(1, Math.ceil(ch / blockSz));
      const tCtx = tmpC.getContext("2d");
      tCtx.drawImage(s.canvas, cx1, cy1, cw, ch, 0, 0, tmpC.width, tmpC.height);
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(tmpC, 0, 0, tmpC.width, tmpC.height, cx1, cy1, cw, ch);
      ctx.imageSmoothingEnabled = true;
      break;
    }
    case "number": {
      if (!a.position) break;
      const r = Math.max(sz * 3, 12);
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.arc(a.position.x, a.position.y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = "#fff";
      ctx.font = `bold ${r * 1.1}px sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(a.number), a.position.x, a.position.y + 1);
      break;
    }
  }
  ctx.restore();
}

function openPhotoMarkupModal(photoId, oppId) {
  const modal = $("#photo-markup-modal");
  if (!modal) return;
  const canvas = $("#photo-markup-canvas");
  const wrap = $("#photo-markup-canvas-wrap");
  const toolbar = $("#photo-markup-toolbar");
  const footer = $("#photo-markup-footer");
  if (!canvas || !wrap || !toolbar || !footer) return;

  _markupState = {
    canvas, wrap, toolbar, footer,
    ctx: canvas.getContext("2d"),
    img: null, natW: 0, natH: 0,
    tool: "pen", color: "#ff0000", fillColor: null, size: 4,
    actions: [], redoStack: [], currentAction: null,
    drawing: false, numberCounter: 1, oppId, photoId,
    _keyHandler: null, _resizeHandler: null,
  };

  toolbar.innerHTML = "";
  footer.innerHTML = "";

  _markupTools.forEach(t => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "photo-markup-tool-btn" + (t.id === "pen" ? " active" : "");
    btn.title = t.label;
    btn.innerHTML = t.icon;
    btn.dataset.tool = t.id;
    btn.addEventListener("click", () => {
      _markupState.tool = t.id;
      toolbar.querySelectorAll(".photo-markup-tool-btn").forEach(b => b.classList.toggle("active", b.dataset.tool === t.id));
      wrap.className = "photo-markup-canvas-wrap tool-" + t.id;
    });
    toolbar.appendChild(btn);
  });

  const sep1 = document.createElement("span");
  sep1.className = "markup-sep";
  toolbar.appendChild(sep1);

  const colorInput = document.createElement("input");
  colorInput.type = "color";
  colorInput.className = "photo-markup-color-input";
  colorInput.value = "#ff0000";
  colorInput.title = "Stroke color";
  colorInput.addEventListener("input", () => { _markupState.color = colorInput.value; });
  toolbar.appendChild(colorInput);

  const fillColorBtn = document.createElement("button");
  fillColorBtn.type = "button";
  fillColorBtn.className = "photo-markup-tool-btn";
  fillColorBtn.title = "Toggle fill color (for shapes)";
  fillColorBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="1"><rect x="4" y="4" width="16" height="16" rx="2" opacity="0.3"/></svg>';
  let fillEnabled = false;
  const fillInput = document.createElement("input");
  fillInput.type = "color";
  fillInput.value = "#ff000044";
  fillInput.className = "photo-markup-color-input";
  fillInput.style.display = "none";
  fillInput.title = "Fill color";
  fillColorBtn.addEventListener("click", () => {
    fillEnabled = !fillEnabled;
    fillColorBtn.classList.toggle("active", fillEnabled);
    fillInput.style.display = fillEnabled ? "" : "none";
    _markupState.fillColor = fillEnabled ? fillInput.value + "88" : null;
  });
  fillInput.addEventListener("input", () => {
    if (fillEnabled) _markupState.fillColor = fillInput.value + "88";
  });
  toolbar.appendChild(fillColorBtn);
  toolbar.appendChild(fillInput);

  const sep2 = document.createElement("span");
  sep2.className = "markup-sep";
  toolbar.appendChild(sep2);

  const sizeLabel = document.createElement("span");
  sizeLabel.className = "photo-markup-size-label";
  sizeLabel.textContent = "4";
  const sizeSlider = document.createElement("input");
  sizeSlider.type = "range";
  sizeSlider.className = "photo-markup-size-slider";
  sizeSlider.min = "1";
  sizeSlider.max = "40";
  sizeSlider.value = "4";
  sizeSlider.addEventListener("input", () => {
    _markupState.size = parseInt(sizeSlider.value);
    sizeLabel.textContent = sizeSlider.value;
  });
  toolbar.appendChild(sizeLabel);
  toolbar.appendChild(sizeSlider);

  function _footerBtn(html, title, cls, disabled, onClick) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "photo-markup-action-btn" + (cls ? " " + cls : "");
    b.title = title;
    b.innerHTML = html;
    if (disabled) b.disabled = true;
    b.addEventListener("click", onClick);
    return b;
  }

  const undoBtn = _footerBtn('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>', "Undo (Ctrl+Z)", "", true, () => {
    if (!_markupState.actions.length) return;
    _markupState.redoStack.push(_markupState.actions.pop());
    _markupRender();
    _markupUpdateUndoRedo();
  });
  const redoBtn = _footerBtn('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.13-9.36L23 10"/></svg>', "Redo (Ctrl+Y)", "", true, () => {
    if (!_markupState.redoStack.length) return;
    _markupState.actions.push(_markupState.redoStack.pop());
    _markupRender();
    _markupUpdateUndoRedo();
  });

  function _markupUpdateUndoRedo() {
    undoBtn.disabled = !_markupState.actions.length;
    redoBtn.disabled = !_markupState.redoStack.length;
  }
  _markupState._updateUndoRedo = _markupUpdateUndoRedo;

  const rotateBtn = _footerBtn('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.13-9.36L23 10"/></svg>', "Rotate 90°", "", false, () => _markupRotate());

  const spacer = document.createElement("span");
  spacer.className = "photo-markup-footer-spacer";

  const saveBtn = _footerBtn('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>', "Save Copy", "photo-markup-save-btn", false, () => _markupSave());

  footer.appendChild(undoBtn);
  footer.appendChild(redoBtn);
  footer.appendChild(rotateBtn);
  footer.appendChild(spacer);
  footer.appendChild(saveBtn);

  _markupState._undoBtn = undoBtn;
  _markupState._redoBtn = redoBtn;

  wrap.className = "photo-markup-canvas-wrap tool-pen";

  _markupBindCanvasEvents();
  _markupBindKeyboard();

  modal.querySelectorAll("[data-photo-markup-dismiss]").forEach(el => {
    el.addEventListener("click", () => closePhotoMarkupModal());
  });

  modal.classList.remove("hidden");

  const loadEl = document.createElement("div");
  loadEl.className = "photo-markup-loading";
  loadEl.textContent = "Loading image...";
  wrap.appendChild(loadEl);

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.onload = () => {
    loadEl.remove();
    if (!_markupState) return;
    _markupState.img = img;
    _markupState.natW = img.naturalWidth;
    _markupState.natH = img.naturalHeight;
    _markupRender();
  };
  img.onerror = () => {
    loadEl.textContent = "Failed to load image";
  };
  img.src = `/api/v2/photos/${photoId}`;
}

function closePhotoMarkupModal() {
  const modal = $("#photo-markup-modal");
  if (modal) modal.classList.add("hidden");
  if (_markupState) {
    if (_markupState._keyHandler) document.removeEventListener("keydown", _markupState._keyHandler);
    if (_markupState._resizeHandler) window.removeEventListener("resize", _markupState._resizeHandler);
    _markupState = null;
  }
}

function _markupBindCanvasEvents() {
  const s = _markupState;
  if (!s) return;
  const { canvas, wrap } = s;
  let isDown = false;

  function getPos(e) {
    const pt = e.touches ? e.touches[0] : e;
    return _markupScreenToImage(pt.clientX, pt.clientY);
  }

  function onDown(e) {
    if (s.tool === "select") return;
    isDown = true;
    const pos = getPos(e);
    if (s.tool === "text") {
      _markupShowTextInput(pos, canvas, wrap);
      isDown = false;
      return;
    }
    if (s.tool === "number") {
      s.actions.push({ type: "number", position: pos, number: s.numberCounter++, color: s.color, size: s.size });
      s.redoStack = [];
      _markupRender();
      _markupUpdateUndoRedo();
      isDown = false;
      return;
    }
    if (s.tool === "pen" || s.tool === "highlighter") {
      s.currentAction = { type: s.tool, points: [pos], color: s.color, size: s.size };
    } else {
      s.currentAction = { type: s.tool, start: pos, end: pos, color: s.color, size: s.size, fillColor: s.fillColor };
    }
    if (e.cancelable) e.preventDefault();
  }

  function onMove(e) {
    if (!isDown || !s.currentAction) return;
    const pos = getPos(e);
    if (s.tool === "pen" || s.tool === "highlighter") {
      s.currentAction.points.push(pos);
      if (e.shiftKey && s.currentAction.points.length >= 2) {
        const pts = s.currentAction.points;
        const first = pts[0];
        const last = pts[pts.length - 1];
        const dx = last.x - first.x;
        const dy = last.y - first.y;
        const dist = Math.hypot(dx, dy);
        const angle = Math.atan2(dy, dx);
        const snapped = Math.round(angle / (Math.PI / 4)) * (Math.PI / 4);
        pts[pts.length - 1] = {
          x: first.x + dist * Math.cos(snapped),
          y: first.y + dist * Math.sin(snapped),
        };
      }
    } else {
      s.currentAction.end = pos;
    }
    _markupRender();
    if (e.cancelable) e.preventDefault();
  }

  function onUp() {
    if (!isDown) return;
    isDown = false;
    if (s.currentAction) {
      s.actions.push(s.currentAction);
      s.currentAction = null;
      s.redoStack = [];
      _markupRender();
      _markupUpdateUndoRedo();
    }
  }

  canvas.addEventListener("mousedown", onDown);
  canvas.addEventListener("mousemove", onMove);
  canvas.addEventListener("mouseup", onUp);
  canvas.addEventListener("mouseleave", onUp);
  canvas.addEventListener("touchstart", onDown, { passive: false });
  canvas.addEventListener("touchmove", onMove, { passive: false });
  canvas.addEventListener("touchend", onUp);
}

function _markupShowTextInput(pos, canvas, wrap) {
  const s = _markupState;
  if (!s) return;
  const rect = canvas.getBoundingClientRect();
  const displayW = rect.width;
  const displayH = rect.height;
  const scale = Math.min(displayW / s.natW, displayH / s.natH);
  const drawW = s.natW * scale;
  const drawH = s.natH * scale;
  const offX = (displayW - drawW) / 2;
  const offY = (displayH - drawH) / 2;
  const screenX = pos.x * scale + offX + rect.left;
  const screenY = pos.y * scale + offY + rect.top;

  const existing = wrap.querySelector(".photo-markup-text-input");
  if (existing) existing.remove();

  const input = document.createElement("input");
  input.type = "text";
  input.className = "photo-markup-text-input";
  input.style.left = (pos.x * scale + offX - 30) + "px";
  input.style.top = (pos.y * scale + offY - 12) + "px";
  input.style.color = s.color;
  const canvasFontSize = Math.max(s.size * 2.5, 18);
  input.style.fontSize = (canvasFontSize * scale) + "px";
  input.placeholder = "Type text...";
  wrap.appendChild(input);
  requestAnimationFrame(() => input.focus());

  let committed = false;
  function commit() {
    if (committed) return;
    committed = true;
    const text = input.value.trim();
    input.remove();
    if (text) {
      s.actions.push({ type: "text", position: pos, text, color: s.color, size: s.size });
      s.redoStack = [];
      _markupRender();
      _markupUpdateUndoRedo();
    }
  }
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") { commit(); e.preventDefault(); }
    if (e.key === "Escape") { committed = true; input.remove(); }
    e.stopPropagation();
  });
  input.addEventListener("blur", () => { setTimeout(commit, 150); });
}

function _markupRotate() {
  const s = _markupState;
  if (!s || !s.img) return;
  const tmpC = document.createElement("canvas");
  tmpC.width = s.natW;
  tmpC.height = s.natH;
  const tCtx = tmpC.getContext("2d");
  tCtx.drawImage(s.canvas, 0, 0);
  const newW = s.natH;
  const newH = s.natW;
  s.natW = newW;
  s.natH = newH;
  s.canvas.width = newW;
  s.canvas.height = newH;
  s.ctx.clearRect(0, 0, newW, newH);
  s.ctx.save();
  s.ctx.translate(newW, 0);
  s.ctx.rotate(Math.PI / 2);
  s.ctx.drawImage(tmpC, 0, 0);
  s.ctx.restore();
  const newImg = new Image();
  newImg.src = s.canvas.toDataURL();
  newImg.onload = () => { s.img = newImg; _markupRender(); };
}

function _markupBindKeyboard() {
  const handler = (e) => {
    if (!_markupState) return;
    if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
    if ((e.ctrlKey || e.metaKey) && e.key === "z") {
      e.preventDefault();
      if (e.shiftKey) {
        if (_markupState.redoStack.length) {
          _markupState.actions.push(_markupState.redoStack.pop());
          _markupRender();
          _markupUpdateUndoRedo();
        }
      } else {
        if (_markupState.actions.length) {
          _markupState.redoStack.push(_markupState.actions.pop());
          _markupRender();
          _markupUpdateUndoRedo();
        }
      }
    }
    if ((e.ctrlKey || e.metaKey) && e.key === "y") {
      e.preventDefault();
      if (_markupState.redoStack.length) {
        _markupState.actions.push(_markupState.redoStack.pop());
        _markupRender();
        _markupUpdateUndoRedo();
      }
    }
    if (e.key === "Escape") closePhotoMarkupModal();
  };
  document.addEventListener("keydown", handler);
  _markupState._keyHandler = handler;
}

function _markupUpdateUndoRedo() {
  if (_markupState && _markupState._updateUndoRedo) _markupState._updateUndoRedo();
}

async function _markupSave() {
  const s = _markupState;
  if (!s) return;
  const saveBtn = s.footer.querySelector(".photo-markup-save-btn");
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = "Saving..."; }
  try {
    const blob = await new Promise(resolve => s.canvas.toBlob(resolve, "image/png"));
    if (!blob) throw new Error("Failed to create image");
    const formData = new FormData();
    formData.append("file", blob, "markup.png");
    formData.append("source_photo_id", String(s.photoId));
    const resp = await fetch(`/api/v2/projects/${s.oppId}/photos/markup`, {
      method: "POST", credentials: "same-origin", body: formData,
    });
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      throw new Error(err.error || `HTTP ${resp.status}`);
    }
    showToast("Markup saved as new photo");
    _markupRefreshPhotosGrid(s.oppId);
    closePhotoMarkupModal();
  } catch (err) {
    showToast("Save failed: " + err.message, true);
  } finally {
    if (saveBtn) { saveBtn.disabled = false; saveBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg> Save Copy'; }
  }
}

function _markupRefreshPhotosGrid(oppId) {
  const photosContainer = document.querySelector('.opp-preview-tab-content[data-tab-content="photos"]');
  if (!photosContainer) return;
  const oppPreviewModal = $("#opp-preview-modal");
  if (oppPreviewModal && oppPreviewModal.classList.contains("hidden")) return;
  api(`/api/v2/projects/${oppId}/photos`).then(data => {
    const photos = (data && data.photos) ? data.photos : [];
    renderOpportunityPreviewPhotosTab(photosContainer, oppId, photos);
  }).catch(() => {});
}

